-- scripts/build_question_import_sql.py で作り直せる。
WITH v (category, topic, difficulty, exam_type, question_text, choices, correct_choice_key, explanation, choice_explanations, visibility, question_type, blueprint_code, class_group, status, source) AS (VALUES
('肝・胆・膵', '', 2, 'KOKUSHI', '疾患と治療の組合せで正しいのはどれか。', '[{"key": "A", "text": "多発肝細胞癌 — 経カテーテル的動脈化学塞栓術〈TACE〉"}, {"key": "B", "text": "胆石合併胆囊癌 — 腹腔鏡下胆囊摘出術"}, {"key": "C", "text": "特発性門脈圧亢進症 — 門脈内ステント留置"}, {"key": "D", "text": "膵管内乳頭粘液性腫瘍 — 膵管ステント留置"}, {"key": "E", "text": "急性化膿性閉塞性胆管炎 — 胆管切除術"}]'::jsonb, 'A', '正答は A「多発肝細胞癌 — 経カテーテル的動脈化学塞栓術〈TACE〉」。

多発する肝細胞癌で、切除や穿刺局所療法の適応がない中間期（肝機能が保たれ、脈管侵襲や遠隔転移がない）では、肝動脈から抗癌薬と塞栓物質を入れるTACEが標準治療である。肝細胞癌は主に肝動脈から栄養されるため、塞栓で腫瘍を選択的に壊死させられる。

出典：厚生労働省ホームページ 第114回医師国家試験 A007', '{"B": "癌と分かっている胆嚢では、腹腔鏡下手術は胆汁の漏出による播種の危険がある。肝床切除やリンパ節郭清を伴う開腹の拡大胆嚢摘出術を行う。", "C": "特発性門脈圧亢進症では、食道静脈瘤に内視鏡治療を、脾機能亢進に脾摘や部分的脾動脈塞栓術を行う。門脈へのステント留置は治療にならない。", "D": "膵管内乳頭粘液性腫瘍は経過観察か、悪性を疑う所見があれば膵切除を行う。膵管ステントでは腫瘍を治療できない。", "E": "急性化膿性閉塞性胆管炎には、内視鏡的または経皮的な緊急の胆道ドレナージと抗菌薬で対応する。胆管切除は行わない。"}'::jsonb, 'public', 'M', '114-A-7', '', 'pending', 'llm'),
('耳鼻咽喉科', '', 2, 'KOKUSHI', '2か月の乳児。新生児聴覚スクリーニングで精密検査が必要となり、両親とともに来院した。家族の呼びかけや周囲の音への反応はほとんどない。身長・体重は月齢相当である。外耳道と鼓膜とに異常を認めない。側頭骨CTでは中耳・内耳に異常を認めない。聴性脳幹反応〈ABR〉は両耳とも無反応である。耳音響放射〈OAE〉では、両耳で低中音部に残存聴力が確認された。医師から両親への説明として適切なのはどれか。', '[{"key": "A", "text": "「機能性難聴です」"}, {"key": "B", "text": "「補聴器装用を開始しましょう」"}, {"key": "C", "text": "「副腎皮質ステロイドで治療します」"}, {"key": "D", "text": "「人工内耳埋込み術をすぐに予定します」"}, {"key": "E", "text": "「1歳6か月児健康診査まで様子をみてください」"}]'::jsonb, 'B', '正答は B「「補聴器装用を開始しましょう」」。

ABRは無反応だが、耳音響放射で低中音部の蝸牛機能が残っており、両側の難聴に対して補聴器で聴覚を活用できる見込みがある。言語発達のために、生後6か月までに補聴器の装用と療育を始めることが目標とされる。

出典：厚生労働省ホームページ 第114回医師国家試験 A017', '{"A": "機能性（心因性）難聴は他覚的検査が正常なのに自覚的な聴力が悪いもので、ABRが無反応の乳児には当たらない。", "C": "副腎皮質ステロイドは突発性難聴などに用いるもので、先天性の難聴の治療にはならない。", "D": "人工内耳は補聴器の効果が不十分な場合に、原則1歳以上・体重8kg以上で検討する。まず補聴器を試す。", "E": "難聴は早期の発見と療育が言語発達を左右するため、様子をみて療育を遅らせてはならない。"}'::jsonb, 'public', 'M', '114-A-17', '', 'pending', 'llm'),
('神経', '', 2, 'KOKUSHI', '3歳の男児。5日前から右の眼瞼下垂が出現し、次第に目立ってきたため、祖母に連れられて受診した。1年前の写真では両側とも眼瞼下垂はなかった。外傷の既往はない。意識は清明で、活発に走り回っている。右優位の両側眼瞼下垂を認めるが、祖母によると朝は目立たず、夜になると悪化するという。嚥下に問題はない。四肢の筋萎縮はなく、腱反射は正常である。視力は右0.8(1.2×+1.0D)、左0.7(1.2×+1.0D)で乱視は認めず、眼球運動にも異常を認めない。診断に有用なのはどれか。', '[{"key": "A", "text": "脳波"}, {"key": "B", "text": "脳脊髄液検査"}, {"key": "C", "text": "ポリソムノグラフィ"}, {"key": "D", "text": "聴性脳幹反応〈ABR〉"}, {"key": "E", "text": "エドロホニウムテスト"}]'::jsonb, 'E', '正答は E「エドロホニウムテスト」。

朝は目立たず夕方に増悪する眼瞼下垂は、易疲労性と日内変動を示し、眼筋型重症筋無力症を考える。コリンエステラーゼ阻害薬のエドロホニウムを静注して眼瞼下垂が一時的に改善すれば診断を支持する。抗アセチルコリン受容体抗体の測定やアイスパックテストも合わせて行う。

出典：厚生労働省ホームページ 第114回医師国家試験 A019', '{"A": "脳波はてんかんの診断に用いる検査で、神経筋接合部の障害は評価できない。", "B": "脳脊髄液検査は髄膜炎やGuillain-Barré症候群で行い、重症筋無力症では異常を示さない。", "C": "ポリソムノグラフィは睡眠時無呼吸などの睡眠障害を調べる検査で、眼瞼下垂の原因検索には用いない。", "D": "聴性脳幹反応は聴覚路の検査で、眼瞼下垂の診断には役立たない。"}'::jsonb, 'public', 'M', '114-A-19', '', 'pending', 'llm'),
('免疫・膠原病', '', 2, 'KOKUSHI', '24歳の女性。頭痛と発熱のため3日前から入院中である。2週前から微熱と多発関節痛を自覚していた。3日前に38°C台の発熱と頭痛が出現したため受診し、同日入院した。入院時、身長160cm、体重48kg。体温38.3°C。脈拍92/分、整。血圧126/74mmHg。呼吸数18/分。頰部紅斑、無痛性の口腔内潰瘍を認める。両手関節、両膝関節に圧痛を認める。血液所見:赤血球326万、Hb10.4g/dL、Ht 28%、白血球2,600(桿状核好中球70%、分葉核好中球12%、好酸球2%、リンパ球16%)、血小板23万。免疫血清学所見:CRP0.1mg/dL、リウマトイド因子〈RF〉陰性、抗CCP抗体陰性、抗核抗体陽性、抗dsDNA抗体134IU/mL(基準12以下)、抗Sm抗体陽性。抗β2GPI抗体陰性、抗カルジオリピン抗体陰性、ループス抗凝固因子陰性。入院2日目から見当識障害を認め、その後せん妄状態となった。脳脊髄液所見:無色、水様透明。初圧130mmH2O(基準70〜170)。細胞数52/mm3(基準0〜2)(多核球20%、単核球80%)。蛋白87mg/dL(基準15〜45)、糖48mg/dL(基準50〜75)。頭部MRIで異常を認めない。この患者の治療で副腎皮質ステロイドと併用する薬剤として適切なのはどれか。', '[{"key": "A", "text": "コルヒチン"}, {"key": "B", "text": "抗TNF-α抗体"}, {"key": "C", "text": "メトトレキサート"}, {"key": "D", "text": "抗IL-6受容体抗体"}, {"key": "E", "text": "シクロフォスファミド"}]'::jsonb, 'E', '正答は E「シクロフォスファミド」。

頰部紅斑、無痛性の口腔内潰瘍、関節炎、白血球減少に、抗dsDNA抗体と抗Sm抗体の陽性がそろいSLEである。入院後のせん妄と髄液の細胞数・蛋白の増加は中枢神経ループスを示す。重い臓器病変なので、大量の副腎皮質ステロイドにシクロホスファミドの静注療法を併用する。

出典：厚生労働省ホームページ 第114回医師国家試験 A020', '{"A": "コルヒチンは痛風発作や家族性地中海熱に用いる薬で、ループスの中枢神経病変は抑えられない。", "B": "抗TNF-α抗体は関節リウマチなどに用いる。SLEには効果がなく、薬剤性ループスを起こすこともある。", "C": "メトトレキサートはSLEの関節症状に用いることはあるが、重い中枢神経病変の寛解導入には用いない。", "D": "抗IL-6受容体抗体は関節リウマチや大型血管炎に用いる薬で、SLEの治療には用いない。"}'::jsonb, 'public', 'M', '114-A-20', '', 'pending', 'llm'),
('整形外科', '', 2, 'KOKUSHI', '72歳の男性。左足のしびれ感と歩行困難を主訴に来院した。進行期肝癌の加療中で、6か月間で体重が5kg減少した。本日、自宅で足を組んだ状態で1時間程度テレビを見た後に歩こうとすると、床に左足のつま先が引っかかり、何度か転びそうになったため来院した。意識は清明。身長162cm、体重49kg。体温36.3°C。脈拍68/分、整。血圧108/72mmHg。呼吸数16/分。SpO298%(room air)。左足背部に鈍いしびれ感がある。下腿に腫脹は認めず、足背動脈は両側とも触知良好。腱反射は両側上下肢とも正常。徒手筋力テストで、上肢は左右差なく正常、下肢(右/左)は股関節屈曲5/5、膝関節伸展5/5、足関節背屈5/1であった。腰椎MRIで明らかな異常を認めない。確定診断のため有用な検査はどれか。', '[{"key": "A", "text": "骨密度測定"}, {"key": "B", "text": "脊髄腔造影検査"}, {"key": "C", "text": "骨シンチグラフィ"}, {"key": "D", "text": "末梢神経伝導検査"}, {"key": "E", "text": "下肢動脈超音波検査"}]'::jsonb, 'D', '正答は D「末梢神経伝導検査」。

やせた人が足を組んで座り続けたあとに生じた下垂足で、足関節の背屈だけが著しく弱く、足背のしびれを伴う。腓骨頭部での総腓骨神経の圧迫性麻痺を考え、神経伝導検査で腓骨頭をはさむ部位の伝導ブロックを確かめる。

出典：厚生労働省ホームページ 第114回医師国家試験 A030', '{"A": "骨密度測定は骨粗鬆症の評価に用いる検査で、神経麻痺の診断には役立たない。", "B": "腰椎MRIで異常がなく、神経根や馬尾の圧迫を探す脊髄腔造影の必要はない。", "C": "骨シンチグラフィは骨転移の検索には用いるが、腓骨神経麻痺の診断はできない。", "E": "足背動脈は両側とも良好に触れ、血流障害による症状ではない。"}'::jsonb, 'public', 'M', '114-A-30', '', 'pending', 'llm'),
('呼吸器', '', 2, 'KOKUSHI', '23歳の男性。呼吸困難を主訴に来院した。2週前から続く咳嗽および喀痰、4日前から発熱がある。1か月前から喫煙を始めたという。呼吸数22/分。SpO289%(room air)。心音に異常を認めない。両側背部にfine cracklesを聴取する。胸部エックス線写真で両側びまん性のすりガラス陰影および浸潤影を認める。胸部CTでは、小葉間隔壁の肥厚を伴うすりガラス陰影、区域を超えた浸潤影を認めた。肺生検組織で著明な好酸球浸潤を認めた。気管支肺胞洗浄液中の好酸球は42%と増加を認めた。本疾患の特徴として誤っているのはどれか。', '[{"key": "A", "text": "気管支喘息の合併が多い。"}, {"key": "B", "text": "喫煙が誘因となり得る。"}, {"key": "C", "text": "初期の末梢血好酸球数は正常である。"}, {"key": "D", "text": "治療後の再発は少ない。"}, {"key": "E", "text": "副腎皮質ステロイドの反応性は良好である。"}]'::jsonb, 'A', '正答は A「気管支喘息の合併が多い。」。

喫煙を始めて間もない若年者に急性の呼吸不全が起こり、気管支肺胞洗浄液の好酸球が著しく多い。急性好酸球性肺炎である。気管支喘息を合併しやすいのは慢性好酸球性肺炎の特徴で、急性型にはあてはまらない。

出典：厚生労働省ホームページ 第114回医師国家試験 A033', '{"B": "喫煙の開始や再開が誘因になることがよく知られており、正しい。", "C": "急性型では発症初期の末梢血好酸球は正常のことが多く、経過中に増えてくる。正しい。", "D": "急性型は治療でよく改善し、禁煙を守れば再発は少ない（再発が多いのは慢性型）。正しい。", "E": "副腎皮質ステロイドへの反応は良好で、速やかに改善する。正しい。"}'::jsonb, 'public', 'M', '114-A-33', '', 'pending', 'llm'),
('神経', '', 2, 'KOKUSHI', '78歳の女性。異常行動を主訴に来院した。2年前から徐々に物忘れが目立つようになり、1年前に軽度認知機能障害〈MCI〉と診断された。日常生活に支障がないため経過観察されていた。1か月前、自宅で夫と昼食中に急に箸を落とした際に、夫が声をかけたが返事をせず、動作が止まって中空を見つめ、唾をコックンコックンと飲み込むような動作を繰り返していた。1分程してから突然立ち上がり、部屋の中を行ったり来たりするため、夫が制止しようとすると激しく抵抗した。30分程して徐々に会話が可能となり、普段通りの状態に戻ったが、本人はこの間のことを覚えていなかったという。このような異常行動が1週間に2、3回みられるため、心配した夫に付き添われて受診した。意識は清明。身長148cm、体重46kg。体温36.2°C。脈拍64/分、整。血圧116/68mmHg。呼吸数18/分。心音と呼吸音とに異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。改訂長谷川式簡易知能評価スケール21点(30点満点)。脳神経に異常を認めない。腱反射は正常で運動麻痺、感覚障害および運動失調を認めない。考えられるのはどれか。', '[{"key": "A", "text": "せん妄"}, {"key": "B", "text": "常同運動症"}, {"key": "C", "text": "複雑部分発作"}, {"key": "D", "text": "一過性脳虚血発作"}, {"key": "E", "text": "むずむず脚症候群"}]'::jsonb, 'C', '正答は C「複雑部分発作」。

動作が止まって一点を見つめ、飲み込むような口の動き（口部自動症）に続いて歩き回り、その間の記憶がない。意識の減損を伴う焦点発作（複雑部分発作）で、側頭葉てんかんに典型的である。高齢で発症するてんかんは認知症の症状と誤られやすい。

出典：厚生労働省ホームページ 第114回医師国家試験 A046', '{"A": "せん妄は数時間から数日続く意識・注意の障害で、同じ形の短い発作を繰り返すものではない。", "B": "常同運動症は発達期から続く反復的な無目的の運動で、意識の障害や健忘は伴わない。", "D": "一過性脳虚血発作は麻痺や失語などの局所の脱落症状を示し、自動症や健忘を繰り返す形はとらない。", "E": "むずむず脚症候群は安静時の下肢の不快感と動かしたい衝動が主で、意識は保たれる。"}'::jsonb, 'public', 'M', '114-A-46', '', 'pending', 'llm'),
('神経', '', 2, 'KOKUSHI', '筋萎縮性側索硬化症〈ALS〉の診断に有用なのはどれか。', '[{"key": "A", "text": "脳波検査"}, {"key": "B", "text": "針筋電図検査"}, {"key": "C", "text": "平衡機能検査"}, {"key": "D", "text": "脊髄腔造影検査"}, {"key": "E", "text": "感覚神経伝導検査"}]'::jsonb, 'B', '正答は B「針筋電図検査」。

ALSの診断では、上位と下位の運動ニューロン障害の広がりを確かめる。針筋電図は線維束自発電位や脱神経電位を捉え、臨床的にはまだ目立たない下位運動ニューロン障害まで検出できるので、診断基準の中心になる。

出典：厚生労働省ホームページ 第114回医師国家試験 B011', '{"A": "ALSは運動ニューロンの変性で、脳波に診断に役立つ変化は出ない。", "C": "平衡機能検査はめまいや前庭の障害を調べる検査で、ALSの診断には用いない。", "D": "脊髄の圧迫性病変の除外にはMRIを用いる。脊髄腔造影はALSの診断に役立たない。", "E": "ALSでは感覚神経が保たれるため、感覚神経伝導検査は正常で、診断の決め手にはならない。"}'::jsonb, 'public', 'M', '114-B-11', '', 'pending', 'llm'),
('医学総論', '', 2, 'KOKUSHI', '咳嗽を主訴に受診した、喫煙をしている25歳男性の問題志向型医療記録〈POMR〉に基づいた診療録の一部を以下に示す。問題リスト#1 乾性咳嗽①初期計画#1 乾性咳嗽診断的計画胸部単純エックス線撮影②血液生化学検査アレルギー検査禁煙指導③治療的計画鎮咳薬処方④吸入薬処方教育的計画禁煙外来への通院助言⑤記載する場所が誤っているのはどれか。', '[{"key": "A", "text": "①"}, {"key": "B", "text": "②"}, {"key": "C", "text": "③"}, {"key": "D", "text": "④"}, {"key": "E", "text": "⑤"}]'::jsonb, 'C', '正答は C「③」。

POMRの初期計画は、診断的計画（検査）、治療的計画（処方や処置）、教育的計画（患者への説明や指導）に分けて書く。禁煙指導は患者教育なので教育的計画に書くべきで、診断的計画に置いた③が誤りである。

出典：厚生労働省ホームページ 第114回医師国家試験 B013', '{"A": "乾性咳嗽は患者の問題として問題リストに挙げる。正しい。", "B": "胸部エックス線撮影は診断のための検査で、診断的計画に書く。正しい。", "D": "鎮咳薬の処方は治療的計画に書く。正しい。", "E": "禁煙外来への通院の助言は患者教育で、教育的計画に書く。正しい。"}'::jsonb, 'public', 'M', '114-B-13', '', 'pending', 'llm'),
('公衆衛生', '', 2, 'KOKUSHI', '医薬品医療機器総合機構〈PMDA〉が医療者から収集する副作用・感染症・不具合等の報告に含まれないのはどれか。', '[{"key": "A", "text": "医薬品"}, {"key": "B", "text": "医療機器"}, {"key": "C", "text": "健康食品"}, {"key": "D", "text": "予防接種"}, {"key": "E", "text": "再生医療等製品"}]'::jsonb, 'C', '正答は C「健康食品」。

医療関係者による医薬品・医療機器等安全性情報報告制度では、医薬品、医療機器、再生医療等製品の副作用・感染症・不具合をPMDAに報告する。予防接種後の副反応疑い報告もPMDAが受け付ける。健康食品は医薬品医療機器等法の対象外で、健康被害は保健所に相談・報告する。

出典：厚生労働省ホームページ 第114回医師国家試験 B015', '{"A": "医薬品の副作用や感染症は報告の対象である。", "B": "医療機器の不具合も報告の対象である。", "D": "予防接種の副反応疑い報告も、予防接種法に基づきPMDAが受け付ける。", "E": "再生医療等製品の副作用・感染症・不具合も報告の対象である。"}'::jsonb, 'public', 'M', '114-B-15', '', 'pending', 'llm'),
('呼吸器', '', 2, 'KOKUSHI', '症候と疾患の組合せで適切でないのはどれか。', '[{"key": "A", "text": "小顎 — 睡眠時無呼吸症候群"}, {"key": "B", "text": "皮疹 — サルコイドーシス"}, {"key": "C", "text": "ばち指 — マイコプラズマ肺炎"}, {"key": "D", "text": "チアノーゼ — 急性呼吸窮迫症候群〈ARDS〉"}, {"key": "E", "text": "口すぼめ呼吸 — COPD"}]'::jsonb, 'C', '正答は C「ばち指 — マイコプラズマ肺炎」。

ばち指は、慢性の低酸素や肺癌、間質性肺炎、気管支拡張症、チアノーゼ性心疾患など、長く続く病態で生じる。急性の感染症であるマイコプラズマ肺炎では起こらない。

出典：厚生労働省ホームページ 第114回医師国家試験 B024', '{"A": "小顎は上気道を狭くし、閉塞性睡眠時無呼吸の危険因子になる。適切である。", "B": "サルコイドーシスでは結節性紅斑や皮膚サルコイドなどの皮疹がみられる。適切である。", "D": "ARDSでは高度の低酸素血症によりチアノーゼを呈する。適切である。", "E": "COPDでは呼気時の気道の虚脱を防ぐために口すぼめ呼吸をとる。適切である。"}'::jsonb, 'public', 'M', '114-B-24', '', 'pending', 'llm'),
('産科', '', 2, 'KOKUSHI', '23歳の女性。全身倦怠感を主訴に受診した。2週前に市販の妊娠検査薬が陽性となり来院し、子宮内に胎囊と10mmの胎芽を認めた。10日前から悪心を自覚し、1週前から嘔吐を繰り返し、食事がほとんど摂取できていないという。性器出血や下腹部痛の訴えはない。意識は清明。身長155cm、体重50kg。妊娠前の体重は54kgであった。体温37.1°C。脈拍84/分、整。血圧122/68mmHg。呼吸数16/分。口唇の乾燥を認める。経腟超音波検査にて頭殿長20mmの胎児と心拍動を認める。まず行う検査はどれか。', '[{"key": "A", "text": "尿ケトン体"}, {"key": "B", "text": "血中hCG定量"}, {"key": "C", "text": "甲状腺機能検査"}, {"key": "D", "text": "動脈血ガス分析"}, {"key": "E", "text": "上部消化管内視鏡検査"}]'::jsonb, 'A', '正答は A「尿ケトン体」。

妊娠初期に嘔吐を繰り返して食事がとれず、体重が妊娠前から4kg（約8%）減り、口唇も乾燥している。妊娠悪阻を考え、まず尿ケトン体で飢餓による脂肪分解の程度をみて、脱水と合わせて輸液の要否を判断する。

出典：厚生労働省ホームページ 第114回医師国家試験 B028', '{"B": "胎児の心拍を確認した正常妊娠であり、hCGの定量は悪阻の重症度の評価に用いない。", "C": "hCGの作用で一過性の甲状腺機能亢進を伴うことはあるが、まず確かめるのは飢餓と脱水の程度である。", "D": "意識は清明でバイタルサインも安定しており、まず動脈血ガス分析を行う必要はない。", "E": "妊娠初期の悪心・嘔吐で妊娠悪阻として説明がつき、上部消化管内視鏡は不要である。"}'::jsonb, 'public', 'M', '114-B-28', '', 'pending', 'llm'),
('医学総論', '', 2, 'KOKUSHI', '78歳の男性。食欲不振、体重減少と全身倦怠感を主訴に来院した。2年前に膵頭部癌で切除術を受けたが、1年前に肝と肺への多発転移を指摘された。本人および家族ともにこれ以上の抗癌治療を望まず、通院していなかったという。1か月前から食欲不振と5kgの体重減少をきたし、1週前から全身倦怠感も認めるようになったため再度受診した。疼痛や不眠を認めない。身長167cm、体重38kg。体温36.0°C。脈拍80/分、整。血圧100/68mmHg。呼吸数14/分。癌悪液質と診断した。この時点での対応として正しいのはどれか。', '[{"key": "A", "text": "NSAIDを投与する。"}, {"key": "B", "text": "抗うつ薬を投与する。"}, {"key": "C", "text": "抗癌治療を実施する。"}, {"key": "D", "text": "直ちに高カロリー輸液を行う。"}, {"key": "E", "text": "在宅ケアに関する患者の意向を聞く。"}]'::jsonb, 'E', '正答は E「在宅ケアに関する患者の意向を聞く。」。

抗癌治療を望まない膵癌の多発転移で、痛みや不眠はなく、不可逆的な癌悪液質に進んでいる。残された時間の過ごし方を本人と家族で決める時期であり、在宅でのケアも含めて患者の意向を確かめ、アドバンス・ケア・プランニングを進める。

出典：厚生労働省ホームページ 第114回医師国家試験 B030', '{"A": "疼痛はなく、NSAIDを使う理由がない。消化管出血や腎障害の危険だけが増える。", "B": "抑うつや不眠はみられず、抗うつ薬の適応はない。", "C": "本人も家族も抗癌治療を望んでおらず、全身状態からも行う段階ではない。", "D": "不可逆的な悪液質では、栄養を入れても体重や予後は改善せず、過剰な輸液は浮腫や胸水・腹水を悪化させる。"}'::jsonb, 'public', 'M', '114-B-30', '', 'pending', 'llm'),
('医学総論', '', 2, 'KOKUSHI', '82歳の男性。右下肢のしびれと痛みのため救急車で搬入された。本日、夕方にテレビを見ていたときに突然右下肢のしびれと痛みを感じた。しばらく様子をみていたが徐々に痛みが増悪し、3時間経過しても改善しないため救急車を要請した。意識は清明。体温36.4°C。心拍数98/分、不整。血圧160/96mmHg。呼吸数14/分。SpO299%(マスク5L/分酸素投与下)。心音と呼吸音とに異常を認めない。右下腿は蒼白で冷感を認める。右大腿動脈、右膝窩動脈、右足背動脈の触診で動脈拍動を触知しない。下肢に浮腫は認めない。造影CTによる血栓の局在を確認した後、再灌流療法を行った。治療後に認められる可能性が低いのはどれか。', '[{"key": "A", "text": "右下腿浮腫"}, {"key": "B", "text": "ビリルビン尿"}, {"key": "C", "text": "高カリウム血症"}, {"key": "D", "text": "乳酸アシドーシス"}, {"key": "E", "text": "血清クレアチンキナーゼ高値"}]'::jsonb, 'B', '正答は B「ビリルビン尿」。

急性下肢動脈閉塞に対する再灌流では、虚血で壊死した筋から細胞内成分が全身へ流入する。高カリウム血症、乳酸アシドーシス、CK上昇、ミオグロビン尿による赤褐色尿、そしてコンパートメント症候群による浮腫が問題となる。ビリルビン尿は肝胆道疾患による所見で、この病態では生じない。

出典：厚生労働省ホームページ 第114回医師国家試験 B033', '{"A": "再灌流後の浮腫やコンパートメント症候群は典型的な合併症である。", "C": "壊死筋から細胞内カリウムが放出され、致死的不整脈の原因となる。", "D": "虚血組織に貯留した乳酸が再灌流により全身循環へ流入する。", "E": "横紋筋融解によりクレアチンキナーゼが著明に上昇する。"}'::jsonb, 'public', 'M', '114-B-33', '', 'pending', 'llm'),
('循環器', '', 2, 'KOKUSHI', '80歳の女性。失神のため救急車で搬入された。現病歴 : 1か月前から咳が出現し、5m歩行しても息切れするようになった。発熱や喀痰、胸痛はなく、体重が1か月で3kg増加した。本日、自宅の居間で倒れているのを家族が発見し、救急車を要請した。救急隊到着時には意識はすでに回復し清明であった。既往歴 : 高血圧症および不眠症があり、降圧薬と睡眠薬を内服中である。アレルギー歴 : 特記すべきことはない。生活歴 : 喫煙歴と飲酒歴はない。認知機能は正常で介護保険サービスは利用していない。夫とは8年前に死別し、現在は息子夫婦および孫3人と同居している。家族歴 : 突然死や心疾患はなく、姉は70歳時に乳癌で死亡した。
この患者で、失神の原因として不整脈を疑う場合に聞くべき質問はどれか。', '[{"key": "A", "text": "「倒れた後、舌を噛んで口から血が出ていませんでしたか」"}, {"key": "B", "text": "「呼吸が速くなってきて、手足がしびれてきませんでしたか」"}, {"key": "C", "text": "「倒れた後、30分程度意識がもうろうとしていませんでしたか」"}, {"key": "D", "text": "「座っていたときに急に目の前が暗くなって倒れませんでしたか」"}, {"key": "E", "text": "「突然バットで殴られたような激しい頭痛の後に意識を失いませんでしたか」"}]'::jsonb, 'D', '正答は D「「座っていたときに急に目の前が暗くなって倒れませんでしたか」」。

不整脈による失神は、体位や誘因と関係なく、座位や臥位でも前触れなく突然起こるのが特徴である。この患者は体重増加と労作時の息切れから心不全が疑われ、器質的心疾患に伴う不整脈性の失神を考えて聴取する。

出典：厚生労働省ホームページ 第114回医師国家試験 B041', '{"A": "舌の側面を噛む咬傷は、てんかん発作を疑うときに聞く質問である。", "B": "呼吸が速くなって手足がしびれるのは過換気症候群を疑うときの質問である。", "C": "発作後に長くもうろうとするのはてんかん発作の特徴で、失神では意識は速やかに戻る。", "E": "突然の激しい頭痛に続く意識消失は、くも膜下出血を疑うときの質問である。"}'::jsonb, 'public', 'M', '114-B-41', '', 'pending', 'llm'),
('循環器', '', 2, 'KOKUSHI', '65歳の男性。意識障害のため救急車で搬入された。現病歴 : 午前8時に農作業に行くと家族に伝えて外出した。昼食の時間になっても帰宅しないため家族が様子を見に行ったところ、ビニールハウス内で倒れているのを発見し、救急車を要請した。現症 : 救急車からの予備情報によると、意識レベルはJCSIII-200。体温39.2°C。心拍数144/分、整。血圧82/40mmHg。呼吸数20/分。SpO2100%(リザーバー付マスク10L/分酸素投与下)。
直ちに行うべき検査はどれか。', '[{"key": "A", "text": "脳波"}, {"key": "B", "text": "血糖測定"}, {"key": "C", "text": "腰椎穿刺"}, {"key": "D", "text": "胸部単純CT"}, {"key": "E", "text": "腹部超音波検査"}]'::jsonb, 'B', '正答は B「血糖測定」。

意識障害の患者では、原因が何であれ最初に血糖を測る。低血糖は数分で判断でき、ブドウ糖投与で速やかに戻せる一方、見逃して時間が経つと不可逆的な脳障害を残す。本例は2型糖尿病で投薬を受けており、低血糖の可能性を真っ先に否定する必要がある。

出典：厚生労働省ホームページ 第114回医師国家試験 B043', '{"A": "脳波はてんかん重積などの評価に有用だが、その場で治療方針を変える情報は得られず、緊急度が低い。", "C": "腰椎穿刺は髄膜炎を疑えば必要になるが、ショック状態で先に行う検査ではない。", "D": "胸部単純CTは意識障害の原因検索としての優先度が低い。", "E": "腹部超音波検査も同様で、この時点で意識障害の原因に迫れる検査ではない。"}'::jsonb, 'public', 'M', '114-B-43', '', 'pending', 'llm'),
('代謝・内分泌', '', 2, 'KOKUSHI', '65歳の男性。意識障害のため救急車で搬入された。現病歴 : 午前8時に農作業に行くと家族に伝えて外出した。昼食の時間になっても帰宅しないため家族が様子を見に行ったところ、ビニールハウス内で倒れているのを発見し、救急車を要請した。現症 : 救急車からの予備情報によると、意識レベルはJCSIII-200。体温39.2°C。心拍数144/分、整。血圧82/40mmHg。呼吸数20/分。SpO2100%(リザーバー付マスク10L/分酸素投与下)。
家族への病歴聴取や身体診察、検査を行った結果、以下の結果が得られた。現病歴 : 作業に出かけるまでは、特に普段と変わりがなかった。朝食も普段通り摂取していた。家族が様子を見に行った際には、ビニールハウスの中はかなり暑くなっていた。既往歴 : 50歳時から2型糖尿病と高血圧症で通院して投薬を受けている。生活歴 : 喫煙は20本/日を40年間。飲酒はビール350mL/日を40年間。家族歴 : 父が心筋梗塞。現症 : 意識レベルはJCSIII-200。体温39.0°C。心拍数138/分、整。血圧84/46mmHg。呼吸数18/分。SpO299%(鼻カニューラ3L/分酸素投与下)。瞳孔は両側3mmで対光反射は両側とも迅速。眼瞼結膜と眼球結膜とに異常を認めない。口腔内は乾燥している。頸部リンパ節は触知しない。心音と呼吸音とに異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。浮腫を認めない。腱反射に異常を認めない。検査所見 : 尿所見:蛋白1+、糖(−)、ケトン体(−)。血液所見:赤血球610万、Hb17.2g/dL、Ht60%、白血球10,800(分葉核好中球80%、好酸球1%、好塩基球1%、単球8%、リンパ球10%)、血小板42万。血液生化学所見:総蛋白9.0g/dL、アルブミン5.2g/dL、総ビリルビン0.8mg/dL、AST20U/L、ALT 13U/L、LD350U/L(基準120〜245)、尿素窒素53mg/dL、クレアチニン1.8 mg/dL、血糖153mg/dL、Na166mEq/L、K4.8mEq/L、Cl120mEq/L。CRP 0.2mg/dL。
まず投与すべきなのはどれか。', '[{"key": "A", "text": "抗菌薬"}, {"key": "B", "text": "昇圧薬"}, {"key": "C", "text": "NSAID"}, {"key": "D", "text": "生理食塩液"}, {"key": "E", "text": "副腎皮質ステロイド"}]'::jsonb, 'D', '正答は D「生理食塩液」。

高温のビニールハウス内で倒れており、体温39.0°C、意識障害を伴う熱中症（III度）である。Na 166mEq/L、Ht 60%、総蛋白9.0g/dL、アルブミン5.2g/dLはいずれも血液が濃縮されていることを示し、血圧84/46mmHgと循環血液量減少性ショックに陥っている。まず生理食塩液で血管内容量を回復させ、並行して体表冷却を行う。

出典：厚生労働省ホームページ 第114回医師国家試験 B044', '{"A": "CRP 0.2mg/dLと炎症反応に乏しく、感染症を示す所見がない。", "B": "昇圧薬は輸液で血管内容量を戻しても血圧が保てないときに考えるもので、脱水が明らかな段階で先に使う薬ではない。", "C": "熱中症の高体温は視床下部の設定温度が上がったものではないため、解熱薬は効かない。冷却が必要である。", "E": "副腎不全を示す所見はなく（Naは高値、Kは4.8mEq/Lと正常）、ステロイドの適応がない。"}'::jsonb, 'public', 'M', '114-B-44', '', 'pending', 'llm'),
('感染症', '', 2, 'KOKUSHI', '75歳の女性。発熱を主訴に来院した。現病歴 : 昨日からわずかな排尿痛を自覚していた。今朝から悪寒戦慄を伴う発熱が出現したため、家族に付き添われて受診した。既往歴 : 高血圧症のため、自宅近くの診療所で投薬を受けている。胆石症のため、同じ診療所で年1回の腹部超音波検査を実施している。生活歴 : 60歳まで小学校の教諭をしていた。夫は5年前に死去し、現在は長男夫婦および中学生の孫と同居している。家族歴 : 父が胃癌、母が大腸癌。
この患者の診察にあたり必要な感染予防策はどれか。', '[{"key": "A", "text": "標準予防策"}, {"key": "B", "text": "空気感染予防策"}, {"key": "C", "text": "接触感染予防策"}, {"key": "D", "text": "飛沫感染予防策"}, {"key": "E", "text": "診察に用いたディスポーザブル物品の焼却"}]'::jsonb, 'A', '正答は A「標準予防策」。

排尿痛に続く悪寒戦慄と発熱、左肋骨脊柱角の叩打痛、膿尿があり急性腎盂腎炎である。人から人へ空気・飛沫・接触で伝播する病態ではないので、追加の予防策は要らず、すべての患者に対して常に行う標準予防策で足りる。

出典：厚生労働省ホームページ 第114回医師国家試験 B045', '{"B": "空気感染予防策は結核・麻疹・水痘のように微小な飛沫核で伝播する感染症に用いる。", "C": "接触感染予防策は多剤耐性菌やクロストリジオイデス・ディフィシルなどで追加する。", "D": "飛沫感染予防策はインフルエンザや流行性耳下腺炎などで追加する。", "E": "使用済みのディスポーザブル物品は通常の感染性廃棄物として処理すればよく、個別に焼却を指示するものではない。"}'::jsonb, 'public', 'M', '114-B-45', '', 'pending', 'llm'),
('肝・胆・膵', '', 2, 'KOKUSHI', '75歳の女性。発熱を主訴に来院した。現病歴 : 昨日からわずかな排尿痛を自覚していた。今朝から悪寒戦慄を伴う発熱が出現したため、家族に付き添われて受診した。既往歴 : 高血圧症のため、自宅近くの診療所で投薬を受けている。胆石症のため、同じ診療所で年1回の腹部超音波検査を実施している。生活歴 : 60歳まで小学校の教諭をしていた。夫は5年前に死去し、現在は長男夫婦および中学生の孫と同居している。家族歴 : 父が胃癌、母が大腸癌。
現症 : 意識は清明。身長152cm、体重45kg。体温38.3°C。脈拍96/分、整。血圧114/72mmHg。呼吸数20/分。SpO295%(room air)。眼瞼結膜と眼球結膜とに異常を認めない。咽頭に異常を認めない。頸静脈の怒張を認めない。甲状腺腫を認めない。心音と呼吸音とに異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。左肋骨脊柱角に叩打痛を認める。四肢に浮腫を認めない。検査所見 : 尿所見:黄色で混濁、蛋白(±)、糖(−)、潜血1+、沈渣に赤血球を認めず、白血球100以上/HPF。血液所見:赤血球382万、Hb11.2g/dL、Ht33%、白血球10,100(桿状核好中球17%、分葉核好中球55%、好酸球2%、好塩基球0%、単球10%、リンパ球16%)、血小板15万。血液生化学所見:総蛋白7.5 g/dL、アルブミン3.2g/dL、総ビリルビン0.7mg/dL、AST19U/L、ALT9 U/L、LD220U/L(基準120〜245)、ALP336U/L(基準115〜359)、γ-GT36U/L(基準8〜50)、尿素窒素15mg/dL、クレアチニン0.8mg/dL、血糖120mg/dL、Na137mEq/L、K4.4mEq/L、Cl100mEq/L。CRP14mg/dL。
尿培養とともにさらに培養のために採取すべき検体はどれか。', '[{"key": "A", "text": "咽頭粘液"}, {"key": "B", "text": "血液"}, {"key": "C", "text": "脳脊髄液"}, {"key": "D", "text": "鼻腔ぬぐい液"}, {"key": "E", "text": "便"}]'::jsonb, 'B', '正答は B「血液」。

悪寒戦慄を伴う発熱は菌血症を強く示唆する。腎盂腎炎では起因菌が血流に入っていることが少なくないため、尿培養と同時に血液培養を2セット採取してから抗菌薬を開始する。起因菌と感受性が分かれば、狭域の薬へ切り替えられる。

出典：厚生労働省ホームページ 第114回医師国家試験 B046', '{"A": "咽頭に異常を認めず、咽頭粘液を培養する根拠がない。", "C": "意識は清明で髄膜刺激症状もなく、脳脊髄液の採取は適応がない。", "D": "鼻腔ぬぐい液はMRSAの保菌調査に用いるもので、この発熱の起因菌検索にはならない。", "E": "下痢や腹痛がなく、便培養の適応がない。"}'::jsonb, 'public', 'M', '114-B-46', '', 'pending', 'llm'),
('代謝・内分泌', '', 2, 'KOKUSHI', '22歳の男性。全身の脱力のため救急車で搬入された。現病歴 : 3か月前から運動時の動悸を自覚していた。1か月前にテニスをしたところ、翌日起床時にベッドから起き上がりづらく、4時間ほど休んでいたら元に戻った。昨日は特別な運動をしなかったが、焼き肉店で遅くまで友人と大量に飲食したのち、30分程度歩いて帰ったという。本日起床時ベッドから立ち上がろうとして力が入らず、次第に上肢にも力が入らなくなってきたため救急車を要請した。既往歴 : 特記すべきことはない。生活歴 : 大学生で実家暮らし。喫煙歴はない。飲酒は機会飲酒。家族歴 : 特記すべきことはない。現症 : 意識は清明。身長172cm、体重55kg。体温37.8°C。脈拍104/分、整。血圧96/44mmHg。呼吸数22/分。皮膚は著明に湿潤している。瞳孔と眼球運動とに異常を認めない。構音に異常はない。徒手筋力テストで近位筋優位の筋力低下を認める。四肢腱反射は低下しているが、左右差は認めない。筋萎縮は認めない。感覚系に異常は認めない。検査所見 : 尿所見:蛋白(−)、糖(−)、潜血(−)。血液所見:赤血球515万、Hb17.3g/dL、Ht48%、白血球5,900、血小板20万。血液生化学所見:総蛋白7.0g/dL、AST20U/L、ALT25U/L、CK120U/L(基準30〜140)、尿素窒素28 mg/dL、クレアチニン0.5mg/dL、血糖85mg/dL、Na139mEq/L、K2.4 mEq/L、Cl101mEq/L。
この病態の原因として最も考えられる臓器はどれか。', '[{"key": "A", "text": "胸腺"}, {"key": "B", "text": "膵臓"}, {"key": "C", "text": "副腎"}, {"key": "D", "text": "甲状腺"}, {"key": "E", "text": "副甲状腺"}]'::jsonb, 'D', '正答は D「甲状腺」。

大量の飲食後に生じた近位筋優位の弛緩性麻痺で、K 2.4mEq/Lの低カリウム血症を伴う。3か月前からの動悸、頻脈、発汗、微熱もあり、甲状腺中毒性周期性四肢麻痺と考える。甲状腺ホルモン過剰がNa-K ATPaseを亢進させ、糖質の負荷でカリウムが細胞内へ移動して麻痺が起こる。

出典：厚生労働省ホームページ 第114回医師国家試験 B047', '{"A": "胸腺は重症筋無力症で問題になるが、それでは低カリウム血症も腱反射の低下も説明できない。", "B": "膵臓のインスリノーマなら低血糖をきたすが、血糖は85mg/dLと保たれている。", "C": "原発性アルドステロン症でも低カリウム性の麻痺は起こるが、高血圧を伴うのが普通で、本例は96/44mmHgと低い。", "E": "副甲状腺の異常はカルシウム代謝の問題であり、低カリウム血症による麻痺は説明できない。"}'::jsonb, 'public', 'M', '114-B-47', '', 'pending', 'llm'),
('眼科', '', 2, 'KOKUSHI', '22歳の男性。全身の脱力のため救急車で搬入された。現病歴 : 3か月前から運動時の動悸を自覚していた。1か月前にテニスをしたところ、翌日起床時にベッドから起き上がりづらく、4時間ほど休んでいたら元に戻った。昨日は特別な運動をしなかったが、焼き肉店で遅くまで友人と大量に飲食したのち、30分程度歩いて帰ったという。本日起床時ベッドから立ち上がろうとして力が入らず、次第に上肢にも力が入らなくなってきたため救急車を要請した。既往歴 : 特記すべきことはない。生活歴 : 大学生で実家暮らし。喫煙歴はない。飲酒は機会飲酒。家族歴 : 特記すべきことはない。現症 : 意識は清明。身長172cm、体重55kg。体温37.8°C。脈拍104/分、整。血圧96/44mmHg。呼吸数22/分。皮膚は著明に湿潤している。瞳孔と眼球運動とに異常を認めない。構音に異常はない。徒手筋力テストで近位筋優位の筋力低下を認める。四肢腱反射は低下しているが、左右差は認めない。筋萎縮は認めない。感覚系に異常は認めない。検査所見 : 尿所見:蛋白(−)、糖(−)、潜血(−)。血液所見:赤血球515万、Hb17.3g/dL、Ht48%、白血球5,900、血小板20万。血液生化学所見:総蛋白7.0g/dL、AST20U/L、ALT25U/L、CK120U/L(基準30〜140)、尿素窒素28 mg/dL、クレアチニン0.5mg/dL、血糖85mg/dL、Na139mEq/L、K2.4 mEq/L、Cl101mEq/L。
SOAPでこの患者の診療記録を作成するとき、Aの項目として記載すべきなのはどれか。', '[{"key": "A", "text": "起立困難"}, {"key": "B", "text": "意識レベル"}, {"key": "C", "text": "考えられる病態"}, {"key": "D", "text": "行うべき検査の計画"}, {"key": "E", "text": "徒手筋力テストの結果"}]'::jsonb, 'C', '正答は C「考えられる病態」。

SOAPのAはAssessment、すなわち集めた情報から医師が何を考えたかを書く欄である。本例なら「低カリウム血症による周期性四肢麻痺、甲状腺機能亢進症を疑う」といった病態の評価がここに入る。

出典：厚生労働省ホームページ 第114回医師国家試験 B048', '{"A": "起立困難は患者本人の訴えなのでS（Subjective）に書く。", "B": "意識レベルは診察して得た所見なのでO（Objective）に書く。", "D": "行うべき検査の計画はP（Plan）に書く。", "E": "徒手筋力テストの結果も診察所見なのでOに書く。"}'::jsonb, 'public', 'M', '114-B-48', '', 'pending', 'llm'),
('免疫・膠原病', '', 2, 'KOKUSHI', '42歳の女性。倦怠感と関節痛を主訴に来院した。現病歴 : 半年前に全身の倦怠感と両手首の痛みを自覚した。その後、両肘にも痛みが出現し、物を握りにくくなったという。発熱や咽頭痛、咳、痰、体重減少、発熱および寝汗はない。既往歴 : 高血圧症で診療所に通院中。生活歴 : 喫煙歴と飲酒歴はない。夫と10歳の息子との3人暮らし。仕事は病院事務をしている。家族歴 : 兄が糖尿病。その他、特記すべきことはない。現症 : 意識は清明。身長153cm、体重49kg。体温36.0°C。脈拍88/分、整。血圧134/80mmHg。呼吸数18/分。SpO297%(room air)。皮疹を認めない。眼瞼結膜は貧血様で眼球結膜に黄染を認めない。咽頭に異常を認めない。甲状腺腫と頸部リンパ節を触知しない。心音と呼吸音とに異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。両側の肘、手関節、中手指節関節、近位指節間関節の圧痛と腫脹を認める。検査所見 : 血液所見:赤血球384万、Hb11.0g/dL、Ht33%、白血球6,200、血小板38万。血液生化学所見:総蛋白7.8g/dL、アルブミン3.3g/dL、総ビリルビン0.4mg/dL、AST11U/L、ALT8U/L、LD160U/L(基準120〜245)、CK 22U/L(基準30〜140)、尿素窒素10mg/dL、クレアチニン0.4mg/dL、Na143 mEq/L、K4.4mEq/L、Cl105mEq/L。CRP3.3mg/dL。
この患者が訴える症状はどれか。', '[{"key": "A", "text": "「爪が分厚くなりました」"}, {"key": "B", "text": "「午前中はペットボトルの蓋が開けられません」"}, {"key": "C", "text": "「手洗いすると中指と薬指の先が白くなります」"}, {"key": "D", "text": "「ペンで文字を書いているとだんだん字が小さくなります」"}, {"key": "E", "text": "「パソコンで長時間仕事をすると手首から指先までしびれます」"}]'::jsonb, 'B', '正答は B「「午前中はペットボトルの蓋が開けられません」」。

両側の手関節、中手指節関節、近位指節間関節の腫脹と圧痛が半年続く多関節炎で、関節リウマチを考える。朝のこわばりのために午前中は手が使いにくいという訴えが特徴的である。

出典：厚生労働省ホームページ 第114回医師国家試験 B049', '{"A": "爪の肥厚や点状陥凹は乾癬や乾癬性関節炎でみられる所見である。", "C": "水や寒冷で指先が白くなるのはRaynaud現象で、全身性強皮症や混合性結合組織病でみられる。", "D": "書字がだんだん小さくなる小字症は、Parkinson病の症状である。", "E": "作業で手首から指先がしびれるのは、手根管症候群などの末梢神経障害の訴えである。"}'::jsonb, 'public', 'M', '114-B-49', '', 'pending', 'llm'),
('免疫・膠原病', '', 2, 'KOKUSHI', '42歳の女性。倦怠感と関節痛を主訴に来院した。現病歴 : 半年前に全身の倦怠感と両手首の痛みを自覚した。その後、両肘にも痛みが出現し、物を握りにくくなったという。発熱や咽頭痛、咳、痰、体重減少、発熱および寝汗はない。既往歴 : 高血圧症で診療所に通院中。生活歴 : 喫煙歴と飲酒歴はない。夫と10歳の息子との3人暮らし。仕事は病院事務をしている。家族歴 : 兄が糖尿病。その他、特記すべきことはない。現症 : 意識は清明。身長153cm、体重49kg。体温36.0°C。脈拍88/分、整。血圧134/80mmHg。呼吸数18/分。SpO297%(room air)。皮疹を認めない。眼瞼結膜は貧血様で眼球結膜に黄染を認めない。咽頭に異常を認めない。甲状腺腫と頸部リンパ節を触知しない。心音と呼吸音とに異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。両側の肘、手関節、中手指節関節、近位指節間関節の圧痛と腫脹を認める。検査所見 : 血液所見:赤血球384万、Hb11.0g/dL、Ht33%、白血球6,200、血小板38万。血液生化学所見:総蛋白7.8g/dL、アルブミン3.3g/dL、総ビリルビン0.4mg/dL、AST11U/L、ALT8U/L、LD160U/L(基準120〜245)、CK 22U/L(基準30〜140)、尿素窒素10mg/dL、クレアチニン0.4mg/dL、Na143 mEq/L、K4.4mEq/L、Cl105mEq/L。CRP3.3mg/dL。
この患者を診断する上で最も特異度の高い検査はどれか。', '[{"key": "A", "text": "CRP"}, {"key": "B", "text": "抗核抗体"}, {"key": "C", "text": "血清IgG"}, {"key": "D", "text": "抗CCP抗体"}, {"key": "E", "text": "リウマトイド因子〈RF〉"}]'::jsonb, 'D', '正答は D「抗CCP抗体」。

関節リウマチの診断で最も特異度が高いのは抗CCP抗体で、特異度はおよそ90〜95%に達する。発症早期から陽性になり、関節破壊の進行を予測する指標にもなる。

出典：厚生労働省ホームページ 第114回医師国家試験 B050', '{"A": "CRPは炎症の強さを示すが、どの炎症でも上がり、診断の特異性はない。", "B": "抗核抗体はSLEをはじめ多くの膠原病で陽性になり、関節リウマチに特異的ではない。", "C": "血清IgGの増加は慢性炎症や多くの自己免疫疾患でみられ、特異性はない。", "E": "リウマトイド因子は感度は高いが、他の膠原病や慢性感染症、高齢者でも陽性になり、特異度は低い。"}'::jsonb, 'public', 'M', '114-B-50', '', 'pending', 'llm'),
('公衆衛生', '', 2, 'KOKUSHI', '小学校における保健指導により一次予防が期待される疾患はどれか。', '[{"key": "A", "text": "肥満症"}, {"key": "B", "text": "低身長症"}, {"key": "C", "text": "1型糖尿病"}, {"key": "D", "text": "甲状腺機能亢進症"}, {"key": "E", "text": "神経性食思〈欲〉不振症"}]'::jsonb, 'A', '正答は A「肥満症」。

小児の肥満の多くは食事と運動の習慣による単純性肥満で、学校での保健指導で生活習慣を整えれば発症そのものを防げる（一次予防）。成人後の生活習慣病の予防にもつながる。

出典：厚生労働省ホームページ 第114回医師国家試験 C019', '{"B": "低身長は成長ホルモン分泌不全や体質などによるもので、保健指導では予防できない。", "C": "1型糖尿病は自己免疫による膵β細胞の破壊で起こり、生活習慣の指導では予防できない。", "D": "甲状腺機能亢進症の多くはBasedow病という自己免疫疾患で、保健指導では予防できない。", "E": "保健指導は早期発見には役立つが、神経性食思不振症の発症を防ぐ確かな方法は確立していない。"}'::jsonb, 'public', 'M', '114-C-19', '', 'pending', 'llm'),
('血液', '', 2, 'KOKUSHI', 'プロトロンビン時間が延長するのはどれか。', '[{"key": "A", "text": "血友病"}, {"key": "B", "text": "血小板無力症"}, {"key": "C", "text": "ビタミンK欠乏症"}, {"key": "D", "text": "von Willebrand病"}, {"key": "E", "text": "IgA血管炎〈Schönlein-Henoch紫斑病〉"}]'::jsonb, 'C', '正答は C「ビタミンK欠乏症」。

プロトロンビン時間は外因系（第VII因子）と共通系の凝固因子を反映する。ビタミンKが欠乏すると第II・VII・IX・X因子が作られず、半減期の短い第VII因子から低下するので、まずPTが延長する。

出典：厚生労働省ホームページ 第114回医師国家試験 C021', '{"A": "血友病は第VIII因子または第IX因子の欠乏で内因系が障害され、APTTが延長してPTは正常である。", "B": "血小板無力症は血小板の凝集の異常で、PTやAPTTなどの凝固検査は正常である。", "D": "von Willebrand病では出血時間が延長し、第VIII因子の低下を伴えばAPTTも延長するが、PTは正常である。", "E": "IgA血管炎は血管炎による紫斑で、凝固検査も血小板数も正常である。"}'::jsonb, 'public', 'M', '114-C-21', '', 'pending', 'llm'),
('麻酔', '', 2, 'KOKUSHI', '循環は保たれているが、自発呼吸がみられない患者に緊急頭部CTを行う場合の呼吸管理として適切なのはどれか。', '[{"key": "A", "text": "酸素マスク"}, {"key": "B", "text": "経鼻エアウェイ挿入"}, {"key": "C", "text": "気管挿管による人工呼吸"}, {"key": "D", "text": "非侵襲的陽圧換気〈NPPV〉"}, {"key": "E", "text": "緊急気管切開による人工呼吸"}]'::jsonb, 'C', '正答は C「気管挿管による人工呼吸」。

自発呼吸がない患者では換気そのものを代行する必要がある。CT室への移動と撮影の間も確実に換気を続けるため、気管挿管で気道を確保して人工呼吸を行う。

出典：厚生労働省ホームページ 第114回医師国家試験 C023', '{"A": "酸素マスクは自発呼吸のある患者に酸素を足すもので、呼吸のない患者は換気できない。", "B": "経鼻エアウェイは舌根沈下による気道の閉塞を防ぐだけで、換気はできない。", "D": "NPPVは自発呼吸を補助する方法で、自発呼吸がない患者には使えない。", "E": "経口の気管挿管ができるのに、侵襲の大きい緊急気管切開を選ぶ理由はない。"}'::jsonb, 'public', 'M', '114-C-23', '', 'pending', 'llm'),
('小児科', '', 2, 'KOKUSHI', '9歳の男児。毎年学校で行われる体力測定において、有酸素運動能力の指標である往復持久走(20mシャトルラン)の折り返し数が7歳時をピークに低下していることが学校医に報告された。6歳:20回【19.2】、7歳:26回【28.6】、8歳:24回【38.5】、9歳:19回【48.0】(【 】内は全国平均回数)。身長の伸びはよく、体重の減少もない。本人に確認したところ毎年全力で走っているとのことである。学校医として適切な対応はどれか。', '[{"key": "A", "text": "運動指導を行う。"}, {"key": "B", "text": "栄養指導を行う。"}, {"key": "C", "text": "体育実技を見学させる。"}, {"key": "D", "text": "医療機関への受診を促す。"}, {"key": "E", "text": "10歳時の体力測定の結果を待って対応を判断する。"}]'::jsonb, 'D', '正答は D「医療機関への受診を促す。」。

全力で走っているのに持久走の回数が年々減っており、成長とともに伸びるはずの持久力が落ちている。心筋症や不整脈などの心疾患、筋疾患、貧血などが隠れている可能性があり、医療機関での精査を勧める。

出典：厚生労働省ホームページ 第114回医師国家試験 C040', '{"A": "努力不足ではなく持久力そのものが落ちており、原因を調べる前に運動を課すのは危険である。", "B": "身長は伸び、体重も減っておらず、栄養の問題ではない。", "C": "原因がわからないまま運動を制限するより、まず受診させて原因を明らかにする。", "E": "3年続けて低下しており、さらに1年待つ理由はない。心疾患であれば突然死の危険もある。"}'::jsonb, 'public', 'M', '114-C-40', '', 'pending', 'llm'),
('小児科', '', 2, 'KOKUSHI', '2歳の男児。生来健康であったが、発熱を主訴に母親に連れられて来院した。診察時に母親が離れても泣しない。体温38.2°C。心拍数110/分、整。血圧98/62 mmHg。呼吸数30/分。SpO298%(room air)。毛細血管再充満時間は2秒以内。自発的に開眼しており光をまぶしがるが、視線が合わず追視をしない。この患児に疑われるのはどれか。', '[{"key": "A", "text": "頻拍"}, {"key": "B", "text": "低血圧"}, {"key": "C", "text": "意識障害"}, {"key": "D", "text": "呼吸不全"}, {"key": "E", "text": "末梢循環障害"}]'::jsonb, 'C', '正答は C「意識障害」。

発熱のある2歳児が、母親が離れても泣かず、目を開けていても視線が合わず追視もしない。周囲への反応の乏しさは小児の意識障害の徴候で、髄膜炎や脳症などを疑って急いで評価する。呼吸と循環の指標はいずれも正常範囲である。

出典：厚生労働省ホームページ 第114回医師国家試験 C044', '{"A": "2歳児の心拍数110/分は正常範囲である。", "B": "血圧98/62mmHgは2歳児として正常である。", "D": "呼吸数30/分は2歳児の正常範囲で、SpO2も98%に保たれている。", "E": "毛細血管再充満時間は2秒以内で、末梢循環は保たれている。"}'::jsonb, 'public', 'M', '114-C-44', '', 'pending', 'llm'),
('産科', '', 2, 'KOKUSHI', '32歳の経産婦(2妊1産)。妊娠12週。出生前診断について相談するため、遺伝カウンセリング外来に夫婦で来院した。これまでの妊娠経過に異常を認めない。28歳の時に出産した子供がDown症候群であった。無侵襲的出生前遺伝学的検査〈NIPT〉について知りたいという。説明として適切なのはどれか。', '[{"key": "A", "text": "「羊水を使って検査を行います」"}, {"key": "B", "text": "「検査のために流産する確率は0.3%です」"}, {"key": "C", "text": "「検査で先天性疾患の80%が診断できます」"}, {"key": "D", "text": "「検査の結果が陽性であっても確定診断にはなりません」"}, {"key": "E", "text": "「妊娠16週以降にならないと検査することができません」"}]'::jsonb, 'D', '正答は D「「検査の結果が陽性であっても確定診断にはなりません」」。

NIPTは母体血中の胎児由来のDNAを調べる非確定的検査で、21・18・13トリソミーの可能性を推定する。陽性でも偽陽性があるため、確定には羊水検査や絨毛検査が必要である。

出典：厚生労働省ホームページ 第114回医師国家試験 C046', '{"A": "NIPTは母体からの採血で行う検査で、羊水は用いない。", "B": "採血だけなので流産の危険はない。0.3%前後の流産率は羊水検査の説明である。", "C": "調べるのは主に3つの染色体の数の異常で、先天性疾患全体のごく一部しかわからない。", "E": "NIPTは妊娠10週前後から受けられる。15〜16週以降に行うのは羊水検査である。"}'::jsonb, 'public', 'M', '114-C-46', '', 'pending', 'llm'),
('公衆衛生', '', 2, 'KOKUSHI', '35歳の初妊婦(1妊0産)。妊娠33週6日。妊婦健康診査のため来院した。これまでの妊娠経過に異常を認めていなかった。脈拍96/分、整。血圧126/68mmHg。尿所見:蛋白(−)、糖(−)。子宮底長29cm、腹囲94cm。内診で子宮口は閉鎖している。胎児推定体重2,120g、羊水指数〈AFI〉18cm。胎盤は子宮底部に位置している。職業は事務職である。明日から休業を申請するという。この妊婦の休業を規定する法律はどれか。', '[{"key": "A", "text": "健康増進法"}, {"key": "B", "text": "母子保健法"}, {"key": "C", "text": "母体保護法"}, {"key": "D", "text": "労働基準法"}, {"key": "E", "text": "次世代育成支援対策推進法"}]'::jsonb, 'D', '正答は D「労働基準法」。

産前休業は労働基準法に定められ、出産予定日の6週間前（多胎妊娠では14週間前）から本人の請求により取得できる。妊娠33週6日の翌日は34週0日で、ちょうど産前6週に入る。産後8週間の休業も同じ法律による。

出典：厚生労働省ホームページ 第114回医師国家試験 C051', '{"A": "健康増進法は国民の健康づくりや受動喫煙の防止を定める法律で、休業は扱わない。", "B": "母子保健法は妊娠の届出、母子健康手帳、妊婦健康診査などを定めるが、休業は定めない。", "C": "母体保護法は人工妊娠中絶や不妊手術について定める法律である。", "E": "次世代育成支援対策推進法は企業などに子育て支援の行動計画をつくらせる法律で、産前休業は定めない。"}'::jsonb, 'public', 'M', '114-C-51', '', 'pending', 'llm'),
('救急・中毒', '', 2, 'KOKUSHI', '23歳の男性。自宅で倒れているのを発見され救急車で搬入された。現病歴 : 徹夜でゲームをしており、昨夜から母親の制止を聞かずに市販のカフェイン含有飲料を多量に飲用していた。摂取カフェイン総量は2,500mg以上と推定された。今朝、自宅で倒れているのを母親が発見し救急車を要請した。既往歴 : 特記すべきことはない。生活歴 : 家族と同居、一日中家にいて、外出することは少ない。3年前に退職後は定職についていない。家族歴 : 特記すべきことはない。現症 : 呼びかけにより開眼、「アー」と発語はあるが問いかけには答えられない。痛み刺激に対して手で払いのける。体温38.2°C。心拍数148/分、整。血圧98/70mmHg。呼吸数30/分。SpO297%(マスク5L/分酸素投与下)。瞳孔径5mmで左右差を認めない。口腔内に吐物を認める。運動麻痺を認めない。腱反射の異常を認めない。心音に異常を認めない。両胸部にcoarse cracklesを聴取する。多量の尿失禁を認める。検査所見 : 血液所見:赤血球459万、Hb15.1g/dL、Ht44%、白血球11,400、血小板25万。血液生化学所見:AST28U/L、ALT24U/L、CK624U/L(基準30〜140)、尿素窒素40mg/dL、クレアチニン0.9mg/dL、血糖112mg/dL、Na 142mEq/L、K3.8mEq/L、Cl96mEq/L。CRP2.4mg/dL。
最初に行う輸液の組成として最も適切なのはどれか。', '[{"key": "A", "text": "5%ブドウ糖液"}, {"key": "B", "text": "Na+35mEq/L、K+20mEq/L、Cl−35mEq/L"}, {"key": "C", "text": "Na+154mEq/L、濃グリセリン、フルクトース配合液"}, {"key": "D", "text": "Na+30mEq/L、K+0mEq/L、Cl−20mEq/L、L-Lactate−10mEq/L"}, {"key": "E", "text": "Na+130mEq/L、K+4mEq/L、Cl−109mEq/L、L-Lactate−28mEq/L"}]'::jsonb, 'E', '正答は E「Na+130mEq/L、K+4mEq/L、Cl−109mEq/L、L-Lactate−28mEq/L」。

大量のカフェインで頻脈、発熱、嘔吐、多尿が起こり、尿素窒素の上昇から脱水がある。循環血液量を補うため、まず細胞外液に近い組成の輸液（乳酸リンゲル液）を投与する。

出典：厚生労働省ホームページ 第114回医師国家試験 C063', '{"A": "ブドウ糖液は代謝されて自由水になり、多くが細胞内に移るため、循環血液量を保てない。", "B": "維持輸液（3号液）の組成で、脱水の初期治療には向かない。", "C": "濃グリセリン・果糖液は脳浮腫に用いる浸透圧利尿薬で、利尿で脱水を悪化させる。", "D": "カリウムを含まない低張液（4号液）で、水分の多くが細胞内に移り、脱水の初期治療には向かない。"}'::jsonb, 'public', 'M', '114-C-63', '', 'pending', 'llm'),
('救急・中毒', '', 2, 'KOKUSHI', '23歳の男性。自宅で倒れているのを発見され救急車で搬入された。現病歴 : 徹夜でゲームをしており、昨夜から母親の制止を聞かずに市販のカフェイン含有飲料を多量に飲用していた。摂取カフェイン総量は2,500mg以上と推定された。今朝、自宅で倒れているのを母親が発見し救急車を要請した。既往歴 : 特記すべきことはない。生活歴 : 家族と同居、一日中家にいて、外出することは少ない。3年前に退職後は定職についていない。家族歴 : 特記すべきことはない。現症 : 呼びかけにより開眼、「アー」と発語はあるが問いかけには答えられない。痛み刺激に対して手で払いのける。体温38.2°C。心拍数148/分、整。血圧98/70mmHg。呼吸数30/分。SpO297%(マスク5L/分酸素投与下)。瞳孔径5mmで左右差を認めない。口腔内に吐物を認める。運動麻痺を認めない。腱反射の異常を認めない。心音に異常を認めない。両胸部にcoarse cracklesを聴取する。多量の尿失禁を認める。検査所見 : 血液所見:赤血球459万、Hb15.1g/dL、Ht44%、白血球11,400、血小板25万。血液生化学所見:AST28U/L、ALT24U/L、CK624U/L(基準30〜140)、尿素窒素40mg/dL、クレアチニン0.9mg/dL、血糖112mg/dL、Na 142mEq/L、K3.8mEq/L、Cl96mEq/L。CRP2.4mg/dL。
静脈路確保の次に行うべき対応はどれか。', '[{"key": "A", "text": "胃洗浄"}, {"key": "B", "text": "気管挿管"}, {"key": "C", "text": "血液透析"}, {"key": "D", "text": "血液濾過"}, {"key": "E", "text": "活性炭投与"}]'::jsonb, 'B', '正答は B「気管挿管」。

意識障害があり、口腔内に吐物が残り、両側でcoarse cracklesを聴取して誤嚥が疑われる。嘔吐を繰り返すカフェイン中毒で自分で気道を守れない状態なので、静脈路の次に気管挿管で気道を確保する。

出典：厚生労働省ホームページ 第114回医師国家試験 C064', '{"A": "摂取から時間が経っており、意識障害のある患者に気道を確保しないまま胃洗浄を行うと誤嚥を悪化させる。", "C": "カフェインは血液透析で除去できるが、まず気道を確保してから、重症度を見て検討する。", "D": "カフェインの除去には血液透析のほうが効率がよく、いま優先すべきは気道の確保である。", "E": "活性炭の投与も、意識障害と嘔吐のある患者では気道を確保してからでないと誤嚥の危険がある。"}'::jsonb, 'public', 'M', '114-C-64', '', 'pending', 'llm'),
('救急・中毒', '', 2, 'KOKUSHI', '23歳の男性。自宅で倒れているのを発見され救急車で搬入された。現病歴 : 徹夜でゲームをしており、昨夜から母親の制止を聞かずに市販のカフェイン含有飲料を多量に飲用していた。摂取カフェイン総量は2,500mg以上と推定された。今朝、自宅で倒れているのを母親が発見し救急車を要請した。既往歴 : 特記すべきことはない。生活歴 : 家族と同居、一日中家にいて、外出することは少ない。3年前に退職後は定職についていない。家族歴 : 特記すべきことはない。現症 : 呼びかけにより開眼、「アー」と発語はあるが問いかけには答えられない。痛み刺激に対して手で払いのける。体温38.2°C。心拍数148/分、整。血圧98/70mmHg。呼吸数30/分。SpO297%(マスク5L/分酸素投与下)。瞳孔径5mmで左右差を認めない。口腔内に吐物を認める。運動麻痺を認めない。腱反射の異常を認めない。心音に異常を認めない。両胸部にcoarse cracklesを聴取する。多量の尿失禁を認める。検査所見 : 血液所見:赤血球459万、Hb15.1g/dL、Ht44%、白血球11,400、血小板25万。血液生化学所見:AST28U/L、ALT24U/L、CK624U/L(基準30〜140)、尿素窒素40mg/dL、クレアチニン0.9mg/dL、血糖112mg/dL、Na 142mEq/L、K3.8mEq/L、Cl96mEq/L。CRP2.4mg/dL。
救急外来での処置後に集中治療室においてエコー下で右内頸静脈から中心静脈カテーテルを留置する方針となった。局所麻酔後にカテーテル留置のための穿刺を行ったところ鮮紅色の血液の逆流を認めた。穿刺針を抜去したところ同部位が急速に腫脹し始めた。血圧92/60mmHg。心拍数130/分、整。直ちに行うべきなのはどれか。', '[{"key": "A", "text": "赤血球輸血"}, {"key": "B", "text": "昇圧薬の投与"}, {"key": "C", "text": "局所の圧迫止血"}, {"key": "D", "text": "逆流した血液の血液ガス分析"}, {"key": "E", "text": "反対側でのカテーテル挿入手技の継続"}]'::jsonb, 'C', '正答は C「局所の圧迫止血」。

鮮紅色の血液の逆流と、抜針後に急速に腫れてきた経過から、総頸動脈を誤って穿刺し血腫ができている。まず穿刺部位を圧迫して止血する。血腫が大きくなると気道を圧迫するので、その後も頸部の腫れと呼吸を観察する。

出典：厚生労働省ホームページ 第114回医師国家試験 C065', '{"A": "血圧は保たれており、まず出血部位を圧迫して止めることが先である。", "B": "血圧の低下は軽く、出血を止めないまま昇圧薬を使うのは誤りである。", "D": "逆流の色と勢いで動脈の穿刺はほぼ確かで、確かめるために止血を遅らせてはならない。", "E": "両側の頸部に血腫ができると気道閉塞の危険がある。止血を優先し、手技はいったん中止する。"}'::jsonb, 'public', 'M', '114-C-65', '', 'pending', 'llm'),
('整形外科', '', 2, 'KOKUSHI', '76歳の女性。全身倦怠感と食欲不振を主訴に来院した。現病歴 : 65歳時に高血圧症および骨粗鬆症と診断され、かかりつけ医にて内服加療を受けていた。2か月前から変形性膝関節症の治療を受けていたが、立位や歩行時の痛みが強く、ベッド上で過ごすことが増えていた。1週前から食欲が徐々に低下していた。3日前から全身倦怠感の訴えがあり、ベッド上からほぼ動かなくなった。同居していた家族が心配し、付き添われて受診した。既往歴 : 74歳時に脳梗塞を発症。生活歴 : 左上下肢の不全麻痺としびれ感が残っており、杖歩行であるが身の回りのことは1人でできていた。喫煙歴と飲酒歴はない。家族歴 : 父親が68歳時に肺癌で死亡。現症 : 意識は清明。身長155cm、体重41kg。体温36.2°C。脈拍104/分、整。血圧86/54mmHg。呼吸数16/分。SpO297%(room air)。眼瞼はくぼんでいる。眼瞼結膜は貧血を認めない。口腔粘膜は乾燥している。頸静脈は虚脱している。心音と呼吸音とに異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。下腿に浮腫を認めない。左上下肢に麻痺を認める。検査所見 : 尿所見:蛋白(−)、潜血(−)、糖(−)。血液所見:赤血球396万、Hb12.1g/dL、Ht39%、白血球8,600、血小板25万。血液生化学所見:総蛋白6.2g/dL、アルブミン3.1g/dL、AST34U/L、ALT12U/L、LD221U/L(基準120〜245)、ALP352U/L(基準115〜359)、CK38U/L(基準30〜140)、尿素窒素52mg/dL、クレアチニン2.2mg/dL、血糖104mg/dL、Na142mEq/L、K4.4 mEq/L、Cl108mEq/L、Ca12.4mg/dL、P3.6mg/dL。CRP0.2mg/dL。改訂長谷川式簡易知能評価スケールは26点(30点満点)。
この患者で退院後の転倒・骨折リスクを低下させるために有用なのはどれか。', '[{"key": "A", "text": "外出の制限"}, {"key": "B", "text": "軽い運動の励行"}, {"key": "C", "text": "体重減量の励行"}, {"key": "D", "text": "塩分摂取量の増加"}, {"key": "E", "text": "リン摂取量の増加"}]'::jsonb, 'B', '正答は B「軽い運動の励行」。

転倒と骨折を防ぐには、筋力とバランスを保つ運動を続けることが有効である。臥床が続くと骨からカルシウムが溶け出して骨量が減り、高カルシウム血症も悪化するので、痛みに配慮しながら軽い運動を促す。

出典：厚生労働省ホームページ 第114回医師国家試験 C074', '{"A": "外出を控えると活動量と筋力が落ち、かえって転倒しやすくなる。", "C": "BMIは約17でやせており、減量は筋肉量をさらに減らして転倒の危険を高める。", "D": "塩分を増やしても転倒や骨折の予防にはならず、高血圧を悪化させる。", "E": "リンを多くとっても骨折の予防にはならず、腎機能の低下した患者では高リン血症を招く。"}'::jsonb, 'public', 'M', '114-C-74', '', 'pending', 'llm'),
('眼科', '', 2, 'KOKUSHI', '乳幼児揺さぶられ症候群〈Shaken Baby Syndrome〉を疑った場合、確認すべき眼所見はどれか。', '[{"key": "A", "text": "眼瞼炎"}, {"key": "B", "text": "白内障"}, {"key": "C", "text": "緑内障"}, {"key": "D", "text": "角膜白斑"}, {"key": "E", "text": "網膜出血"}]'::jsonb, 'E', '正答は E「網膜出血」。

乳幼児揺さぶられ症候群では、硬膜下血腫や脳浮腫とともに、多発性の網膜出血が特徴的である。虐待を疑ったら眼底検査で網膜出血の有無と広がりを確かめる。

出典：厚生労働省ホームページ 第114回医師国家試験 D003', '{"A": "眼瞼炎は細菌感染や脂漏などによる眼瞼の炎症で、揺さぶりとは関係しない。", "B": "白内障は先天性や加齢などによるもので、揺さぶりで急に生じる所見ではない。", "C": "緑内障は眼圧の上昇などによる視神経の障害で、揺さぶりの所見ではない。", "D": "角膜白斑は角膜の炎症や外傷の瘢痕で、揺さぶりに特徴的な所見ではない。"}'::jsonb, 'public', 'M', '114-D-3', '', 'pending', 'llm'),
('腎臓', '', 2, 'KOKUSHI', '68歳の男性。全身倦怠感と体重減少を主訴に来院した。6か月前から5kgの体重減少と2か月前からの全身倦怠感が著明になったため受診した。身長164cm、体重44kg。脈拍72/分、整。血圧104/70mmHg。意識は清明。眼瞼結膜は貧血様である。心音と呼吸音とに異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。両下肢に浮腫を認める。尿所見:蛋白3+、糖(−)、潜血1+、沈渣は赤血球5〜9/HPF。随時尿の尿蛋白/Cr比は4.6g/gCr(基準0.15未満)。血液所見:赤血球300万、Hb10.7g/dL、Ht31%、白血球7,800、血小板28万。血液生化学所見:総蛋白5.5g/dL、アルブミン3.1g/dL、IgG764mg/dL(基準960〜1,960)、IgA100mg/dL (基準110〜410)、IgM42mg/dL (基準65〜350)、尿素窒素23 mg/dL、クレアチニン1.6mg/dL、HbA1c5.6%(基準4.6〜6.2)、総コレステロール200mg/dL、免疫血清学所見:MPO-ANCA陰性、PR3-ANCA陰性、抗核抗体陰性。尿免疫電気泳動でM蛋白を認める。血清遊離軽鎖κ/λ比0.01(基準0.26〜1.65)。心電図は低電位である。腹部超音波検査で腎の腫大が認められる。心エコー検査で軽度の左室壁肥厚を認める。腎病変の原因として、考えられるのはどれか。', '[{"key": "A", "text": "糖尿病腎症"}, {"key": "B", "text": "ループス腎炎"}, {"key": "C", "text": "アミロイド腎症"}, {"key": "D", "text": "慢性間質性腎炎"}, {"key": "E", "text": "ANCA関連腎炎"}]'::jsonb, 'C', '正答は C「アミロイド腎症」。

尿免疫電気泳動でM蛋白を認め、遊離軽鎖のκ/λ比が著しく低いλ型の単クローン性の異常がある。ネフローゼ症候群に、心電図の低電位、左室壁の肥厚、腎の腫大を伴っており、ALアミロイドーシスによる腎症と考える。

出典：厚生労働省ホームページ 第114回医師国家試験 D021', '{"A": "HbA1cは正常で糖尿病はなく、糖尿病腎症は考えにくい。", "B": "抗核抗体が陰性で、SLEを示す症状もない。", "D": "慢性間質性腎炎では高度の蛋白尿は出にくく、腎はむしろ萎縮する。", "E": "MPO-ANCAもPR3-ANCAも陰性である。"}'::jsonb, 'public', 'M', '114-D-21', '', 'pending', 'llm'),
('循環器', '', 2, 'KOKUSHI', '20歳の男性。高身長および長い手指を指摘されて受診した。1週前に感冒様症状があり自宅近くの診療所を受診した際に、高身長や長い手指を指摘され、専門の医療機関を受診するよう勧められた。中学時からバレーボール部の選手として活躍している。喫煙歴および飲酒歴はない。父親が34歳で突然死している。15歳の妹も高身長である。意識は清明。身長190cm、体重75kg。脈拍80/分、整。血圧132/72mmHg。手足は長く、クモ状手指を認める。胸骨左縁第3肋間を最強点とするII/VIの拡張期雑音を聴取する。呼吸音に異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。血液所見:赤血球424万、Hb13.5g/dL、白血球6,800、血小板18万。血液生化学所見:総蛋白7.0g/dL、アルブミン4.3g/dL、AST21 U/L、ALT21U/L、尿素窒素13mg/dL、クレアチニン0.6mg/dL。心エコー検査で大動脈基部径の軽度の拡大と大動脈弁逆流とを認める。左室駆出率は60%。胸腹部造影CTでは、大動脈基部の拡大以外の異常所見を認めない。眼科受診で水晶体亜脱臼を認めた。この患者への説明として適切なのはどれか。', '[{"key": "A", "text": "「内分泌異常が原因となる疾患です」"}, {"key": "B", "text": "「競技スポーツ参加を制限する必要はありません」"}, {"key": "C", "text": "「今後、大血管病変が進行する可能性もあります」"}, {"key": "D", "text": "「高身長の妹が同じ疾患に罹患している可能性はありません」"}, {"key": "E", "text": "「アンジオテンシン変換酵素〈ACE〉阻害薬の内服は禁忌です」"}]'::jsonb, 'C', '正答は C「「今後、大血管病変が進行する可能性もあります」」。

高身長、クモ状指、水晶体亜脱臼、大動脈基部の拡大に、父親の若年での突然死が加わりMarfan症候群である。フィブリリン1の遺伝子異常による結合組織の疾患で、大動脈基部の拡大は進行して大動脈解離や破裂を起こしうるため、定期的に画像で経過をみる。

出典：厚生労働省ホームページ 第114回医師国家試験 D034', '{"A": "Marfan症候群はフィブリリン1の遺伝子異常による疾患で、内分泌の異常が原因ではない。", "B": "大動脈基部が拡大しており、激しい運動や接触を伴う競技は大動脈解離の危険があるので制限する。", "D": "常染色体顕性（優性）遺伝で、高身長の妹も罹患している可能性があり、診察を勧める。", "E": "大動脈の拡大を抑えるためにβ遮断薬やARBを用いる。ACE阻害薬が禁忌ということはない。"}'::jsonb, 'public', 'M', '114-D-34', '', 'pending', 'llm'),
('消化管', '', 2, 'KOKUSHI', '50歳の男性。右下腹部痛を主訴に転院してきた。船上勤務中、7日前に右下腹部痛と発熱をきたし寄港先の病院を受診した。急性虫垂炎と診断され入院となった。絶食下で末梢静脈からの輸液と抗菌薬の点滴治療を受け、入院3日目には解熱し下腹部痛は軽減した。自宅近くでの治療を希望し当院を紹介され転院となった。意識は清明。身長173cm、体重70kg。体温36.2°C。腹部は平坦、軟で、圧痛を認めない。腸雑音は正常である。血液所見:赤血球486万、Hb14.8g/dL、Ht43%、白血球6,400、血小板21万。血液生化学所見:総蛋白6.4g/dL、アルブミン3.2g/dL、総ビリルビン0.7mg/dL、AST14U/L、ALT14U/L、尿素窒素19 mg/dL、クレアチニン0.8mg/dL。CRP0.8mg/dL。転院後、排ガスと排便を認めた。次に行うべきなのはどれか。', '[{"key": "A", "text": "経口食開始"}, {"key": "B", "text": "虫垂切除術"}, {"key": "C", "text": "右半結腸切除術"}, {"key": "D", "text": "膿瘍ドレナージ"}, {"key": "E", "text": "外科的イレウス解除術"}]'::jsonb, 'A', '正答は A「経口食開始」。

急性虫垂炎を抗菌薬で保存的に治療し、解熱して腹痛と圧痛が消え、炎症反応も下がり、排ガスと排便もみられる。腸管の働きが戻っているので経口摂取を再開する。膿瘍などが残っていなければ手術を急ぐ必要はない。

出典：厚生労働省ホームページ 第114回医師国家試験 D045', '{"B": "保存的治療で軽快しており、いま手術をする理由はない。再発予防の待機的な手術はあとで検討する。", "C": "悪性腫瘍を疑う所見はなく、右半結腸切除の適応はない。", "D": "圧痛も発熱もなく、膿瘍を疑う所見はない。", "E": "排ガスと排便があり、腸閉塞はない。"}'::jsonb, 'public', 'M', '114-D-45', '', 'pending', 'llm'),
('消化管', '', 2, 'KOKUSHI', '74歳の女性。嚥下困難を主訴に来院した。6か月前から時々胸のつかえ感を自覚していた。3か月前に行った上部消化管内視鏡検査で逆流性食道炎を認め内服薬を処方された。その後も症状は持続し、2週前から食事摂取が困難となったため再度受診した。橋本病、高血圧症、骨粗鬆症および不眠症があり内服加療中である。身長156cm、体重45kg。脈拍76/分、整。血圧140/86mmHg。眼瞼結膜と眼球結膜とに異常を認めない。心音と呼吸音とに異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。服用している薬剤のうち、休薬によって症状の改善が見込まれるのはどれか。', '[{"key": "A", "text": "甲状腺ホルモン"}, {"key": "B", "text": "プロトンポンプ阻害薬"}, {"key": "C", "text": "経口ビスホスホネート製剤"}, {"key": "D", "text": "ベンゾジアゼピン系睡眠薬"}, {"key": "E", "text": "アンジオテンシン変換酵素〈ACE〉阻害薬"}]'::jsonb, 'C', '正答は C「経口ビスホスホネート製剤」。

経口ビスホスホネート製剤は食道の粘膜を傷つけ、食道炎や食道潰瘍の原因になる。起床時にコップ1杯の水で飲み、服用後30分は横にならない決まりがあり、守られないと起こりやすい。逆流性食道炎の治療を受けても続くつかえ感は、休薬で改善が見込める。

出典：厚生労働省ホームページ 第114回医師国家試験 D050', '{"A": "橋本病による甲状腺機能低下症の補充で、嚥下困難の原因にはならない。休薬すると機能低下が悪化する。", "B": "逆流性食道炎の治療薬で、やめると食道炎が悪化する。", "D": "ふらつきや転倒の原因にはなるが、食道の粘膜を傷つける薬ではない。", "E": "ACE阻害薬の副作用は空咳や血管性浮腫で、嚥下困難の原因にはならない。"}'::jsonb, 'public', 'M', '114-D-50', '', 'pending', 'llm'),
('血液', '', 2, 'KOKUSHI', '70歳の女性。発熱と頸部のしこりを主訴に来院した。8年前に関節リウマチと診断されプレドニゾロン、メトトレキサート及びNSAIDによる治療を継続している。1週前から誘因なく発熱が持続するため受診した。身長155cm、体重43kg。体温38.4°C。脈拍104/分、整。血圧120/80mmHg。呼吸数20/分。口蓋扁桃の腫大を認めない。両頸部と両腋窩に径2cmの圧痛を伴わないリンパ節を1個ずつ触知する。心音と呼吸音とに異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。関節に腫脹と圧痛とを認めない。血液所見:赤血球315万、Hb10.2g/dL、Ht32%、白血球2,800(桿状核好中球36%、分葉核好中球44%、好酸球2%、好塩基球1%、単球8%、リンパ球9%)、血小板12万。血液生化学所見:総蛋白6.6g/dL、アルブミン3.3g/dL、AST35U/L、ALT23U/L、LD780U/L(基準120〜245)。免疫血清学所見:CRP2.2mg/dL、抗核抗体陰性、可溶性IL-2受容体952U/mL(基準157〜474)、結核菌特異的全血インターフェロンγ遊離測定法〈IGRA〉陰性。造影CTで縦隔・腸間膜に多発性のリンパ節腫大を認める。まず行うべき対応はどれか。', '[{"key": "A", "text": "NSAIDの中止"}, {"key": "B", "text": "JAK阻害薬の追加"}, {"key": "C", "text": "抗TNF-α抗体の追加"}, {"key": "D", "text": "プレドニゾロンの中止"}, {"key": "E", "text": "メトトレキサートの中止"}]'::jsonb, 'E', '正答は E「メトトレキサートの中止」。

メトトレキサートで治療中の関節リウマチ患者に、発熱、多発リンパ節腫大、LDと可溶性IL-2受容体の上昇がみられ、メトトレキサート関連リンパ増殖性疾患を考える。まずメトトレキサートを中止する。中止だけで縮小する例が多く、改善しなければ生検をして化学療法を検討する。

出典：厚生労働省ホームページ 第114回医師国家試験 D051', '{"A": "NSAIDはリンパ増殖性疾患の原因にならず、やめても改善は見込めない。", "B": "免疫抑制を強めると、リンパ増殖性疾患を悪化させうる。", "C": "免疫抑制を強めることは避けるべきで、関節炎も落ち着いている。", "D": "長く使っている副腎皮質ステロイドを急にやめると副腎不全を起こす。原因として疑うのはメトトレキサートである。"}'::jsonb, 'public', 'M', '114-D-51', '', 'pending', 'llm'),
('肝・胆・膵', '', 2, 'KOKUSHI', '80歳の女性。右上腹部痛、体重減少および皮膚の黄染を主訴に来院した。1年前から食後に軽度の悪心を自覚していた。3か月前から食後に右上腹部痛が出現するため好物の天ぷらを食べたくなくなったという。1か月前から体重が減少し、家族に皮膚の黄染を指摘され受診した。身長145cm、体重38kg。体温36.7°C。脈拍92/分、整。血圧114/70mmHg。呼吸数14/分。眼瞼結膜は軽度貧血様で、眼球結膜に黄染を認める。心音と呼吸音とに異常を認めない。腹部は平坦で、心窩部から右季肋部にかけて圧痛を認め、同部に呼吸に応じて移動する径3cmの腫瘤を触知する。尿所見:蛋白(−)、糖(−)、ウロビリノゲン(−)、潜血(−)、ビリルビン1+。便潜血反応陰性。血液所見:赤血球354万、Hb10.9g/dL、Ht34%、白血球6,700、血小板14万。血液生化学所見:総蛋白5.8g/dL、アルブミン3.1 g/dL、総ビリルビン4.8mg/dL、AST76U/L、ALT65U/L、LD759U/L(基準120〜245)、γ-GT145U/L(基準8〜50)、アミラーゼ134U/L(基準37〜160)、尿素窒素19mg/dL、クレアチニン0.7mg/dL、血糖118mg/dL、Na138mEq/L、K4.0mEq/L、Cl100mEq/L、CEA6.7ng/mL(基準5以下)、CA19-989U/mL(基準37以下)。CRP0.4mg/dL。胸部および腹部エックス線写真で異常を認めない。腹部超音波検査で両側肝内胆管の拡張と肝門部での途絶を認めた。次に行うべき検査として適切なのはどれか。', '[{"key": "A", "text": "腹部造影CT"}, {"key": "B", "text": "超音波内視鏡検査"}, {"key": "C", "text": "下部消化管内視鏡検査"}, {"key": "D", "text": "上部消化管内視鏡検査"}, {"key": "E", "text": "内視鏡的逆行性胆管膵管造影〈ERCP〉"}]'::jsonb, 'A', '正答は A「腹部造影CT」。

閉塞性黄疸で、超音波では両側の肝内胆管が拡張して肝門部で途絶し、腫瘍マーカーも高い。胆嚢癌や肝門部胆管癌を考える。胆道に処置を加える前に、造影CTで腫瘍の広がり、血管への浸潤、転移を評価し、ドレナージや手術の計画を立てる。

出典：厚生労働省ホームページ 第114回医師国家試験 D052', '{"B": "胆道や膵の病変を詳しくみるのに使うが、肝門部の病変の広がりと遠隔転移をまず全体として把握するのは造影CTである。", "C": "便潜血は陰性で、黄疸の原因の検索には役立たない。", "D": "胃や十二指腸の病変を探す検査で、肝門部の胆管閉塞は評価できない。", "E": "胆道ドレナージには必要になるが、先に造影CTで病変の範囲を確かめる。先に胆管を造影すると胆管炎を招き、画像の評価も難しくなる。"}'::jsonb, 'public', 'M', '114-D-52', '', 'pending', 'llm'),
('泌尿器', '', 2, 'KOKUSHI', '72歳の男性。下腹部痛を主訴に来院した。現病歴 : 10年前から高血圧症で通院中であり、降圧薬による内服療法を受けている。1か月前から動悸を伴う心房細動が出現し、抗不整脈薬と抗凝固薬の処方も受けていた。昨日昼から尿が出ず、下腹部が張ってきていたが様子をみていた。今朝、下腹部の痛みで目覚め、症状が増悪するため受診した。既往歴 : 特記すべきことはない。生活歴 : 喫煙歴は20本/日を40年間。飲酒は日本酒1〜2合/日。家族歴 : 父親が68歳時に胃癌で死亡。現症 : 意識は清明。身長165cm、体重61kg。体温36.9°C。脈拍52/分、不整。血圧142/94mmHg。呼吸数18/分。SpO296%(room air)。頸静脈の怒張を認めない。心尖部を最強点とするII/VIの収縮期雑音を認める。呼吸音に異常を認めない。腹部は下腹部が膨隆し、圧痛を認める。下腿浮腫は認めない。腹部超音波検査で膀胱容積は拡大しており、尿道カテーテルを一時的に留置することとした。
カテーテル留置で正しいのはどれか。', '[{"key": "A", "text": "挿入時は患者を側臥位にする。"}, {"key": "B", "text": "陰茎に潤滑剤を塗布した後に消毒を行う。"}, {"key": "C", "text": "陰茎は垂直方向に軽く引き上げるように保持する。"}, {"key": "D", "text": "蓄尿バックは膀胱と同じ高さの位置でベッド柵に固定する。"}, {"key": "E", "text": "挿入途中で抵抗が強い場合、その位置でバルーンを膨らませる。"}]'::jsonb, 'C', '正答は C「陰茎は垂直方向に軽く引き上げるように保持する。」。

男性の尿道は陰茎の根元で屈曲しているため、陰茎を体に対して垂直に軽く引き上げて尿道をまっすぐにしてからカテーテルを進める。患者は仰臥位とし、外尿道口を消毒してから潤滑剤を付けたカテーテルを挿入する。

出典：厚生労働省ホームページ 第114回医師国家試験 E041', '{"A": "尿道カテーテルは仰臥位で挿入する。", "B": "先に外尿道口を消毒し、そのあと潤滑剤を付けたカテーテルを挿入する。順序が逆である。", "D": "尿の逆流による感染を防ぐため、蓄尿バッグは膀胱より低い位置に置く。", "E": "尿道の中でバルーンを膨らませると尿道を損傷する。尿の流出で膀胱内に入ったことを確かめてから膨らませる。"}'::jsonb, 'public', 'M', '114-E-41', '', 'pending', 'llm'),
('循環器', '', 2, 'KOKUSHI', '72歳の男性。下腹部痛を主訴に来院した。現病歴 : 10年前から高血圧症で通院中であり、降圧薬による内服療法を受けている。1か月前から動悸を伴う心房細動が出現し、抗不整脈薬と抗凝固薬の処方も受けていた。昨日昼から尿が出ず、下腹部が張ってきていたが様子をみていた。今朝、下腹部の痛みで目覚め、症状が増悪するため受診した。既往歴 : 特記すべきことはない。生活歴 : 喫煙歴は20本/日を40年間。飲酒は日本酒1〜2合/日。家族歴 : 父親が68歳時に胃癌で死亡。現症 : 意識は清明。身長165cm、体重61kg。体温36.9°C。脈拍52/分、不整。血圧142/94mmHg。呼吸数18/分。SpO296%(room air)。頸静脈の怒張を認めない。心尖部を最強点とするII/VIの収縮期雑音を認める。呼吸音に異常を認めない。腹部は下腹部が膨隆し、圧痛を認める。下腿浮腫は認めない。腹部超音波検査で膀胱容積は拡大しており、尿道カテーテルを一時的に留置することとした。
外来での処置中、検査室から「パニック値が出ているので、検査結果を至急報告します」との連絡があった。検査所見 : 尿所見:蛋白2+、糖(−)、潜血2+、沈渣は赤血球30〜50/HPF、白血球1〜4/HPF、細菌(−)。血液所見:赤血球450万、Hb13.2g/dL、Ht42%、白血球8,200、血小板24万、PT-INR1.9(基準0.9〜1.1)。血液生化学所見:総蛋白6.8g/dL、AST44U/L、ALT20U/L、尿素窒素68mg/dL、クレアチニン3.8mg/dL、血糖136mg/dL、Na134mEq/L、K7.2mEq/L、Cl106mEq/L、Ca8.4mg/dL。CRP1.2mg/dL。
直ちに行うべき対応はどれか。', '[{"key": "A", "text": "腹部CT"}, {"key": "B", "text": "心電図検査"}, {"key": "C", "text": "膀胱鏡検査"}, {"key": "D", "text": "動脈血ガス分析"}, {"key": "E", "text": "部位を変えての静脈採血"}]'::jsonb, 'B', '正答は B「心電図検査」。

K 7.2mEq/Lは致死的な不整脈を起こしうる値で、脈拍も52/分と遅い。尿閉による腎後性の急性腎障害で高カリウム血症が起きており、直ちに心電図でテント状T波やQRS幅の拡大、徐脈を確かめ、変化があればカルシウム製剤の静注などの治療を始める。

出典：厚生労働省ホームページ 第114回医師国家試験 E042', '{"A": "尿閉の原因の検索は必要だが、命にかかわる高カリウム血症の評価が先である。", "C": "血尿の原因の検索はあとでよく、いまは高カリウム血症への対応が優先である。", "D": "アシドーシスの評価には役立つが、まず心電図で心臓への影響を確かめる。", "E": "溶血による偽性高カリウム血症もありうるが、腎障害と徐脈があり真の高カリウム血症の可能性が高い。再検で治療を遅らせず、まず心電図をとる。"}'::jsonb, 'public', 'M', '114-E-42', '', 'pending', 'llm'),
('循環器', '', 2, 'KOKUSHI', '49歳の男性。動悸と息苦しさを主訴に来院した。現病歴 : 今朝、朝食時に強い動悸を自覚し、息苦しさを伴っていた。自分で脈を触れたところ脈のリズムは不整で、脈拍数は112〜124/分であったという。動悸や息苦しさは2時間程度持続したが症状は徐々に改善し、来院時には消失していた。既往歴 : 高尿酸血症を指摘され食事療法を行っている。生活歴 : 喫煙歴は40本/日を24年間。飲酒歴はビール3L/日を29年間。家族歴 : 心疾患の家族歴はない。現症 : 意識は清明。身長167cm、体重79kg。体温36.2°C。脈拍80/分、整。血圧152/94mmHg。呼吸数18/分。SpO297%(room air)。眼瞼結膜と眼球結膜とに異常を認めない。心音と呼吸音とに異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。検査所見 : 血液所見:赤血球463万、Hb14.5g/dL、白血球7,600、血小板20万。血液生化学所見:AST35U/L、ALT38U/L、γ-GT47U/L(基準8〜50)、尿素窒素18mg/dL、クレアチニン1.1mg/dL、尿酸8.1mg/dL、Na138mEq/L、K4.9mEq/L、Cl101mEq/L。胸部エックス線写真で心胸郭比57%。心電図は、心拍数76/分の洞調律で、有意なST-T変化を認めない。心エコー検査で左室の拡張末期径は58mmと拡大し、駆出率は45%と低下している。
動悸の原因の鑑別に最も有用な情報はどれか。', '[{"key": "A", "text": "家族歴"}, {"key": "B", "text": "喫煙歴"}, {"key": "C", "text": "高尿酸血症"}, {"key": "D", "text": "動悸時の脈のリズム"}, {"key": "E", "text": "来院時の心電図所見"}]'::jsonb, 'D', '正答は D「動悸時の脈のリズム」。

動悸は受診時には消えており、来院時の心電図は洞調律で手掛かりがない。発作中に本人が触れた脈が不整で112〜124/分だったという情報は、心房細動のような絶対性不整脈か、規則正しい発作性上室頻拍かを分ける決定的な材料になる。

出典：厚生労働省ホームページ 第114回医師国家試験 E043', '{"A": "心疾患の家族歴はなく、鑑別に寄与しない。", "B": "喫煙は心血管疾患の危険因子だが、どの不整脈かを絞る情報にはならない。", "C": "高尿酸血症は動悸の原因と直接は結びつかない。", "E": "来院時の心電図は症状が消えた後の記録で、発作中の調律を捉えていない。"}'::jsonb, 'public', 'M', '114-E-43', '', 'pending', 'llm'),
('循環器', '', 2, 'KOKUSHI', '49歳の男性。動悸と息苦しさを主訴に来院した。現病歴 : 今朝、朝食時に強い動悸を自覚し、息苦しさを伴っていた。自分で脈を触れたところ脈のリズムは不整で、脈拍数は112〜124/分であったという。動悸や息苦しさは2時間程度持続したが症状は徐々に改善し、来院時には消失していた。既往歴 : 高尿酸血症を指摘され食事療法を行っている。生活歴 : 喫煙歴は40本/日を24年間。飲酒歴はビール3L/日を29年間。家族歴 : 心疾患の家族歴はない。現症 : 意識は清明。身長167cm、体重79kg。体温36.2°C。脈拍80/分、整。血圧152/94mmHg。呼吸数18/分。SpO297%(room air)。眼瞼結膜と眼球結膜とに異常を認めない。心音と呼吸音とに異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。検査所見 : 血液所見:赤血球463万、Hb14.5g/dL、白血球7,600、血小板20万。血液生化学所見:AST35U/L、ALT38U/L、γ-GT47U/L(基準8〜50)、尿素窒素18mg/dL、クレアチニン1.1mg/dL、尿酸8.1mg/dL、Na138mEq/L、K4.9mEq/L、Cl101mEq/L。胸部エックス線写真で心胸郭比57%。心電図は、心拍数76/分の洞調律で、有意なST-T変化を認めない。心エコー検査で左室の拡張末期径は58mmと拡大し、駆出率は45%と低下している。
飲酒習慣に関する説明として誤っているのはどれか。', '[{"key": "A", "text": "「多量の飲酒は血圧を上昇させます」"}, {"key": "B", "text": "「多量の飲酒は心不全を起こしやすくします」"}, {"key": "C", "text": "「多量の飲酒は不整脈を起こしやすくします」"}, {"key": "D", "text": "「禁酒により心機能障害の回復が期待できます」"}, {"key": "E", "text": "「心臓に悪影響を与えないためにはお酒の種類を変更すればよいです」"}]'::jsonb, 'E', '正答は E「「心臓に悪影響を与えないためにはお酒の種類を変更すればよいです」」。

設問は「誤っている」説明を選ぶもの。心臓への影響を決めるのは摂取したアルコールの総量であって酒の種類ではない。種類を変えれば大丈夫という説明は誤りで、本例のようにビール3L/日を29年続けている場合は総量を減らすことが要る。

出典：厚生労働省ホームページ 第114回医師国家試験 E044', '{"A": "多量の飲酒が血圧を上げるのは正しく、本例も152/94mmHgと高い。", "B": "多量の飲酒はアルコール性心筋症を起こしうる。本例も左室拡大と駆出率45%への低下があり、正しい説明である。", "C": "多量の飲酒は心房細動を誘発しやすく（holiday heart syndrome）、正しい説明である。", "D": "アルコール性心筋症は禁酒により心機能の改善が期待でき、正しい説明である。"}'::jsonb, 'public', 'M', '114-E-44', '', 'pending', 'llm'),
('小児科', '', 2, 'KOKUSHI', '20歳の男性。医学部在籍中の2年次学生である。1週間の病院実習に初めての参加を予定しており、10か月前(1年次)に受けた抗体検査の結果を持って病院実習担当の医師に相談に来た。既往歴 : 感染症の既往はないという。予防接種で発熱などの副反応が出たことはない。生活歴 : 喫煙歴と飲酒歴はない。家族歴 : 特記すべきことはない。検査所見 : 10か月前の抗体検査の報告書を示す。血中抗体価報告書氏名 ◯◯◯◯病院実習の基準を測定方法 — 検査結果 — 単位満たす陽性麻疹 — (IgG-EIA法) — 20.4 — (≧16.0)風疹 — (IgG-EIA法) — 10.0 — (≧ 8.0)水痘 — (IgG-EIA法) — 6.4 — (≧ 4.0)流行性耳下腺炎 (IgG-EIA法) — 陽性 — 陽性B型肝炎 — (CLIA法) — 4.8 — (≧10.0) — mIU/mL結核 — (IGRA)* — 陰性 — 陰性*結核菌特異的全血インターフェロンγ遊離測定法
この学生の相談の際に話す内容で適切なのはどれか。', '[{"key": "A", "text": "「BCG接種が必要です」"}, {"key": "B", "text": "「MRワクチンの再接種が必要です」"}, {"key": "C", "text": "「帯状疱疹になる可能性が高いです」"}, {"key": "D", "text": "「B型肝炎ワクチンの接種状況を教えてください」"}, {"key": "E", "text": "「流行性耳下腺炎患者の診療には参加できません」"}]'::jsonb, 'D', '正答は D「「B型肝炎ワクチンの接種状況を教えてください」」。

報告書のうち基準を満たしていないのはB型肝炎だけで、HBs抗体4.8mIU/mLは基準の10mIU/mL未満である。病院実習では針刺しの危険があるため、まずワクチンの接種歴を確認し、未完了なら接種を進める。

出典：厚生労働省ホームページ 第114回医師国家試験 E045', '{"A": "IGRAは陰性で結核に感染しておらず、成人へのBCG接種の適応もない。", "B": "麻疹20.4、風疹10.0といずれも基準を満たしており、MRワクチンの再接種は要らない。", "C": "水痘の抗体価6.4は基準の4.0を満たしている。帯状疱疹になりやすいと言う根拠はない。", "E": "流行性耳下腺炎の抗体は陽性で基準を満たしており、診療への参加を制限する理由がない。"}'::jsonb, 'public', 'M', '114-E-45', '', 'pending', 'llm'),
('小児科', '', 2, 'KOKUSHI', '20歳の男性。医学部在籍中の2年次学生である。1週間の病院実習に初めての参加を予定しており、10か月前(1年次)に受けた抗体検査の結果を持って病院実習担当の医師に相談に来た。既往歴 : 感染症の既往はないという。予防接種で発熱などの副反応が出たことはない。生活歴 : 喫煙歴と飲酒歴はない。家族歴 : 特記すべきことはない。検査所見 : 10か月前の抗体検査の報告書を示す。血中抗体価報告書氏名 ◯◯◯◯病院実習の基準を測定方法 — 検査結果 — 単位満たす陽性麻疹 — (IgG-EIA法) — 20.4 — (≧16.0)風疹 — (IgG-EIA法) — 10.0 — (≧ 8.0)水痘 — (IgG-EIA法) — 6.4 — (≧ 4.0)流行性耳下腺炎 (IgG-EIA法) — 陽性 — 陽性B型肝炎 — (CLIA法) — 4.8 — (≧10.0) — mIU/mL結核 — (IGRA)* — 陰性 — 陰性*結核菌特異的全血インターフェロンγ遊離測定法
その後の経過 : 相談に来た学生は医学部を卒業し、5年後に研修医として同じ大学病院で勤務を始めた。この研修医が平日に救急外来で勤務していたところ、54歳の男性が自転車の転倒による挫創のため来院した。初診患者でこの病院に受診歴はない。この研修医が創部の縫合処置を行っている最中、誤って縫合針を自分の指に刺した。研修医は創部から血を絞り出し流水で十分に洗浄すると同時に、直ちに研修医自身と患者の血液検査を行った。
外傷患者の血液検査結果が陽性だった場合、できるだけ早期に研修医に対する内服予防投与の開始が必要なのはどれか。', '[{"key": "A", "text": "HIV"}, {"key": "B", "text": "HBV"}, {"key": "C", "text": "HCV"}, {"key": "D", "text": "梅毒"}, {"key": "E", "text": "HTLV-1"}]'::jsonb, 'A', '正答は A「HIV」。

針刺し事故で、内服薬による曝露後予防をできるだけ早く（できれば2時間以内）始める必要があるのはHIVである。抗HIV薬を原則4週間内服する。開始が遅れるほど効果が下がるため、検査結果を待たずに方針を決めることもある。

出典：厚生労働省ホームページ 第114回医師国家試験 E046', '{"B": "HBVの曝露後予防はB型肝炎ワクチンと抗HBsヒト免疫グロブリンで、内服薬ではない。", "C": "HCVには有効な曝露後予防がなく、経過を追って感染が成立した時点で治療する。", "D": "梅毒は針刺しでの感染がまれで、緊急の内服予防投与は行わない。", "E": "HTLV-1にも確立した曝露後予防はない。"}'::jsonb, 'public', 'M', '114-E-46', '', 'pending', 'llm'),
('代謝・内分泌', '', 2, 'KOKUSHI', '48歳の男性。倦怠感と口渇を主訴に来院した。現病歴 : 2年前から糖尿病を指摘されていたが医療機関を受診していなかった。3か月前から倦怠感、体重減少および口渇が出現した。ここ数日で口渇が顕著になったため来院した。既往歴 : 特記すべきことはない。生活歴 : 会社員で1人暮らし。喫煙歴は15本/日を28年間。36歳から禁酒している。朝食は菓子パン、昼食は社内食堂の定食、夕食はコンビニエンスストアのお惣菜などの食生活である。家族歴 : 父が72歳の時に膵癌。母が脂質異常症。現症 : 意識は清明。身長174cm、体重90kg。体温36.8°C。 脈拍80/分、整。血圧126/88mmHg。呼吸数24/分。眼瞼結膜と眼球結膜とに異常を認めない。口腔内の乾燥を認める。心音と呼吸音とに異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。アキレス腱反射の低下を認める。検査所見 : 尿所見:蛋白1+、糖4+、ケトン体4+、潜血(−)。血液所見:赤血球478万、Hb15.4g/dL、Ht35%、白血球9,800、血小板15万。血液生化学所見:総蛋白7.1g/dL、AST29U/L、ALT54U/L、LD214U/L(基準120〜245)、γ-GT173U/L(基準8〜50)、尿素窒素12mg/dL、クレアチニン0.8mg/dL、随時血糖281mg/dL、HbA1c10.8% (基準4.6〜6.2)、総コレステロール150 mg/dL、Na134mEq/L、K4.2mEq/L、Cl98mEq/L。
糖尿病と診断し治療を開始するとともに、教育入院を行うこととした。適切なのはどれか。', '[{"key": "A", "text": "クリニカルパスの適応ではない。"}, {"key": "B", "text": "シックデイの対処方法を教育する。"}, {"key": "C", "text": "主治医のみの判断で指導計画を行う。"}, {"key": "D", "text": "過去に教育入院歴がないことが条件である。"}, {"key": "E", "text": "糖尿病合併症が診断されると教育入院は中止となる。"}]'::jsonb, 'B', '正答は B「シックデイの対処方法を教育する。」。

糖尿病の教育入院では、食事・運動・薬物療法とともに、発熱や嘔吐で食事がとれないときの対処（シックデイ・ルール）を教える。薬の調整、水分と糖質のとり方、受診の目安を身につけてもらう。

出典：厚生労働省ホームページ 第114回医師国家試験 E047', '{"A": "教育入院は内容と日程が定型的で、クリニカルパスがよく使われる。", "C": "医師、看護師、管理栄養士、薬剤師などの多職種で指導計画を立てる。", "D": "血糖のコントロールが悪くなれば、何度でも教育入院を行ってよい。", "E": "合併症があればその評価と指導も加えて教育を続ける。中止する理由にはならない。"}'::jsonb, 'public', 'M', '114-E-47', '', 'pending', 'llm'),
('代謝・内分泌', '', 2, 'KOKUSHI', '48歳の男性。倦怠感と口渇を主訴に来院した。現病歴 : 2年前から糖尿病を指摘されていたが医療機関を受診していなかった。3か月前から倦怠感、体重減少および口渇が出現した。ここ数日で口渇が顕著になったため来院した。既往歴 : 特記すべきことはない。生活歴 : 会社員で1人暮らし。喫煙歴は15本/日を28年間。36歳から禁酒している。朝食は菓子パン、昼食は社内食堂の定食、夕食はコンビニエンスストアのお惣菜などの食生活である。家族歴 : 父が72歳の時に膵癌。母が脂質異常症。現症 : 意識は清明。身長174cm、体重90kg。体温36.8°C。 脈拍80/分、整。血圧126/88mmHg。呼吸数24/分。眼瞼結膜と眼球結膜とに異常を認めない。口腔内の乾燥を認める。心音と呼吸音とに異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。アキレス腱反射の低下を認める。検査所見 : 尿所見:蛋白1+、糖4+、ケトン体4+、潜血(−)。血液所見:赤血球478万、Hb15.4g/dL、Ht35%、白血球9,800、血小板15万。血液生化学所見:総蛋白7.1g/dL、AST29U/L、ALT54U/L、LD214U/L(基準120〜245)、γ-GT173U/L(基準8〜50)、尿素窒素12mg/dL、クレアチニン0.8mg/dL、随時血糖281mg/dL、HbA1c10.8% (基準4.6〜6.2)、総コレステロール150 mg/dL、Na134mEq/L、K4.2mEq/L、Cl98mEq/L。
血糖コントロールのためインスリン自己注射の指導を行うことになった。適切なのはどれか。', '[{"key": "A", "text": "自己血糖測定機器の指導も行う。"}, {"key": "B", "text": "未使用のインスリン製剤は常温で保管する。"}, {"key": "C", "text": "21Gの注射針を使用する。"}, {"key": "D", "text": "注射は毎回同じ部位に行うように指導する。"}, {"key": "E", "text": "薬剤の注入はできるだけ急速に行うように指導する。"}]'::jsonb, 'A', '正答は A「自己血糖測定機器の指導も行う。」。

インスリン自己注射を始めるときは、低血糖に気づき量を調整できるよう、自己血糖測定の方法もあわせて指導する。

出典：厚生労働省ホームページ 第114回医師国家試験 E048', '{"B": "未使用のインスリンは凍らせないように冷蔵庫（2〜8°C）で保管する。使用中のものは室温でよい。", "C": "自己注射には、ペン型注入器用の細く短い針（32〜34G程度）を使う。21Gは太すぎる。", "D": "同じ部位に打ち続けると皮下に硬結ができて吸収が不安定になるので、少しずつ部位をずらす。", "E": "注入はゆっくり行い、注入後も数秒は針を刺したままにして薬液が漏れないようにする。"}'::jsonb, 'public', 'M', '114-E-48', '', 'pending', 'llm'),
('消化管', '', 2, 'KOKUSHI', '79歳の女性。貧血の精査のため夫に付き添われて来院した。現病歴 : 2週前の健康診断の結果、1年前には正常であった血液検査に異常がみられ、精査を勧められた。自覚症状はない。既往歴 : 65歳時から高血圧症で降圧薬を服用している。76歳時から変形性膝関節症のため歩行困難で車椅子で移動をしている。生活歴 : 80歳の夫と2人暮らし。家族歴 : 特記すべきことはない。現症 : 意識は清明。身長150cm、体重54kg。体温36.2°C。脈拍96/分、整。血圧126/80mmHg。呼吸数18/分。SpO298%(room air)。眼瞼結膜は貧血様である。甲状腺腫と頸部リンパ節とを触知しない。心音と呼吸音とに異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。腱反射は正常である。感覚系に異常を認めない。検査所見 : 血液所見:赤血球381万、Hb8.5g/dL、Ht29%、白血球4,500、血小板29万。血液生化学所見:総蛋白6.9g/dL、アルブミン4.5g/dL、総ビリルビン0.4mg/dL、AST24U/L、ALT22U/L、LD163U/L(基準120〜245)、ALP 146U/L(基準115〜359)、尿素窒素11mg/dL、クレアチニン0.7mg/dL、血糖93 mg/dL。
病状説明を行い、診断のために翌日の下部消化管内視鏡検査を勧めたところ、患者から一言目に「検査は受けたくありません」と返答があった。この時点でふさわしい医師の言葉はどれか。', '[{"key": "A", "text": "「検査を中止しましょう」"}, {"key": "B", "text": "「検査は危険なものではありません」"}, {"key": "C", "text": "「ご家族の意見を聞いてみましょう」"}, {"key": "D", "text": "「検査の必要性がわかっていませんね」"}, {"key": "E", "text": "「なぜ検査を受けたくないのか、お聞かせください」"}]'::jsonb, 'E', '正答は E「「なぜ検査を受けたくないのか、お聞かせください」」。

検査の拒否は、痛みへの不安、費用、家族の負担、以前の不快な経験など、背景がさまざまである。理由を聴かずに説得や中止に進むと、本当の障壁は解けない。まず開かれた質問で理由を尋ねるのが、この時点でふさわしい。

出典：厚生労働省ホームページ 第114回医師国家試験 E049', '{"A": "理由も聴かずに中止すれば、早期に治せる大腸癌を見逃すことになる。", "B": "何を不安に思っているか分からないまま安全性だけを断言しても、患者には届かない。", "C": "意思決定の主体は本人である。いきなり家族に判断を委ねる進め方は適切でない。", "D": "理解していないと決めつける言い方は患者を責めることになり、信頼関係を損なう。"}'::jsonb, 'public', 'M', '114-E-49', '', 'pending', 'llm'),
('代謝・内分泌', '', 2, 'KOKUSHI', '79歳の女性。貧血の精査のため夫に付き添われて来院した。現病歴 : 2週前の健康診断の結果、1年前には正常であった血液検査に異常がみられ、精査を勧められた。自覚症状はない。既往歴 : 65歳時から高血圧症で降圧薬を服用している。76歳時から変形性膝関節症のため歩行困難で車椅子で移動をしている。生活歴 : 80歳の夫と2人暮らし。家族歴 : 特記すべきことはない。現症 : 意識は清明。身長150cm、体重54kg。体温36.2°C。脈拍96/分、整。血圧126/80mmHg。呼吸数18/分。SpO298%(room air)。眼瞼結膜は貧血様である。甲状腺腫と頸部リンパ節とを触知しない。心音と呼吸音とに異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。腱反射は正常である。感覚系に異常を認めない。検査所見 : 血液所見:赤血球381万、Hb8.5g/dL、Ht29%、白血球4,500、血小板29万。血液生化学所見:総蛋白6.9g/dL、アルブミン4.5g/dL、総ビリルビン0.4mg/dL、AST24U/L、ALT22U/L、LD163U/L(基準120〜245)、ALP 146U/L(基準115〜359)、尿素窒素11mg/dL、クレアチニン0.7mg/dL、血糖93 mg/dL。
その後、患者は下部内視鏡検査を受け早期大腸癌が認められた。加療のため4床室に入院した。治療に関する説明のため医師が病室を訪れると、患者はベッドを起こした状態で、そばの椅子に座っている夫と話していた。4床室は満床で、空いている椅子は見当たらない。
医師から病状説明を行う際に望ましい方法はどれか。', '[{"key": "A", "text": "夫だけを別室に呼んで座って話す。"}, {"key": "B", "text": "患者のベッドサイドに立って話す。"}, {"key": "C", "text": "患者の足側のベッドの上に座って話す。"}, {"key": "D", "text": "椅子を持ってきて患者のベッドサイドに座って話す。"}, {"key": "E", "text": "患者を車椅子に乗せ、夫と一緒に車椅子で別室に移動して話す。"}]'::jsonb, 'E', '正答は E「患者を車椅子に乗せ、夫と一緒に車椅子で別室に移動して話す。」。

癌の告知を含む病状説明は、他の患者に聞かれない場所で、本人を中心に、同席してほしい人と一緒に行う。4床室は満床でプライバシーが保てず、患者は車椅子で移動できるので、夫とともに別室へ移って話すのが望ましい。

出典：厚生労働省ホームページ 第114回医師国家試験 E050', '{"A": "本人を差し置いて家族にだけ説明するのは、本人の知る権利と意思決定を損なう。", "B": "立ったまま話すと患者を見下ろす姿勢になり、しかも同室の患者に話が聞こえてしまう。", "C": "患者のベッドの上に座るのは、私的な領域に立ち入る行為で適切でない。", "D": "座って目線を合わせる点はよいが、4床室のままではプライバシーが保てない。"}'::jsonb, 'public', 'M', '114-E-50', '', 'pending', 'llm'),
('感染症', '', 2, 'KOKUSHI', '日本の薬剤耐性〈AMR〉対策アクションプラン(2016−2020)に含まれない内容はどれか。', '[{"key": "A", "text": "薬剤耐性の動向調査"}, {"key": "B", "text": "抗微生物剤の適正使用"}, {"key": "C", "text": "適切な感染予防と管理"}, {"key": "D", "text": "薬剤耐性に関する知識や理解の普及"}, {"key": "E", "text": "薬剤耐性菌を保菌する医療従事者の就業停止"}]'::jsonb, 'E', '正答は E「薬剤耐性菌を保菌する医療従事者の就業停止」。

日本のAMR対策アクションプランは、普及啓発・教育、動向調査・監視、感染予防・管理、抗微生物剤の適正使用、研究開発・創薬、国際協力の6分野からなる。耐性菌を保菌する医療従事者の就業停止は含まれず、保菌者には標準予防策と接触予防策で対応する。

出典：厚生労働省ホームページ 第114回医師国家試験 F003', '{"A": "薬剤耐性と抗微生物剤の使用量の動向調査・監視は、6分野の一つである。", "B": "抗微生物剤の適正使用は、6分野の一つである。", "C": "適切な感染予防・管理は、6分野の一つである。", "D": "知識や理解の普及啓発・教育は、6分野の一つである。"}'::jsonb, 'public', 'M', '114-F-3', '', 'pending', 'llm'),
('免疫・膠原病', '', 2, 'KOKUSHI', '疾患とその疾患に特異的な自己抗体との組合せで正しいのはどれか。', '[{"key": "A", "text": "多発性筋炎 — 抗Sm抗体"}, {"key": "B", "text": "全身性強皮症 — 抗RNAポリメラーゼIII抗体"}, {"key": "C", "text": "Sjögren症候群 — MPO-ANCA"}, {"key": "D", "text": "顕微鏡的多発血管炎 — 抗RNP抗体"}, {"key": "E", "text": "全身性エリテマトーデス〈SLE〉 — 抗アミノアシルtRNA合成酵素抗体〈抗ARS抗体〉"}]'::jsonb, 'B', '正答は B「全身性強皮症 — 抗RNAポリメラーゼIII抗体」。

抗RNAポリメラーゼIII抗体は全身性強皮症に特異的な自己抗体で、びまん皮膚硬化型に多く、急速な皮膚硬化の進行や強皮症腎クリーゼと関連する。

出典：厚生労働省ホームページ 第114回医師国家試験 F007', '{"A": "抗Sm抗体はSLEに特異的な抗体である。多発性筋炎では抗ARS抗体などがみられる。", "C": "Sjögren症候群では抗SS-A抗体と抗SS-B抗体がみられる。MPO-ANCAは顕微鏡的多発血管炎の抗体である。", "D": "顕微鏡的多発血管炎ではMPO-ANCAがみられる。抗RNP抗体は混合性結合組織病の抗体である。", "E": "抗ARS抗体は多発性筋炎・皮膚筋炎の抗体である。SLEでは抗dsDNA抗体や抗Sm抗体がみられる。"}'::jsonb, 'public', 'M', '114-F-7', '', 'pending', 'llm'),
('公衆衛生', '', 2, 'KOKUSHI', '受動喫煙の防止を規定している法律はどれか。', '[{"key": "A", "text": "健康増進法"}, {"key": "B", "text": "地域保健法"}, {"key": "C", "text": "母子保健法"}, {"key": "D", "text": "たばこ事業法"}, {"key": "E", "text": "医薬品、医療機器等の品質、有効性及び安全性の確保等に関する法律〈医薬品医療機器等法〉"}]'::jsonb, 'A', '正答は A「健康増進法」。

受動喫煙の防止は健康増進法に定められている。2018年の改正で、多くの人が利用する施設では原則として屋内が禁煙となった。

出典：厚生労働省ホームページ 第114回医師国家試験 F016', '{"B": "地域保健法は保健所や市町村保健センターなど、地域保健の体制を定める法律である。", "C": "母子保健法は母子健康手帳や乳幼児健康診査などを定める法律である。", "D": "たばこ事業法はたばこの製造や販売の事業について定める法律で、受動喫煙の防止は定めていない。", "E": "医薬品や医療機器の品質・有効性・安全性を確保する法律で、たばこは対象外である。"}'::jsonb, 'public', 'M', '114-F-16', '', 'pending', 'llm'),
('腎臓', '', 2, 'KOKUSHI', '尿蛋白量を決定する因子でないのはどれか。', '[{"key": "A", "text": "尿浸透圧"}, {"key": "B", "text": "糸球体内圧"}, {"key": "C", "text": "尿細管機能"}, {"key": "D", "text": "糸球体基底膜の蛋白透過性"}, {"key": "E", "text": "糸球体上皮細胞〈ポドサイト〉機能"}]'::jsonb, 'A', '正答は A「尿浸透圧」。

尿蛋白の量は、糸球体からの蛋白の漏れ（基底膜とポドサイトによる濾過障壁の透過性、糸球体内圧）と、尿細管での再吸収で決まる。尿浸透圧は尿の濃さを表すだけで、排泄される蛋白の量そのものは変えない。

出典：厚生労働省ホームページ 第114回医師国家試験 F023', '{"B": "糸球体内圧が上がると蛋白の漏出が増える。ACE阻害薬やARBが尿蛋白を減らすのはこのためである。", "C": "濾過された低分子の蛋白は近位尿細管で再吸収されるので、尿細管の機能が落ちると尿蛋白が増える。", "D": "基底膜の構造や陰性荷電が障害されると、蛋白が濾過されやすくなる。", "E": "ポドサイトとスリット膜は濾過障壁の要で、その障害は大量の蛋白尿を招く。"}'::jsonb, 'public', 'M', '114-F-23', '', 'pending', 'llm'),
('公衆衛生', '', 2, 'KOKUSHI', '精神障害者の保健、医療、福祉について正しいのはどれか。', '[{"key": "A", "text": "治療を行う際のインフォームド・コンセントは必要ない。"}, {"key": "B", "text": "緊急措置入院は複数の精神保健指定医の診察を必要とする。"}, {"key": "C", "text": "知的障害者の福祉対策は成人後も児童福祉法に基づいて行われる。"}, {"key": "D", "text": "精神保健福祉センターは精神保健福祉の知識について普及・啓発を行う。"}, {"key": "E", "text": "精神保健及び精神障害者福祉に関する法律〈精神保健福祉法〉の目的は犯罪予防である。"}]'::jsonb, 'D', '正答は D「精神保健福祉センターは精神保健福祉の知識について普及・啓発を行う。」。

精神保健福祉センターは都道府県と政令指定都市に置かれ、精神保健福祉に関する知識の普及・啓発、調査研究、複雑で困難な相談への対応、保健所などへの技術的な支援を行う。

出典：厚生労働省ホームページ 第114回医師国家試験 F026', '{"A": "精神疾患の治療でも、原則としてインフォームド・コンセントを得て行う。", "B": "緊急措置入院は精神保健指定医1名の診察で、72時間に限って入院させる手続きである。2名以上の指定医の診察が要るのは措置入院である。", "C": "成人の知的障害者の福祉は、知的障害者福祉法や障害者総合支援法に基づいて行う。", "E": "精神保健福祉法の目的は、精神障害者の医療と保護、社会復帰と自立の支援、国民の精神的健康の保持・増進であり、犯罪予防ではない。"}'::jsonb, 'public', 'M', '114-F-26', '', 'pending', 'llm'),
('感染症', '', 2, 'KOKUSHI', '40歳の男性。両下腿の皮膚のただれを主訴に来院した。職場で作業中に有機溶剤の入ったドラム缶が転倒し、下半身の広い範囲にクレゾールがかかった。そのまま作業を続けたが、着替え時に下肢の皮膚が赤くただれているのに気付いて受診した。診察時、事故から4時間が経過していた。両側下腿が全体に発赤、右下腿外側に面積約20cm2ほどのびらんがみられる。患部のドレッシングを行った後、次に行うべき対応として正しいのはどれか。', '[{"key": "A", "text": "これ以上の処置は不要である。"}, {"key": "B", "text": "翌日皮膚科を受診することを患者に勧める。"}, {"key": "C", "text": "疼痛時に服用するようNSAIDを処方し帰宅させる。"}, {"key": "D", "text": "臓器障害の全身管理が可能な医療施設に緊急に転院させる。"}, {"key": "E", "text": "抗菌薬を処方して、悪化すれば再度受診するように伝える。"}]'::jsonb, 'D', '正答は D「臓器障害の全身管理が可能な医療施設に緊急に転院させる。」。

クレゾールはフェノール系の化合物で、皮膚から吸収されて肝障害・腎障害・溶血・メトヘモグロビン血症・中枢神経抑制をきたす。下半身の広範囲に曝露しており、局所の創処置だけでは足りない。全身管理のできる施設へ緊急に搬送する。

出典：厚生労働省ホームページ 第114回医師国家試験 F039', '{"A": "経皮吸収による全身毒性が起こりうるため、処置を終えて帰すことはできない。", "B": "翌日まで待つ間に肝腎障害や溶血が進行する危険がある。", "C": "鎮痛だけを行って帰宅させると全身毒性を見逃す。", "E": "問題は感染ではなく化学物質の全身毒性である。"}'::jsonb, 'public', 'M', '114-F-39', '', 'pending', 'llm'),
('医学総論', '', 2, 'KOKUSHI', '70歳の男性。脳梗塞で入院し、現在、①積極的にリハビリテーションに取り組んでいる。②右上下肢に重度の運動麻痺が残存しており、高次脳機能障害はないが、日常生活を1人で行うのは現時点では不可能である。もともと③山間部の過疎地域で1人暮らしをしていた。家族はおらず、④近所付き合いはない。発症以前は無農薬野菜の栽培に取り組み、⑤独力で事業を展開していた。下線部のうち国際生活機能分類〈ICF〉の心身機能・身体構造に分類されるのはどれか。', '[{"key": "A", "text": "①"}, {"key": "B", "text": "②"}, {"key": "C", "text": "③"}, {"key": "D", "text": "④"}, {"key": "E", "text": "⑤"}]'::jsonb, 'B', '正答は B「②」。

ICFは生活機能を心身機能・身体構造、活動、参加に分け、それに影響する背景因子として環境因子と個人因子を置く。右上下肢の運動麻痺は身体の機能の障害で、心身機能・身体構造に分類される。

出典：厚生労働省ホームページ 第114回医師国家試験 F047', '{"A": "リハビリテーションへの取り組み方は、本人の意欲や性格にかかわる要素で、心身機能ではない。", "C": "山間部の過疎地域という住まいの条件は、環境因子である。", "D": "近所付き合いがないことは地域社会とのかかわりの問題で、心身機能ではない。", "E": "独力で事業を営んでいたことは社会での役割で、参加に分類される。"}'::jsonb, 'public', 'M', '114-F-47', '', 'pending', 'llm'),
('産科', '', 2, 'KOKUSHI', '28歳の初妊婦(1妊0産)。妊娠12週に妊婦健康診査のため来院した。妊娠8週に妊娠のため受診し、妊娠初期血液検査を受けた。以後、悪阻や性器出血等の症状はない。生来健康である。母がB型肝炎ウイルスのキャリアであるという。身長156cm、体重55kg。尿所見:蛋白(−)、糖(−)。腹部超音波検査で胎児に異常を認めない。4週前の血液検査でHBs抗原陽性、HBe抗原陽性が判明した。適切な説明はどれか。', '[{"key": "A", "text": "「人工妊娠中絶が必要です」"}, {"key": "B", "text": "「母乳栄養は避けましょう」"}, {"key": "C", "text": "「今すぐB型肝炎ワクチンを接種しましょう」"}, {"key": "D", "text": "「妊娠中に赤ちゃんにウイルスが感染する可能性が高いです」"}, {"key": "E", "text": "「出産後、赤ちゃんに抗HBsヒト免疫グロブリンを接種しましょう」"}]'::jsonb, 'E', '正答は E「「出産後、赤ちゃんに抗HBsヒト免疫グロブリンを接種しましょう」」。

HBs抗原とHBe抗原がともに陽性の母親からの児には、出生後できるだけ早く（12時間以内が目安）抗HBsヒト免疫グロブリンとB型肝炎ワクチンを投与し、その後もワクチンを続けて母子感染を防ぐ。

出典：厚生労働省ホームページ 第114回医師国家試験 F051', '{"A": "出生後の予防で母子感染はほぼ防げ、人工妊娠中絶の理由にはならない。", "B": "出生後の予防を行えば、母乳栄養を控える必要はない。", "C": "キャリアである母親にワクチンは効かない。予防の対象は出生後の児である。", "D": "感染の多くは分娩時の産道感染で、妊娠中の胎内感染はまれである。"}'::jsonb, 'public', 'M', '114-F-51', '', 'pending', 'llm'),
('精神科', '', 2, 'KOKUSHI', '17歳の女子。体重減少を主訴に来院した。2年前から摂食量を意識的に減らすようになり、学校における定期健康診断でやせを指摘された。医療機関への受診を指導されたが受診しなかったという。その後も体重がさらに減少しており、心配した母親に付き添われて受診した。身長150cm、体重27kg。 体温36.1°C。脈拍52/分、整。血圧90/50mmHg。前腕や背部に産毛の増生を認める。下腿に軽度の圧痕浮腫を認める。この患者で認められる可能性が高いのはどれか。', '[{"key": "A", "text": "GHが高値である。"}, {"key": "B", "text": "月経周期は正常である。"}, {"key": "C", "text": "LH/FSH比が高値である。"}, {"key": "D", "text": "コルチゾールが低値である。"}, {"key": "E", "text": "遊離トリヨードサイロニン〈FT3〉が高値である。"}]'::jsonb, 'A', '正答は A「GHが高値である。」。

神経性やせ症では、低栄養でIGF-1が下がり、そのフィードバックでGHは高値になる。ほかに視床下部性の無月経、低T3症候群、コルチゾールの高値がみられる。

出典：厚生労働省ホームページ 第114回医師国家試験 F055', '{"B": "低栄養でゴナドトロピンの分泌が落ち、無月経になる。", "C": "LH/FSH比の高値は多嚢胞性卵巣症候群の所見である。神経性やせ症ではLHもFSHも低下する。", "D": "ストレスと低栄養により、コルチゾールはむしろ高値になる。", "E": "エネルギーの消費を抑えるためにT4からT3への変換が落ち、FT3は低値になる（低T3症候群）。"}'::jsonb, 'public', 'M', '114-F-55', '', 'pending', 'llm'),
('産科', '', 2, 'KOKUSHI', '28歳の初妊婦(1妊0産)。妊娠12週に自宅近くの診療所で実施した血液検査で異常を指摘され、妊娠16週に紹介され受診した。検査結果を表に示す。検査項目 — 計測値 — 基準値風疹抗体〈HI〉 — 8倍未満 — 8倍未満HTLV-1抗体〈PA〉 — 陽性 — 陰性トキソプラズマ抗体〈PHA〉 — 320倍 — 160倍未満RPR — 32倍 — 1倍未満TPHA — 640倍 — 80倍未満C型肝炎ウイルス抗体〈EIA〉 — 陽性 — 陰性妊婦への説明として適切なのはどれか。', '[{"key": "A", "text": "「風疹ワクチンを接種しましょう」"}, {"key": "B", "text": "「成人T細胞白血病ウイルス感染の精密検査が必要です」"}, {"key": "C", "text": "「トキソプラズマの母子感染のリスクはありません」"}, {"key": "D", "text": "「梅毒に感染している可能性はありません」"}, {"key": "E", "text": "「出産後、赤ちゃんにC型肝炎ウイルスのワクチンを接種しましょう」"}]'::jsonb, 'B', '正答は B「「成人T細胞白血病ウイルス感染の精密検査が必要です」」。

HTLV-1抗体のスクリーニング（PA法）の陽性には偽陽性もあるため、ウエスタンブロット法やラインブロット法で確認検査を行う。キャリアと確定すれば、主な感染経路である母乳の与え方を相談する。

出典：厚生労働省ホームページ 第114回医師国家試験 F056', '{"A": "風疹抗体は陰性だが、風疹ワクチンは生ワクチンなので妊娠中は接種できない。産後に接種する。", "C": "トキソプラズマ抗体が高く、妊娠中の初感染を否定できない。IgM抗体などで感染の時期を調べる必要がある。", "D": "RPRとTPHAがともに陽性で、活動性の梅毒の可能性が高い。ペニシリンで治療する。", "E": "C型肝炎ウイルスのワクチンはない。まずHCV-RNAで感染が続いているかを確かめる。"}'::jsonb, 'public', 'M', '114-F-56', '', 'pending', 'llm'),
('公衆衛生', '', 2, 'KOKUSHI', '86歳の女性。発熱を主訴に来院した。現病歴 : 2日前に長男が患者に連絡した際「風邪をひいている」との訴えがあった。本日長男が連絡した際に電話がつながらなかったため長男が訪問したところ、発熱があり食事も摂れず布団の中でぐったりしていた。長男に付き添われて来院した。既往歴 : 70歳から2型糖尿病で内服加療中。82歳時に脳梗塞を発症、後遺症による左下肢不全麻痺がある。生活歴 : 1人暮らしをしており、近所に住む息子が週2〜3回訪問していた。家族歴 : 妹が脂質異常症。現症 : 意識レベルはGCS14(E4V4M6)。身長150cm、体重38kg。体温38.2°C。脈拍100/分、整。血圧120/72mmHg。呼吸数20/分。SpO299%(room air)。心音と呼吸音とに異常を認めない。腋窩は乾燥している。体表に外傷は認めなかったが、左大転子部に発赤を認める。検査所見 : 尿所見:蛋白(−)、糖2+、潜血(−)。血液所見:赤血球490万、Hb16.0g/dL、Ht47%、白血球9,000(好中球60%、リンパ球40%)、血小板36万。血液生化学所見:尿素窒素56mg/dL、クレアチニン1.2mg/dL、随時血糖360mg/dL、HbA1c8.0%(基準4.6〜6.2)、Na130mEq/L、K4.0mEq/L、Cl91 mEq/L。CRP0.3mg/dL。頭部CTで陳旧性脳梗塞を認める。
10日間の入院加療によって全身状態が改善したため退院を検討している。入院前は2型糖尿病治療のため、月1回本人が1人で外来受診していた。しかし、現時点で歩行には介助が必要であり、1人で外来を受診するのは難しいと判断している。退院に向けての本人および家族への説明で適切なのはどれか。', '[{"key": "A", "text": "「外出は控えるようにしてください」"}, {"key": "B", "text": "「自宅に帰ると認知機能が低下します」"}, {"key": "C", "text": "「要介護認定の申請をご検討ください」"}, {"key": "D", "text": "「高次医療機関への転院を検討しましょう」"}, {"key": "E", "text": "「HbA1cを6.0%未満にコントロールする必要があります」"}]'::jsonb, 'C', '正答は C「「要介護認定の申請をご検討ください」」。

退院後は歩行に介助が要り、1人暮らしで1人では通院できない。介護保険の要介護認定を申請すれば、訪問介護や通所サービス、通院の支援などを受けられるので、退院に向けて申請を勧める。

出典：厚生労働省ホームページ 第114回医師国家試験 F065', '{"A": "活動を減らすと廃用が進み、介護の必要性をかえって高める。", "B": "根拠のない説明で、本人と家族の不安をあおるだけである。", "D": "全身状態は改善しており、専門的な治療が要る状態ではない。", "E": "高齢者の目標は認知機能やADLに応じて緩め、低血糖を避ける。6.0%未満を目指すのは危険である。"}'::jsonb, 'public', 'M', '114-F-65', '', 'pending', 'llm'),
('腎臓', '', 2, 'KOKUSHI', '22歳の男性。むくみを主訴に来院した。2週前、急に顔面と下腿のむくみ及び排尿後の尿の細かい泡立ちに気付いた。むくみは次第に増悪し、この間に体重は約20kg増加した。5日前から食欲がなく食事量は半減し、下痢気味で、全身倦怠感が悪化している。一昨日から排尿回数が減少し、昨日は色が濃く泡立ちの強い尿が2回、いずれも少量出たのみで、本日は起床後10時間でまだ排尿がない。意識は清明。身長176cm、体重92kg。血圧110/70mmHg。脈拍88/分、整。呼吸数16/分。顕著な両側眼瞼浮腫があり、四肢に左右差のない圧痕性浮腫を認める。今後1週間以内に合併する可能性の高い病態はどれか。', '[{"key": "A", "text": "肺水腫"}, {"key": "B", "text": "気道閉塞"}, {"key": "C", "text": "出血傾向"}, {"key": "D", "text": "急性腎障害"}, {"key": "E", "text": "高血糖緊急症"}]'::jsonb, 'D', '正答は D「急性腎障害」。

急激に増えた浮腫と泡立つ尿からネフローゼ症候群を考える（若年者の急な発症では微小変化型が多い）。高度の低アルブミン血症で血管内の水分が減っているうえ、食事量の低下と下痢も加わって尿量が減り、無尿に近づいている。腎前性を中心とした急性腎障害を起こしやすい状態である。

出典：厚生労働省ホームページ 第115回医師国家試験 A026', '{"A": "ネフローゼでは水分は主に間質に移り、血管内の容量はむしろ減っているため、肺水腫は起こりにくい。呼吸状態も保たれている。", "B": "顔面の浮腫は強いが、ネフローゼ症候群で喉頭浮腫による気道閉塞を起こすことは考えにくい。", "C": "ネフローゼ症候群では凝固因子の増加と抗凝固因子の喪失で、むしろ血栓症を起こしやすい。", "E": "糖尿病を示す所見はなく、高血糖緊急症は考えにくい。"}'::jsonb, 'public', 'M', '115-A-26', '', 'pending', 'llm'),
('代謝・内分泌', '', 2, 'KOKUSHI', '54歳の女性。倦怠感を主訴に来院した。進行卵巣癌のため10日前に外来で薬物による抗癌治療を受けた。その後、水分は多めに摂取するようにしていたという。3日前から倦怠感が出現したため受診した。意識は清明。脈拍60/分、整。血圧134/86mmHg。皮膚のツルゴールの低下を認めない。下腹部に径11cmの腫瘤を触知する。腹水はない。血液生化学所見:クレアチニン0.8mg/dL、尿酸3.2 mg/dL、Na124mEq/L、Cl102mEq/L、コルチゾール6.6μg/dL (基準5.2〜12.6)。血清浸透圧は250mOsm/L(基準275〜288)で低値、尿浸透圧は390 mOsm/Lで高値、尿中Naは45mEq/Lで高値であった。胸部エックス線写真で心拡大を認めない。血清浸透圧の低下に対してまず行うのはどれか。', '[{"key": "A", "text": "水分の制限"}, {"key": "B", "text": "生理食塩液の点滴投与"}, {"key": "C", "text": "5%ブドウ糖液の点滴投与"}, {"key": "D", "text": "塩化ナトリウムの経口投与"}, {"key": "E", "text": "カルシウム拮抗薬の経口投与"}]'::jsonb, 'A', '正答は A「水分の制限」。

低ナトリウム血症で血清浸透圧が低いのに尿は濃く、尿中Naも多い。脱水も浮腫もなく、腎機能とコルチゾールは正常で、尿酸は低い。抗癌薬によるSIADHと考え、まず水分を制限する。

出典：厚生労働省ホームページ 第115回医師国家試験 A045', '{"B": "体液量の保たれたSIADHでは、生理食塩液を入れてもNaは尿に出て水が残り、かえって低ナトリウム血症が悪化することがある。", "C": "ブドウ糖液は自由水を補うことになり、低ナトリウム血症を悪化させる。", "D": "水分制限で改善しないときに食塩の補充を加えることはあるが、まず行うのは水分の制限である。", "E": "カルシウム拮抗薬は降圧薬で、低ナトリウム血症の治療にはならない。"}'::jsonb, 'public', 'M', '115-A-45', '', 'pending', 'llm'),
('医学総論', '', 2, 'KOKUSHI', 'ランダム化比較試験〈RCT〉について正しいのはどれか。', '[{"key": "A", "text": "内的妥当性が高い。"}, {"key": "B", "text": "二重盲検を要件とする。"}, {"key": "C", "text": "第1相臨床試験で用いられる。"}, {"key": "D", "text": "メタ分析〈メタアナリシス〉の一種である。"}, {"key": "E", "text": "観察研究に比べて交絡因子の影響が大きい。"}]'::jsonb, 'A', '正答は A「内的妥当性が高い。」。

ランダム化によって、既知の交絡因子も未知の交絡因子も介入群と対照群に均等に分かれるため、群間の差を介入の効果と結論しやすい。これが内的妥当性の高さで、RCTが因果関係の検証に最も強い研究デザインとされる理由である。

出典：厚生労働省ホームページ 第115回医師国家試験 B006', '{"B": "盲検化は望ましいが要件ではなく、手術と薬物療法の比較のように盲検化できないRCTもある。", "C": "第1相試験は少数の健常者などで安全性や薬物動態を調べるもので、多くは比較群を置かない。RCTは主に第3相で用いる。", "D": "メタ分析は複数の研究の結果を統合する方法で、RCTはその材料となる個々の研究である。", "E": "ランダム化により、交絡因子の影響は観察研究より小さくなる。"}'::jsonb, 'public', 'M', '115-B-6', '', 'pending', 'llm'),
('婦人科・乳腺外科', '', 2, 'KOKUSHI', '子宮内膜症を強く疑う所見はどれか。', '[{"key": "A", "text": "下腹部の筋性防御"}, {"key": "B", "text": "圧痛のある硬い子宮"}, {"key": "C", "text": "柔らかく腫大した子宮"}, {"key": "D", "text": "直腸子宮窩〈Douglas窩〉の有痛性硬結"}, {"key": "E", "text": "可動性の良い無痛性で柔らかい球状腫瘤"}]'::jsonb, 'D', '正答は D「直腸子宮窩〈Douglas窩〉の有痛性硬結」。

子宮内膜症では、Douglas窩や仙骨子宮靱帯の病変が癒着・線維化し、内診や直腸診で痛みを伴う硬結として触れる。子宮の後屈固定や、付属器のチョコレート嚢胞もみられる。

出典：厚生労働省ホームページ 第115回医師国家試験 B009', '{"A": "筋性防御は腹膜炎の徴候で、子宮内膜症に特有の所見ではない。", "B": "硬く腫大して圧痛のある子宮は子宮腺筋症でみられる所見で、子宮内膜症を強く疑う所見ではない。", "C": "柔らかく大きな子宮は妊娠子宮の所見である。", "E": "可動性がよく痛みのない柔らかな腫瘤は良性の卵巣嚢腫でみられる。内膜症性の嚢胞は癒着して動きにくい。"}'::jsonb, 'public', 'M', '115-B-9', '', 'pending', 'llm'),
('医学総論', '', 2, 'KOKUSHI', '採取した血液を容器に分注する際、検体量の不足による測定値への影響が大きいのはどれか。', '[{"key": "A", "text": "ALT"}, {"key": "B", "text": "白血球数"}, {"key": "C", "text": "ナトリウム"}, {"key": "D", "text": "クレアチニン"}, {"key": "E", "text": "活性化部分トロンボプラスチン時間〈APTT〉"}]'::jsonb, 'E', '正答は E「活性化部分トロンボプラスチン時間〈APTT〉」。

凝固検査の採血管には一定量のクエン酸ナトリウムが入っており、血液9に対して1の割合で混ざるように作られている。採血量が足りないと抗凝固薬が相対的に多くなり、APTTやPTが見かけ上延長する。

出典：厚生労働省ホームページ 第115回医師国家試験 B020', '{"A": "ALTは血清の酵素で、採血量が少なくても測定値は変わらない。", "B": "血算用のEDTA管は採血量の多少の影響が小さく、白血球数はほとんど変わらない。", "C": "血清のナトリウムは採血量の影響を受けない。", "D": "血清のクレアチニンは採血量の影響を受けない。"}'::jsonb, 'public', 'M', '115-B-20', '', 'pending', 'llm'),
('感染症', '', 2, 'KOKUSHI', '26歳の男性。研修医。診療中にHIV抗原・抗体陽性者の体液に曝露したことを指導医に報告してきた。オートバイの転倒事故による多発外傷で救急搬送された38歳の男性患者の診療をした。意識障害のため当初は患者の基本情報がなかったが、駆け付けた患者家族によりHIV感染者であることが判明した。事実が判明するまでに、研修医は気管挿管、末梢静脈路の確保、血液検体採取、尿道カテーテル留置を行った。いずれも標準予防策として手袋、サージカルマスク及びプラスチックエプロンを着用した。針刺しなどの受傷はないが、尿道カテーテル留置の際に腕の皮膚に患者の尿が飛散した。研修医に対する指導医の対応として誤っているのはどれか。', '[{"key": "A", "text": "尿が付着した皮膚を流水と石けんで洗浄させる。"}, {"key": "B", "text": "尿が付着した皮膚に外傷がないか確認する。"}, {"key": "C", "text": "患者の血液が付着していないか確認する。"}, {"key": "D", "text": "直ちに抗HIV薬の内服を開始させる。"}, {"key": "E", "text": "研修医の心理的反応に配慮する。"}]'::jsonb, 'D', '正答は D「直ちに抗HIV薬の内服を開始させる。」。

HIVの感染源になるのは血液や血液の混じった体液、精液、腟分泌液などで、血液の混じっていない尿は感染の危険のない体液とされる。傷のない皮膚への付着でもあり、曝露後予防として抗HIV薬を飲む必要はない。

出典：厚生労働省ホームページ 第115回医師国家試験 B033', '{"A": "付着した体液はすぐに流水と石けんで洗い流す。適切である。", "B": "皮膚に傷や皮膚炎があれば危険度の評価が変わるため、確かめる。適切である。", "C": "血液が付いていれば曝露の評価が変わるので、確かめる。適切である。", "E": "曝露した医療者は強い不安を抱くため、心理面に配慮して支える。適切である。"}'::jsonb, 'public', 'M', '115-B-33', '', 'pending', 'llm'),
('循環器', '', 2, 'KOKUSHI', '59歳の男性。1時間持続する前胸部痛のために救急車で搬入された。現病歴 : 1か月前から階段昇降時に前胸部絞扼感を自覚していたが、安静にすると5分間ほどで消失した。本日早朝に前胸部絞扼感で覚醒した。しばらく我慢していたが次第に増強し、自力で歩けなくなったため救急搬送された。既往歴 : 5年前から高血圧症で降圧薬を服用している。生活歴 : 自営業。喫煙は20本/日を39年間。飲酒はビールを500mL/日。現症 : 意識は清明。身長168cm、体重82kg。体温36.6°C。心拍数104/分、整。血圧160/94mmHg。呼吸数24/分。SpO296%(room air)。冷汗を伴い、四肢は冷たい。心雑音はないが、奔馬調律を聴取する。呼吸音に異常を認めない。腹部は平坦で、肝・脾を触知しない。下肢に浮腫を認めない。検査所見 : 心電図では明らかなST-T変化を認めない。急性心筋梗塞を疑い、心筋トロポニンTを測定することとした。発症からの時間経過から感度は60%、特異度は90%であるとする。この患者の検査前確率を80%と考えたが、結果は陰性であった。
陰性結果にもかかわらず急性心筋梗塞である確率はどれか。', '[{"key": "A", "text": "80%"}, {"key": "B", "text": "72%"}, {"key": "C", "text": "64%"}, {"key": "D", "text": "54%"}, {"key": "E", "text": "50%"}]'::jsonb, 'C', '正答は C「64%」。

検査後の確率は「事前オッズ×尤度比」で求める。検査前確率80%の事前オッズは0.8/0.2＝4。陰性尤度比は(1−感度)/特異度＝0.4/0.9≒0.44なので、事後オッズは4×0.44≒1.78、事後確率は1.78/(1+1.78)≒0.64で64%になる。感度60%の検査が陰性でも、これだけ疑わしい患者では6割以上が心筋梗塞であり、陰性を理由に帰宅させてはいけない。

出典：厚生労働省ホームページ 第115回医師国家試験 B041', '{"A": "検査前確率をそのまま答えた値で、陰性という結果をまったく反映していない。", "B": "0.8×0.9のように確率と特異度を直接掛けた形の値で、尤度比を使う手順になっていない。", "D": "0.6×0.9のように感度と特異度を掛けた形の値で、事前オッズを経由していない。", "E": "確率が求まらないときの「半々」に相当する値で、与えられた数値から導けない。"}'::jsonb, 'public', 'M', '115-B-41', '', 'pending', 'llm'),
('循環器', '', 2, 'KOKUSHI', '59歳の男性。1時間持続する前胸部痛のために救急車で搬入された。現病歴 : 1か月前から階段昇降時に前胸部絞扼感を自覚していたが、安静にすると5分間ほどで消失した。本日早朝に前胸部絞扼感で覚醒した。しばらく我慢していたが次第に増強し、自力で歩けなくなったため救急搬送された。既往歴 : 5年前から高血圧症で降圧薬を服用している。生活歴 : 自営業。喫煙は20本/日を39年間。飲酒はビールを500mL/日。現症 : 意識は清明。身長168cm、体重82kg。体温36.6°C。心拍数104/分、整。血圧160/94mmHg。呼吸数24/分。SpO296%(room air)。冷汗を伴い、四肢は冷たい。心雑音はないが、奔馬調律を聴取する。呼吸音に異常を認めない。腹部は平坦で、肝・脾を触知しない。下肢に浮腫を認めない。検査所見 : 心電図では明らかなST-T変化を認めない。急性心筋梗塞を疑い、心筋トロポニンTを測定することとした。発症からの時間経過から感度は60%、特異度は90%であるとする。この患者の検査前確率を80%と考えたが、結果は陰性であった。
検査の結果は陰性であったが、担当医は病歴や症状から急性冠症候群である可能性が否定できないと判断し、患者にここまでの状況を説明することとした。担当医が患者にかける言葉の中で、説明内容に対する患者の理解を確認しているものはどれか。', '[{"key": "A", "text": "「治療法について何かご希望はありますか」"}, {"key": "B", "text": "「今までの説明で分からないことはありますか」"}, {"key": "C", "text": "「今後についてご家族に話したほうが良いですか」"}, {"key": "D", "text": "「なぜこの病気になってしまったとお考えですか」"}, {"key": "E", "text": "「こちらの病院で検査と治療を受けるのでよろしいでしょうか」"}]'::jsonb, 'B', '正答は B「「今までの説明で分からないことはありますか」」。

説明したことが伝わったかを確かめるには、患者の側に分からない点が残っていないかを開かれた形で尋ねる。「今までの説明で分からないことはありますか」はそのための問いで、理解の確認にあたる。

出典：厚生労働省ホームページ 第115回医師国家試験 B042', '{"A": "治療法の希望を聞くのは、患者の意向・価値観の確認であって理解の確認ではない。", "C": "家族へ話すかどうかは、情報を共有する範囲の確認である。", "D": "病気の原因をどう考えているかを聞くのは、患者自身の解釈を知るための問いである。", "E": "この病院で受けるかを尋ねるのは、方針への同意の確認である。"}'::jsonb, 'public', 'M', '115-B-42', '', 'pending', 'llm'),
('消化管', '', 2, 'KOKUSHI', '36歳の女性。頭痛を主訴に来院した。現病歴 : 本日午前7時頃から視界にきらきらした点が現れ、その後に頭痛、悪心が出現したため、同日昼に病院を受診した。頭痛は徐々に出現し、増悪はしていない。21歳時から年に数回同様の頭痛を経験しており、頭痛は毎回1日で改善する。今回よりも強い頭痛を経験したことがあるという。既往歴 : 5歳時に急性虫垂炎で手術。生活歴 : 喫煙歴はない。飲酒は機会飲酒。家族歴 : 母が頭痛持ちであった。現症 : 意識は清明。身長160cm、体重50kg。体温36.5°C。脈拍72/分、整。血圧126/76mmHg。呼吸数12/分。SpO298%(room air)。眼瞼結膜に貧血を認めない。瞳孔は左右差なく、対光反射は迅速。眼球運動に異常は認めない。心音と呼吸音とに異常を認めない。項部硬直を認めない。四肢の筋力は保たれており、感覚障害も認めない。四肢の腱反射は正常であり、病的反射は認めない。検査所見 : 血液所見:赤血球372万、Hb12.2g/dL、Ht40%、白血球6,800、血小板16万。血液生化学所見:AST29U/L、ALT21U/L、LD171U/L(基準120〜245)、ALP350U/L(基準115〜359)、尿素窒素10mg/dL、クレアチニン0.5mg/dL、Na135mEq/L、K4.2mEq/L、Cl98mEq/L。CRP0.1mg/dL。頭痛に関する文献を調べると、「突然発症である」、「増悪している」、「これまで経験した中で最悪の頭痛である」の3項目について、該当項目数に応じた重篤な原因による頭痛の尤度比が以下のように掲載されていた。該当項目数 — 重篤な原因による頭痛の尤度比0 — 0.1 1 — 2.1 2 — 9.1 3 — 12.5
この患者が重篤な原因による頭痛を起こしている可能性について、事前確率と比べた事後確率の変化として適切なのはどれか。', '[{"key": "A", "text": "高くなる。"}, {"key": "B", "text": "低くなる。"}, {"key": "C", "text": "変化しない。"}, {"key": "D", "text": "計算できない。"}, {"key": "E", "text": "事前オッズにより異なる。"}]'::jsonb, 'B', '正答は B「低くなる。」。

3項目のいずれにも当てはまらない。頭痛は徐々に出現して増悪しておらず、これまでにもっと強い頭痛を経験している。当てはまる項目がないときの尤度比は0.1で、1より小さいため、事後オッズは事前オッズより小さくなり、重篤な原因である確率は低くなる。

出典：厚生労働省ホームページ 第115回医師国家試験 B043', '{"A": "尤度比が1より小さいので、確率は上がらない。", "C": "尤度比がちょうど1のときだけ変化しない。0.1なので確率は動く。", "D": "事前オッズに尤度比を掛ければ求まるので、計算できないわけではない。", "E": "事後確率の値は事前オッズによって変わるが、尤度比が1未満である以上「低くなる」という向きは変わらない。"}'::jsonb, 'public', 'M', '115-B-43', '', 'pending', 'llm'),
('消化管', '', 2, 'KOKUSHI', '36歳の女性。頭痛を主訴に来院した。現病歴 : 本日午前7時頃から視界にきらきらした点が現れ、その後に頭痛、悪心が出現したため、同日昼に病院を受診した。頭痛は徐々に出現し、増悪はしていない。21歳時から年に数回同様の頭痛を経験しており、頭痛は毎回1日で改善する。今回よりも強い頭痛を経験したことがあるという。既往歴 : 5歳時に急性虫垂炎で手術。生活歴 : 喫煙歴はない。飲酒は機会飲酒。家族歴 : 母が頭痛持ちであった。現症 : 意識は清明。身長160cm、体重50kg。体温36.5°C。脈拍72/分、整。血圧126/76mmHg。呼吸数12/分。SpO298%(room air)。眼瞼結膜に貧血を認めない。瞳孔は左右差なく、対光反射は迅速。眼球運動に異常は認めない。心音と呼吸音とに異常を認めない。項部硬直を認めない。四肢の筋力は保たれており、感覚障害も認めない。四肢の腱反射は正常であり、病的反射は認めない。検査所見 : 血液所見:赤血球372万、Hb12.2g/dL、Ht40%、白血球6,800、血小板16万。血液生化学所見:AST29U/L、ALT21U/L、LD171U/L(基準120〜245)、ALP350U/L(基準115〜359)、尿素窒素10mg/dL、クレアチニン0.5mg/dL、Na135mEq/L、K4.2mEq/L、Cl98mEq/L。CRP0.1mg/dL。頭痛に関する文献を調べると、「突然発症である」、「増悪している」、「これまで経験した中で最悪の頭痛である」の3項目について、該当項目数に応じた重篤な原因による頭痛の尤度比が以下のように掲載されていた。該当項目数 — 重篤な原因による頭痛の尤度比0 — 0.1 1 — 2.1 2 — 9.1 3 — 12.5
この頭痛の特徴はどれか。', '[{"key": "A", "text": "男性に多い。"}, {"key": "B", "text": "高齢者に多い。"}, {"key": "C", "text": "光過敏を伴う。"}, {"key": "D", "text": "NSAIDは無効である。"}, {"key": "E", "text": "動き回ると痛みが軽減する。"}]'::jsonb, 'C', '正答は C「光過敏を伴う。」。

きらきらした点が見えた後に頭痛と悪心が続いており、前兆（閃輝暗点）を伴う片頭痛である。片頭痛では光や音に過敏になり、暗く静かな場所で休むと楽になる。

出典：厚生労働省ホームページ 第115回医師国家試験 B044', '{"A": "片頭痛は女性に多い。本例も母が頭痛持ちで、家族内発症が多いことも特徴である。", "B": "思春期から40歳代に多く、加齢とともにむしろ減っていく。", "D": "軽度から中等度の発作にはNSAIDが有効で、効かないときにトリプタンを用いる。", "E": "体を動かすと拍動性の痛みが強まるのが片頭痛の特徴で、軽減はしない。"}'::jsonb, 'public', 'M', '115-B-44', '', 'pending', 'llm'),
('救急・中毒', '', 2, 'KOKUSHI', '43歳の男性。熱傷のため救急車で搬入された。現病歴 : 揚げ物の調理中に着衣に着火し、職場の同僚が救急要請した。既往歴 : 高血圧症と脂質異常症について食事療法中。生活歴 : 飲食店の調理場で働いている。喫煙は10本/日を10年間、飲酒はビールを350mL/日。妻と2人暮らし。家族歴 : 両親が高血圧症。現症 : 意識レベルはJCSII-10。身長170cm、体重70kg。体温37.1°C。心拍数90/分、整。血圧90/60mmHg。呼吸数36/分。SpO293%(リザーバー付マスク10L/分酸素投与下)。頭髪の前面と眉毛が焦げている。顔面、両上肢および胸腹部に、38%TBSA〈total body surface area〉の II〜III度熱傷を認める。口腔と咽頭の粘膜には煤が付着していた。嗄声が認められる。検査所見 : 血液所見:赤血球550万、Hb17.0g/dL、Ht49%、白血球7,200、血小板30万。血液生化学所見:総蛋白6.1g/dL、AST45U/L、ALT17U/L、LD499U/L(基準120〜245)、尿素窒素22mg/dL、クレアチニン0.5mg/dL、Na 132mEq/L、K4.4mEq/L、Cl99mEq/L。
搬入時の輸液として適切なのはどれか。', '[{"key": "A", "text": "10%食塩液"}, {"key": "B", "text": "新鮮凍結血漿"}, {"key": "C", "text": "5%ブドウ糖液"}, {"key": "D", "text": "乳酸リンゲル液"}, {"key": "E", "text": "25%アルブミン液"}]'::jsonb, 'D', '正答は D「乳酸リンゲル液」。

広範囲熱傷では受傷直後から血管の透過性が高まり、大量の血漿成分が漏れ出て循環血液量が減る（熱傷ショック）。初期輸液には乳酸リンゲル液などの細胞外液を用い、Baxter法（4mL×体重×熱傷面積%、最初の8時間で半量）を目安に、尿量をみながら調整する。

出典：厚生労働省ホームページ 第115回医師国家試験 B045', '{"A": "10%食塩液は高ナトリウム血症の危険が大きく、熱傷の初期輸液の標準ではない。", "B": "新鮮凍結血漿は凝固因子の補充に用いる製剤で、熱傷の初期輸液には使わない。", "C": "ブドウ糖液は自由水となって細胞内に移り、循環血液量を保てない。", "E": "受傷早期は血管の透過性が高く、アルブミンも漏れ出るため、初期輸液には使わない。"}'::jsonb, 'public', 'M', '115-B-45', '', 'pending', 'llm'),
('救急・中毒', '', 2, 'KOKUSHI', '43歳の男性。熱傷のため救急車で搬入された。現病歴 : 揚げ物の調理中に着衣に着火し、職場の同僚が救急要請した。既往歴 : 高血圧症と脂質異常症について食事療法中。生活歴 : 飲食店の調理場で働いている。喫煙は10本/日を10年間、飲酒はビールを350mL/日。妻と2人暮らし。家族歴 : 両親が高血圧症。現症 : 意識レベルはJCSII-10。身長170cm、体重70kg。体温37.1°C。心拍数90/分、整。血圧90/60mmHg。呼吸数36/分。SpO293%(リザーバー付マスク10L/分酸素投与下)。頭髪の前面と眉毛が焦げている。顔面、両上肢および胸腹部に、38%TBSA〈total body surface area〉の II〜III度熱傷を認める。口腔と咽頭の粘膜には煤が付着していた。嗄声が認められる。検査所見 : 血液所見:赤血球550万、Hb17.0g/dL、Ht49%、白血球7,200、血小板30万。血液生化学所見:総蛋白6.1g/dL、AST45U/L、ALT17U/L、LD499U/L(基準120〜245)、尿素窒素22mg/dL、クレアチニン0.5mg/dL、Na 132mEq/L、K4.4mEq/L、Cl99mEq/L。
気道熱傷と診断し、気管挿管を行った。換気を行った際、気管内に正しく挿管が行われていないと判断されるものはどれか。', '[{"key": "A", "text": "呼気にCO2が検出される。"}, {"key": "B", "text": "胸郭の動きが左右対称である。"}, {"key": "C", "text": "心窩部で送気音が聴取される。"}, {"key": "D", "text": "両側肺野で同等の呼吸音が聴取される。"}, {"key": "E", "text": "気管チューブ内壁に呼気時の曇りがみられる。"}]'::jsonb, 'C', '正答は C「心窩部で送気音が聴取される。」。

換気のたびに心窩部で送気音が聞こえるのは、チューブが食道に入り胃に空気を送っているためである。直ちにチューブを抜いて挿管し直す。気管内にあることの確認には、呼気の二酸化炭素の検出を用いるのが最も確実である。

出典：厚生労働省ホームページ 第115回医師国家試験 B046', '{"A": "呼気の二酸化炭素が続けて検出されるのは、気管内に入っていることの最も確かな証拠である。", "B": "胸郭が左右対称に上がるのは、正しく挿管されているときの所見である。", "D": "両側で同じように呼吸音が聞こえれば、片肺挿管もなく正しい位置にある。", "E": "呼気時の曇りは気管内にあることを示唆する所見である（単独では確実ではない）。"}'::jsonb, 'public', 'M', '115-B-46', '', 'pending', 'llm'),
('医学総論', '', 2, 'KOKUSHI', '37歳の女性。全身倦怠感と頭痛を主訴に来院した。現病歴 : 半年前から倦怠感を自覚していた。3か月前から頭痛も出現するようになった。1か月前からは起きた時にも強い全身倦怠感があるため、仕事を休むようになった。頭痛の程度は軽いが、2か月前に脇から出てくる自転車に気付かずに接触し、転倒したことがあった。
さらに情報を集めるとき、システムレビューに相当する質問はどれか。', '[{"key": "A", "text": "「血の繋がった方で、何かご病気をされた方はいますか」"}, {"key": "B", "text": "「ご自分ではどのような病気を心配されていますか」"}, {"key": "C", "text": "「これまでに大きな病気をしたことはありますか」"}, {"key": "D", "text": "「頭痛はどのような痛みですか」"}, {"key": "E", "text": "「食欲や睡眠はいかがですか」"}]'::jsonb, 'E', '正答は E「「食欲や睡眠はいかがですか」」。

システムレビューは、主訴とは直接関係がなさそうな全身の症状を系統立てて漏れなく聞く手順で、食欲、睡眠、体重の変化、排便・排尿などを尋ねる。

出典：厚生労働省ホームページ 第115回医師国家試験 B047', '{"A": "血縁者の病気を尋ねるのは家族歴の聴取である。", "B": "患者自身の考えや心配（解釈モデル）を尋ねる質問である。", "C": "これまでの病気を尋ねるのは既往歴の聴取である。", "D": "主訴である頭痛の性状は、現病歴として聞く。"}'::jsonb, 'public', 'M', '115-B-47', '', 'pending', 'llm'),
('代謝・内分泌', '', 2, 'KOKUSHI', '37歳の女性。全身倦怠感と頭痛を主訴に来院した。現病歴 : 半年前から倦怠感を自覚していた。3か月前から頭痛も出現するようになった。1か月前からは起きた時にも強い全身倦怠感があるため、仕事を休むようになった。頭痛の程度は軽いが、2か月前に脇から出てくる自転車に気付かずに接触し、転倒したことがあった。
さらに医療面接と診察を進めた。現病歴 : 頭痛は眼の奥が重く痛むようなものである。3か月前から無月経になっている。食欲も落ちており、体重は半年で3kg低下している。癌なのではないかと心配している。睡眠障害はない。3か月前から便秘が悪化している。既往歴 : 特記すべきことはない。生活歴 : 会社員。夫と子どもと3人暮らし。喫煙歴と飲酒歴はない。家族歴 : 特記すべきことはない。現症 : 意識は清明。身長153cm、体重48.2kg。脈拍72/分、整。血圧98/56 mmHg。呼吸数16/分。眼瞼結膜と眼球結膜とに異常を認めない。甲状腺腫を認めない。胸部では乳頭の圧迫で白色乳汁分泌を認める。腹部に異常を認めない。両耳側半盲を認める。検査所見 : 血液所見:赤血球357万、Hb11.1g/dL、Ht34%、白血球4,200、血小板18万。血液生化学所見:AST21U/L、ALT14U/L、LD146U/L(基準120〜245)、尿素窒素15mg/dL、クレアチニン0.7mg/dL、血糖78mg/dL、Na 131mEq/L、K4.4mEq/L、Cl97mEq/L。内分泌検査所見:ACTH9pg/mL(基準60以下)、コルチゾール1.9μg/dL(基準5.2〜12.6)、TSH0.76μU/mL(基準0.500〜5.00)、FT32.27pg/mL (基準2.30〜4.30)、FT40.51ng/dL (基準0.90〜1.70)、 LH0.3mIU/mL (基準1.8〜7.6)、 FSH4.4mIU/mL (基準5.2〜14.4)、エストラジオール <10pg/mL(基準11〜230)、プロゲステロン0.2 ng/mL(基準0.5以下)、プロラクチン198ng/mL(基準15以下)。頭部造影MRIで下垂体腺腫を認める。
治療で誤っているのはどれか。', '[{"key": "A", "text": "薬物療法で腫瘍の縮小が期待できる。"}, {"key": "B", "text": "発熱時は副腎皮質ステロイド補充を減量する。"}, {"key": "C", "text": "手術を行う場合、下垂体機能評価を事前に行う。"}, {"key": "D", "text": "ホルモン補充は副腎皮質ステロイドから開始する。"}, {"key": "E", "text": "副腎皮質ステロイド補充開始後は尿崩症の出現に注意する。"}]'::jsonb, 'B', '正答は B「発熱時は副腎皮質ステロイド補充を減量する。」。

両耳側半盲、乳汁分泌、プロラクチンの高値から下垂体腺腫（プロラクチノーマ）で、副腎・甲状腺・性腺の機能が低下している。発熱などのストレス時には副腎皮質ステロイドの補充量を2〜3倍に増やすのが原則で、減らすと副腎クリーゼを招く。

出典：厚生労働省ホームページ 第115回医師国家試験 B048', '{"A": "プロラクチノーマはカベルゴリンなどのドパミン作動薬でよく縮小する。正しい。", "C": "周術期の管理のため、手術の前に下垂体機能を評価しておく。正しい。", "D": "甲状腺ホルモンを先に補充すると代謝が高まって副腎不全が悪化するので、副腎皮質ステロイドから始める。正しい。", "E": "副腎皮質ステロイドには水の排泄を促す作用があり、補充を始めると隠れていた尿崩症が現れることがある。正しい。"}'::jsonb, 'public', 'M', '115-B-48', '', 'pending', 'llm'),
('血液', '', 2, 'KOKUSHI', '52歳の男性。腹部膨満感を主訴に来院した。現病歴 : 3週前から腹部膨満感を自覚するようになった。食欲はあるがすぐに満腹を感じ、食事摂取量が減っている。腹痛や悪心はない。便通は毎日あり、便の性状は以前と変わっていない。1か月で体重が1kg減少した。既往歴 : 特記すべきことはない。生活歴 : 会社員で事務職。喫煙歴はない。飲酒は機会飲酒。家族歴 : 父が高血圧症。母が糖尿病。現症 : 意識は清明。身長174cm、体重67kg。体温36.3°C。脈拍76/分、整。血圧124/78mmHg。呼吸数18/分。SpO298%(room air)。眼瞼結膜と眼球結膜に異常を認めない。心音と呼吸音とに異常を認めない。腹部はやや膨隆し、右肋骨弓下に肝を1cm、左肋骨弓下に脾を2cm触知する。臍左側に径8cmの弾性硬の無痛性腫瘤を触知し、可動性や呼吸性移動や拍動を認めない。両側頸部と鼠径部に径2〜3cmのリンパ節を複数触知する。いずれも弾性硬で可動性があり、圧痛はない。下腿に浮腫を認めない。検査所見 : 尿所見:蛋白(−)、潜血(−)。血液所見:赤血球452万、Hb14.5 g/dL、Ht41%、白血球7,200(好中球68%、好酸球2%、好塩基球0%、単球4%、リンパ球26%)、血小板37万。血液生化学所見:総蛋白6.5g/dL、アルブミン4.0g/dL、総ビリルビン0.3mg/dL、AST18U/L、ALT16U/L、LD765U/L(基準120〜245)、ALP221U/L(基準115〜359)、γ-GT28U/L(基準8〜50)、尿素窒素32mg/dL、クレアチニン0.6mg/dL、血糖98mg/dL、CEA3ng/mL(基準 5 以下)、CA19-9 12U/mL (基準37以下)。免疫血清学所見:CRP0.1 mg/dL、可溶性IL-2受容体5,920U/mL(基準157〜474)。
この患者でみられる身体所見はどれか。', '[{"key": "A", "text": "反跳痛"}, {"key": "B", "text": "腸雑音の亢進"}, {"key": "C", "text": "腹壁静脈の怒張"}, {"key": "D", "text": "Traube三角の濁音"}, {"key": "E", "text": "肋骨脊柱角の叩打痛"}]'::jsonb, 'D', '正答は D「Traube三角の濁音」。

頸部と鼠径部のリンパ節腫大、腹部の腫瘤、LDと可溶性IL-2受容体の著明な上昇から悪性リンパ腫を考える。脾が腫大しており、左季肋部のTraube三角（本来は胃泡で鼓音）が濁音になる。

出典：厚生労働省ホームページ 第115回医師国家試験 B049', '{"A": "反跳痛は腹膜炎の徴候で、腹痛も圧痛もない本例ではみられない。", "B": "腸雑音の亢進は腸閉塞や腸炎でみられる所見で、便通は正常である。", "C": "腹壁静脈の怒張は門脈圧亢進や下大静脈の閉塞でみられるが、肝機能は正常で浮腫もない。", "E": "肋骨脊柱角の叩打痛は腎盂腎炎や尿路結石でみられる所見である。"}'::jsonb, 'public', 'M', '115-B-49', '', 'pending', 'llm'),
('血液', '', 2, 'KOKUSHI', '52歳の男性。腹部膨満感を主訴に来院した。現病歴 : 3週前から腹部膨満感を自覚するようになった。食欲はあるがすぐに満腹を感じ、食事摂取量が減っている。腹痛や悪心はない。便通は毎日あり、便の性状は以前と変わっていない。1か月で体重が1kg減少した。既往歴 : 特記すべきことはない。生活歴 : 会社員で事務職。喫煙歴はない。飲酒は機会飲酒。家族歴 : 父が高血圧症。母が糖尿病。現症 : 意識は清明。身長174cm、体重67kg。体温36.3°C。脈拍76/分、整。血圧124/78mmHg。呼吸数18/分。SpO298%(room air)。眼瞼結膜と眼球結膜に異常を認めない。心音と呼吸音とに異常を認めない。腹部はやや膨隆し、右肋骨弓下に肝を1cm、左肋骨弓下に脾を2cm触知する。臍左側に径8cmの弾性硬の無痛性腫瘤を触知し、可動性や呼吸性移動や拍動を認めない。両側頸部と鼠径部に径2〜3cmのリンパ節を複数触知する。いずれも弾性硬で可動性があり、圧痛はない。下腿に浮腫を認めない。検査所見 : 尿所見:蛋白(−)、潜血(−)。血液所見:赤血球452万、Hb14.5 g/dL、Ht41%、白血球7,200(好中球68%、好酸球2%、好塩基球0%、単球4%、リンパ球26%)、血小板37万。血液生化学所見:総蛋白6.5g/dL、アルブミン4.0g/dL、総ビリルビン0.3mg/dL、AST18U/L、ALT16U/L、LD765U/L(基準120〜245)、ALP221U/L(基準115〜359)、γ-GT28U/L(基準8〜50)、尿素窒素32mg/dL、クレアチニン0.6mg/dL、血糖98mg/dL、CEA3ng/mL(基準 5 以下)、CA19-9 12U/mL (基準37以下)。免疫血清学所見:CRP0.1 mg/dL、可溶性IL-2受容体5,920U/mL(基準157〜474)。
胸腹部CTで後腹膜、縦隔などにも腫瘤を認めた。今後の治療方針を確定するために最も重要な検査はどれか。', '[{"key": "A", "text": "腹部MRI"}, {"key": "B", "text": "FDG-PET"}, {"key": "C", "text": "腹部血管造影検査"}, {"key": "D", "text": "表在リンパ節からの組織診"}, {"key": "E", "text": "後腹膜腫瘤からのCTガイド下穿刺吸引細胞診"}]'::jsonb, 'D', '正答は D「表在リンパ節からの組織診」。

悪性リンパ腫の治療方針は組織型で決まるため、リンパ節をまとめて取り出す生検で組織の構築と免疫染色を調べる。体表から取れる頸部や鼠径部の腫大リンパ節があれば、侵襲の少ないその生検を選ぶ。

出典：厚生労働省ホームページ 第115回医師国家試験 B050', '{"A": "病変の広がりの評価には役立つが、組織型は決められない。", "B": "病期の決定や治療効果の判定に用いるが、組織型の診断はできない。", "C": "腫瘤の血流はわかるが、診断にも治療方針の決定にも役立たない。", "E": "細胞診では組織の構築がわからず組織型の確定には足りない。深部の穿刺で侵襲も大きい。"}'::jsonb, 'public', 'M', '115-B-50', '', 'pending', 'llm'),
('医学総論', '', 2, 'KOKUSHI', '国際生活機能分類〈ICF〉について誤っているのはどれか。', '[{"key": "A", "text": "統計分類が主目的である。"}, {"key": "B", "text": "多職種間の共通理解に寄与する。"}, {"key": "C", "text": "障害を生活機能というプラス面からみる。"}, {"key": "D", "text": "背景因子には環境因子と個人因子がある。"}, {"key": "E", "text": "WHOの国際分類ファミリーのひとつである。"}]'::jsonb, 'A', '正答は A「統計分類が主目的である。」。

ICFは健康状態と生活機能を記述する共通の言葉として作られた分類で、統計にも使えるが、主な目的は当事者や多職種が状態を同じ枠組みで理解し、支援に生かすことにある。疾病や死因の統計を主な目的とするのはICDである。

出典：厚生労働省ホームページ 第115回医師国家試験 C008', '{"B": "共通の言葉で生活機能を記述でき、多職種の連携に役立つ。正しい。", "C": "障害を、心身機能・活動・参加という生活機能の面から中立的・肯定的にとらえる。正しい。", "D": "背景因子は環境因子と個人因子からなる。正しい。", "E": "ICDとともに、WHO国際分類ファミリーの中心分類の一つである。正しい。"}'::jsonb, 'public', 'M', '115-C-8', '', 'pending', 'llm'),
('公衆衛生', '', 2, 'KOKUSHI', 'WHOの活動にあてはまらないのはどれか。', '[{"key": "A", "text": "健康の定義"}, {"key": "B", "text": "識字率の向上"}, {"key": "C", "text": "たばこ規制の推進"}, {"key": "D", "text": "国際疾病分類〈ICD〉の改訂"}, {"key": "E", "text": "国際保健規則に基づく感染症対策"}]'::jsonb, 'B', '正答は B「識字率の向上」。

識字率の向上は教育の分野の課題で、主にUNESCO（国連教育科学文化機関）が担う。WHOは健康の定義、たばこ規制枠組条約、ICDの改訂、国際保健規則に基づく感染症対策などを担っている。

出典：厚生労働省ホームページ 第115回医師国家試験 C020', '{"A": "WHO憲章の前文で健康を定義している。WHOの活動である。", "C": "WHOたばこ規制枠組条約を採択し、推進している。", "D": "ICDはWHOが作成・改訂している（現行はICD-11）。", "E": "国際保健規則に基づき、感染症などの国際的な公衆衛生上の脅威に対応している。"}'::jsonb, 'public', 'M', '115-C-20', '', 'pending', 'llm'),
('公衆衛生', '', 2, 'KOKUSHI', '50歳の男性。職場の定期健康診断を受けた結果、高血圧を指摘された。その結果を踏まえたトータルヘルスプロモーションプラン〈THP〉に含まれないのはどれか。', '[{"key": "A", "text": "禁煙指導"}, {"key": "B", "text": "降圧薬の処方"}, {"key": "C", "text": "運動の計画立案"}, {"key": "D", "text": "塩分制限食の調理指導"}, {"key": "E", "text": "生活習慣の改善に伴う精神的ストレスのケア"}]'::jsonb, 'B', '正答は B「降圧薬の処方」。

THPは事業場で行う心とからだの健康づくりで、健康測定に基づいて運動指導、メンタルヘルスケア、栄養指導、保健指導を行う。降圧薬の処方は医療機関での治療であり、THPには含まれない。

出典：厚生労働省ホームページ 第115回医師国家試験 C037', '{"A": "喫煙などの生活習慣の改善を促す保健指導に含まれる。", "C": "運動の計画を立てて実践を支える運動指導は、THPの柱の一つである。", "D": "食生活の改善を支える栄養指導に含まれる。", "E": "生活習慣を変える際のストレスへのケアは、メンタルヘルスケアとしてTHPに含まれる。"}'::jsonb, 'public', 'M', '115-C-37', '', 'pending', 'llm'),
('救急・中毒', '', 2, 'KOKUSHI', '34歳の男性。右下腿の外傷のため救急車で搬入された。5時間前に倉庫での荷物運搬の作業中に、崩れた荷物に右下腿を挟まれて受傷した。救急隊による救出までの間、長時間挟まれていたという。意識は清明。体温36.2°C。心拍数96/分、整。血圧85/40mmHg。呼吸数32/分。SpO295%(room air)。右下腿に腫脹と変形を認めるが、皮膚の損傷はない。足部の感覚と運動に異常を認めない。その他の部位に外傷はない。尿所見:赤色、蛋白(−)、糖(−)、ケトン体(−)、潜血3+。検査所見:血液所見:赤血球400万、Hb13.9g/dL、Ht54%、白血球11,000(桿状核好中球20%、分葉核好中球50%、好酸球1%、好塩基球1%、単球8%、リンパ球20%)、血小板38万。血液生化学所見:総蛋白6.5g/dL、アルブミン4.6 g/dL、総ビリルビン1.3mg/dL、AST125U/L、ALT60U/L、LD570U/L(基準120〜245)、ALP343U/L(基準115〜359)、CK6,350U/L(基準30〜140)、尿素窒素10.2mg/dL、クレアチニン0.8mg/dL、尿酸7.6mg/dL、血糖98mg/dL、Na 137mEq/L、K5.1mEq/L、Cl100mEq/L。CRP0.84mg/dL。動脈血ガス分析:pH7.30、PaCO225Torr、PaO2105Torr、HCO3−12mEq/L。右下腿エックス線写真で、脛骨および腓骨の骨幹部骨折を認めた。今後起こり得る病態として最も注意すべきなのはどれか。', '[{"key": "A", "text": "菌血症"}, {"key": "B", "text": "急性肝不全"}, {"key": "C", "text": "急性腎障害"}, {"key": "D", "text": "急性心筋梗塞"}, {"key": "E", "text": "急性腸管壊死"}]'::jsonb, 'C', '正答は C「急性腎障害」。

長時間挟まれていた下腿の筋が壊死し、CKの著しい上昇、赤色で潜血が強陽性の尿（ミオグロビン尿）、代謝性アシドーシスを認める。圧挫症候群で、ミオグロビンによる尿細管の障害と循環血液量の減少から急性腎障害を起こしやすい。大量の輸液で尿量を保つ。

出典：厚生労働省ホームページ 第115回医師国家試験 C047', '{"A": "皮膚に傷のない閉鎖性の骨折で、菌血症を最も警戒すべき状況ではない。", "B": "ASTやLDの上昇は筋の崩壊によるもので、肝不全を示すものではない。", "D": "高カリウム血症による不整脈には注意するが、心筋梗塞を起こす病態ではない。", "E": "腹部の外傷はなく、腸管の虚血を示す所見もない。"}'::jsonb, 'public', 'M', '115-C-47', '', 'pending', 'llm'),
('血液', '', 2, 'KOKUSHI', '4歳の男児。鼻出血を主訴に母親に連れられて来院した。朝から鼻出血があり、夕方になっても止まらないため心配した母親に連れられて受診した。2歳ころから鼻出血を繰り返しており、いつも止血するまでに3〜4時間要した。関節内出血や筋肉内出血の既往はない。父親に同様の出血傾向がある。身長104cm、体重15.4 kg。体表に出血斑を認めない。血液所見:赤血球312万、Hb10.2g/dL、Ht31%、白血球8,900、血小板18万、出血時間延長、PT-INR1.0(基準0.9〜1.1)、APTT48.4秒(基準対照32.2)。最も考えられるのはどれか。', '[{"key": "A", "text": "血友病A"}, {"key": "B", "text": "von Willebrand病"}, {"key": "C", "text": "ビタミンK欠乏症"}, {"key": "D", "text": "IgA血管炎〈Schönlein-Henoch紫斑病〉"}, {"key": "E", "text": "遺伝性出血性末梢血管拡張症〈Osler病〉"}]'::jsonb, 'B', '正答は B「von Willebrand病」。

鼻出血を繰り返す粘膜出血型の出血傾向で、出血時間とAPTTがともに延長し、血小板数とPTは正常である。父親にも同じ出血傾向があり（常染色体顕性遺伝）、von Willebrand病を考える。VWFが少ないと血小板の粘着が落ち、VWFに守られている第VIII因子も減るためAPTTも延長する。

出典：厚生労働省ホームページ 第115回医師国家試験 C051', '{"A": "血友病AはX連鎖性で父から息子には遺伝せず、関節内や筋肉内の出血が特徴で、出血時間は正常である。", "C": "ビタミンK欠乏ではPTが延長する。", "D": "IgA血管炎は下肢の紫斑、腹痛、関節痛を示し、凝固検査は正常である。", "E": "Osler病も鼻出血を繰り返すが、原因は血管の拡張で、出血時間やAPTTは正常である。"}'::jsonb, 'public', 'M', '115-C-51', '', 'pending', 'llm'),
('救急・中毒', '', 2, 'KOKUSHI', '82歳の女性。発熱と意識障害のため救急車で搬入された。現病歴 : 3日前から発熱し、食事もむせるようになった。本日朝から呼びかけへの反応が乏しくなった。既往歴 : 72歳時からAlzheimer型認知症に対してドネペジルを内服中である。生活歴 : ADLは車いす移動。2年前からサービス付き高齢者向け住宅に入居している。家族歴 : 特記すべきことはない。現症 : 呼びかけにより開眼し「苦しい」と発語はあるが問いかけには答えられない。痛み刺激に対して手で払いのける。体温38.2°C。心拍数40/分、整。血圧140/90mmHg。呼吸数24/分。SpO292%(リザーバー付マスク10L/分酸素投与下)。瞳孔は高度に縮瞳し、対光反射は消失している。鼻汁、流涎および発汗がみられる。運動麻痺を認めない。腱反射の異常を認めない。両側肺底部にcoarse cracklesを聴取する。腹部は平坦、軟で、肝・脾を触知しない。下腿に浮腫を認めない。下肢に筋力低下を認める。
流涎に対して最初に行うべき処置はどれか。', '[{"key": "A", "text": "気管挿管"}, {"key": "B", "text": "口腔内吸引"}, {"key": "C", "text": "経鼻胃管挿入"}, {"key": "D", "text": "輪状甲状靱帯穿刺"}, {"key": "E", "text": "経鼻エアウェイ挿入"}]'::jsonb, 'B', '正答は B「口腔内吸引」。

意識障害のある患者の口腔内に唾液がたまると、誤嚥や窒息の危険がある。まず口腔内を吸引して気道を開き、そのうえで呼吸状態に応じて気管挿管などを考える。

出典：厚生労働省ホームページ 第115回医師国家試験 C063', '{"A": "呼吸不全が進めば必要になるが、まず口腔内の分泌物を吸引して気道を開く。", "C": "経鼻胃管は胃の内容の吸引や栄養に用いるもので、口腔内の唾液は除けない。", "D": "上気道が完全に閉塞して挿管もできないときの最後の手段で、流涎への処置ではない。", "E": "舌根沈下による閉塞には有効だが、たまった唾液は取り除けない。"}'::jsonb, 'public', 'M', '115-C-63', '', 'pending', 'llm'),
('救急・中毒', '', 2, 'KOKUSHI', '82歳の女性。発熱と意識障害のため救急車で搬入された。現病歴 : 3日前から発熱し、食事もむせるようになった。本日朝から呼びかけへの反応が乏しくなった。既往歴 : 72歳時からAlzheimer型認知症に対してドネペジルを内服中である。生活歴 : ADLは車いす移動。2年前からサービス付き高齢者向け住宅に入居している。家族歴 : 特記すべきことはない。現症 : 呼びかけにより開眼し「苦しい」と発語はあるが問いかけには答えられない。痛み刺激に対して手で払いのける。体温38.2°C。心拍数40/分、整。血圧140/90mmHg。呼吸数24/分。SpO292%(リザーバー付マスク10L/分酸素投与下)。瞳孔は高度に縮瞳し、対光反射は消失している。鼻汁、流涎および発汗がみられる。運動麻痺を認めない。腱反射の異常を認めない。両側肺底部にcoarse cracklesを聴取する。腹部は平坦、軟で、肝・脾を触知しない。下腿に浮腫を認めない。下肢に筋力低下を認める。
この病態の診断に有用な血液検査項目はどれか。', '[{"key": "A", "text": "Ca"}, {"key": "B", "text": "TSH"}, {"key": "C", "text": "血糖"}, {"key": "D", "text": "血清補体値"}, {"key": "E", "text": "コリンエステラーゼ"}]'::jsonb, 'E', '正答は E「コリンエステラーゼ」。

縮瞳、徐脈、流涎・鼻汁・発汗、筋力の低下は、アセチルコリン過剰によるムスカリン様作用とニコチン様作用で、コリン作動性クリーゼ（有機リン中毒と同じ病態）を示す。血清コリンエステラーゼ活性の低下が診断に役立つ。

出典：厚生労働省ホームページ 第115回医師国家試験 C064', '{"A": "カルシウムの異常では、縮瞳や分泌物の増加などのコリン作動性の症状は説明できない。", "B": "甲状腺機能低下では徐脈はあっても、縮瞳や分泌物の増加は起こらない。", "C": "低血糖は発汗や意識障害を起こすが、縮瞳、徐脈、流涎は説明できない。", "D": "補体は免疫複合体による疾患などの評価に用いるもので、この病態の診断には役立たない。"}'::jsonb, 'public', 'M', '115-C-64', '', 'pending', 'llm'),
('肝・胆・膵', '', 2, 'KOKUSHI', '75歳の男性。腹痛を主訴に来院した。現病歴 : 3週前から食思不振と倦怠感を自覚していた。2日前から上腹部の鈍痛が出現したため受診した。既往歴 : 45歳から高血圧症と糖尿病で内服加療中である。血糖コントロールは良好であった。61歳時に早期胃癌の診断で幽門側胃切除(Billroth I法再建)術。生活歴 : 妻と長男夫婦と4人暮らし。喫煙は20本/日を45年間。飲酒は機会飲酒。家族歴 : 特記すべきことはない。現症 : 意識は清明。身長166cm、体重57kg。体温36.7°C。脈拍76/分、整。血圧134/86mmHg。呼吸数14/分。SpO298%(room air)。眼瞼結膜と眼球結膜とに異常を認めない。心音と呼吸音とに異常を認めない。腹部は平坦、軟で、手術痕を認める。圧痛のない腫大した胆囊を触知する。肝・脾を触知しない。腸雑音に異常を認めない。検査所見 : 血液所見:赤血球411万、Hb13.8g/dL、Ht41%、白血球8,600、血小板18万。血液生化学所見:総蛋白7.1g/dL、アルブミン3.7g/dL、総ビリルビン2.1mg/dL、直接ビリルビン1.3mg/dL、AST328U/L、ALT216U/L、LD564U/L(基準120〜245)、ALP1,235U/L(基準115〜359)、γ-GT602U/L(基準8〜50)、アミラーゼ101U/L(基準37〜160)、尿素窒素24mg/dL、クレアチニン1.2mg/dL、 尿酸5.4mg/dL、 血糖123mg/dL、 HbA1c7.0% (基準4.6〜6.2)、総コレステロール196mg/dL、トリグリセリド110mg/dL、Na139 mEq/L、K4.4mEq/L、Cl99mEq/L、CEA5.3ng/mL(基準5以下)、CA19-9 133U/mL(基準37以下)。CRP1.5mg/dL。
この患者にみられるのはどれか。', '[{"key": "A", "text": "Charcot三徴"}, {"key": "B", "text": "Courvoisier徴候"}, {"key": "C", "text": "Grey-Turner徴候"}, {"key": "D", "text": "Murphy徴候"}, {"key": "E", "text": "Reynolds五徴"}]'::jsonb, 'B', '正答は B「Courvoisier徴候」。

圧痛のない腫大した胆嚢を触れ、閉塞性の胆道系酵素の上昇と黄疸がある。Courvoisier徴候で、胆嚢管の合流部より下流の総胆管が、膵頭部癌や下部胆管癌などでゆっくり閉塞したことを示す。CA19-9も上昇している。

出典：厚生労働省ホームページ 第115回医師国家試験 C066', '{"A": "発熱、黄疸、右上腹部痛の三徴は急性胆管炎の所見で、本例に発熱はない。", "C": "側腹部の皮下出血斑で、重症急性膵炎などによる後腹膜への出血を示す。", "D": "右季肋部を圧迫して深く吸気させると痛みで止まる急性胆嚢炎の所見で、本例の胆嚢に圧痛はない。", "E": "Charcot三徴にショックと意識障害を加えた重症の胆管炎の所見である。"}'::jsonb, 'public', 'M', '115-C-66', '', 'pending', 'llm'),
('肝・胆・膵', '', 2, 'KOKUSHI', '75歳の男性。腹痛を主訴に来院した。現病歴 : 3週前から食思不振と倦怠感を自覚していた。2日前から上腹部の鈍痛が出現したため受診した。既往歴 : 45歳から高血圧症と糖尿病で内服加療中である。血糖コントロールは良好であった。61歳時に早期胃癌の診断で幽門側胃切除(Billroth I法再建)術。生活歴 : 妻と長男夫婦と4人暮らし。喫煙は20本/日を45年間。飲酒は機会飲酒。家族歴 : 特記すべきことはない。現症 : 意識は清明。身長166cm、体重57kg。体温36.7°C。脈拍76/分、整。血圧134/86mmHg。呼吸数14/分。SpO298%(room air)。眼瞼結膜と眼球結膜とに異常を認めない。心音と呼吸音とに異常を認めない。腹部は平坦、軟で、手術痕を認める。圧痛のない腫大した胆囊を触知する。肝・脾を触知しない。腸雑音に異常を認めない。検査所見 : 血液所見:赤血球411万、Hb13.8g/dL、Ht41%、白血球8,600、血小板18万。血液生化学所見:総蛋白7.1g/dL、アルブミン3.7g/dL、総ビリルビン2.1mg/dL、直接ビリルビン1.3mg/dL、AST328U/L、ALT216U/L、LD564U/L(基準120〜245)、ALP1,235U/L(基準115〜359)、γ-GT602U/L(基準8〜50)、アミラーゼ101U/L(基準37〜160)、尿素窒素24mg/dL、クレアチニン1.2mg/dL、 尿酸5.4mg/dL、 血糖123mg/dL、 HbA1c7.0% (基準4.6〜6.2)、総コレステロール196mg/dL、トリグリセリド110mg/dL、Na139 mEq/L、K4.4mEq/L、Cl99mEq/L、CEA5.3ng/mL(基準5以下)、CA19-9 133U/mL(基準37以下)。CRP1.5mg/dL。
まず行う対応として適切なのはどれか。', '[{"key": "A", "text": "胆囊摘出術"}, {"key": "B", "text": "肝動脈塞栓術"}, {"key": "C", "text": "経皮的膿瘍ドレナージ"}, {"key": "D", "text": "内視鏡的胆管ドレナージ"}, {"key": "E", "text": "内視鏡的十二指腸ステント留置"}]'::jsonb, 'D', '正答は D「内視鏡的胆管ドレナージ」。

閉塞性黄疸で肝機能が悪化しており、まず胆道を減圧する必要がある。Billroth I法の再建では十二指腸乳頭に内視鏡で届くので、ERCPによる内視鏡的胆管ドレナージを行い、あわせて狭窄部の評価と細胞診も行う。

出典：厚生労働省ホームページ 第115回医師国家試験 C068', '{"A": "胆嚢の腫大は下流の閉塞によるもので、胆嚢を取っても黄疸は改善しない。", "B": "肝動脈塞栓術は肝細胞癌の治療法で、胆道の閉塞の治療にはならない。", "C": "膿瘍を示す所見はない。", "E": "十二指腸の閉塞を示す症状はなく、胆管の減圧が優先である。"}'::jsonb, 'public', 'M', '115-C-68', '', 'pending', 'llm'),
('腎臓', '', 2, 'KOKUSHI', '78歳の女性。胸部不快感を主訴に来院した。現病歴 : 2週前から労作時に胸部の不快感を自覚するようになり受診した。既往歴 : 61歳時に糖尿病、65歳時に高血圧症、高尿酸血症と診断され、内服加療中。76歳時に肺炎で入院加療を受けた。1年前から椎間板ヘルニアによる腰痛に対し鎮痛薬の処方も受けている。腰痛のため運動量の減少に伴い、最近は筋肉量の減少も指摘されていた。生活歴 : 80歳の夫と2人暮らし。喫煙は24歳から20本/日を37年間。飲酒は機会飲酒。家族歴 : 父親が70歳時に心不全で死亡。現症 : 意識は清明。身長154cm、体重41kg。体温35.8°C。脈拍84/分、整。血圧142/88mmHg。呼吸数16/分。SpO296%(room air)。眼瞼結膜に異常を認めない。頸静脈の怒張を認めない。胸骨左縁第3肋間を最強点とするLevine2/6の収縮期雑音を聴取する。呼吸音に異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。左足背動脈は触知が不良で冷感を認める。検査所見 : 尿所見:蛋白2+、潜血(−)、糖(−)、尿蛋白1.5g/日。血液所見:赤血球362万、Hb11.0g/dL、Ht35%、白血球6,800、血小板16万。血液生化学所見:総蛋白6.2g/dL、アルブミン3.2g/dL、AST20U/L、ALT12U/L、LD 198U/L (基準120〜245)、ALP288U/L (基準115〜359)、CK28U/L (基準30〜140)、尿素窒素32mg/dL、クレアチニン0.9mg/dL、eGFR37ml/分/1.73 m2、尿酸8.2mg/dL、血糖118mg/dL、HbA1c6.6%(基準4.6〜6.2)、総コレステロール142mg/dL、Na136mEq/L、K4.0mEq/L、Cl104mEq/L。CRP0.8 mg/dL。12誘導心電図でII、III、aVF、V4-6誘導のST低下を認める。胸部エックス線写真で心胸郭比56%。虚血性心疾患が疑われ、冠動脈造影検査の実施を検討することとなった。
この患者の腎機能をより正確に把握するために有用な指標はどれか。', '[{"key": "A", "text": "尿中NAG値"}, {"key": "B", "text": "尿蛋白/クレアチニン比"}, {"key": "C", "text": "尿中β2-マイクログロブリン値"}, {"key": "D", "text": "血液尿素窒素/血清クレアチニン比"}, {"key": "E", "text": "血清シスタチンCによるGFR推算値"}]'::jsonb, 'E', '正答は E「血清シスタチンCによるGFR推算値」。

筋肉量の少ない高齢のやせた患者ではクレアチニンの産生が少なく、血清クレアチニンが低めに出るため、クレアチニンによるeGFRは腎機能を過大に評価する。筋肉量の影響を受けにくい血清シスタチンCによる推算値のほうが正確である。

出典：厚生労働省ホームページ 第115回医師国家試験 C069', '{"A": "尿中NAGは尿細管障害の指標で、糸球体濾過量は評価できない。", "B": "尿蛋白/クレアチニン比は蛋白尿の程度を表す指標で、GFRはわからない。", "C": "尿中β2-マイクログロブリンは近位尿細管の再吸収障害の指標で、GFRの評価には用いない。", "D": "BUN/Cr比は脱水や消化管出血などの鑑別に用いる比で、GFRの推定には用いない。"}'::jsonb, 'public', 'M', '115-C-69', '', 'pending', 'llm'),
('腎臓', '', 2, 'KOKUSHI', '78歳の女性。胸部不快感を主訴に来院した。現病歴 : 2週前から労作時に胸部の不快感を自覚するようになり受診した。既往歴 : 61歳時に糖尿病、65歳時に高血圧症、高尿酸血症と診断され、内服加療中。76歳時に肺炎で入院加療を受けた。1年前から椎間板ヘルニアによる腰痛に対し鎮痛薬の処方も受けている。腰痛のため運動量の減少に伴い、最近は筋肉量の減少も指摘されていた。生活歴 : 80歳の夫と2人暮らし。喫煙は24歳から20本/日を37年間。飲酒は機会飲酒。家族歴 : 父親が70歳時に心不全で死亡。現症 : 意識は清明。身長154cm、体重41kg。体温35.8°C。脈拍84/分、整。血圧142/88mmHg。呼吸数16/分。SpO296%(room air)。眼瞼結膜に異常を認めない。頸静脈の怒張を認めない。胸骨左縁第3肋間を最強点とするLevine2/6の収縮期雑音を聴取する。呼吸音に異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。左足背動脈は触知が不良で冷感を認める。検査所見 : 尿所見:蛋白2+、潜血(−)、糖(−)、尿蛋白1.5g/日。血液所見:赤血球362万、Hb11.0g/dL、Ht35%、白血球6,800、血小板16万。血液生化学所見:総蛋白6.2g/dL、アルブミン3.2g/dL、AST20U/L、ALT12U/L、LD 198U/L (基準120〜245)、ALP288U/L (基準115〜359)、CK28U/L (基準30〜140)、尿素窒素32mg/dL、クレアチニン0.9mg/dL、eGFR37ml/分/1.73 m2、尿酸8.2mg/dL、血糖118mg/dL、HbA1c6.6%(基準4.6〜6.2)、総コレステロール142mg/dL、Na136mEq/L、K4.0mEq/L、Cl104mEq/L。CRP0.8 mg/dL。12誘導心電図でII、III、aVF、V4-6誘導のST低下を認める。胸部エックス線写真で心胸郭比56%。虚血性心疾患が疑われ、冠動脈造影検査の実施を検討することとなった。
腎機能は中等度の障害であり、冠動脈造影検査を行うことになった。この患者で造影剤使用前に中止を検討すべき内服薬はどれか。', '[{"key": "A", "text": "利尿薬"}, {"key": "B", "text": "NSAID"}, {"key": "C", "text": "尿酸合成阻害薬"}, {"key": "D", "text": "αグルコシダーゼ阻害薬"}, {"key": "E", "text": "アンジオテンシン変換酵素〈ACE〉阻害薬"}]'::jsonb, 'B', '正答は B「NSAID」。

NSAIDは腎血流を保つプロスタグランジンの産生を抑え、造影剤腎症の危険を高める。腰痛に対して処方されている鎮痛薬を、造影の前後はできるだけ休薬する。

出典：厚生労働省ホームページ 第115回医師国家試験 C070', '{"A": "利尿薬の中止は一律には勧められておらず、必要なら続ける。脱水にしないよう注意する。", "C": "尿酸合成阻害薬が造影剤腎症の危険を高めることはなく、中止は要らない。", "D": "αグルコシダーゼ阻害薬は造影剤と問題になる相互作用がなく、中止は要らない。", "E": "ACE阻害薬を休薬すると造影剤腎症が減るという根拠は乏しく、一律には中止しない。"}'::jsonb, 'public', 'M', '115-C-70', '', 'pending', 'llm'),
('腎臓', '', 2, 'KOKUSHI', '78歳の女性。胸部不快感を主訴に来院した。現病歴 : 2週前から労作時に胸部の不快感を自覚するようになり受診した。既往歴 : 61歳時に糖尿病、65歳時に高血圧症、高尿酸血症と診断され、内服加療中。76歳時に肺炎で入院加療を受けた。1年前から椎間板ヘルニアによる腰痛に対し鎮痛薬の処方も受けている。腰痛のため運動量の減少に伴い、最近は筋肉量の減少も指摘されていた。生活歴 : 80歳の夫と2人暮らし。喫煙は24歳から20本/日を37年間。飲酒は機会飲酒。家族歴 : 父親が70歳時に心不全で死亡。現症 : 意識は清明。身長154cm、体重41kg。体温35.8°C。脈拍84/分、整。血圧142/88mmHg。呼吸数16/分。SpO296%(room air)。眼瞼結膜に異常を認めない。頸静脈の怒張を認めない。胸骨左縁第3肋間を最強点とするLevine2/6の収縮期雑音を聴取する。呼吸音に異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。左足背動脈は触知が不良で冷感を認める。検査所見 : 尿所見:蛋白2+、潜血(−)、糖(−)、尿蛋白1.5g/日。血液所見:赤血球362万、Hb11.0g/dL、Ht35%、白血球6,800、血小板16万。血液生化学所見:総蛋白6.2g/dL、アルブミン3.2g/dL、AST20U/L、ALT12U/L、LD 198U/L (基準120〜245)、ALP288U/L (基準115〜359)、CK28U/L (基準30〜140)、尿素窒素32mg/dL、クレアチニン0.9mg/dL、eGFR37ml/分/1.73 m2、尿酸8.2mg/dL、血糖118mg/dL、HbA1c6.6%(基準4.6〜6.2)、総コレステロール142mg/dL、Na136mEq/L、K4.0mEq/L、Cl104mEq/L。CRP0.8 mg/dL。12誘導心電図でII、III、aVF、V4-6誘導のST低下を認める。胸部エックス線写真で心胸郭比56%。虚血性心疾患が疑われ、冠動脈造影検査の実施を検討することとなった。
冠動脈造影検査前に行うべき対応はどれか。', '[{"key": "A", "text": "血液透析"}, {"key": "B", "text": "スタチン内服"}, {"key": "C", "text": "生理食塩液点滴静注"}, {"key": "D", "text": "ドーパミン点滴静注"}, {"key": "E", "text": "ヒト心房利尿ペプチド〈hANP〉点滴静注"}]'::jsonb, 'C', '正答は C「生理食塩液点滴静注」。

eGFR 37の中等度の腎機能障害があり、造影剤腎症の危険が高い。予防として確立しているのは、造影の前後に生理食塩液などの等張液を点滴して尿量を保つことである。

出典：厚生労働省ホームページ 第115回医師国家試験 C071', '{"A": "造影剤の除去を目的とした予防的な透析は、造影剤腎症を減らさず勧められない。", "B": "スタチンによる造影剤腎症の予防効果は確立していない。", "D": "低用量のドパミンで腎を保護する効果は否定されている。", "E": "hANPによる予防効果は確立しておらず、一般には用いない。"}'::jsonb, 'public', 'M', '115-C-71', '', 'pending', 'llm'),
('循環器', '', 2, 'KOKUSHI', '80歳の男性。胸痛のため救急車で搬入された。現病歴 : 昨日午後7時ころ夕食中に急に胸部絞扼感を感じた。胸痛は約30分持続したが自然に軽快し、その日は就寝した。本日朝6時、起床時に昨晩と同様の胸痛が出現した。昨夜より症状が強く動けない状態が持続し、その後呼吸困難も生じてきたため救急車を要請し、午前7時に救急搬送された。既往歴 : 10年前から高血圧症で通院加療中。生活歴 : 妻と2人暮らし。喫煙は20本/日、60年間。飲酒は機会飲酒。家族歴 : 特記すべきことはない。現症 : 意識は清明。身長155cm、体重60kg。心拍数108/分、整。血圧106/86 mmHgで明らかな左右差を認めない。呼吸数20/分。SpO294%(リザーバー付マスク10L/分酸素投与下)。冷汗を認める。眼瞼結膜と眼球結膜とに異常を認めない。頸静脈の怒張を認める。心音はIII音ギャロップを呈しており、心尖部を最強点とするLevine3/6の収縮期雑音を聴取する。呼吸音は両側中下胸部に湿性ラ音を聴取する。腹部は平坦、軟で、肝・脾を触知しない。下腿に浮腫を認めない。検査所見 : 赤血球 463万、Hb13.2g/dL、Ht40%、白血球 9,800、血小板28万、総ビリルビン0.5mg/dL、AST118U/L、ALT32U/L、LD320U/L(基準120〜245)、CK346U/L(基準30〜140)、尿素窒素12mg/dL、クレアチニン0.8 mg/dL、血糖98mg/dL、Na138mEq/L、K4.4mEq/L、Cl97mEq/L。心筋トロポニンT迅速検査陽性。心電図は心拍数108/分の洞調律で、広範な誘導でST低下を認めた。
冠血行再建術が施行された後、ICUに入室した。血行動態は安定し補助循環装置も抜去された。この患者への心臓リハビリテーションの説明で誤っているのはどれか。', '[{"key": "A", "text": "「最初は監視下で行います」"}, {"key": "B", "text": "「心拍数を見ながら進めていきます」"}, {"key": "C", "text": "「息切れや胸痛があれば無理に進めません」"}, {"key": "D", "text": "「心臓リハビリは退院の時点で終了となります」"}, {"key": "E", "text": "「ご家族と一緒に食事やお薬についても勉強しましょう」"}]'::jsonb, 'D', '正答は D「「心臓リハビリは退院の時点で終了となります」」。

心臓リハビリテーションは入院中の急性期に始まり、退院後の外来での回復期、生涯続ける維持期へと続く。運動療法に加え、食事、服薬、禁煙などの再発予防の教育を続けることで予後が改善する。退院で終わるという説明は誤りである。

出典：厚生労働省ホームページ 第115回医師国家試験 C074', '{"A": "開始時は心電図や血圧を監視しながら行う。正しい。", "B": "心拍数や自覚症状を指標に運動の強さを決め、段階的に進める。正しい。", "C": "息切れや胸痛、心電図の変化が出れば中止や減量をする。正しい。", "E": "食事や服薬の管理には家族の協力が大切で、家族への教育も含まれる。正しい。"}'::jsonb, 'public', 'M', '115-C-74', '', 'pending', 'llm'),
('循環器', '', 2, 'KOKUSHI', '合併症として完全房室ブロックを最も生じやすいのはどれか。', '[{"key": "A", "text": "強皮症"}, {"key": "B", "text": "Sjögren症候群"}, {"key": "C", "text": "甲状腺機能低下症"}, {"key": "D", "text": "心サルコイドーシス"}, {"key": "E", "text": "全身性エリテマトーデス〈SLE〉"}]'::jsonb, 'D', '正答は D「心サルコイドーシス」。

心サルコイドーシスでは心室中隔の基部に肉芽腫ができやすく、刺激伝導系が障害されて完全房室ブロックを起こすのが代表的である。中年以降に原因のわからない房室ブロックをみたら本症を疑う。心室頻拍や心不全の原因にもなる。

出典：厚生労働省ホームページ 第115回医師国家試験 D009', '{"A": "強皮症は心筋の線維化で不整脈や伝導障害を起こしうるが、完全房室ブロックの頻度は心サルコイドーシスほど高くない。", "B": "成人のSjögren症候群で伝導障害はまれである。母親の抗SS-A抗体による児の先天性房室ブロックとは別である。", "C": "甲状腺機能低下症は洞性徐脈や低電位を示すが、完全房室ブロックはまれである。", "E": "SLEの心病変は心膜炎が多く、成人の完全房室ブロックはまれである。"}'::jsonb, 'public', 'M', '115-D-9', '', 'pending', 'llm'),
('神経', '', 2, 'KOKUSHI', '54歳の男性。脳梗塞後の右片麻痺のため回復期リハビリテーション病棟に入院中である。発症して1か月経過し、痛みの訴えはない。意識は清明。身長168cm、体重60kg。言語理解は良好であるが、言語表出は単語レベルである。構音障害は認めない。徒手筋力テストで右上肢筋力は4で、手指も1本ずつ順番に指折りと伸展が可能である。徒手筋力テストで右腸腰筋4、右大腿四頭筋4、右前脛骨筋4である。座位、立位は安定している。右半身の表在覚、位置覚ともに正常である。この患者に必要なのはどれか。', '[{"key": "A", "text": "三角巾使用による右上肢固定"}, {"key": "B", "text": "長下肢装具使用での歩行訓練"}, {"key": "C", "text": "日常生活における右手使用の指導"}, {"key": "D", "text": "環境制御装置を用いたナースコール"}, {"key": "E", "text": "文字盤使用によるコミュニケーション"}]'::jsonb, 'C', '正答は C「日常生活における右手使用の指導」。

右上肢の筋力は4で、手指を1本ずつ動かせるほど分離運動が回復し、感覚も保たれている。日常生活の中で積極的に右手を使うよう指導すると機能の回復がさらに進む。使わずにいると健側に頼る癖がつき、麻痺側が使われなくなる。

出典：厚生労働省ホームページ 第115回医師国家試験 D048', '{"A": "三角巾で固定すると麻痺側を使わなくなり、拘縮と機能の低下を招く。亜脱臼を起こす弛緩性麻痺のときの対応である。", "B": "下肢の筋力は4で座位も立位も安定しており、長下肢装具は要らない。", "D": "上肢は十分に動かせ、通常のナースコールを使える。", "E": "失語症では文字の理解や表出も障害されやすく、文字盤は役立ちにくい。構音障害はないので、言語訓練で発話を促す。"}'::jsonb, 'public', 'M', '115-D-48', '', 'pending', 'llm'),
('肝・胆・膵', '', 2, 'KOKUSHI', '78歳の女性。発熱、悪寒および上腹部痛を主訴に来院した。本日夕食後に右上腹部痛と悪寒を自覚し受診した。身長155cm、体重45kg。体温38.4°C。脈拍104/分、整。血圧110/58mmHg。呼吸数18/分。SpO296%(room air)。眼球結膜に黄染を認める。心音と呼吸音とに異常を認めない。右季肋部に圧痛を伴う腫瘤を触知する。尿所見:潜血(−)、沈渣に白血球を認めない。血液所見:赤血球335万、Hb10.2g/dL、Ht33%、白血球12,800、血小板12万。血液生化学所見:総蛋白6.2g/dL、アルブミン2.9g/dL、総ビリルビン4.6mg/dL、直接ビリルビン3.8mg/dL、AST346U/L、ALT434U/L、LD568U/L (基準120〜245)、ALP 557U/L(基準115〜359)、γ-GT238U/L(基準8〜50)、アミラーゼ278U/L(基準37〜160)、尿素窒素18mg/dL、クレアチニン1.0mg/dL、血糖146mg/dL、Na 135mEq/L、K3.6mEq/L、Cl98mEq/L。CRP12mg/dL。次に行う検査はどれか。', '[{"key": "A", "text": "腹部単純CT"}, {"key": "B", "text": "腹部超音波検査"}, {"key": "C", "text": "超音波内視鏡検査"}, {"key": "D", "text": "腹腔動脈造影検査"}, {"key": "E", "text": "磁気共鳴胆管膵管撮影〈MRCP〉"}]'::jsonb, 'B', '正答は B「腹部超音波検査」。

発熱、黄疸、右上腹部痛のCharcot三徴と胆道系酵素の上昇から急性胆管炎を考える。まず、ベッドサイドで速やかに行えて侵襲のない腹部超音波検査で、胆管の拡張や結石、胆嚢の状態を確かめる。

出典：厚生労働省ホームページ 第115回医師国家試験 D050', '{"A": "CTも有用だが、胆管の拡張や結石を最初に手早く評価できるのは超音波検査である。", "C": "総胆管結石の精査に優れるが、鎮静を要する侵襲的な検査で、最初には行わない。", "D": "腹腔動脈造影は胆道の評価には用いない。", "E": "胆管の詳しい評価には役立つが、時間がかかり、重症化しうる胆管炎の最初の検査には向かない。"}'::jsonb, 'public', 'M', '115-D-50', '', 'pending', 'llm'),
('免疫・膠原病', '', 2, 'KOKUSHI', '63歳の男性。発熱と下肢の皮疹を主訴に来院した。10年前に自宅近くの医療機関で関節リウマチと診断され、抗リウマチ薬による治療を受けていた。1年前から多発関節痛が増悪し、抗リウマチ薬の増量や追加をされたが改善しなかった。1週前から37°C台の発熱を認め、市販の解熱鎮痛薬を内服していたが改善しなかった。2日前から38°C台の発熱となり、下肢の皮疹に気付いたため受診した。体温38.3°C。脈拍96/分、整。血圧142/86mmHg。呼吸数18/分。眼球結膜の充血を認める。心音と呼吸音とに異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。両側下腿に一部潰瘍を伴う紫斑を認める。尿所見:蛋白(−)、潜血(−)。血液所見:赤血球392万、Hb10.2g/dL、Ht32%、白血球13,700(桿状核好中球26%、分葉核好中球44%、好酸球1%、好塩基球1%、単球10%、リンパ球18%)、血小板36万。血液生化学所見:総ビリルビン0.9mg/dL、AST38U/L、ALT42 U/L、LD315U/L (基準120〜245)、γ-GT72U/L (基準 8〜50)、尿素窒素22 mg/dL、クレアチニン0.6mg/dL。免疫血清学所見:CRP8.2mg/dL、リウマトイド因子〈RF〉1,260IU/mL(基準20未満)、抗核抗体陰性、CH5022U/mL(基準30〜40)、C3 42mg/dL(基準52〜112)、C4 12mg/dL(基準16〜51)。現時点で行うべき検査として適切なのはどれか。', '[{"key": "A", "text": "肝生検"}, {"key": "B", "text": "関節穿刺"}, {"key": "C", "text": "骨髄穿刺"}, {"key": "D", "text": "皮膚生検"}, {"key": "E", "text": "骨シンチグラフィ"}]'::jsonb, 'D', '正答は D「皮膚生検」。

長く活動性の続く関節リウマチに、発熱、潰瘍を伴う下腿の紫斑、リウマトイド因子の著明な高値、補体の低下がみられ、リウマトイド血管炎（悪性関節リウマチ）を考える。確定には紫斑や潰瘍の辺縁から皮膚生検を行い、血管炎を組織で確かめる。

出典：厚生労働省ホームページ 第115回医師国家試験 D054', '{"A": "肝機能の異常は軽く、肝生検の適応はない。", "B": "関節穿刺は化膿性関節炎や結晶性関節炎の鑑別に用いるもので、血管炎の診断にはならない。", "C": "骨髄の病気を疑う血球の異常はなく、骨髄穿刺の適応はない。", "E": "骨シンチグラフィは骨の病変の検索に用いるもので、血管炎の診断には役立たない。"}'::jsonb, 'public', 'M', '115-D-54', '', 'pending', 'llm'),
('救急・中毒', '', 2, 'KOKUSHI', '外傷の初期診療において迅速簡易超音波検査〈FAST〉で確認するのはどれか。', '[{"key": "A", "text": "気胸"}, {"key": "B", "text": "骨折"}, {"key": "C", "text": "臓器損傷"}, {"key": "D", "text": "大動脈径"}, {"key": "E", "text": "体腔内出血"}]'::jsonb, 'E', '正答は E「体腔内出血」。

FASTは外傷の初期診療でショックの原因となる出血を探すための迅速な超音波検査で、心嚢、右胸腔、Morison窩、左胸腔、脾周囲、膀胱直腸窩に液体（出血）がたまっていないかをみる。

出典：厚生労働省ホームページ 第115回医師国家試験 E009', '{"A": "気胸は胸部の超音波でも評価できるが、FASTで確かめる項目ではない（拡張したE-FASTで評価する）。", "B": "骨折の評価はエックス線やCTで行う。", "C": "FASTは出血の有無をみる検査で、臓器の損傷そのものはCTで評価する。", "D": "大動脈の評価はFASTに含まれない。"}'::jsonb, 'public', 'M', '115-E-9', '', 'pending', 'llm'),
('神経', '', 2, 'KOKUSHI', '末梢神経伝導検査が診断に有用なのはどれか。', '[{"key": "A", "text": "肘部管症候群"}, {"key": "B", "text": "Parkinson病"}, {"key": "C", "text": "多発性筋炎"}, {"key": "D", "text": "脊髄損傷"}, {"key": "E", "text": "脳梗塞"}]'::jsonb, 'A', '正答は A「肘部管症候群」。

肘部管症候群は肘で尺骨神経が絞扼される障害で、神経伝導検査で肘をはさむ区間の伝導速度の低下や伝導ブロックを確かめ、診断と重症度の評価ができる。

出典：厚生労働省ホームページ 第115回医師国家試験 E014', '{"B": "Parkinson病は中枢の神経変性疾患で、末梢神経の伝導は正常である。", "C": "多発性筋炎は筋の疾患で、診断には針筋電図、CK、筋生検を用いる。", "D": "脊髄損傷は中枢の障害で、MRIで評価する。", "E": "脳梗塞は脳の病変で、CTやMRIで診断する。"}'::jsonb, 'public', 'M', '115-E-14', '', 'pending', 'llm'),
('循環器', '', 2, 'KOKUSHI', '心臓ペースメーカー植込み患者に対して、ペースメーカーの機種を確認してから実施すべきなのはどれか。', '[{"key": "A", "text": "食道生検"}, {"key": "B", "text": "FDG-PET"}, {"key": "C", "text": "腹部造影CT"}, {"key": "D", "text": "超音波内視鏡検査"}, {"key": "E", "text": "磁気共鳴胆管膵管撮影〈MRCP〉"}]'::jsonb, 'E', '正答は E「磁気共鳴胆管膵管撮影〈MRCP〉」。

MRCPはMRIによる検査で、強い磁場がペースメーカーの誤作動や発熱を起こしうる。条件付きでMRIに対応する機種かを確かめ、設定の変更などの準備をしたうえで行う。

出典：厚生労働省ホームページ 第115回医師国家試験 E016', '{"A": "内視鏡下の生検で、磁場は使わない。", "B": "FDG-PETは放射性薬剤を用いる検査で、ペースメーカーには影響しない。", "C": "CTは磁場を使わず、ペースメーカーを植え込んでいても行える。", "D": "超音波はペースメーカーに影響しない。"}'::jsonb, 'public', 'M', '115-E-16', '', 'pending', 'llm'),
('医学総論', '', 2, 'KOKUSHI', '末梢静脈路ではなく末梢挿入中心静脈カテーテル〈PICC〉を選択すべき輸液製剤の組成はどれか。', '[{"key": "A", "text": "Na — 154mEq/L"}, {"key": "B", "text": "K — 20mEq/L"}, {"key": "C", "text": "Cl — 35mEq/L"}, {"key": "D", "text": "Lactate 20mEq/L"}, {"key": "E", "text": "Glucose 20%"}]'::jsonb, 'E', '正答は E「Glucose 20%」。

末梢静脈から入れられる輸液の浸透圧は、血漿のおよそ3倍（約900mOsm/L）までが目安で、それを超えると静脈炎を起こしやすい。20%ブドウ糖液は約1,100mOsm/Lと高く、中心静脈（PICCを含む）から投与する。

出典：厚生労働省ホームページ 第115回医師国家試験 E020', '{"A": "生理食塩液の組成で、等張なので末梢から投与できる。", "B": "末梢からのカリウムの投与は40mEq/L以下が目安で、20mEq/Lなら末梢から入れられる。", "C": "維持輸液ほどの組成で、末梢から投与できる。", "D": "乳酸を含むふつうの輸液の組成で、末梢から投与できる。"}'::jsonb, 'public', 'M', '115-E-20', '', 'pending', 'llm'),
('産科', '', 2, 'KOKUSHI', '37歳の初妊婦(1妊0産)。妊娠26週。血糖値の異常を指摘され紹介受診した。妊娠初期から妊婦健康診査を受けていた。妊娠24週時に施行された50gブドウ糖負荷試験で血糖値156mg/dLであったため精査のため紹介となった。既往歴に特記すべきものはない。身長156cm、体重75kg(非妊時69kg)。体温37.0°C。脈拍76/分、整。血圧122/76mmHg。呼吸数18/分。尿蛋白(−)、尿糖(±)。来院後に施行した75g経口ブドウ糖負荷試験〈OGTT〉は、空腹時血糖値90mg/dL、1時間値192mg/dL、2時間値138mg/dLであった。今後の管理としてまず行うのはどれか。', '[{"key": "A", "text": "運動療法"}, {"key": "B", "text": "経過観察"}, {"key": "C", "text": "食事療法"}, {"key": "D", "text": "インスリン投与"}, {"key": "E", "text": "経口血糖降下薬投与"}]'::jsonb, 'C', '正答は C「食事療法」。

75gOGTTの1時間値が180mg/dL以上で、妊娠糖尿病と診断する（空腹時92、1時間180、2時間153mg/dLのうち1点以上）。まず食事療法を行い、血糖の自己測定で目標に届かなければインスリンを加える。

出典：厚生労働省ホームページ 第115回医師国家試験 E034', '{"A": "補助的に勧めることはあるが、管理の基本はまず食事療法である。", "B": "妊娠糖尿病は巨大児や新生児低血糖などの危険を高めるので、治療が必要である。", "D": "インスリンは食事療法で血糖が目標に届かない場合に用いる。", "E": "日本では妊娠中の血糖管理にはインスリンを用い、経口血糖降下薬は原則として使わない。"}'::jsonb, 'public', 'M', '115-E-34', '', 'pending', 'llm'),
('呼吸器', '', 2, 'KOKUSHI', '23歳の男性。咳嗽および血痰を主訴に来院した。3日前から乾性咳嗽が出現し、激しくせき込むようになった。今朝、咳嗽時に少量の血痰が1回出現したため心配になって受診した。悪心や嘔吐はなく、食欲良好で体重減少や盗汗はない。結核曝露歴や最近1か月の海外渡航歴はない。既往歴に特記すべきことはなく、喫煙歴と飲酒歴はない。意識は清明。診察中には咳嗽が時々出るが血痰は出ていない。身長160cm、体重72kg。体温36.1°C。脈拍72/分、整。血圧122/58mmHg。呼吸数12/分。口腔内と咽頭に異常はなく、頸部リンパ節腫脹を認めない。心音と呼吸音とに異常を認めない。この時点で最も事前確率の高い疾患はどれか。', '[{"key": "A", "text": "肺癌"}, {"key": "B", "text": "気管支喘息"}, {"key": "C", "text": "急性気管支炎"}, {"key": "D", "text": "Goodpasture症候群"}, {"key": "E", "text": "好酸球性多発血管炎性肉芽腫症〈Churg-Strauss症候群〉"}]'::jsonb, 'C', '正答は C「急性気管支炎」。

生来健康な若年者が数日前からの咳とともに少量の血痰を1回出しただけで、発熱や体重減少はなく、診察所見も正常である。血痰の原因として最も多いのは急性気管支炎で、事前確率が最も高い。

出典：厚生労働省ホームページ 第115回医師国家試験 E037', '{"A": "23歳の非喫煙者で、肺癌の事前確率は低い。", "B": "喘鳴や発作性の呼吸困難がなく、気管支喘息で血痰が出ることも少ない。", "D": "肺胞出血と急速に進む腎炎を起こすまれな疾患で、事前確率は低い。", "E": "喘息の先行と好酸球増多を伴うまれな血管炎で、この経過では考えにくい。"}'::jsonb, 'public', 'M', '115-E-37', '', 'pending', 'llm'),
('小児科', '', 2, 'KOKUSHI', '9か月の男児。RSウイルス感染症による呼吸窮迫とチアノーゼのため入院中である。在胎40週、体重3,250gで出生した。呼吸心拍モニターのアラームが鳴ったため、医師が病室に行ったところ児の顔色不良を認め、気道開通の体位をとった。末梢静脈ルートは確保されていて蘇生のための準備は整っている。心拍数50/分、整。呼吸数10/分。SpO260%(酸素テント40%酸素投与下)。呼吸音は両側弱く喘鳴を認める。右上腕動脈の脈は触知した。直ちに行う処置はどれか。', '[{"key": "A", "text": "除細動"}, {"key": "B", "text": "胸骨圧迫"}, {"key": "C", "text": "アドレナリン静注"}, {"key": "D", "text": "吸入酸素濃度増加"}, {"key": "E", "text": "バッグバルブマスク換気"}]'::jsonb, 'E', '正答は E「バッグバルブマスク換気」。

呼吸数10/分、SpO2 60%と呼吸が不十分で、低酸素による徐脈（50/分）が起きている。脈は触れるので、まずバッグバルブマスクで酸素を与えながら換気する。換気しても心拍数が60/分未満で循環が悪ければ胸骨圧迫を始める。

出典：厚生労働省ホームページ 第115回医師国家試験 E038', '{"A": "除細動は心室細動や無脈性心室頻拍に行うもので、洞調律の徐脈には適応がない。", "B": "脈は触れており、まず換気で酸素化を改善する。換気しても心拍数が60/分未満のままなら胸骨圧迫を加える。", "C": "アドレナリンは換気と胸骨圧迫をしても改善しない徐脈に使う。まず換気である。", "D": "自発呼吸が弱く、酸素の濃度を上げるだけでは換気が足りない。"}'::jsonb, 'public', 'M', '115-E-38', '', 'pending', 'llm'),
('神経', '', 2, 'KOKUSHI', '60歳の男性。右片麻痺と言語障害を主訴に救急車で搬入された。現在高血圧症で内服加療中である。今朝起きて1時間後から右手足の動きが悪く、言葉が出にくいことに気付いた。意識はJCSI-1。体温36.5°C、心拍数90/分、整。血圧160/94mmHg。呼吸数16/分。SpO296%(room air)。運動性失語を認める。右片麻痺は徒手筋力テストで上下肢共に3。心電図は洞調律であった。胸部エックス線写真で異常を認めない。頭部単純CTで異常を認めない。血液所見:赤血球450万、Hb14.2g/dL、Ht42%、白血球8,800、血小板18万、PT-INR1.0 (基準0.9〜1.1)。血液生化学所見:尿素窒素15mg/dL、クレアチニン0.8mg/dL、血糖102mg/dL、Na140mEq/L、K3.7mEq/L、Cl99mEq/L。血液検査の結果が出るまでに施行した頭部MRIの拡散強調像では、左中大脳動脈領域の一部で限局性に淡い高信号域を認めた。発症から90分経過している。まず急速静注すべき薬剤はどれか。', '[{"key": "A", "text": "β遮断薬"}, {"key": "B", "text": "ベラパミル"}, {"key": "C", "text": "塩化カリウム"}, {"key": "D", "text": "副腎皮質ステロイド"}, {"key": "E", "text": "t-PA〈tissue plasminogen activator〉"}]'::jsonb, 'E', '正答は E「t-PA〈tissue plasminogen activator〉」。

発症から90分で、頭部CTに出血はなく、MRIの拡散強調像で左中大脳動脈領域の急性期梗塞を認める。発症4.5時間以内で禁忌がなければ、アルテプラーゼ（t-PA）の静注による血栓溶解療法を行う（総量の10%を急速に静注し、残りを1時間かけて点滴する）。

出典：厚生労働省ホームページ 第115回医師国家試験 E040', '{"A": "β遮断薬は脳梗塞の急性期の治療ではない。血圧160/94mmHgは血栓溶解療法の基準（185/110mmHg未満）を満たしている。", "B": "ベラパミルは頻脈性不整脈の治療薬で、洞調律の本例には用いない。", "C": "K 3.7mEq/Lは正常範囲で、しかもカリウムの急速静注は心停止を招くので禁忌である。", "D": "脳梗塞の急性期に副腎皮質ステロイドの効果は示されておらず、用いない。"}'::jsonb, 'public', 'M', '115-E-40', '', 'pending', 'llm'),
('精神科', '', 2, 'KOKUSHI', '28歳の女性。意識障害のため救急車で搬入された。現病歴 : 自室内のベッドで仰向けに倒れているのを友人が発見し、呼びかけに反応が乏しいため救急車を要請した。友人とはその3時間前に電話にて口論となり「死にたい」などと話した後に連絡が取れなくなったという。救急車到着時、自室内の戸棚に錠剤の空包が多数あった。既往歴 : うつ病の診断で3か月前から三環系抗うつ薬とベンゾジアゼピン系睡眠薬を服用中。1か月前にも過量服薬による意識障害で他院に緊急入院している。生活歴 : 喫煙歴と飲酒歴はない。仕事は事務職で半年前に部署が変わり、ストレスが多いと感じていたという。家族歴 : 特記すべきことはない。現症 : 意識レベルはJCSIII-100。身長158cm、体重45kg。体温36.7°C。心拍数108/分、整。血圧108/60mmHg。呼吸数24/分。SpO291%(リザーバー付マスク10L/分酸素投与下)。舌根沈下が強く、いびき様の呼吸をしている。皮膚はやや乾燥している。眼瞼結膜と眼球結膜とに異常を認めない。瞳孔径は両側6.0 mm正円で、対光反射は両側で遅延している。頸静脈の怒張は認めない。甲状腺腫と頸部リンパ節とを触知しない。心音に異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。腸雑音はやや弱い。四肢に麻痺はなく、腱反射は正常である。心電図は洞調律で不整はないが、QRS幅が広がりQT間隔の延長を認める。ST-T変化は認めない。
直ちに行うべき処置はどれか。', '[{"key": "A", "text": "胃洗浄"}, {"key": "B", "text": "気管挿管"}, {"key": "C", "text": "アトロピン静注"}, {"key": "D", "text": "フロセミド静注"}, {"key": "E", "text": "プレドニゾロン静注"}]'::jsonb, 'B', '正答は B「気管挿管」。

JCS III-100の意識障害に舌根沈下といびき様呼吸があり、リザーバー付マスクで10L/分投与してもSpO2は91%にとどまる。気道が保てておらず、まず気管挿管で気道を確保して換気を確実にする。三環系抗うつ薬の過量服薬でQRS幅の延長もあり、けいれんや不整脈で急変しうるため、気道の確保は先延ばしにできない。

出典：厚生労働省ホームページ 第115回医師国家試験 E045', '{"A": "胃洗浄は気道を確保する前に行うと誤嚥を招く。適応も限られ、この場面で最初にするものではない。", "C": "頻脈と散瞳は三環系抗うつ薬の抗コリン作用によるもので、アトロピンはそれをさらに強める。", "D": "三環系抗うつ薬は蛋白結合率が高く組織へ広く分布するため、利尿では除去できない。循環血液量を減らす不利益のほうが大きい。", "E": "副腎皮質ステロイドの適応となる病態がない。"}'::jsonb, 'public', 'M', '115-E-45', '', 'pending', 'llm'),
('精神科', '', 2, 'KOKUSHI', '28歳の女性。意識障害のため救急車で搬入された。現病歴 : 自室内のベッドで仰向けに倒れているのを友人が発見し、呼びかけに反応が乏しいため救急車を要請した。友人とはその3時間前に電話にて口論となり「死にたい」などと話した後に連絡が取れなくなったという。救急車到着時、自室内の戸棚に錠剤の空包が多数あった。既往歴 : うつ病の診断で3か月前から三環系抗うつ薬とベンゾジアゼピン系睡眠薬を服用中。1か月前にも過量服薬による意識障害で他院に緊急入院している。生活歴 : 喫煙歴と飲酒歴はない。仕事は事務職で半年前に部署が変わり、ストレスが多いと感じていたという。家族歴 : 特記すべきことはない。現症 : 意識レベルはJCSIII-100。身長158cm、体重45kg。体温36.7°C。心拍数108/分、整。血圧108/60mmHg。呼吸数24/分。SpO291%(リザーバー付マスク10L/分酸素投与下)。舌根沈下が強く、いびき様の呼吸をしている。皮膚はやや乾燥している。眼瞼結膜と眼球結膜とに異常を認めない。瞳孔径は両側6.0 mm正円で、対光反射は両側で遅延している。頸静脈の怒張は認めない。甲状腺腫と頸部リンパ節とを触知しない。心音に異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。腸雑音はやや弱い。四肢に麻痺はなく、腱反射は正常である。心電図は洞調律で不整はないが、QRS幅が広がりQT間隔の延長を認める。ST-T変化は認めない。
診察により肺炎の合併が疑われた。誤嚥性肺炎の所見と合致しないのはどれか。', '[{"key": "A", "text": "胸郭打診による濁音"}, {"key": "B", "text": "胸壁触診による皮下握雪感"}, {"key": "C", "text": "視診による口腔内の吐物残渣"}, {"key": "D", "text": "聴診によるcoarse cracklesの聴取"}, {"key": "E", "text": "聴診による呼吸音の減弱"}]'::jsonb, 'B', '正答は B「胸壁触診による皮下握雪感」。

設問は誤嚥性肺炎の所見と「合致しない」ものを選ぶもの。皮下握雪感は皮下気腫の触診所見で、気胸や気道・食道の損傷を示す。誤嚥性肺炎そのものでは生じない。

出典：厚生労働省ホームページ 第115回医師国家試験 E046', '{"A": "浸潤影や胸水があれば打診で濁音となり、合致する所見である。", "C": "口腔内に吐物の残渣があれば誤嚥を裏づけるもので、合致する。", "D": "気道内の分泌物により coarse crackles が聴かれ、合致する。", "E": "無気肺や胸水を伴えば呼吸音は減弱し、合致する。"}'::jsonb, 'public', 'M', '115-E-46', '', 'pending', 'llm'),
('感染症', '', 2, 'KOKUSHI', '75歳の男性。発熱、腹痛および下痢のため救急車で搬入された。現病歴 : 10日前から左下腿蜂窩織炎のために入院して抗菌薬の点滴を行い、改善したため抗菌薬を内服投与に切り替えて4日前に退院した。2日前から発熱、腹痛および1日5回以上の水様下痢が出現した。経口摂取と体動が困難となったため同居する妻が救急車を要請した。退院後に食中毒の原因となり得る食物の摂取歴はない。周囲に同じ症状の人はいない。既往歴 : 50歳台から高血圧症で降圧薬を服用中である。66歳時に2型糖尿病と診断され1年前からインスリン治療を行っている。生活歴 : 妻と2人暮らし。喫煙歴はない。飲酒は機会飲酒。家族歴 : 兄が糖尿病で治療中である。現症 : 意識は清明。身長168cm、体重73kg。体温38.6°C。心拍数120/分、整。血圧136/70mmHg。呼吸数20/分。SpO296%(room air)。皮膚のツルゴールは低下している。眼瞼結膜と眼球結膜とに異常は認めない。口腔内は乾燥している。心音と呼吸音とに異常を認めない。腹部は平坦、軟で肝・脾を触知しない。下腹部に圧痛があるが反跳痛はない。腸雑音は亢進している。四肢は下腿に発赤や熱感を認めない。検査所見 : 血液所見:赤血球490万、Hb14.3g/dL、Ht42%、白血球18,200(好中球84%、好酸球1%、単球3%、リンパ球12%)、血小板20万、血液生化学所見:総蛋白6.2g/dL、アルブミン3.8g/dL、総ビリルビン0.4mg/dL、AST 30U/L、ALT38U/L、尿素窒素40mg/dL、クレアチニン1.8mg/dL、尿酸9.6 mg/dL、血糖158mg/dL。CRP4.3mg/dL。
診察にあたり誤っている感染予防策はどれか。', '[{"key": "A", "text": "個室での診察"}, {"key": "B", "text": "直腸診実施時のゴーグルの着用"}, {"key": "C", "text": "入室時のディスポーザブルガウンの着用"}, {"key": "D", "text": "便検体採取時のサージカルマスクの着用"}, {"key": "E", "text": "診察後の次亜塩素酸ナトリウムによる手指衛生"}]'::jsonb, 'E', '正答は E「診察後の次亜塩素酸ナトリウムによる手指衛生」。

抗菌薬の投与後に発熱と水様下痢が出ており、Clostridioides difficile感染症を疑う。芽胞にはアルコールが効きにくいので、手指は石けんと流水で洗い流す。次亜塩素酸ナトリウムは環境や器具の消毒に使うもので、皮膚を傷めるため手指衛生には用いない。

出典：厚生労働省ホームページ 第115回医師国家試験 E047', '{"A": "接触感染を防ぐため、個室で対応するのは適切である。", "B": "便の飛散に備えて目を保護するのは適切である。", "C": "接触予防策としてガウンと手袋を着けるのは適切である。", "D": "飛沫を浴びるおそれのある処置でマスクを着けるのは適切である。"}'::jsonb, 'public', 'M', '115-E-47', '', 'pending', 'llm'),
('感染症', '', 2, 'KOKUSHI', '75歳の男性。発熱、腹痛および下痢のため救急車で搬入された。現病歴 : 10日前から左下腿蜂窩織炎のために入院して抗菌薬の点滴を行い、改善したため抗菌薬を内服投与に切り替えて4日前に退院した。2日前から発熱、腹痛および1日5回以上の水様下痢が出現した。経口摂取と体動が困難となったため同居する妻が救急車を要請した。退院後に食中毒の原因となり得る食物の摂取歴はない。周囲に同じ症状の人はいない。既往歴 : 50歳台から高血圧症で降圧薬を服用中である。66歳時に2型糖尿病と診断され1年前からインスリン治療を行っている。生活歴 : 妻と2人暮らし。喫煙歴はない。飲酒は機会飲酒。家族歴 : 兄が糖尿病で治療中である。現症 : 意識は清明。身長168cm、体重73kg。体温38.6°C。心拍数120/分、整。血圧136/70mmHg。呼吸数20/分。SpO296%(room air)。皮膚のツルゴールは低下している。眼瞼結膜と眼球結膜とに異常は認めない。口腔内は乾燥している。心音と呼吸音とに異常を認めない。腹部は平坦、軟で肝・脾を触知しない。下腹部に圧痛があるが反跳痛はない。腸雑音は亢進している。四肢は下腿に発赤や熱感を認めない。検査所見 : 血液所見:赤血球490万、Hb14.3g/dL、Ht42%、白血球18,200(好中球84%、好酸球1%、単球3%、リンパ球12%)、血小板20万、血液生化学所見:総蛋白6.2g/dL、アルブミン3.8g/dL、総ビリルビン0.4mg/dL、AST 30U/L、ALT38U/L、尿素窒素40mg/dL、クレアチニン1.8mg/dL、尿酸9.6 mg/dL、血糖158mg/dL。CRP4.3mg/dL。
便を用いた検査のうち、診断に最も有用なのはどれか。', '[{"key": "A", "text": "脂肪染色"}, {"key": "B", "text": "潜血"}, {"key": "C", "text": "虫卵"}, {"key": "D", "text": "毒素検出"}, {"key": "E", "text": "培養"}]'::jsonb, 'D', '正答は D「毒素検出」。

抗菌薬を使ったあとに起きた水様下痢で、Clostridioides difficile感染症を疑う。便のCDトキシン（とGDH抗原）を調べて診断する。毒素を作らない株もあるため、菌の培養だけでは診断できない。

出典：厚生労働省ホームページ 第115回医師国家試験 E048', '{"A": "脂肪染色は脂肪便を調べる検査で、膵外分泌不全や吸収不良の評価に用いる。", "B": "便潜血は消化管出血の検出に用いるもので、原因の特定には役立たない。", "C": "虫卵検査は寄生虫の感染を調べるもので、この経過では考えにくい。", "E": "嫌気培養で菌は分離できるが時間がかかり、毒素を作らない株も育つため、診断には毒素の検出が要る。"}'::jsonb, 'public', 'M', '115-E-48', '', 'pending', 'llm'),
('医学総論', '', 2, 'KOKUSHI', 'メタ分析〈メタアナリシス〉について正しいのはどれか。', '[{"key": "A", "text": "異なる指標を統合することができる。"}, {"key": "B", "text": "指標を統合することで標準誤差は大きくなる。"}, {"key": "C", "text": "研究から抽出した指標を用いて統合指標を算出する。"}, {"key": "D", "text": "できるだけ多くの研究を選択して出版バイアスを防止する。"}, {"key": "E", "text": "対象者をプールすることでデータを統合して再解析する研究である。"}]'::jsonb, 'C', '正答は C「研究から抽出した指標を用いて統合指標を算出する。」。

メタ分析は、複数の研究から抽出した効果の指標（リスク比、オッズ比、平均差など）を、精度に応じて重み付けして統合し、1つの統合指標を算出する方法である。

出典：厚生労働省ホームページ 第115回医師国家試験 F003', '{"A": "統合できるのは同じ種類の指標どうしである。", "B": "対象が増えるので、統合した推定値の標準誤差は小さくなり、信頼区間は狭くなる。", "D": "研究の数を増やしても、結果の出なかった研究が公表されにくいという出版バイアスは防げない。未公表の研究を探したり、ファンネルプロットで評価したりする。", "E": "個々の研究の生データを集めて解析し直すのは個人データを用いた特別なメタ分析で、ふつうは研究ごとの要約された指標を統合する。"}'::jsonb, 'public', 'M', '115-F-3', '', 'pending', 'llm'),
('精神科', '', 2, 'KOKUSHI', '成人において、自閉症スペクトラム障害に比べて注意欠陥多動性障害〈ADHD〉で高頻度にみられる症状はどれか。', '[{"key": "A", "text": "視線が合わない。"}, {"key": "B", "text": "冗談が通じない。"}, {"key": "C", "text": "ケアレスミスが多い。"}, {"key": "D", "text": "的はずれの応答が多い。"}, {"key": "E", "text": "左右対象であることにこだわる。"}]'::jsonb, 'C', '正答は C「ケアレスミスが多い。」。

ADHDの中核は不注意、多動性、衝動性で、成人では不注意が目立ち、うっかりミス、忘れ物、段取りの悪さとして現れる。ほかの選択肢は対人関係やこだわりの特徴で、自閉スペクトラム症に多い。

出典：厚生労働省ホームページ 第115回医師国家試験 F004', '{"A": "視線を合わせにくいのは、自閉スペクトラム症の対人関係の特徴である。", "B": "言葉を字義どおりに受け取り冗談が通じないのは、自閉スペクトラム症に多い。", "D": "文脈を読み取れず的はずれな応答をするのは、自閉スペクトラム症に多い。", "E": "こだわりや常同的な行動は、自閉スペクトラム症の特徴である。"}'::jsonb, 'public', 'M', '115-F-4', '', 'pending', 'llm'),
('救急・中毒', '', 2, 'KOKUSHI', '各病態で使用する医薬品と投与経路の組合せで正しいのはどれか。', '[{"key": "A", "text": "アナフィラキシーショックにおけるアドレナリン — 筋肉注射"}, {"key": "B", "text": "下腿挫創における破傷風トキソイド — 静脈内注射"}, {"key": "C", "text": "高血圧緊急症におけるカルシウム拮抗薬 — 舌下投与"}, {"key": "D", "text": "糖尿病性ケトアシドーシスにおけるインスリン — 皮下注射"}, {"key": "E", "text": "熱性けいれんにおけるジアゼパム — 皮下注射"}]'::jsonb, 'A', '正答は A「アナフィラキシーショックにおけるアドレナリン — 筋肉注射」。

アナフィラキシーショックでは、アドレナリン0.01mg/kg（成人で最大0.5mg、小児で最大0.3mg）を大腿前外側に筋肉注射する。筋注は吸収が速く安全で、第一選択の投与経路である。

出典：厚生労働省ホームページ 第115回医師国家試験 F010', '{"B": "破傷風トキソイドは筋肉内または皮下に注射し、静注はしない。", "C": "ニフェジピンの舌下投与は急激な降圧で脳や心臓の虚血を招くため行わない。高血圧緊急症では静注薬で調節しながら下げる。", "D": "糖尿病性ケトアシドーシスでは速効型インスリンを持続静注する。脱水があり、皮下からの吸収は不安定である。", "E": "ジアゼパムは静注か坐剤で用い、皮下注射はしない。"}'::jsonb, 'public', 'M', '115-F-10', '', 'pending', 'llm'),
('小児科', '', 2, 'KOKUSHI', '予防接種法で任意の予防接種に含まれるのはどれか。', '[{"key": "A", "text": "MRワクチン"}, {"key": "B", "text": "水痘ワクチン"}, {"key": "C", "text": "日本脳炎ワクチン"}, {"key": "D", "text": "おたふくかぜワクチン"}, {"key": "E", "text": "ヒトパピローマウイルス〈HPV〉ワクチン"}]'::jsonb, 'D', '正答は D「おたふくかぜワクチン」。

おたふくかぜ（流行性耳下腺炎）のワクチンは日本では定期接種に含まれておらず、任意接種である。MR、水痘、日本脳炎、HPVのワクチンは予防接種法に基づく定期接種である。

出典：厚生労働省ホームページ 第115回医師国家試験 F011', '{"A": "MRワクチンは定期接種（1歳時と小学校入学前の年の2回）である。", "B": "水痘ワクチンは2014年から定期接種になっている。", "C": "日本脳炎ワクチンは定期接種である。", "E": "HPVワクチンは定期接種で、小学6年から高校1年相当の女子が対象である。"}'::jsonb, 'public', 'M', '115-F-11', '', 'pending', 'llm'),
('医学総論', '', 2, 'KOKUSHI', '死亡確認された成人遺体で、背部から下腿後面にかけての死斑と顎関節および四肢関節の硬直がみられた。角膜の混濁はみられず、直腸温は32°Cであった(外気温20°C)。推定される死後経過時間はどれか。', '[{"key": "A", "text": "1時間以内"}, {"key": "B", "text": "6〜12時間"}, {"key": "C", "text": "24〜30時間"}, {"key": "D", "text": "36〜42時間"}, {"key": "E", "text": "48時間以上"}]'::jsonb, 'B', '正答は B「6〜12時間」。

硬直が顎関節から四肢関節まで及んでいるのは死後6〜12時間ごろで、角膜の混濁がないことはおよそ12時間以内を示す。直腸温は37°Cから約5°C下がっており、室温20°Cで1時間に0.5〜1°C下がるとすると5〜10時間になる。合わせて死後6〜12時間と推定する。

出典：厚生労働省ホームページ 第115回医師国家試験 F015', '{"A": "硬直は死後2〜3時間で顎関節から始まり、1時間以内に四肢まで及ぶことはない。直腸温も下がりすぎている。", "C": "死後24〜30時間では角膜が混濁し、硬直も緩み始める。", "D": "死後36〜42時間では硬直が解け始め、角膜の混濁も強い。直腸温も外気温に近づいている。", "E": "死後48時間以上では硬直は解け、腐敗の徴候が現れてくる。"}'::jsonb, 'public', 'M', '115-F-15', '', 'pending', 'llm'),
('耳鼻咽喉科', '', 2, 'KOKUSHI', '悪性腫瘍とリスクファクターの組合せで正しいのはどれか。', '[{"key": "A", "text": "乳癌 — 多産"}, {"key": "B", "text": "肺癌 — β-ナフチルアミン"}, {"key": "C", "text": "結腸癌 — 炭水化物"}, {"key": "D", "text": "子宮頸癌 — EBウイルス"}, {"key": "E", "text": "中咽頭癌 — ヒトパピローマウイルス〈HPV〉"}]'::jsonb, 'E', '正答は E「中咽頭癌 — ヒトパピローマウイルス〈HPV〉」。

中咽頭癌（特に口蓋扁桃と舌根）の多くにはHPV（主に16型）の感染が関与している。喫煙や飲酒による癌より若い人に多く、予後は比較的よい。

出典：厚生労働省ホームページ 第115回医師国家試験 F016', '{"A": "乳癌の危険因子は未産、高齢での初産、早い初経と遅い閉経などで、多産はむしろ危険を下げる。", "B": "β-ナフチルアミンは膀胱癌の原因物質である。肺癌では喫煙、アスベスト、ラドンなどが知られる。", "C": "結腸癌の危険因子は赤肉や加工肉、肥満、飲酒などで、炭水化物ではない。", "D": "子宮頸癌の原因はHPVである。EBウイルスは上咽頭癌やBurkittリンパ腫に関与する。"}'::jsonb, 'public', 'M', '115-F-16', '', 'pending', 'llm'),
('小児科', '', 2, 'KOKUSHI', '救急外来で小児を診察した研修医から指導医への報告を以下に示す。研修医:「6歳の女児です。昨日から腹痛が持続するということで来院されました。膝関節も少し痛むということです。2週前に上気道炎で自宅近くの診療所を受診されていました。発熱、下痢や嘔吐はありません」指導医:「患児の外観はどうですか」研修医:「腹痛があり少し苦悶様です」指導医:「腹部所見はどうですか」研修医:「臍周辺の圧痛を認めます」指導医:「他の診察所見はどうですか」研修医:「胸部聴診上、異常所見なく、咽頭発赤もありません」指導医:「体幹に発疹はありますか」研修医:「ありません」指導医:「下腿に発疹はありませんでしたか」研修医:「あ、下腿はみていません」指導医:「下腿では、まずどのような所見を確認しますか」これに続く研修医の返答として最も適切なのはどれか。', '[{"key": "A", "text": "「紫斑の有無を確認します」"}, {"key": "B", "text": "「白斑の有無を確認します」"}, {"key": "C", "text": "「静脈瘤の有無を確認します」"}, {"key": "D", "text": "「爬行性線状疹の有無を確認します」"}, {"key": "E", "text": "「café au lait斑の有無を確認します」"}]'::jsonb, 'A', '正答は A「「紫斑の有無を確認します」」。

上気道炎の2週後に腹痛と関節痛が出ており、IgA血管炎を考える。下腿や殿部の触れることのできる紫斑が診断の手がかりになるので、まず下腿に紫斑がないかを確かめる。

出典：厚生労働省ホームページ 第115回医師国家試験 F042', '{"B": "白斑は尋常性白斑などでみられ、腹痛や関節痛とは結びつかない。", "C": "小児で静脈瘤はまれで、この症状とは関係しない。", "D": "爬行性線状疹は動物の幼虫が皮膚を移動してできる皮疹で、この症状とは関係しない。", "E": "café au lait斑は神経線維腫症1型などでみられ、急な腹痛や関節痛とは関係しない。"}'::jsonb, 'public', 'M', '115-F-42', '', 'pending', 'llm'),
('産科', '', 2, 'KOKUSHI', '32歳の女性。市販の妊娠検査薬で陽性となったため来院した。月経周期は20日〜60日と不規則で、最終月経開始日は受診日の10週前であった。基礎体温は記録していない。既往歴に特記すべきことはなかった。腟鏡診にて性器出血は認めない。経腟超音波検査にて子宮内に胎児を認め、頭殿長〈CRL〉は14mm(8週0日相当)、胎児心拍数は180bpmであった。妊婦に対する説明で、正しいのはどれか。', '[{"key": "A", "text": "「子宮内感染が疑われます」"}, {"key": "B", "text": "「胎児は順調に発育しています」"}, {"key": "C", "text": "「流産する可能性が高いと思います」"}, {"key": "D", "text": "「入院して安静にする必要があります」"}, {"key": "E", "text": "「分娩予定日は最終月経から決定します」"}]'::jsonb, 'B', '正答は B「「胎児は順調に発育しています」」。

頭殿長14mmは妊娠8週0日に相当し、胎児心拍数180bpmはこの時期の正常範囲（妊娠9週ごろに最も速く170〜180bpm）である。月経が不規則なので最終月経からの週数とずれるのは当然で、胎児は順調に発育している。

出典：厚生労働省ホームページ 第115回医師国家試験 F045', '{"A": "胎児心拍数は正常で、発熱など感染を示す所見もない。", "C": "胎児心拍が確認でき出血もなく、流産を心配する所見はない。", "D": "異常はなく、入院の必要はない。", "E": "月経が不規則なので、分娩予定日は妊娠初期の頭殿長から決める。"}'::jsonb, 'public', 'M', '115-F-45', '', 'pending', 'llm'),
('循環器', '', 2, 'KOKUSHI', '53歳の男性。心房細動に対するアブレーション治療を目的として入院した。40歳時に僧帽弁狭窄症に対して機械弁置換術が行われワルファリンが開始となった。48歳時から高血圧症、糖尿病に対して薬物療法が行われている。5か月前に突然動悸を自覚し、定期的に通院している診療所で心房細動と診断された。その後も月に数回、3〜5日程度持続する動悸発作が出現した。3か月前および1か月前の外来受診時の心電図でも心房細動が確認されたため、カテーテルアブレーション目的に紹介され入院となった。入院時は心房細動調律であった。入院2日目に行ったカテーテルアブレーションで洞調律に復帰し、入院6日目に退院となった。退院後のワルファリン治療について正しいのはどれか。', '[{"key": "A", "text": "継続して行う。"}, {"key": "B", "text": "アスピリンに変更する。"}, {"key": "C", "text": "動悸出現時に頓服する。"}, {"key": "D", "text": "ビタミンK製剤と併用する。"}, {"key": "E", "text": "直接経口抗凝固薬[direct oral anticoagulant〈DOAC〉]に変更する。"}]'::jsonb, 'A', '正答は A「継続して行う。」。

機械弁で置換したあとは、心房細動の有無にかかわらず、弁の血栓と塞栓症を防ぐためにワルファリンを生涯続ける。アブレーションで洞調律に戻っても中止しない。機械弁の患者にはDOACは使えない。

出典：厚生労働省ホームページ 第115回医師国家試験 F047', '{"B": "抗血小板薬では機械弁の血栓は防げない。", "C": "ワルファリンは効果が出るまで数日かかり、頓服では血栓を防げない。", "D": "ビタミンKはワルファリンの効果を打ち消してしまう。", "E": "機械弁の患者ではDOACで血栓症や出血が増え、禁忌である。"}'::jsonb, 'public', 'M', '115-F-47', '', 'pending', 'llm'),
('免疫・膠原病', '', 2, 'KOKUSHI', '32歳の女性。多発関節痛を主訴に受診した。半年前に両側手指、手関節および膝関節痛を自覚し、自宅近くの医療機関で関節リウマチと診断され、メトトレキサートの投与を受けた。効果が不十分のためメトトレキサートを漸増されたが、多発関節痛は持続した。最近になり仕事にも支障をきたすようになったため、専門の医療機関を受診するよう勧められ受診した。体温36.8°C、脈拍76/分、整。血圧128/82mmHg。両側手関節、両側示指、中指の中手指節関節および両側膝関節に腫脹と圧痛を認める。皮疹は認めない。血液所見:赤血球428万、Hb12.7g/dL、Ht38%、白血球7,900、血小板28万。血液生化学所見:総蛋白7.2g/dL、アルブミン4.0g/dL、IgG1,230mg/dL(基準960〜1,960)、AST25U/L、ALT28U/L、LD225U/L(基準120〜245)、尿素窒素12mg/dL、クレアチニン0.5mg/dL。免疫血清学所見:CRP5.2mg/dL、リウマトイド因子〈RF〉132IU/mL(基準20未満)、抗CCP抗体112U/mL(基準4.5未満)、抗核抗体陰性。治療方針として最も適切なのはどれか。', '[{"key": "A", "text": "コルヒチンを投与する。"}, {"key": "B", "text": "生物学的製剤を投与する。"}, {"key": "C", "text": "ステロイドパルス療法を行う。"}, {"key": "D", "text": "免疫グロブリン製剤を投与する。"}, {"key": "E", "text": "半年間現在の治療で様子をみるよう勧める。"}]'::jsonb, 'B', '正答は B「生物学的製剤を投与する。」。

リウマトイド因子と抗CCP抗体が高く、メトトレキサートを十分に使っても関節炎が続いている関節リウマチである。3〜6か月で目標（寛解か低疾患活動性）に届かなければ治療を強める。予後の悪い因子（抗体高値など）があるので、生物学的製剤（TNF阻害薬など）かJAK阻害薬を加える。

出典：厚生労働省ホームページ 第115回医師国家試験 F049', '{"A": "コルヒチンは痛風発作や家族性地中海熱に用いる薬で、関節リウマチには効かない。", "C": "ステロイドパルス療法は血管炎や重い臓器障害に行うもので、関節リウマチの関節炎には行わない。", "D": "免疫グロブリン製剤は川崎病、免疫性血小板減少症、Guillain-Barré症候群などに用いる。関節リウマチには用いない。", "E": "関節の破壊は発症早期に進むので、目標に届かないまま同じ治療を続けてはいけない。"}'::jsonb, 'public', 'M', '115-F-49', '', 'pending', 'llm'),
('救急・中毒', '', 2, 'KOKUSHI', '22歳の男性。墜落外傷のため救急車で搬入された。現病歴 : 地面から約6mの高所での作業中、誤って下肢から地面に墜落した。強い腰痛と左下肢の痛みを訴える。既往歴 : 特記すべきことはない。生活歴 : 工事現場作業員。家族歴 : 祖父が糖尿病。現症 : 意識レベルJCSI-3。身長170cm、体重60kg。体温35.6°C。心拍数128/分、整。血圧88/60mmHg。呼吸数24/分。SpO297%(リザーバー付マスク10L/分酸素投与下)。毛細血管再充満時間は3秒と延長している。瞳孔径は右4 mm 左4mm、対光反射は正常。顔面に挫創がみられる。口腔からの出血はない。頸静脈の怒張はない。胸部は左前胸部に圧痛がみられる。両側呼吸音は正常で左右差を認めない。皮下気腫はない。左下肢は外旋位で痛みのため動かそうとしないが、知覚異常は認めない。左下腿の創部から持続出血がみられ、土が多量に付着している。左足趾の動きに異常を認めない。離握手や開眼、閉眼の指示に応じる。皮膚には冷汗と湿潤がみられる。検査所見 : 尿所見:蛋白(−)、糖(−)、ケトン体(−)、潜血(−)、沈渣に白血球を認めない。血液所見:赤血球360万、Hb10.8g/dL、Ht32%、白血球12,600、血小板30万、PT-INR1.4(基準0.9〜1.1)、APTT41.0秒(基準対照32.2秒)、血漿フィブリノゲン168mg/dL(基準200〜400)。血液生化学所見:総蛋白5.0 g/dL、アルブミン2.9g/dL、総ビリルビン0.9mg/dL、AST60U/L、ALT22 U/L、CK130U/L (基準30〜140)、尿素窒素30mg/dL、クレアチニン0.9 mg/dL、血糖124mg/dL、Na133mEq/L、K4.8mEq/L、Cl104mEq/L。12誘導心電図:正常。画像所見:迅速簡易超音波検査〈FAST〉で心囊腔、胸腔および腹腔内の液体貯留はみられない。胸部エックス線写真で左4-7肋骨骨折と左肺野の透過性低下がみられる。骨盤エックス線写真で左第5腰椎横突起骨折、左腸骨骨折、左恥坐骨骨折および左仙腸関節の離開がみられる。下腿エックス線写真で左脛骨骨幹部骨折がみられる。
病態として最も考えられるのはどれか。', '[{"key": "A", "text": "アナフィラキシーショック"}, {"key": "B", "text": "出血性ショック"}, {"key": "C", "text": "神経原性ショック"}, {"key": "D", "text": "心原性ショック"}, {"key": "E", "text": "閉塞性ショック"}]'::jsonb, 'B', '正答は B「出血性ショック」。

骨盤骨折（仙腸関節の離開を伴う不安定型）と脛骨の開放骨折からの出血で、頻脈、血圧低下、冷汗、毛細血管再充満時間の延長がある。出血性ショックである。骨盤骨折の出血は後腹膜に広がるため、FASTでは液体貯留が見えない。

出典：厚生労働省ホームページ 第115回医師国家試験 F060', '{"A": "アナフィラキシーの原因となる曝露がなく、皮疹や喘鳴もない。", "C": "神経原性ショックは頸髄や上位胸髄の損傷で交感神経が遮断されて起き、徐脈と温かい皮膚が特徴である。本例は頻脈で冷汗があり、麻痺もない。", "D": "心電図は正常で、心囊液もなく、心臓の損傷を示す所見はない。", "E": "緊張性気胸や心タンポナーデを示す頸静脈の怒張、呼吸音の左右差、心囊液はいずれもない。"}'::jsonb, 'public', 'M', '115-F-60', '', 'pending', 'llm'),
('救急・中毒', '', 2, 'KOKUSHI', '22歳の男性。墜落外傷のため救急車で搬入された。現病歴 : 地面から約6mの高所での作業中、誤って下肢から地面に墜落した。強い腰痛と左下肢の痛みを訴える。既往歴 : 特記すべきことはない。生活歴 : 工事現場作業員。家族歴 : 祖父が糖尿病。現症 : 意識レベルJCSI-3。身長170cm、体重60kg。体温35.6°C。心拍数128/分、整。血圧88/60mmHg。呼吸数24/分。SpO297%(リザーバー付マスク10L/分酸素投与下)。毛細血管再充満時間は3秒と延長している。瞳孔径は右4 mm 左4mm、対光反射は正常。顔面に挫創がみられる。口腔からの出血はない。頸静脈の怒張はない。胸部は左前胸部に圧痛がみられる。両側呼吸音は正常で左右差を認めない。皮下気腫はない。左下肢は外旋位で痛みのため動かそうとしないが、知覚異常は認めない。左下腿の創部から持続出血がみられ、土が多量に付着している。左足趾の動きに異常を認めない。離握手や開眼、閉眼の指示に応じる。皮膚には冷汗と湿潤がみられる。検査所見 : 尿所見:蛋白(−)、糖(−)、ケトン体(−)、潜血(−)、沈渣に白血球を認めない。血液所見:赤血球360万、Hb10.8g/dL、Ht32%、白血球12,600、血小板30万、PT-INR1.4(基準0.9〜1.1)、APTT41.0秒(基準対照32.2秒)、血漿フィブリノゲン168mg/dL(基準200〜400)。血液生化学所見:総蛋白5.0 g/dL、アルブミン2.9g/dL、総ビリルビン0.9mg/dL、AST60U/L、ALT22 U/L、CK130U/L (基準30〜140)、尿素窒素30mg/dL、クレアチニン0.9 mg/dL、血糖124mg/dL、Na133mEq/L、K4.8mEq/L、Cl104mEq/L。12誘導心電図:正常。画像所見:迅速簡易超音波検査〈FAST〉で心囊腔、胸腔および腹腔内の液体貯留はみられない。胸部エックス線写真で左4-7肋骨骨折と左肺野の透過性低下がみられる。骨盤エックス線写真で左第5腰椎横突起骨折、左腸骨骨折、左恥坐骨骨折および左仙腸関節の離開がみられる。下腿エックス線写真で左脛骨骨幹部骨折がみられる。
その後、努力呼吸と舌根沈下が出現したため気管挿管を行った。CT検査に向かう準備をしていたところ、急にSpO2が70%となった(6L/分酸素投与下)。意識レベルはJCSIII-100。脈拍52/分、整。収縮期血圧50mmHg、拡張期血圧は測定不可。瞳孔径は右3mm、左3mm。対光反射は正常である。左前胸部に皮下気腫が出現した。聴診では左の呼吸音が消失し、打診で左前胸部に鼓音がみられる。再度行った迅速簡易超音波検査〈FAST〉では心囊腔、胸腔および腹腔内液体貯留はみられない。直ちに行うべき処置はどれか。', '[{"key": "A", "text": "胸腔穿刺"}, {"key": "B", "text": "胸骨圧迫"}, {"key": "C", "text": "高圧酸素療法〈高気圧酸素治療〉"}, {"key": "D", "text": "心囊穿刺"}, {"key": "E", "text": "鎮痛薬投与"}]'::jsonb, 'A', '正答は A「胸腔穿刺」。

陽圧換気を始めたあとに、左の呼吸音の消失、左胸部の鼓音、皮下気腫、急な低酸素と血圧低下が出ている。肋骨骨折に伴う気胸が陽圧換気で緊張性気胸になったもので、画像を待たずに胸腔穿刺で脱気し、続けて胸腔ドレーンを入れる。

出典：厚生労働省ホームページ 第115回医師国家試験 F062', '{"B": "脈拍は触れており心停止ではない。原因の緊張性気胸を解除しなければ循環は戻らない。", "C": "高気圧酸素治療は一酸化炭素中毒や減圧症に用いる。処置していない気胸は禁忌である。", "D": "心囊穿刺は心タンポナーデに行う。FASTで心囊液はない。", "E": "鎮痛薬では気胸は解除されず、かえって血圧を下げるおそれがある。"}'::jsonb, 'public', 'M', '115-F-62', '', 'pending', 'llm'),
('呼吸器', '', 2, 'KOKUSHI', '83歳の男性。食欲が低下し元気がないため妻とともに来院した。現病歴 : 約5年前から物忘れが目立ち、Alzheimer型認知症と診断されていた。1年前から記憶の低下がさらに進行し、5分前のことも忘れていることが多かった。同居する妻によると、2週前に38°Cの発熱があったが市販の総合感冒薬を内服して解熱したという。その頃から家でうとうとしながら座っていることが増え、食事量も半分くらいに減った。1週前、通い慣れている施設から家へ帰る道が初めて分からなくなった。昨日トイレ動作にも介助を要するようになったため、他院において緊急で頭部単純CTを行ったが、異常はなかった。本人は特に苦痛を訴えないが、妻によると3日前から喀痰がみられるという。既往歴 : 糖尿病でDPP-4阻害薬を服用中である。生活歴 : 喫煙は20本/日を40年間。飲酒は機会飲酒。妻と2人暮らし。家族歴 : 父母とも老衰で死亡。現症 : 意識レベルはJCSI-2。身長165cm、体重60kg。体温37.0°C。脈拍96/分、整。血圧106/60mmHg。呼吸数22/分。SpO294%(room air)。眼瞼結膜と眼球結膜とに異常を認めない。心音に異常を認めない。右下背部にcoarse cracklesを聴取する。腹部は平坦、軟で、肝・脾を触知しない。浮腫を認めない。瞳孔と眼球運動とに異常を認めない。腱反射は正常で運動麻痺、感覚障害および運動失調を認めない。検査所見 : 尿所見:蛋白(−)、糖(−)、潜血(−)、沈渣に赤血球、白血球を認めない。血液所見:赤血球370万、Hb12.0g/dL、Ht36%、白血球11,300(好中球79%、好酸球1%、好塩基球0%、単球6%、リンパ球13%)、血小板26万。血液生化学所見:総蛋白7.5g/dL、アルブミン3.5g/dL、AST22U/L、ALT11 U/L、ALP217U/L(基準115〜359)、γ-GT29U/L(基準8〜50)、アミラーゼ94 U/L(基準37〜160)、尿素窒素29mg/dL、クレアチニン1.1mg/dL、血糖140 mg/dL、HbA1c6.8% (基準4.6〜6.2)、Na136mEq/L、K4.6mEq/L、Cl96 mEq/L、Ca8.2mg/dL。CRP20mg/dL。
次に行うべき検査はどれか。', '[{"key": "A", "text": "頭部MRI"}, {"key": "B", "text": "腰椎穿刺"}, {"key": "C", "text": "腹部造影CT"}, {"key": "D", "text": "胸部エックス線撮影"}, {"key": "E", "text": "上部消化管内視鏡検査"}]'::jsonb, 'D', '正答は D「胸部エックス線撮影」。

高齢者の肺炎は、高熱や咳がはっきりせず、元気がない、食べない、ぼんやりしている、といった形で現れやすい。喀痰、右下背部のcoarse crackles、白血球とCRPの上昇から肺炎（誤嚥性肺炎）を疑い、まず胸部エックス線写真を撮る。

出典：厚生労働省ホームページ 第115回医師国家試験 F063', '{"A": "局所の神経症状はなく、頭部CTにも異常はない。まず肺炎を確かめる。", "B": "項部硬直などの髄膜刺激症状はなく、髄膜炎を疑う所見はない。", "C": "腹部は平坦、軟で、腹部の感染を疑う所見はない。", "E": "貧血や吐血、黒色便はなく、消化管出血を疑う所見はない。"}'::jsonb, 'public', 'M', '115-F-63', '', 'pending', 'llm'),
('呼吸器', '', 2, 'KOKUSHI', '83歳の男性。食欲が低下し元気がないため妻とともに来院した。現病歴 : 約5年前から物忘れが目立ち、Alzheimer型認知症と診断されていた。1年前から記憶の低下がさらに進行し、5分前のことも忘れていることが多かった。同居する妻によると、2週前に38°Cの発熱があったが市販の総合感冒薬を内服して解熱したという。その頃から家でうとうとしながら座っていることが増え、食事量も半分くらいに減った。1週前、通い慣れている施設から家へ帰る道が初めて分からなくなった。昨日トイレ動作にも介助を要するようになったため、他院において緊急で頭部単純CTを行ったが、異常はなかった。本人は特に苦痛を訴えないが、妻によると3日前から喀痰がみられるという。既往歴 : 糖尿病でDPP-4阻害薬を服用中である。生活歴 : 喫煙は20本/日を40年間。飲酒は機会飲酒。妻と2人暮らし。家族歴 : 父母とも老衰で死亡。現症 : 意識レベルはJCSI-2。身長165cm、体重60kg。体温37.0°C。脈拍96/分、整。血圧106/60mmHg。呼吸数22/分。SpO294%(room air)。眼瞼結膜と眼球結膜とに異常を認めない。心音に異常を認めない。右下背部にcoarse cracklesを聴取する。腹部は平坦、軟で、肝・脾を触知しない。浮腫を認めない。瞳孔と眼球運動とに異常を認めない。腱反射は正常で運動麻痺、感覚障害および運動失調を認めない。検査所見 : 尿所見:蛋白(−)、糖(−)、潜血(−)、沈渣に赤血球、白血球を認めない。血液所見:赤血球370万、Hb12.0g/dL、Ht36%、白血球11,300(好中球79%、好酸球1%、好塩基球0%、単球6%、リンパ球13%)、血小板26万。血液生化学所見:総蛋白7.5g/dL、アルブミン3.5g/dL、AST22U/L、ALT11 U/L、ALP217U/L(基準115〜359)、γ-GT29U/L(基準8〜50)、アミラーゼ94 U/L(基準37〜160)、尿素窒素29mg/dL、クレアチニン1.1mg/dL、血糖140 mg/dL、HbA1c6.8% (基準4.6〜6.2)、Na136mEq/L、K4.6mEq/L、Cl96 mEq/L、Ca8.2mg/dL。CRP20mg/dL。
検査の結果を確認すると「動脈血ガス分析(room air):pH7.38、PaCO245Torr、PaO230Torr、HCO3−26mEq/L」とあった。患者の呼吸数やSpO2(room air)は来院時と変化はない。採血時の状況を確認すると、シリンジへの逆流が弱く陰圧をかけながら採取したとのことであった。適切な対応はどれか。', '[{"key": "A", "text": "深呼吸を促す。"}, {"key": "B", "text": "酸素投与を開始する。"}, {"key": "C", "text": "Dダイマーを測定する。"}, {"key": "D", "text": "心エコー検査を実施する。"}, {"key": "E", "text": "動脈血を採取しなおして分析する。"}]'::jsonb, 'E', '正答は E「動脈血を採取しなおして分析する。」。

SpO2 94%ならPaO2はおよそ70Torrのはずで、PaO2 30Torrとは合わない。呼吸状態も変わっていない。シリンジへの逆流が弱く陰圧をかけて採ったことから、静脈血を採った可能性が高い。検査値と患者の状態が合わないときは、まず検体を疑い、動脈血を採り直す。

出典：厚生労働省ホームページ 第115回医師国家試験 F064', '{"A": "深呼吸をしても、採血の誤りは正せない。", "B": "SpO2は94%のままで、PaO2 30Torrは患者の実際の値ではない。値だけを見て酸素を始めない。", "C": "肺血栓塞栓症を疑う経過や所見はない。まず検体の誤りを正す。", "D": "心エコーで調べるべき所見はない。まず検体の誤りを正す。"}'::jsonb, 'public', 'M', '115-F-64', '', 'pending', 'llm'),
('医学総論', '', 2, 'KOKUSHI', '83歳の男性。食欲が低下し元気がないため妻とともに来院した。現病歴 : 約5年前から物忘れが目立ち、Alzheimer型認知症と診断されていた。1年前から記憶の低下がさらに進行し、5分前のことも忘れていることが多かった。同居する妻によると、2週前に38°Cの発熱があったが市販の総合感冒薬を内服して解熱したという。その頃から家でうとうとしながら座っていることが増え、食事量も半分くらいに減った。1週前、通い慣れている施設から家へ帰る道が初めて分からなくなった。昨日トイレ動作にも介助を要するようになったため、他院において緊急で頭部単純CTを行ったが、異常はなかった。本人は特に苦痛を訴えないが、妻によると3日前から喀痰がみられるという。既往歴 : 糖尿病でDPP-4阻害薬を服用中である。生活歴 : 喫煙は20本/日を40年間。飲酒は機会飲酒。妻と2人暮らし。家族歴 : 父母とも老衰で死亡。現症 : 意識レベルはJCSI-2。身長165cm、体重60kg。体温37.0°C。脈拍96/分、整。血圧106/60mmHg。呼吸数22/分。SpO294%(room air)。眼瞼結膜と眼球結膜とに異常を認めない。心音に異常を認めない。右下背部にcoarse cracklesを聴取する。腹部は平坦、軟で、肝・脾を触知しない。浮腫を認めない。瞳孔と眼球運動とに異常を認めない。腱反射は正常で運動麻痺、感覚障害および運動失調を認めない。検査所見 : 尿所見:蛋白(−)、糖(−)、潜血(−)、沈渣に赤血球、白血球を認めない。血液所見:赤血球370万、Hb12.0g/dL、Ht36%、白血球11,300(好中球79%、好酸球1%、好塩基球0%、単球6%、リンパ球13%)、血小板26万。血液生化学所見:総蛋白7.5g/dL、アルブミン3.5g/dL、AST22U/L、ALT11 U/L、ALP217U/L(基準115〜359)、γ-GT29U/L(基準8〜50)、アミラーゼ94 U/L(基準37〜160)、尿素窒素29mg/dL、クレアチニン1.1mg/dL、血糖140 mg/dL、HbA1c6.8% (基準4.6〜6.2)、Na136mEq/L、K4.6mEq/L、Cl96 mEq/L、Ca8.2mg/dL。CRP20mg/dL。
患者は入院加療の後、退院して介護保健施設に入所する方針となった。介助をすればきざみ食を摂ることができるが、食事中にむせ込むことも多い。今後の栄養摂取方法を決定するにあたりまず行うべきなのはどれか。', '[{"key": "A", "text": "握力の測定"}, {"key": "B", "text": "嚥下機能の評価"}, {"key": "C", "text": "骨密度の測定"}, {"key": "D", "text": "食事嗜好の確認"}, {"key": "E", "text": "地域の福祉事務所との相談"}]'::jsonb, 'B', '正答は B「嚥下機能の評価」。

食事中のむせ込みがあり、誤嚥性肺炎を起こしている。経口で食べ続けられるか、食事の形態をどう変えるか、経管栄養にするかを決めるには、まず嚥下機能を評価する（水飲みテスト、嚥下内視鏡検査、嚥下造影検査など）。

出典：厚生労働省ホームページ 第115回医師国家試験 F065', '{"A": "握力はサルコペニアの評価に使うが、安全に飲み込めるかは分からない。", "C": "骨密度は骨粗鬆症の評価で、栄養の摂り方を決めるものではない。", "D": "嗜好も大切だが、まず安全に飲み込めるかを確かめる。", "E": "福祉事務所は生活保護などの相談窓口で、栄養の摂り方を決めるためにまず行うことではない。"}'::jsonb, 'public', 'M', '115-F-65', '', 'pending', 'llm'),
('代謝・内分泌', '', 2, 'KOKUSHI', '42歳の男性。職場の健康診断で異常を指摘されて来院した。現病歴 : 20歳代の頃は体重68kg程度であったが、32歳での結婚を機に徐々に増加し、特にこの3年で10kg増加した。現在の体重は過去最大である。既往歴 : 特記すべきことはない。生活歴 : 喫煙歴はない。飲酒はビール500mL/日。仕事は事務作業で通勤以外の運動習慣はない。家族歴 : 父親が糖尿病、高血圧症、脳梗塞。現症 : 意識は清明。身長173cm、体重82kg、腹囲98cm。脈拍68/分。血圧146/92mmHg。腹部は平坦、軟で、肝・脾は触知せず、皮膚線条は認めない。四肢に浮腫を認めない。皮膚の菲薄化を認めない。検査所見 : 尿所見:蛋白(−)、糖(−)、ケトン体(−)。血液所見:赤血球465万、Hb14.6g/dL、Ht46%、白血球6,800、血小板28万。血液生化学所見:AST 38U/L、ALT78U/L、γ-GT52U/L(基準8〜50)、尿素窒素19mg/dL、クレアチニン0.9mg/dL、尿酸6.8mg/dL、空腹時血糖116mg/dL、HbA1c6.2%(基準4.6〜6.2)、総コレステロール264mg/dL、トリグリセリド212mg/dL、HDLコレステロール34mg/dL、Na141mEq/L、K3.5mEq/L、Cl98mEq/L。
この患者で増加しているのはどれか。', '[{"key": "A", "text": "LDLのみ"}, {"key": "B", "text": "HDLのみ"}, {"key": "C", "text": "VLDLのみ"}, {"key": "D", "text": "LDLとHDL"}, {"key": "E", "text": "LDLとVLDL"}]'::jsonb, 'E', '正答は E「LDLとVLDL」。

Friedewaldの式でLDLコレステロールは264−34−212/5≒188mg/dLと高く、トリグリセリドも212mg/dLと高い。トリグリセリドを多く運ぶのはVLDLなので、LDLとVLDLがともに増えている（IIb型）。HDLコレステロールは34mg/dLと低い。

出典：厚生労働省ホームページ 第115回医師国家試験 F074', '{"A": "トリグリセリドが高く、VLDLも増えている。", "B": "HDLコレステロールは34mg/dLと低い。", "C": "LDLコレステロールも約188mg/dLと高い。", "D": "HDLコレステロールは低下している。"}'::jsonb, 'public', 'M', '115-F-74', '', 'pending', 'llm'),
('呼吸器', '', 2, 'KOKUSHI', '睡眠時無呼吸症候群による高血圧について、正しくないのはどれか。', '[{"key": "A", "text": "夜間高血圧となることが多い。"}, {"key": "B", "text": "肥満患者では減量を推奨する。"}, {"key": "C", "text": "α遮断薬が第一選択薬である。"}, {"key": "D", "text": "家庭血圧では早朝に高血圧となることが多い。"}, {"key": "E", "text": "持続的気道陽圧法〈CPAP〉で降圧が期待される。"}]'::jsonb, 'C', '正答は C「α遮断薬が第一選択薬である。」。

睡眠時無呼吸症候群では、無呼吸による低酸素と覚醒のたびに交感神経が高まり、夜間から早朝の血圧が上がる。治療の基本は減量とCPAPで、降圧薬はふつうの高血圧と同じくCa拮抗薬やARB・ACE阻害薬などを用いる。α遮断薬は第一選択ではない。

出典：厚生労働省ホームページ 第116回医師国家試験 A001', '{"A": "交感神経の緊張で夜間に血圧が下がらず、夜間高血圧となることが多い。正しい。", "B": "肥満は最大の危険因子で、減量で無呼吸も血圧も改善する。正しい。", "D": "夜間から続く交感神経の緊張で、早朝の高血圧となることが多い。正しい。", "E": "CPAPで無呼吸が減り、血圧が下がる。正しい。"}'::jsonb, 'public', 'M', '116-A-1', '', 'pending', 'llm'),
('産科', '', 2, 'KOKUSHI', '妊娠末期の腟分泌物細菌培養検査でB群連鎖球菌〈GBS〉が陽性となった妊婦に対する母子感染予防対策として、ペニシリン系抗菌薬の投与を開始する適切な時期はどれか。', '[{"key": "A", "text": "陽性判明の時点"}, {"key": "B", "text": "妊娠37週時"}, {"key": "C", "text": "陣痛開始時"}, {"key": "D", "text": "子宮口全開大時"}, {"key": "E", "text": "児頭排臨時"}]'::jsonb, 'C', '正答は C「陣痛開始時」。

GBSは分娩のときに産道で児に感染し、新生児の敗血症や髄膜炎を起こす。予防の抗菌薬は、陣痛が始まったとき（または破水したとき）から分娩までペニシリンを静注する。分娩の4時間以上前に始めると効果が高い。

出典：厚生労働省ホームページ 第116回医師国家試験 A002', '{"A": "分娩前に投与しても、分娩のときには再び保菌しているので予防にならない。", "B": "妊娠37週に投与しても、分娩のときには再び保菌している。", "D": "子宮口が全開大してからでは分娩までの時間が短く、十分な効果が得られない。", "E": "児頭排臨の時点では遅すぎる。"}'::jsonb, 'public', 'M', '116-A-2', '', 'pending', 'llm'),
('眼科', '', 2, 'KOKUSHI', '中心性漿液性脈絡網膜症について誤っているのはどれか。', '[{"key": "A", "text": "夜盲を自覚する。"}, {"key": "B", "text": "変視症を自覚する。"}, {"key": "C", "text": "自然治癒することが多い。"}, {"key": "D", "text": "蛍光眼底造影が有用である。"}, {"key": "E", "text": "光干渉断層計〈OCT〉が有用である。"}]'::jsonb, 'A', '正答は A「夜盲を自覚する。」。

中心性漿液性脈絡網膜症は働き盛りの男性に多く、ストレスや副腎皮質ステロイドが誘因になる。黄斑部に漿液性網膜剝離ができ、中心暗点、変視症、小視症を訴える。夜盲は網膜色素変性症やビタミンA欠乏症の症状である。

出典：厚生労働省ホームページ 第116回医師国家試験 A003', '{"B": "黄斑部の網膜剝離で、ゆがんで見える（変視症）。正しい。", "C": "数か月で自然に治ることが多い。長引けば漏出点をレーザーで凝固する。正しい。", "D": "蛍光眼底造影で網膜色素上皮からの漏出点が分かる。正しい。", "E": "OCTで黄斑部の漿液性網膜剝離が分かる。正しい。"}'::jsonb, 'public', 'M', '116-A-3', '', 'pending', 'llm'),
('循環器', '', 2, 'KOKUSHI', '62歳の女性。息切れと全身倦怠感を主訴に来院した。7日前に発作性心房細動に対してカテーテルアブレーションが施行されており、3日前に退院していた。退院翌日に息切れと全身倦怠感が出現し、症状が徐々に増悪するため受診した。意識は清明。体温36.2°C。脈拍112/分、整。血圧88/72mmHg。血圧は吸気時に収縮期血圧が18mmHg低下する。呼吸数18/分。SpO295%(room air)。呼吸音に異常を認めない。心音は微弱だが雑音は聴取しない。頸静脈は怒張している。血液所見:赤血球462万、Hb13.2g/dL、Ht39%、白血球9,700、血小板39万。血液生化学所見:尿素窒素44mg/dL、クレアチニン1.7mg/dL、Na141mEq/L、K4.2 mEq/L、Cl110mEq/L。最も考えられる病態はどれか。', '[{"key": "A", "text": "後腹膜血腫"}, {"key": "B", "text": "心室中隔穿孔"}, {"key": "C", "text": "肺血栓塞栓症"}, {"key": "D", "text": "心タンポナーデ"}, {"key": "E", "text": "完全房室ブロック"}]'::jsonb, 'D', '正答は D「心タンポナーデ」。

カテーテルアブレーションのあとに、頻脈、低血圧、頸静脈の怒張、心音の減弱（Beckの三徴）と奇脈（吸気時に収縮期血圧が10mmHg以上下がる）が出ている。手技で心臓に穴が開いて起きた心タンポナーデで、心エコーで確かめて心囊穿刺を行う。

出典：厚生労働省ホームページ 第116回医師国家試験 A019', '{"A": "後腹膜血腫は穿刺部からの出血で起き、出血性ショックとなるが、頸静脈は怒張しない。Hbも保たれている。", "B": "心室中隔穿孔は心筋梗塞のあとに起き、大きな汎収縮期雑音を聴取する。", "C": "肺血栓塞栓症では低酸素血症が目立つ。SpO2は保たれ、心音の減弱と奇脈は心タンポナーデに合う。", "E": "完全房室ブロックでは徐脈になる。脈拍は112/分である。"}'::jsonb, 'public', 'M', '116-A-19', '', 'pending', 'llm'),
('代謝・内分泌', '', 2, 'KOKUSHI', '48歳の女性。口渇と全身倦怠感を主訴に来院した。5日前に発熱と腹痛があった。食事はいつも通り摂取している。意識は清明。体温36.8°C。脈拍84/分、整。血圧108/68mmHg。眼瞼結膜と眼球結膜に異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。尿所見:蛋白(−)、糖3+、ケトン体3+、潜血(−)。血液所見:Hb13.2g/dL、白血球9,500、血小板24万。血液生化学所見:血糖440 mg/dL、HbA1c5.8%(基準4.6〜6.2)、Cペプチド0.2ng/mL(基準0.8〜2.5)。患者への説明として適切なのはどれか。', '[{"key": "A", "text": "「食事と運動で良くなります」"}, {"key": "B", "text": "「直ちにインスリンを使用します」"}, {"key": "C", "text": "「まず飲み薬で糖尿病の治療を始めます」"}, {"key": "D", "text": "「HbA1cが正常なので糖尿病とはいえません」"}, {"key": "E", "text": "「経過観察のため半年後に受診してください」"}]'::jsonb, 'B', '正答は B「「直ちにインスリンを使用します」」。

発熱や腹痛のあと数日で高血糖とケトーシスが出ており、HbA1cはほぼ正常で、Cペプチドは枯渇している。劇症1型糖尿病で、膵β細胞が急速に壊れてインスリンが出なくなっている。放置すると急速にケトアシドーシスに陥るので、直ちにインスリンを始める。

出典：厚生労働省ホームページ 第116回医師国家試験 A031', '{"A": "インスリンがほとんど出ておらず、食事と運動では良くならない。", "C": "経口血糖降下薬はインスリンが出なければ効かず、ケトーシスもあるので用いない。", "D": "HbA1cが正常なのは発症が急だからである。血糖440mg/dLとケトン体陽性から、急を要する糖尿病である。", "E": "数日のうちにケトアシドーシスに陥り、命にかかわる。"}'::jsonb, 'public', 'M', '116-A-31', '', 'pending', 'llm'),
('循環器', '', 2, 'KOKUSHI', '73歳の男性。歩行時の左下肢痛を主訴に来院した。2か月前から400m程度の歩行で左ふくらはぎに痛みが出現し、立ち止まって休憩すると消失していた。最近200m程度で症状を認めるため来院した。43歳から糖尿病に対して定期的な投薬治療が行われている。7年前に狭心症に対して冠動脈内ステント留置術が行われており、5年前から透析治療を受けている。喫煙は20歳から現在まで20本/日、飲酒は機会飲酒。意識は清明。身長169cm、体重57kg。体温35.9°C。脈拍84/分、整。血圧158/92mmHg。呼吸数20/分。SpO295%(room air)。足関節上腕血圧比〈ABI〉は右側で0.91、左側で0.65であった。研修医と指導医の会話を示す。指導医:「この患者さんの症状をどう表現しますか」研修医:「①間欠性跛行だと思います」指導医:「背景にある病態として、どのようなものがありますか」研修医:「②神経性のものとして腰部脊柱管狭窄症などがあり、③血管性のものとして浅大腿動脈の狭窄などがあります」指導医:「この患者さんのABI値からは何が疑われますか」研修医:「④閉塞性動脈硬化症の可能性が高いと思います」指導医:「今後、どのような検査を行いますか」研修医:「⑤ガドリニウム造影MRI検査を予定します」下線部のうち誤っているのはどれか。', '[{"key": "A", "text": "①"}, {"key": "B", "text": "②"}, {"key": "C", "text": "③"}, {"key": "D", "text": "④"}, {"key": "E", "text": "⑤"}]'::jsonb, 'E', '正答は E「⑤」。

透析中の患者にガドリニウム造影剤を使うと、腎性全身性線維症を起こすおそれがあり、原則として用いない。下肢動脈の評価には、造影剤を使わないMRA、超音波検査、CT血管造影などを選ぶ。

出典：厚生労働省ホームページ 第116回医師国家試験 A033', '{"A": "歩くと痛み、休むと治まるのは間欠性跛行である。正しい。", "B": "腰部脊柱管狭窄症でも神経性の間欠性跛行が起きる（前かがみで楽になる）。正しい。", "C": "浅大腿動脈が狭くなると、ふくらはぎに跛行が起きる。正しい。", "D": "ABI 0.9以下は下肢動脈の狭窄や閉塞を示す。左0.65で症状も合い、閉塞性動脈硬化症が疑われる。正しい。"}'::jsonb, 'public', 'M', '116-A-33', '', 'pending', 'llm'),
('代謝・内分泌', '', 2, 'KOKUSHI', '52歳の男性。全身倦怠感を主訴に来院した。6週間前に進行肺腺癌と診断され、3週間前に免疫チェックポイント阻害薬による初回治療を受けた。全身倦怠感が出現したため受診した。意識は清明であるが受け答えは緩慢である。体温36.8°C。脈拍108/分、整。血圧72/50mmHg。呼吸数20/分。SpO297%(room air)。軽度腫大した甲状腺を触知する。血液所見:赤血球320万、Hb12.0g/dL、Ht38%。血液生化学所見:血糖104mg/dL、TSH0.1μU/mL(基準0.2〜4.0)、ACTH2.0 pg/mL(基準60以下)、FT41.8ng/dL(基準0.8〜2.2)、コルチゾール0.1μg/dL(基準5.2〜12.6)であった。胸部エックス線写真で原発巣の縮小を認める。甲状腺超音波検査では軽度の甲状腺腫大以外は異常を認めない。治療として適切なのはどれか。', '[{"key": "A", "text": "赤血球輸血"}, {"key": "B", "text": "インスリン投与"}, {"key": "C", "text": "殺細胞性抗癌薬投与"}, {"key": "D", "text": "甲状腺ホルモン投与"}, {"key": "E", "text": "副腎皮質ステロイド投与"}]'::jsonb, 'E', '正答は E「副腎皮質ステロイド投与」。

免疫チェックポイント阻害薬による下垂体炎で、ACTHとコルチゾールが低く、ショックに近い低血圧がある。続発性の副腎不全で、直ちにヒドロコルチゾールを投与する。副腎不全を治す前に甲状腺ホルモンを投与すると、コルチゾールの代謝が進んで副腎クリーゼを悪化させる。

出典：厚生労働省ホームページ 第116回医師国家試験 A035', '{"A": "Hb 12.0g/dLで、輸血の必要はない。", "B": "血糖は104mg/dLで、インスリンは要らない。", "C": "原発巣は縮小している。まず命にかかわる副腎不全を治す。", "D": "FT4は正常範囲である。副腎不全があるときに甲状腺ホルモンを先に投与してはいけない。"}'::jsonb, 'public', 'M', '116-A-35', '', 'pending', 'llm'),
('循環器', '', 2, 'KOKUSHI', '45歳の男性。労作時の息切れ、全身倦怠感を主訴に来院した。5年前からサイクリングで遠出をすると息切れを自覚していた。徐々により軽い労作で症状が出現するようになり、半年前からは15分程度の通勤でも息切れが出現し、駅の階段を一気に昇れないこともあった。会社の健診では、以前から心雑音を指摘されていたが精査は行っていない。家族歴に特記すべきことはない。意識は清明。体温36.0°C。脈拍88/分、整。血圧124/72mmHg。呼吸数16/分。SpO295%(room air)。呼吸音に異常を認めない。Levine4/6の収縮期雑音を聴取する。心電図では左室高電位、心室期外収縮の3連発を認めた。心エコー検査では左室拡張末期径は60 mm、左室駆出率は40%であり、大動脈弁は二尖弁と判断された。連続波ドプラ法による測定では大動脈弁最大血流速度は5.0m/秒であり、大動脈弁口面積は0.65cm2と推定された。適切な対応はどれか。', '[{"key": "A", "text": "大動脈弁置換術"}, {"key": "B", "text": "植込み型除細動器の植込み"}, {"key": "C", "text": "トレッドミル運動負荷心電図"}, {"key": "D", "text": "治療せずに半年後に心エコー検査"}, {"key": "E", "text": "ヒト心房利尿ペプチド〈hANP〉投与"}]'::jsonb, 'A', '正答は A「大動脈弁置換術」。

大動脈弁最大血流速度5.0m/秒、弁口面積0.65cm²の重症大動脈弁狭窄症（二尖弁）で、労作時の息切れがあり、左室駆出率も40%に下がっている。症状のある重症例、左室機能が落ちた重症例はいずれも弁置換の適応で、45歳なので外科的な大動脈弁置換術を行う。

出典：厚生労働省ホームページ 第116回医師国家試験 A049', '{"B": "心室期外収縮は大動脈弁狭窄による左室の負担で起きている。まず原因の弁を治す。", "C": "症状のある重症大動脈弁狭窄症に運動負荷をかけると、失神や突然死の危険があり、禁忌である。", "D": "症状が出た重症例は、治療しなければ突然死や心不全の危険が高い。", "E": "hANPは急性心不全の治療薬で、弁の狭窄は治せない。"}'::jsonb, 'public', 'M', '116-A-49', '', 'pending', 'llm'),
('血液', '', 2, 'KOKUSHI', '18歳の男子。全身倦怠感と発熱を主訴に来院した。2週間前から労作時の息切れを自覚していた。3日前から38°C台の発熱と全身倦怠感があり受診した。身長170cm、体重60kg。体温38.3°C。脈拍100/分、整。血圧118/64mmHg。両下肢に点状出血を認める。眼瞼結膜は貧血様であるが、眼球結膜に黄染を認めない。胸骨右縁第2肋間を最強点とするLevine2/6の収縮期駆出性雑音を聴取する。呼吸音に異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。圧痛を認めない。血液所見:赤血球230万、Hb6.8g/dL、Ht20%、白血球1,400(分葉核好中球24%、単球2%、リンパ球74%)、血小板1.2万。血液生化学所見:総蛋白6.8 g/dL、アルブミン3.4g/dL、総ビリルビン0.7mg/dL、AST56U/L、ALT71 U/L、LD158U/L (基準120〜245)、尿素窒素14mg/dL、クレアチニン0.7 mg/dL、血糖98mg/dL。CRP4.2mg/dL。骨髄生検では著明な低形成所見を認める。この患者で低下するのはどれか。', '[{"key": "A", "text": "フェリチン"}, {"key": "B", "text": "網赤血球数"}, {"key": "C", "text": "ビタミンB12"}, {"key": "D", "text": "エリスロポエチン"}, {"key": "E", "text": "好中球アルカリフォスファターゼスコア"}]'::jsonb, 'B', '正答は B「網赤血球数」。

汎血球減少と骨髄の著明な低形成から、再生不良性貧血である。骨髄で赤血球が作られないので、網赤血球は減る。

出典：厚生労働省ホームページ 第116回医師国家試験 A056', '{"A": "鉄が使われずに余るため、フェリチンは正常か高くなる。輸血を重ねるとさらに高くなる。", "C": "ビタミンB12は正常である。低下するのは巨赤芽球性貧血である。", "D": "貧血に反応してエリスロポエチンは高くなる。", "E": "好中球アルカリフォスファターゼスコアは再生不良性貧血で高くなる。低下するのは慢性骨髄性白血病や発作性夜間ヘモグロビン尿症である。"}'::jsonb, 'public', 'M', '116-A-56', '', 'pending', 'llm'),
('代謝・内分泌', '', 2, 'KOKUSHI', '78歳の女性。1週間前から38°C台の発熱が持続し、全身倦怠感のため来院した。身長151cm、体重42kg。体温38.2°C。脈拍92/分、整。血圧84/50mmHg。胸腹部に異常所見を認めない。皮膚の乾燥や四肢に浮腫を認めない。血液生化学所見:尿素窒素24mg/dL、クレアチニン0.7mg/dL、空腹時血糖65mg/dL、Na 129mEq/L、K5.1mEq/L、抗利尿ホルモン1.4pg/mL(基準0.5〜2.0)。随時尿での尿中Naは16mEq/Lであった。この患者で認められる所見はどれか。', '[{"key": "A", "text": "低尿酸血症"}, {"key": "B", "text": "低レニン血症"}, {"key": "C", "text": "尿浸透圧低下"}, {"key": "D", "text": "甲状腺機能低下症"}, {"key": "E", "text": "低コルチゾール血症"}]'::jsonb, 'E', '正答は E「低コルチゾール血症」。

発熱（感染）をきっかけに、低血圧、低Na血症、高めのK、低血糖が出ている。副腎不全の組み合わせで、コルチゾールが低い。コルチゾールが足りないとADHの分泌が抑えられず、低Na血症を強める（Na 129mEq/LでもADHが抑えられていない）。

出典：厚生労働省ホームページ 第116回医師国家試験 A063', '{"A": "低尿酸血症はSIADHのように体液が増えたときにみられる。本例は低血圧で体液は減っている。", "B": "低血圧で体液が減っているので、レニンは高くなる。", "C": "ADHが抑えられていないので尿は濃く、尿浸透圧は低下しない。", "D": "甲状腺機能低下症でも低Na血症は起きるが、発熱を契機とした低血圧と低血糖は副腎不全で説明できる。"}'::jsonb, 'public', 'M', '116-A-63', '', 'pending', 'llm'),
('精神科', '', 2, 'KOKUSHI', '患者の言葉のうち幻聴ではないと考えられるのはどれか。', '[{"key": "A", "text": "「部屋に誰もいないのに『もっと勉強しろ』と男が話しかけてきます」"}, {"key": "B", "text": "「自分でもおかしいと思うが、近くに線路はないのに電車の走る音がします」"}, {"key": "C", "text": "「家族は誰も聞こえないというが、夜になると車のエンジンをかける音が聞こえます」"}, {"key": "D", "text": "「カチカチという実際の機械の音に重なって『馬鹿、馬鹿』という女性の声が聞こえます」"}, {"key": "E", "text": "「駅の向かい側のホームに立っている友人の仕草から自分の悪口をいっているのがわかります」"}]'::jsonb, 'E', '正答は E「「駅の向かい側のホームに立っている友人の仕草から自分の悪口をいっているのがわかります」」。

幻聴は、実際にはない音や声が聞こえる知覚の異常である。Eは友人の仕草を実際に見ており、知覚そのものに誤りはない。見たものに「自分の悪口をいっている」という意味を確信的に結びつけるのは妄想知覚（関係づけ）で、統合失調症でみられる。

出典：厚生労働省ホームページ 第116回医師国家試験 B003', '{"A": "誰もいないのに人の声が聞こえる。言語性の幻聴である。", "B": "病識はあるが、実際にない電車の音が聞こえている。要素性の幻聴である。", "C": "ほかの人には聞こえない音が聞こえている。幻聴である。", "D": "実際の音に重なって別の声が聞こえる。機能性幻聴と呼ばれる幻聴である。"}'::jsonb, 'public', 'M', '116-B-3', '', 'pending', 'llm'),
('産科', '', 2, 'KOKUSHI', '妊娠後期に比べ妊娠初期に高値を示すのはどれか。', '[{"key": "A", "text": "エストロゲン"}, {"key": "B", "text": "プロラクチン"}, {"key": "C", "text": "プロゲステロン"}, {"key": "D", "text": "ヒト胎盤性ラクトーゲン〈hPL〉"}, {"key": "E", "text": "ヒト絨毛性ゴナドトロピン〈hCG〉"}]'::jsonb, 'E', '正答は E「ヒト絨毛性ゴナドトロピン〈hCG〉」。

hCGは受精卵の絨毛から出て妊娠黄体を保ち、妊娠8〜10週ごろに最も高くなり、その後は下がって低いまま続く。ほかのホルモンは胎盤が大きくなるにつれて増え、妊娠末期に最も高い。

出典：厚生労働省ホームページ 第116回医師国家試験 B007', '{"A": "エストロゲン（エストリオール）は胎児と胎盤で作られ、妊娠末期に向けて増え続ける。", "B": "プロラクチンは妊娠の進行とともに増え、末期に最も高い。", "C": "プロゲステロンは初期は黄体、その後は胎盤で作られ、末期に向けて増える。", "D": "hPLは胎盤の大きさに比例して増え、末期に最も高い。"}'::jsonb, 'public', 'M', '116-B-7', '', 'pending', 'llm'),
('循環器', '', 2, 'KOKUSHI', '83歳の女性。4日前からの右腰部痛と悪寒戦慄を伴う発熱を主訴に来院した。来院時、意識は清明。見当識障害はない。体温38.6°C。脈拍102/分、整。血圧138/88mmHg。呼吸数24/分。SpO297%(room air)。頭頸部に異常を認めない。心臓の聴診で心尖部を最強点とするLevine3/6の収縮期雑音を聴取する。呼吸音に異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。四肢・末梢に皮疹を認めない。入院時に行った血液培養2セット(4本)からクラスター状に集簇するグラム陽性球菌が検出された。次に行うべき検査はどれか。', '[{"key": "A", "text": "胸部単純CT"}, {"key": "B", "text": "頸動脈エコー"}, {"key": "C", "text": "経胸壁心エコー"}, {"key": "D", "text": "上部消化管内視鏡"}, {"key": "E", "text": "腹部単純エックス線"}]'::jsonb, 'C', '正答は C「経胸壁心エコー」。

血液培養2セットともにクラスター状のグラム陽性球菌（ブドウ球菌）が生え、心雑音を聴取する。黄色ブドウ球菌の菌血症は感染性心内膜炎を合併しやすいので、まず経胸壁心エコーで疣贅や弁の破壊を探す（見つからなくても疑いが強ければ経食道心エコーを行う）。腰痛は化膿性脊椎炎や腎梗塞など、菌血症の合併症を考えて調べる。

出典：厚生労働省ホームページ 第116回医師国家試験 B027', '{"A": "呼吸器の症状や所見はなく、胸部CTを急ぐ理由はない。", "B": "頸動脈エコーは動脈硬化の評価で、菌血症の原因や合併症は分からない。", "D": "消化管の症状はなく、上部消化管内視鏡を行う理由はない。", "E": "腹部単純エックス線では感染源も合併症も分からない。"}'::jsonb, 'public', 'M', '116-B-27', '', 'pending', 'llm'),
('救急・中毒', '', 2, 'KOKUSHI', '35歳の男性。登山道脇で動けなくなっているところを発見された。ドクターカーで出動した医師が登山口で待機していた。現地の天候は雨、気温は10°C。医師がこの男性に接触した時、意識レベルはJCSII-30。体温(直腸温)31.4°C。脈拍58/分、整。血圧102/62mmHg。呼吸数30/分。SpO2は測定できず、末梢循環不全によるものと考えられた。病院前救護として誤っているのはどれか。', '[{"key": "A", "text": "全身を毛布で覆う。"}, {"key": "B", "text": "濡れた衣服を脱がせる。"}, {"key": "C", "text": "アドレナリンを静注する。"}, {"key": "D", "text": "加温した輸液を投与する。"}, {"key": "E", "text": "清拭して外傷を確認する。"}]'::jsonb, 'C', '正答は C「アドレナリンを静注する。」。

直腸温31.4°Cの偶発性低体温症で、脈は触れ血圧も保たれている。心停止ではないのでアドレナリンは使わない。濡れた衣服を脱がせ、毛布で覆い、加温した輸液を行う。冷えた心臓は刺激で心室細動を起こしやすいので、体は静かに扱う。

出典：厚生労働省ホームページ 第116回医師国家試験 B036', '{"A": "毛布で覆い、これ以上体温が下がるのを防ぐ。正しい。", "B": "濡れた衣服は気化熱で体温を奪うので脱がせる。正しい。", "D": "加温した輸液で体の中から温める。正しい。", "E": "体を拭いて乾かし、外傷がないか確かめる。正しい。"}'::jsonb, 'public', 'M', '116-B-36', '', 'pending', 'llm'),
('医学総論', '', 2, 'KOKUSHI', '76歳の男性。食欲低下と全身倦怠感を主訴に来院した。現病歴 : 58歳時に高血圧症と診断され、内服加療を受けていた。5年前から尿蛋白1g/日以上が持続するようになり、腎機能も徐々に増悪してきていた。1週間前から食欲が低下し、全身倦怠感が強くなってきたため、外来通院中の病院を受診した。既往歴 : 72歳時に狭心症で入院加療歴がある。生活歴 : 喫煙歴は20歳から40本/日を56年間。飲酒は日本酒1合/日。家族歴 : 母親が高血圧症で治療歴がある。現症 : 意識は清明。身長162cm、体重47kg。体温36.4°C。脈拍64/分、整。血圧146/92mmHg。呼吸数16/分。SpO296%(room air)。眼瞼結膜に異常を認めない。頸静脈の怒張を認めない。心音と呼吸音に異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。両下腿に圧痕性浮腫を認める。検査所見 : 尿所見:蛋白3+、糖(−)、潜血(−)、1日尿蛋白3.3g/日。血液所見:赤血球292万、Hb8.8g/dL、Ht28%、白血球5,800、血小板18万。血液生化学所見:総蛋白6.3g/dL、アルブミン3.4g/dL、尿素窒素86mg/dL、クレアチニン8.4mg/dL、eGFR6mL/min/1.73m2、尿酸9.8mg/dL、血糖113 mg/dL、Na131mEq/L、K7.2mEq/L、Cl104mEq/L。CRP0.8mg/dL。胸部エックス線写真で心胸郭比51%。
血液透析を開始するため右内頸静脈から透析用カテーテルを留置することとなった。超音波ガイド下にカテーテルを挿入中、患者の体動がみられ、胸が苦しいとの訴えがあった。患者の意識と呼吸状態の確認とともにまず行うべきことは何か。', '[{"key": "A", "text": "SpO2の確認"}, {"key": "B", "text": "胸部造影CT"}, {"key": "C", "text": "Dダイマー測定"}, {"key": "D", "text": "フロセミド静注"}, {"key": "E", "text": "ジアゼパム静注"}]'::jsonb, 'A', '正答は A「SpO2の確認」。

中心静脈カテーテルの挿入中に胸苦しさを訴えたら、気胸、空気塞栓、血胸、不整脈などの合併症を疑う。意識と呼吸を確かめるとともに、まずSpO2で酸素化が保たれているかをみて、血圧や心電図も確認する。

出典：厚生労働省ホームページ 第116回医師国家試験 B040', '{"B": "検査に向かう前に、まずベッドサイドで呼吸と循環を確かめる。", "C": "Dダイマーは急変したその場で評価に使うものではない。", "D": "いま起きたことを評価する前に利尿薬を使う理由はない。", "E": "鎮静すると呼吸が抑えられ、症状の評価もできなくなる。"}'::jsonb, 'public', 'M', '116-B-40', '', 'pending', 'llm'),
('医学総論', '', 2, 'KOKUSHI', '76歳の男性。食欲低下と全身倦怠感を主訴に来院した。現病歴 : 58歳時に高血圧症と診断され、内服加療を受けていた。5年前から尿蛋白1g/日以上が持続するようになり、腎機能も徐々に増悪してきていた。1週間前から食欲が低下し、全身倦怠感が強くなってきたため、外来通院中の病院を受診した。既往歴 : 72歳時に狭心症で入院加療歴がある。生活歴 : 喫煙歴は20歳から40本/日を56年間。飲酒は日本酒1合/日。家族歴 : 母親が高血圧症で治療歴がある。現症 : 意識は清明。身長162cm、体重47kg。体温36.4°C。脈拍64/分、整。血圧146/92mmHg。呼吸数16/分。SpO296%(room air)。眼瞼結膜に異常を認めない。頸静脈の怒張を認めない。心音と呼吸音に異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。両下腿に圧痕性浮腫を認める。検査所見 : 尿所見:蛋白3+、糖(−)、潜血(−)、1日尿蛋白3.3g/日。血液所見:赤血球292万、Hb8.8g/dL、Ht28%、白血球5,800、血小板18万。血液生化学所見:総蛋白6.3g/dL、アルブミン3.4g/dL、尿素窒素86mg/dL、クレアチニン8.4mg/dL、eGFR6mL/min/1.73m2、尿酸9.8mg/dL、血糖113 mg/dL、Na131mEq/L、K7.2mEq/L、Cl104mEq/L。CRP0.8mg/dL。胸部エックス線写真で心胸郭比51%。
この患者への処置中に発生した事象として考えにくいのはどれか。', '[{"key": "A", "text": "気胸"}, {"key": "B", "text": "血胸"}, {"key": "C", "text": "空気塞栓"}, {"key": "D", "text": "急性大動脈解離"}, {"key": "E", "text": "血腫による気道狭窄"}]'::jsonb, 'D', '正答は D「急性大動脈解離」。

内頸静脈からのカテーテル挿入では、気胸、血胸、空気塞栓、動脈の誤穿刺による血腫、不整脈などが起きうる。急性大動脈解離は、この手技の合併症としては考えにくい。

出典：厚生労働省ホームページ 第116回医師国家試験 B041', '{"A": "針が胸膜を貫くと気胸が起きる。", "B": "血管を傷つけると胸腔に出血して血胸が起きる。", "C": "静脈が開いたまま吸気で陰圧になると、空気が吸い込まれて空気塞栓が起きる。頭を低くした体位で挿入するのはこれを防ぐためである。", "E": "総頸動脈を誤って穿刺すると頸部に血腫ができ、気道を圧迫することがある。"}'::jsonb, 'public', 'M', '116-B-41', '', 'pending', 'llm'),
('代謝・内分泌', '', 2, 'KOKUSHI', '32歳の男性。左前腕を受傷し救急車で搬入された。現病歴 : 飲酒した状態で入浴し、浴槽から出た際にふらついてガラス戸に倒れ込み、ガラス片で左前腕屈側に受傷した。物音に気付いた家人が上腕部をタオルできつく縛って止血し、救急隊を要請した。既往歴 : 小児喘息の既往がある。生活歴 : 喫煙は20本/日を12年間。飲酒はビール1,000mL/日。家族歴 : 父親が糖尿病。現症 : 酩酊状態だが会話は可能である。身長172cm、体重67kg。体温37.2°C。心拍数84/分、整。血圧120/68mmHg。呼吸数20/分。SpO298%(room air)。搬入時、上腕はタオルで駆血された状態で、創部からの出血は止まっていた。受傷から80分経過していた。眼瞼結膜に異常は認めない。
上腕部のタオルを外すタイミングで適切なのはどれか。', '[{"key": "A", "text": "搬入後直ちに。"}, {"key": "B", "text": "画像所見を評価してから。"}, {"key": "C", "text": "血液検査の結果を確認してから。"}, {"key": "D", "text": "抗菌薬の投与を終えてから。"}, {"key": "E", "text": "手術を開始するとき。"}]'::jsonb, 'A', '正答は A「搬入後直ちに。」。

止血帯（駆血）は血流を止めるので、長く続けば末梢の筋や神経が不可逆的に傷む。受傷から既に80分が経っており、搬入後は直ちに外して出血の有無を見直し、出血していれば創部の直接圧迫に切り替える。

出典：厚生労働省ホームページ 第116回医師国家試験 B042', '{"B": "画像評価を待つ分だけ阻血時間が延びる。止血帯を外してからでも評価できる。", "C": "血液検査の結果を待つ理由がなく、その間も阻血が続く。", "D": "抗菌薬の投与と止血帯の解除は独立した処置で、待つ必要がない。", "E": "手術開始まで置けば阻血時間が最も長くなり、組織壊死の危険が高い。"}'::jsonb, 'public', 'M', '116-B-42', '', 'pending', 'llm'),
('循環器', '', 2, 'KOKUSHI', '78歳の女性。息切れを主訴に来院した。現病歴 : 65歳で事務職を退職するまで毎年、健康診断を受けていたが、異常を指摘されたことはなかった。4年前に感冒症状で自宅近くの診療所を受診した時に、心雑音を指摘されたが精査はされていない。趣味で卓球をしていたが、1年ほど前から競技中に胸部圧迫感を自覚するようになった。1か月ほど前から買い物のためスーパーまで15分程度歩いていく途中に息切れを自覚するようになった。生活歴 : 喫煙は20歳から65歳まで1日20本。飲酒は機会飲酒。家族歴 : 父が73歳時に脳出血で死亡。母は82歳時に腹部大動脈にステントグラフト内挿術を受けた。現症 : 意識は清明。身長154cm、体重54kg。体温36.8°C。脈拍60/分、整。血圧154/92mmHg。呼吸数18/分。SpO297%(room air)。眼瞼結膜に異常を認めない。頸静脈の怒張を認めない。呼吸音に異常を認めない。頸部に放散する胸骨右縁第2肋間を最強点とするLevine3/6の駆出性収縮期雑音を聴取する。腹部は平坦、軟で、肝・脾を触知しない。
可能性の高い疾患はどれか。', '[{"key": "A", "text": "肥大型心筋症"}, {"key": "B", "text": "動脈管開存症"}, {"key": "C", "text": "大動脈弁狭窄症"}, {"key": "D", "text": "心房中隔欠損症"}, {"key": "E", "text": "僧帽弁閉鎖不全症"}]'::jsonb, 'C', '正答は C「大動脈弁狭窄症」。

胸骨右縁第2肋間を最強点とし頸部へ放散する駆出性収縮期雑音は、大動脈弁狭窄症に特徴的である。労作時の胸部圧迫感（狭心症）と息切れ（心不全）が現れており、症状が出た大動脈弁狭窄症は予後が急に悪くなるため、弁置換やTAVIの検討に進む。

出典：厚生労働省ホームページ 第116回医師国家試験 B044', '{"A": "肥大型心筋症の収縮期雑音は胸骨左縁が最強点で頸部へは放散しにくく、Valsalva手技で増強する。", "B": "動脈管開存症は収縮期・拡張期を通じた連続性雑音を呈する。", "D": "心房中隔欠損症はII音の固定性分裂を伴い、雑音の最強点は胸骨左縁第2肋間である。", "E": "僧帽弁閉鎖不全症は心尖部を最強点とする全収縮期雑音で、腋窩へ放散する。"}'::jsonb, 'public', 'M', '116-B-44', '', 'pending', 'llm'),
('神経', '', 2, 'KOKUSHI', '78歳の女性。息切れを主訴に来院した。現病歴 : 65歳で事務職を退職するまで毎年、健康診断を受けていたが、異常を指摘されたことはなかった。4年前に感冒症状で自宅近くの診療所を受診した時に、心雑音を指摘されたが精査はされていない。趣味で卓球をしていたが、1年ほど前から競技中に胸部圧迫感を自覚するようになった。1か月ほど前から買い物のためスーパーまで15分程度歩いていく途中に息切れを自覚するようになった。生活歴 : 喫煙は20歳から65歳まで1日20本。飲酒は機会飲酒。家族歴 : 父が73歳時に脳出血で死亡。母は82歳時に腹部大動脈にステントグラフト内挿術を受けた。現症 : 意識は清明。身長154cm、体重54kg。体温36.8°C。脈拍60/分、整。血圧154/92mmHg。呼吸数18/分。SpO297%(room air)。眼瞼結膜に異常を認めない。頸静脈の怒張を認めない。呼吸音に異常を認めない。頸部に放散する胸骨右縁第2肋間を最強点とするLevine3/6の駆出性収縮期雑音を聴取する。腹部は平坦、軟で、肝・脾を触知しない。
治療方針の決定に役立つ情報に含まれないのはどれか。', '[{"key": "A", "text": "自覚症状"}, {"key": "B", "text": "併存疾患の有無"}, {"key": "C", "text": "心エコー検査の所見"}, {"key": "D", "text": "心臓カテーテル検査の所見"}, {"key": "E", "text": "MIBG心筋シンチグラフィの所見"}]'::jsonb, 'E', '正答は E「MIBG心筋シンチグラフィの所見」。

設問は治療方針の決定に役立つ情報に「含まれない」ものを選ぶもの。MIBG心筋シンチグラフィは心臓の交感神経機能をみる検査で、Lewy小体病の診断や心不全の予後評価に用いる。大動脈弁狭窄症の治療方針を決める材料にはならない。

出典：厚生労働省ホームページ 第116回医師国家試験 B045', '{"A": "症状の有無は介入の時期を決める最も重要な情報である。", "B": "併存疾患は外科的弁置換とTAVIのどちらを選ぶかに直結する。", "C": "心エコーの弁口面積や圧較差で重症度が決まる。", "D": "心臓カテーテル検査で冠動脈病変の有無を確かめ、冠動脈バイパスの同時施行を検討する。"}'::jsonb, 'public', 'M', '116-B-45', '', 'pending', 'llm'),
('医学総論', '', 2, 'KOKUSHI', '20歳の男性。動悸と頭痛を主訴に来院した。現病歴 : 17歳の時から時々動悸と頭痛を自覚していた。本日、知人の引っ越しを手伝うため家具を運ぼうとしたところ、動悸と激しい頭痛が生じ、内科を受診した。既往歴 : 大学入学時の健康診断で血圧高値を指摘された。生活歴 : 大学生。喫煙歴、飲酒歴はない。家族歴 : 父が高血圧症で治療中。現症 : 意識は清明。身長172cm、体重55kg。体温36.3°C。脈拍132/分、整。血圧192/110mmHg。呼吸数24/分。著明な発汗を認める。顔面は紅潮している。四肢に冷感を認める。胸腹部に異常を認めない。検査所見 : 尿所見:蛋白(−)、糖(−)。血液所見:赤血球463万、Hb13.2 g/dL、Ht40%、白血球5,800、血小板22万。血液生化学所見:総蛋白8.8g/dL、AST24U/L、ALT14U/L、LD183U/L(基準120〜245)、尿素窒素17mg/dL、クレアチニン0.8mg/dL、尿酸7.2mg/dL、血糖101mg/dL、Na136mEq/L、K 4.2mEq/dL、Cl100mEq/L。CRP1.2mg/dL。
入院し精査と治療を行うことになった。この時点で患者に対して医師が説明する事項で省略できるのはどれか。', '[{"key": "A", "text": "現在の病状"}, {"key": "B", "text": "現在の診断名"}, {"key": "C", "text": "研究段階の医療の概要"}, {"key": "D", "text": "緊急に行う処置の概要と危険性"}, {"key": "E", "text": "これから行う検査の概要と危険性"}]'::jsonb, 'C', '正答は C「研究段階の医療の概要」。

設問は「省略できる」説明を選ぶもの。医師が説明すべきなのは、現在の病状と診断名、これから行う検査や処置の内容と危険性である。研究段階の医療は確立した標準治療ではなく、この時点で必ず説明しなければならないものではない。

出典：厚生労働省ホームページ 第116回医師国家試験 B046', '{"A": "現在の病状は、患者が自分の状態を理解するための前提であり省略できない。", "B": "診断名を伝えることは、患者が納得して治療を選ぶ出発点になる。", "D": "緊急に行う処置の概要と危険性は、同意を得るために欠かせない。", "E": "これから行う検査の概要と危険性も、同意を得るために必要である。"}'::jsonb, 'public', 'M', '116-B-46', '', 'pending', 'llm'),
('代謝・内分泌', '', 2, 'KOKUSHI', '20歳の男性。動悸と頭痛を主訴に来院した。現病歴 : 17歳の時から時々動悸と頭痛を自覚していた。本日、知人の引っ越しを手伝うため家具を運ぼうとしたところ、動悸と激しい頭痛が生じ、内科を受診した。既往歴 : 大学入学時の健康診断で血圧高値を指摘された。生活歴 : 大学生。喫煙歴、飲酒歴はない。家族歴 : 父が高血圧症で治療中。現症 : 意識は清明。身長172cm、体重55kg。体温36.3°C。脈拍132/分、整。血圧192/110mmHg。呼吸数24/分。著明な発汗を認める。顔面は紅潮している。四肢に冷感を認める。胸腹部に異常を認めない。検査所見 : 尿所見:蛋白(−)、糖(−)。血液所見:赤血球463万、Hb13.2 g/dL、Ht40%、白血球5,800、血小板22万。血液生化学所見:総蛋白8.8g/dL、AST24U/L、ALT14U/L、LD183U/L(基準120〜245)、尿素窒素17mg/dL、クレアチニン0.8mg/dL、尿酸7.2mg/dL、血糖101mg/dL、Na136mEq/L、K 4.2mEq/dL、Cl100mEq/L。CRP1.2mg/dL。
入院後、以下の検査結果が得られた。入院後検査所見:TSH1.76μU/mL (基準0.2〜4.0)、FT33.6pg/mL (基準2.3〜4.3)、FT41.4ng/dL(基準0.8〜2.2)、アルドステロン6ng/dL(基準5〜10)、血漿レニン活性2.0ng/mL/時間(基準1.2〜2.5)、アドレナリン120 pg/mL(基準100以下)、ノルアドレナリン1,200pg/mL(基準100〜450)。尿中VMA18mg/日(基準1.3〜5.1)。腹部超音波検査で左側腹部に径2cmの腫瘤像を認める。経静脈的降圧薬で降圧がみられたのち、最初に投与すべき経口降圧薬はどれか。', '[{"key": "A", "text": "α遮断薬"}, {"key": "B", "text": "アンジオテンシン変換酵素〈ACE〉阻害薬"}, {"key": "C", "text": "カルシウム拮抗薬"}, {"key": "D", "text": "β遮断薬"}, {"key": "E", "text": "ループ利尿薬"}]'::jsonb, 'A', '正答は A「α遮断薬」。

発作性の高血圧、頭痛、動悸、発汗に、カテコールアミンと尿中VMAの高値、腹部の腫瘤があり、褐色細胞腫（パラガングリオーマ）である。経口の降圧はまずα遮断薬（ドキサゾシン）で始め、頻脈が残ればβ遮断薬を加える。

出典：厚生労働省ホームページ 第116回医師国家試験 B047', '{"B": "ACE阻害薬ではカテコールアミンによる血管収縮を抑えられない。", "C": "カルシウム拮抗薬は補助的に加えることはあるが、最初に使うのはα遮断薬である。", "D": "β遮断薬を先に使うと、β2による血管拡張がなくなってα作用が強まり、血圧がさらに上がる。α遮断薬を始めてから加える。", "E": "褐色細胞腫では循環血漿量が減っており、利尿薬でさらに減らすと危険である。"}'::jsonb, 'public', 'M', '116-B-47', '', 'pending', 'llm'),
('循環器', '', 2, 'KOKUSHI', '64歳の女性。意識障害のため救急車で搬送された。現病歴 : 自宅の脱衣場で意識がないのを夫が発見して救急要請をした。本人が入浴のため脱衣場に行って約1時間後に発見し、嘔吐した痕跡を認めたが、明らかな頭部外傷は認めなかった。救急隊到着時には心停止であったが、胸骨圧迫とバッグバルブマスク換気により自己心拍は再開し、救急搬送となった。既往歴 : 54歳から高血圧症で降圧薬を服薬中である。生活歴 : 喫煙は15本/日を44年間。飲酒はビール350mL/日を週6回。夫と2人暮らし。家族歴 : 母は85歳時に脳出血で死亡。現症 : 意識レベルはJCSIII-300。身長160cm、体重54kg。体温36.0°C。心拍数64/分、整。血圧98/50mmHg。換気回数10/分。SpO292%(バッグバルブマスク換気による調節呼吸)。舌根が沈下している。瞳孔は両側ともに径4mm、対光反射は両側で遅延している。心電図モニターは洞調律であるが、巨大陰性T波を認める。
搬入時に優先して行うべきなのはどれか。', '[{"key": "A", "text": "気管挿管"}, {"key": "B", "text": "アドレナリン筋注"}, {"key": "C", "text": "プレドニゾロン静注"}, {"key": "D", "text": "グルコン酸カルシウム静注"}, {"key": "E", "text": "電気的除細動(電気ショック)"}]'::jsonb, 'A', '正答は A「気管挿管」。

心拍は再開したがJCS III-300で舌根が沈下しており、バッグバルブマスクによる換気でもSpO2は92%にとどまる。自発呼吸に頼れない状態なので、まず気管挿管で気道を確保し、確実な換気と誤嚥の防止を図る。

出典：厚生労働省ホームページ 第116回医師国家試験 B048', '{"B": "アドレナリンの筋注はアナフィラキシーの適応で、自己心拍が再開している本例には当たらない。", "C": "副腎皮質ステロイドの適応となる病態がない。", "D": "グルコン酸カルシウムは高カリウム血症などで用いるが、それを示す所見がない。", "E": "心電図モニターは洞調律で、電気ショックの適応となる心室細動や無脈性心室頻拍ではない。"}'::jsonb, 'public', 'M', '116-B-48', '', 'pending', 'llm'),
('血液', '', 2, 'KOKUSHI', '慢性炎症に伴う貧血で増加するのはどれか。', '[{"key": "A", "text": "血清鉄"}, {"key": "B", "text": "フェリチン"}, {"key": "C", "text": "網赤血球数"}, {"key": "D", "text": "ハプトグロビン"}, {"key": "E", "text": "平均赤血球容積〈MCV〉"}]'::jsonb, 'B', '正答は B「フェリチン」。

炎症で肝臓からヘプシジンが出て、鉄がマクロファージに閉じ込められ、腸からの吸収も抑えられる。血清鉄は低いが貯蔵鉄は多く、フェリチンは正常か高い（フェリチンは炎症でも上がる）。鉄欠乏性貧血とはフェリチンとTIBCで見分ける。

出典：厚生労働省ホームページ 第116回医師国家試験 C018', '{"A": "鉄が閉じ込められて使えないので、血清鉄は低下する。", "C": "赤血球が作られにくいので、網赤血球は増えない。", "D": "ハプトグロビンは溶血で低下する検査で、慢性炎症に伴う貧血を見分ける指標ではない。", "E": "貧血は正球性か軽い小球性で、MCVは増加しない。"}'::jsonb, 'public', 'M', '116-C-18', '', 'pending', 'llm'),
('精神科', '', 2, 'KOKUSHI', '64歳の女性。1年前から徐々に物忘れがひどくなってきていることを心配した家族に伴われて来院した。最近は財布をしまったことや食事をしたことを思い出せないこともあるという。この患者の診断に有用な検査はどれか。', '[{"key": "A", "text": "Rorschachテスト"}, {"key": "B", "text": "田中・Binet知能検査"}, {"key": "C", "text": "津守・稲毛式発達検査"}, {"key": "D", "text": "Wechsler成人知能検査"}, {"key": "E", "text": "簡易精神症状評価尺度[Brief Psychiatric Rating Scale〈BPRS〉]"}]'::jsonb, 'D', '正答は D「Wechsler成人知能検査」。

物忘れが1年で進んでおり、認知症を疑う。選択肢の中で成人の認知機能（知能）を測れるのはWechsler成人知能検査（WAIS）である。実際の診療ではMMSEや改訂長谷川式簡易知能評価スケールで評価し、画像や血液の検査も合わせて原因を調べる。

出典：厚生労働省ホームページ 第116回医師国家試験 C039', '{"A": "Rorschachテストは性格（人格）を調べる投影法の検査で、認知機能は測らない。", "B": "田中・Binet知能検査は主に子どもの知能を測る検査である。", "C": "津守・稲毛式発達検査は乳幼児の発達を調べる検査である。", "E": "BPRSは統合失調症などの精神症状の重さを評価する尺度で、認知機能は測らない。"}'::jsonb, 'public', 'M', '116-C-39', '', 'pending', 'llm'),
('血液', '', 2, 'KOKUSHI', '21歳の女性。顔面の皮疹とふらつきを主訴に来院した。1か月前、海水浴に行った後から、微熱、顔面の皮疹、手指関節痛、ふらつきが出現し、改善がないため受診した。体温37.6°C。眼瞼結膜は貧血様で、眼球結膜に軽度黄染を認める。両頰部に紅斑を認める。硬口蓋粘膜に発赤とびらんを認める。両側の複数の近位指節間関節に腫脹と圧痛を認める。尿所見:蛋白2+、潜血3+、沈渣に赤血球、円柱を認めない。血液所見:赤血球298万、Hb7.9g/dL、Ht25%、白血球2,800、血小板12万。血液生化学所見:総蛋白7.0g/dL、アルブミン3.2g/dL、AST45 U/L、ALT20U/L、LD298U/L(基準120〜245)、ALP98U/L(基準38〜113)、尿素窒素12mg/dL、クレアチニン0.6mg/dL、Fe42μg/dL。免疫血清学所見:CRP0.2mg/dL、抗核抗体320倍(基準20以下)、抗dsDNA抗体364IU/mL(基準12以下)、直接クームステスト陽性。この患者で予想される検査所見はどれか。', '[{"key": "A", "text": "網赤血球数低下"}, {"key": "B", "text": "ハプトグロビン低下"}, {"key": "C", "text": "C1インヒビター低下"}, {"key": "D", "text": "ADAMTS-13活性低下"}, {"key": "E", "text": "血清補体価〈CH50〉上昇"}]'::jsonb, 'B', '正答は B「ハプトグロビン低下」。

若い女性の頰部紅斑、口腔のびらん、関節炎、蛋白尿、白血球減少、抗核抗体と抗dsDNA抗体の陽性から全身性エリテマトーデス（SLE）である。貧血、黄疸、LD上昇と直接クームステスト陽性から自己免疫性溶血性貧血を合併しており、溶血で出たヘモグロビンと結合してハプトグロビンが消費され、低下する。

出典：厚生労働省ホームページ 第116回医師国家試験 C040', '{"A": "溶血を補おうと骨髄が赤血球を盛んに作るので、網赤血球は増える。", "C": "C1インヒビターの低下は遺伝性血管性浮腫でみられる。", "D": "ADAMTS13活性の低下は血栓性血小板減少性紫斑病でみられる。本例はクームス陽性の自己免疫性の溶血である。", "E": "活動期のSLEでは補体が消費され、CH50は低下する。"}'::jsonb, 'public', 'M', '116-C-40', '', 'pending', 'llm'),
('公衆衛生', '', 2, 'KOKUSHI', '28歳の女性。悪心と倦怠感を主訴に受診した。最終月経は8週間前。無月経のため5日前に行った妊娠検査薬が陽性だった。軽度の下腹部痛を自覚している。最近食欲が低下しているという。内診で性器出血は認めず、経腟超音波検査で子宮内に頭殿長18mmの心拍を有する胎児を認める。身長156cm、体重48kg(非妊時49kg)。尿ケトンは陰性。飲食店勤務のため立ち仕事が多く勤務時間を短くしたいという相談があった。適切な対応はどれか。', '[{"key": "A", "text": "保健センターへの連絡を勧める。"}, {"key": "B", "text": "勤務先へ診療情報提供書を送付する。"}, {"key": "C", "text": "産前休業を申請するように指示する。"}, {"key": "D", "text": "母性健康管理指導事項連絡カードを発行する。"}, {"key": "E", "text": "職場へ母子健康手帳を提示するように指示する。"}]'::jsonb, 'D', '正答は D「母性健康管理指導事項連絡カードを発行する。」。

妊娠中の働く女性が医師から受けた指導（勤務時間の短縮、休憩、作業の制限など）を事業主に伝えるために、医師は母性健康管理指導事項連絡カード（母健連絡カード）を書く。事業主は男女雇用機会均等法に基づき、指導を守れるよう措置をとる義務がある。

出典：厚生労働省ホームページ 第116回医師国家試験 C048', '{"A": "保健センター（市町村）は妊娠の届出や保健指導を扱うが、勤務時間の調整は職場への指導事項の伝達で行う。", "B": "診療情報提供書は医療機関どうしで患者の情報をやりとりする文書である。職場への連絡には母健連絡カードを使う。", "C": "産前休業は出産予定日の6週前（多胎は14週前）から請求できる。妊娠8週では取れない。", "E": "母子健康手帳は母子の健康の記録で、主治医の指導事項を事業主に伝えるのは母健連絡カードの役目である。"}'::jsonb, 'public', 'M', '116-C-48', '', 'pending', 'llm'),
('腎臓', '', 2, 'KOKUSHI', '57歳の男性。腎機能低下を主訴に来院した。35歳でIgA腎症と診断され、自宅近くの診療所を定期受診していた。腎機能が次第に悪化し、腎代替療法の準備が必要と判断されて受診した。IgA腎症の診断時に高血圧症を指摘されて降圧薬を、50歳からは2型糖尿病を指摘されて経口血糖降下薬を服用中である。身長170 cm、体重80kg。脈拍72/分、整。血圧136/80mmHg。胸腹部に異常はない。両下腿に軽度の浮腫を認める。尿所見:蛋白2+、潜血2+。血液所見:赤血球325万、Hb9.7g/dL、Ht29%、白血球5,700、血小板20万。血液生化学所見:尿素窒素60mg/dL、クレアチニン3.3mg/dL、eGFR16.5mL/分/1.73m2、HbA1c 6.4%(基準4.6〜6.2)、Na142mEq/L、K5.0mEq/L、Cl102mEq/L。血液型はA型、RhD(+)。腎代替療法の説明の際に、患者は妻からの腎移植を希望していることがわかった。妻は55歳で生来健康であり、血液型はO型、RhD(+)である。妻は患者への腎臓提供に同意している。この患者の腎移植に関する説明で適切なのはどれか。', '[{"key": "A", "text": "患者に糖尿病があるので移植を受けられない。"}, {"key": "B", "text": "血液型が違うので妻からの移植は受けられない。"}, {"key": "C", "text": "移植を受けるために患者は退職する必要がある。"}, {"key": "D", "text": "透析を開始した後でなければ移植を受けられない。"}, {"key": "E", "text": "術前検査で患者に癌が見つかれば移植を受けられない。"}]'::jsonb, 'E', '正答は E「術前検査で患者に癌が見つかれば移植を受けられない。」。

活動性の悪性腫瘍や感染症があると、移植後の免疫抑制で悪化するため腎移植はできない。術前に癌の検査を行う。糖尿病や血液型の違いは移植できない理由にならず、透析を始める前に移植することもできる（先行的腎移植）。

出典：厚生労働省ホームページ 第116回医師国家試験 C055', '{"A": "糖尿病は禁忌ではない。糖尿病性腎症の患者も腎移植の対象になる。", "B": "血液型が違っても、脱感作療法（リツキシマブ、血漿交換など）を行えば移植でき、成績も血液型が合う移植とほぼ同じである。", "C": "移植を受けるために退職する必要はなく、移植後も仕事を続けられる。", "D": "透析を経ずに移植することもでき（先行的腎移植）、成績はむしろよい。"}'::jsonb, 'public', 'M', '116-C-55', '', 'pending', 'llm'),
('代謝・内分泌', '', 2, 'KOKUSHI', '82歳の女性。歩行困難のため救急車で搬入された。現病歴 : 1か月前から倦怠感を訴えていた。前日の朝から食欲不振が出現し、午後になって2回嘔吐した。当日朝から落ち着きがなくなり、いつもと違う様子であった。その後、歩行困難と尿失禁を認め次第に呼びかけへの反応が悪くなったため家族が救急車を要請した。既往歴 : 51歳時、子宮筋腫で子宮全摘術。58歳から高血圧症、慢性心房細動、脂質異常症のため自宅近くの医療機関に通院中でありカルシウム拮抗薬、β遮断薬、スタチン、ワルファリンを内服中である。2か月前から三叉神経痛に対しカルバマゼピンが開始となった。生活歴 : 喫煙歴はない。飲酒は機会飲酒。夫(83歳)、長男夫婦と同居。海外渡航歴はない。家族歴 : 母が76歳時に脳梗塞を発症。現症 : 意識レベルはJCSIII-100。身長152cm、体重58kg。体温36.2°C。脈拍92/分、不整。血圧162/98mmHg。呼吸数22/分。SpO299%(room air)。眼位は正位である。瞳孔径は両側3.0mmで、左右差を認めない。対光反射は両側とも迅速。胸腹部に異常を認めない。検査所見 : 尿所見:蛋白2+、糖+、潜血(−)。血液所見:赤血球509万、Hb 15.9g/dL、Ht41%、白血球8,700、血小板26万。血液生化学所見:総蛋白8.5 g/dL、アルブミン5.2g/dL、AST36U/L、ALT20U/L、γ-GT28U/L (基準8〜50)、尿素窒素14.6mg/dL、クレアチニン0.6mg/dL、尿酸3.6mg/dL、Na 108mEq/L、K3.5mEq/L、Cl73mEq/L、Ca10.0mg/dL、P3.8mg/dL、随時血糖198mg/dL、TSH2.28μU/mL(基準0.2〜4.0)、ACTH12.6pg/mL(基準60以下)、FT41.5ng/mL (基準0.8〜2.2)、コルチゾール12.5μg/dL (基準5.2〜12.6)。CRP0.1mg/dL。尿浸透圧702mOsm/L (基準50〜1,300)、尿Na 163mEq/L、尿K68mEq/L、尿Cl190mEq/L。
この患者の病態の原因はどれか。', '[{"key": "A", "text": "レニン"}, {"key": "B", "text": "インスリン"}, {"key": "C", "text": "カテコラミン"}, {"key": "D", "text": "バソプレシン"}, {"key": "E", "text": "エリスロポエチン"}]'::jsonb, 'D', '正答は D「バソプレシン」。

Na 108mEq/Lの著しい低Na血症なのに尿は濃く（尿浸透圧702mOsm/L）、尿Naも多い。甲状腺と副腎の機能、腎機能は保たれており、尿酸は低めである。ADH（バソプレシン）が不適切に出続けるSIADHが原因である。

出典：厚生労働省ホームページ 第116回医師国家試験 C060', '{"A": "レニンが増えるのは体液が減ったときで、そのとき腎臓はNaを保持し、尿Naは少なくなる。", "B": "インスリンは血糖を下げるホルモンで、この低Na血症の原因にはならない。", "C": "カテコラミンが多すぎると発作性の高血圧や頻脈が起きるが、低Na血症の原因にはならない。", "E": "エリスロポエチンは赤血球を増やすホルモンで、Naの調節には関わらない。"}'::jsonb, 'public', 'M', '116-C-60', '', 'pending', 'llm'),
('代謝・内分泌', '', 2, 'KOKUSHI', '82歳の女性。歩行困難のため救急車で搬入された。現病歴 : 1か月前から倦怠感を訴えていた。前日の朝から食欲不振が出現し、午後になって2回嘔吐した。当日朝から落ち着きがなくなり、いつもと違う様子であった。その後、歩行困難と尿失禁を認め次第に呼びかけへの反応が悪くなったため家族が救急車を要請した。既往歴 : 51歳時、子宮筋腫で子宮全摘術。58歳から高血圧症、慢性心房細動、脂質異常症のため自宅近くの医療機関に通院中でありカルシウム拮抗薬、β遮断薬、スタチン、ワルファリンを内服中である。2か月前から三叉神経痛に対しカルバマゼピンが開始となった。生活歴 : 喫煙歴はない。飲酒は機会飲酒。夫(83歳)、長男夫婦と同居。海外渡航歴はない。家族歴 : 母が76歳時に脳梗塞を発症。現症 : 意識レベルはJCSIII-100。身長152cm、体重58kg。体温36.2°C。脈拍92/分、不整。血圧162/98mmHg。呼吸数22/分。SpO299%(room air)。眼位は正位である。瞳孔径は両側3.0mmで、左右差を認めない。対光反射は両側とも迅速。胸腹部に異常を認めない。検査所見 : 尿所見:蛋白2+、糖+、潜血(−)。血液所見:赤血球509万、Hb 15.9g/dL、Ht41%、白血球8,700、血小板26万。血液生化学所見:総蛋白8.5 g/dL、アルブミン5.2g/dL、AST36U/L、ALT20U/L、γ-GT28U/L (基準8〜50)、尿素窒素14.6mg/dL、クレアチニン0.6mg/dL、尿酸3.6mg/dL、Na 108mEq/L、K3.5mEq/L、Cl73mEq/L、Ca10.0mg/dL、P3.8mg/dL、随時血糖198mg/dL、TSH2.28μU/mL(基準0.2〜4.0)、ACTH12.6pg/mL(基準60以下)、FT41.5ng/mL (基準0.8〜2.2)、コルチゾール12.5μg/dL (基準5.2〜12.6)。CRP0.1mg/dL。尿浸透圧702mOsm/L (基準50〜1,300)、尿Na 163mEq/L、尿K68mEq/L、尿Cl190mEq/L。
この患者の内服薬のうち病態の原因として最も可能性が高いのはどれか。', '[{"key": "A", "text": "β遮断薬"}, {"key": "B", "text": "スタチン"}, {"key": "C", "text": "ワルファリン"}, {"key": "D", "text": "カルバマゼピン"}, {"key": "E", "text": "カルシウム拮抗薬"}]'::jsonb, 'D', '正答は D「カルバマゼピン」。

カルバマゼピンはADHの分泌や腎臓での作用を強め、SIADHを起こす。2か月前に飲み始めてから倦怠感が出ており、時期も合う。SIADHを起こす薬には、ほかにSSRIなどの抗うつ薬、ビンクリスチン、シクロホスファミドなどがある。

出典：厚生労働省ホームページ 第116回医師国家試験 C061', '{"A": "β遮断薬は低Na血症の原因にならない。", "B": "スタチンでは横紋筋融解症や肝障害に注意するが、低Na血症は起こさない。", "C": "ワルファリンでは出血に注意するが、低Na血症は起こさない。", "E": "カルシウム拮抗薬は低Na血症の原因にならない。"}'::jsonb, 'public', 'M', '116-C-61', '', 'pending', 'llm'),
('代謝・内分泌', '', 2, 'KOKUSHI', '82歳の女性。歩行困難のため救急車で搬入された。現病歴 : 1か月前から倦怠感を訴えていた。前日の朝から食欲不振が出現し、午後になって2回嘔吐した。当日朝から落ち着きがなくなり、いつもと違う様子であった。その後、歩行困難と尿失禁を認め次第に呼びかけへの反応が悪くなったため家族が救急車を要請した。既往歴 : 51歳時、子宮筋腫で子宮全摘術。58歳から高血圧症、慢性心房細動、脂質異常症のため自宅近くの医療機関に通院中でありカルシウム拮抗薬、β遮断薬、スタチン、ワルファリンを内服中である。2か月前から三叉神経痛に対しカルバマゼピンが開始となった。生活歴 : 喫煙歴はない。飲酒は機会飲酒。夫(83歳)、長男夫婦と同居。海外渡航歴はない。家族歴 : 母が76歳時に脳梗塞を発症。現症 : 意識レベルはJCSIII-100。身長152cm、体重58kg。体温36.2°C。脈拍92/分、不整。血圧162/98mmHg。呼吸数22/分。SpO299%(room air)。眼位は正位である。瞳孔径は両側3.0mmで、左右差を認めない。対光反射は両側とも迅速。胸腹部に異常を認めない。検査所見 : 尿所見:蛋白2+、糖+、潜血(−)。血液所見:赤血球509万、Hb 15.9g/dL、Ht41%、白血球8,700、血小板26万。血液生化学所見:総蛋白8.5 g/dL、アルブミン5.2g/dL、AST36U/L、ALT20U/L、γ-GT28U/L (基準8〜50)、尿素窒素14.6mg/dL、クレアチニン0.6mg/dL、尿酸3.6mg/dL、Na 108mEq/L、K3.5mEq/L、Cl73mEq/L、Ca10.0mg/dL、P3.8mg/dL、随時血糖198mg/dL、TSH2.28μU/mL(基準0.2〜4.0)、ACTH12.6pg/mL(基準60以下)、FT41.5ng/mL (基準0.8〜2.2)、コルチゾール12.5μg/dL (基準5.2〜12.6)。CRP0.1mg/dL。尿浸透圧702mOsm/L (基準50〜1,300)、尿Na 163mEq/L、尿K68mEq/L、尿Cl190mEq/L。
この患者に投与すべきなのはどれか。', '[{"key": "A", "text": "維持輸液(組成:Na+35mEq/L、K+20mEq/L、Cl-35mEq/L、グルコース5.0%)"}, {"key": "B", "text": "高張(3%)食塩液"}, {"key": "C", "text": "脂肪乳剤"}, {"key": "D", "text": "10%ブドウ糖液"}, {"key": "E", "text": "乳酸リンゲル液"}]'::jsonb, 'B', '正答は B「高張(3%)食塩液」。

意識障害を伴う重い低Na血症なので、高張（3%）食塩液でNaを上げる。ただし急に上げすぎると浸透圧性脱髄症候群を起こすため、最初の24時間の上昇は10mEq/L以内にとどめ、Naを頻回に測る。原因のカルバマゼピンは中止する。

出典：厚生労働省ホームページ 第116回医師国家試験 C062', '{"A": "維持輸液はNaが薄く、低Na血症をさらに悪化させる。", "C": "脂肪乳剤はエネルギーの補給で、低Na血症は治らない。", "D": "ブドウ糖は代謝されると水だけが残り、低Na血症を悪化させる。", "E": "乳酸リンゲル液は尿より薄いので、SIADHでは水が体に残り、かえって低Na血症を悪化させうる。"}'::jsonb, 'public', 'M', '116-C-62', '', 'pending', 'llm'),
('腎臓', '', 2, 'KOKUSHI', '73歳の男性。ふらつきを主訴に来院した。現病歴 : 3日前に重い荷物を持ち上げた時に腰痛が出現し、自宅近くの診療所でNSAIDの処方を受けた。早期の症状改善を期待して毎食後に服用していたが、昨日から心窩部痛を自覚し十分に食事や水分がとれなかったという。本日朝からふらつきが出現したため家族に連れられて受診した。既往歴 : 高血圧症、糖尿病、脂質異常症および不眠症に対し、アンジオテンシン変換酵素〈ACE〉阻害薬、スルホニル尿素薬、スタチンおよびベンゾジアゼピン系睡眠薬を内服している。生活歴 : 妻と2人暮らし。喫煙歴はない。飲酒は機会飲酒。家族歴 : 両親が高血圧症であった。現症 : 意識レベルはJCSI-1。脈拍48/分、不整。血圧86/50mmHg。呼吸数20/分。SpO298%(room air)。眼瞼結膜と眼球結膜に異常を認めない。心音と呼吸音に異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。皮膚は乾燥している。検査所見 : 血液所見:赤血球405万、Hb13.4g/dL、Ht36%、白血球6,600、血小板22万。血液生化学所見:総蛋白7.3g/dL、アルブミン4.2g/dL、総ビリルビン0.7mg/dL、AST25U/L、ALT20U/L、LD225U/L(基準120〜245)、ALP100U/L(基準38〜113)、尿素窒素35mg/dL、クレアチニン2.4mg/dL、尿酸8.1mg/dL、血糖120mg/dL、Na138mEq/L、K7.6mEq/L、Cl108mEq/L。CRP0.1mg/dL。
直ちに行うべき検査はどれか。', '[{"key": "A", "text": "頭部CT"}, {"key": "B", "text": "尿中薬物検査"}, {"key": "C", "text": "12誘導心電図"}, {"key": "D", "text": "心エコー検査"}, {"key": "E", "text": "胸部エックス線検査"}]'::jsonb, 'C', '正答は C「12誘導心電図」。

ACE阻害薬を飲んでいる人がNSAIDを続け、食事も水分もとれずに脱水となり、急性腎障害と高K血症（7.6mEq/L）を起こしている。徐脈、不整脈、低血圧があり、致死的な不整脈の危険が迫っている。直ちに12誘導心電図でテント状T波、P波の消失、QRS幅の延長などを確かめ、モニターを着ける。

出典：厚生労働省ホームページ 第116回医師国家試験 C066', '{"A": "局所の神経症状はなく、ふらつきは徐脈と低血圧で説明できる。まず高K血症の心臓への影響を確かめる。", "B": "飲んでいる薬は分かっており、尿中薬物検査を急ぐ必要はない。", "D": "心エコーを急ぐ状況ではない。高K血症による不整脈をまず心電図で確かめる。", "E": "胸部エックス線写真では高K血症の影響は分からない。"}'::jsonb, 'public', 'M', '116-C-66', '', 'pending', 'llm'),
('腎臓', '', 2, 'KOKUSHI', '73歳の男性。ふらつきを主訴に来院した。現病歴 : 3日前に重い荷物を持ち上げた時に腰痛が出現し、自宅近くの診療所でNSAIDの処方を受けた。早期の症状改善を期待して毎食後に服用していたが、昨日から心窩部痛を自覚し十分に食事や水分がとれなかったという。本日朝からふらつきが出現したため家族に連れられて受診した。既往歴 : 高血圧症、糖尿病、脂質異常症および不眠症に対し、アンジオテンシン変換酵素〈ACE〉阻害薬、スルホニル尿素薬、スタチンおよびベンゾジアゼピン系睡眠薬を内服している。生活歴 : 妻と2人暮らし。喫煙歴はない。飲酒は機会飲酒。家族歴 : 両親が高血圧症であった。現症 : 意識レベルはJCSI-1。脈拍48/分、不整。血圧86/50mmHg。呼吸数20/分。SpO298%(room air)。眼瞼結膜と眼球結膜に異常を認めない。心音と呼吸音に異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。皮膚は乾燥している。検査所見 : 血液所見:赤血球405万、Hb13.4g/dL、Ht36%、白血球6,600、血小板22万。血液生化学所見:総蛋白7.3g/dL、アルブミン4.2g/dL、総ビリルビン0.7mg/dL、AST25U/L、ALT20U/L、LD225U/L(基準120〜245)、ALP100U/L(基準38〜113)、尿素窒素35mg/dL、クレアチニン2.4mg/dL、尿酸8.1mg/dL、血糖120mg/dL、Na138mEq/L、K7.6mEq/L、Cl108mEq/L。CRP0.1mg/dL。
直ちに投与すべき薬剤はどれか。', '[{"key": "A", "text": "ドパミン"}, {"key": "B", "text": "アトロピン"}, {"key": "C", "text": "アドレナリン"}, {"key": "D", "text": "硫酸マグネシウム"}, {"key": "E", "text": "グルコン酸カルシウム"}]'::jsonb, 'E', '正答は E「グルコン酸カルシウム」。

心電図変化を伴う高K血症では、まずグルコン酸カルシウムを静注して心筋の膜を安定させる（数分で効くが、Kは下がらない）。続いてグルコース・インスリン療法でKを細胞内に移し、陽イオン交換樹脂や利尿薬、必要なら透析でKを体外に出す。ACE阻害薬とNSAIDは中止し、脱水を輸液で補う。

出典：厚生労働省ホームページ 第116回医師国家試験 C067', '{"A": "ドパミンは血圧を上げるが、高K血症による心筋の異常は治せない。", "B": "高K血症による徐脈にアトロピンは効きにくい。まずカルシウムで心筋の膜を安定させる。", "C": "アドレナリンは心停止などに用いる薬で、高K血症の治療の第一歩ではない。", "D": "硫酸マグネシウムはtorsade de pointesや低Mg血症に用いる。"}'::jsonb, 'public', 'M', '116-C-67', '', 'pending', 'llm'),
('神経', '', 2, 'KOKUSHI', '56歳の女性。歩行困難と嚥下困難を主訴に来院した。現病歴 : 2年前から左上肢の筋力低下を自覚した。1年前から右上肢にも同様の症状を自覚するようになり、自宅近くの診療所を受診したところ、病院の脳神経内科に紹介受診となった。入院精査の結果、筋萎縮性側索硬化症〈ALS〉の診断を受けた。その後、病院に通院していたが下肢筋力が低下して徐々に歩行困難となった。3か月前からは、しゃべりにくさを自覚した。時々食事でむせることもあった。病院への通院が困難となり、在宅医療への移行を相談するために受診した。既往歴 : 健診で高血圧を指摘されたことがあるが、内服治療はしていない。生活歴 : もともとパート勤務をしていたが発症後は退職した。夫と二人暮らし。長男、長女は独立し別居している。家族歴 : 父が肺癌、母は子宮癌であった。現症 : 意識は清明。身長152cm、体重38kg。体温36.6°C。脈拍76/分、整。血圧108/68mmHg。心音と呼吸音に異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。神経診察では①眼球運動は正常。顔面の感覚には異常を認めない。②咬筋および口輪筋の筋力は保たれている。③挺舌は可能だが、舌筋には軽度の萎縮とぴくぴくとした不規則な動きがみられる。発声時の咽頭挙上は不良。四肢は右側優位に筋萎縮、筋力低下がみられ、④立位保持は可能だが、歩行は支えがないと困難である。腱反射は上肢で減弱し、下肢は亢進。Babinski徴候は両側陽性。右肩関節は可動域制限があり他動的に動かすと疼痛を訴える。痛覚、深部感覚の異常はない。トイレへの移動には介助が必要だが、⑤排泄は可能である。検査所見 : 尿所見:蛋白(−)、糖(−)、潜血(−)。血液所見:赤血球462万、Hb12.6g/dL、Ht40%、白血球6,200、血小板24万。血液生化学所見:総蛋白6.6g/dL、アルブミン3.8g/dL、AST26U/L、ALT30U/L、LD204U/L(基準120〜245)、ALP68U/L(基準38〜113)、尿素窒素18mg/dL、クレアチニン0.2 mg/dL、血糖76mg/dL、Na136mEq/L、K4.0mEq/L、Cl98mEq/L。CRP0.1 mg/dL。動脈血ガス分析(自発呼吸、room air):pH7.38、PaCO242Torr、PaO2 92Torr、HCO3−26mEq/L。心電図と胸部エックス線写真に異常を認めない。
今後の在宅療養に向けて必要な検査はどれか。', '[{"key": "A", "text": "頸椎CT"}, {"key": "B", "text": "頭部MRI"}, {"key": "C", "text": "針筋電図"}, {"key": "D", "text": "嚥下機能検査"}, {"key": "E", "text": "末梢神経伝導検査"}]'::jsonb, 'D', '正答は D「嚥下機能検査」。

ALSで構音障害とむせがあり、舌の萎縮と線維束性収縮、咽頭挙上の不良から球麻痺が進んでいる。在宅療養に向けて、誤嚥と低栄養を防ぐために嚥下機能を評価し、食事の形態や胃瘻を検討する。胃瘻は呼吸機能が落ちる前に造るのが安全である。

出典：厚生労働省ホームページ 第116回医師国家試験 C070', '{"A": "頸椎の病気を疑う所見はなく、ALSの診断はすでについている。", "B": "頭部MRIは診断のときにほかの病気を除くための検査で、在宅療養の準備には役立たない。", "C": "針筋電図は診断のための検査で、診断はすでについている。", "E": "末梢神経伝導検査もほかの病気を除くための検査で、在宅療養の準備には要らない。"}'::jsonb, 'public', 'M', '116-C-70', '', 'pending', 'llm'),
('消化管', '', 2, 'KOKUSHI', '成人大腿ヘルニアで正しいのはどれか。', '[{"key": "A", "text": "中年男性に多い。"}, {"key": "B", "text": "嵌頓はまれである。"}, {"key": "C", "text": "手術治療が原則である。"}, {"key": "D", "text": "大腿外側部の痛みを伴う。"}, {"key": "E", "text": "鼠径靱帯の頭側から脱出する。"}]'::jsonb, 'C', '正答は C「手術治療が原則である。」。

大腿ヘルニアは、鼠径靱帯の下の大腿輪から腹膜が脱出するもので、中年以降の女性（特に経産婦）に多い。ヘルニア門が狭く硬いので嵌頓しやすく、自然には治らないため、見つかれば手術を行う。

出典：厚生労働省ホームページ 第116回医師国家試験 D009', '{"A": "中年以降の女性に多い。", "B": "ヘルニア門が狭く硬いため、嵌頓しやすい。", "D": "鼠径靱帯の下、大腿の内側（大腿静脈の内側）が膨らむ。", "E": "鼠径靱帯の尾側（下）から脱出する。頭側から出るのは鼠径ヘルニアである。"}'::jsonb, 'public', 'M', '116-D-9', '', 'pending', 'llm'),
('血液', '', 2, 'KOKUSHI', '84歳の男性。胃癌の精査のため入院中である。入院時に左前腕に皮下血腫を認めていたが、その後血腫は左の側胸部、側腹部から大腿部にまで拡大した。これまでに出血症状の既往はなく、家族歴に特記すべきことはない。意識は清明。体温36.8°C。脈拍110/分、整。血圧100/60mmHg。眼瞼結膜は貧血様で、眼球結膜に黄染を認めない。胸骨右縁第2肋間を最強点とするLevine2/6の収縮期駆出性雑音を聴取する。呼吸音に異常を認めない。腹部は平坦で、心窩部に圧痛を認める。肝・脾を触知しない。四肢等体幹に皮下血腫と紫斑を散在性に認める。血液所見:赤血球298万、Hb7.2g/dL、Ht23%、白血球7,400、血小板33万、出血時間3分30秒(基準7分以下)、PT-INR1.0(基準0.9〜1.1)、APTT70.4秒(基準対照32.2)、血漿フィブリノゲン398mg/dL(基準186〜355)、血清FDP5μg/mL(基準10以下)。最も考えられる疾患はどれか。', '[{"key": "A", "text": "後天性血友病"}, {"key": "B", "text": "ビタミンK欠乏症"}, {"key": "C", "text": "von Willebrand病"}, {"key": "D", "text": "抗リン脂質抗体症候群"}, {"key": "E", "text": "播種性血管内凝固〈DIC〉"}]'::jsonb, 'A', '正答は A「後天性血友病」。

出血の既往のない高齢者に、広い皮下血腫が急に広がっている。APTTだけが延長し、PT、血小板、出血時間、FDPは正常である。第VIII因子に対する自己抗体ができる後天性血友病Aで、高齢者、悪性腫瘍、自己免疫疾患、分娩後に起きやすい。クロスミキシング試験でインヒビター型を示し、第VIII因子活性の低下とインヒビターを確かめる。

出典：厚生労働省ホームページ 第116回医師国家試験 D025', '{"B": "ビタミンK欠乏では、PT（第VII因子）が先に延長する。PT-INRは正常である。", "C": "von Willebrand病は生まれつきの病気で、出血時間が延長し、鼻出血などの粘膜出血が多い。", "D": "抗リン脂質抗体症候群ではAPTTが延長するが、起きるのは出血ではなく血栓症である。", "E": "DICでは血小板の減少、フィブリノゲンの低下、FDPの上昇がみられる。"}'::jsonb, 'public', 'M', '116-D-25', '', 'pending', 'llm'),
('腎臓', '', 2, 'KOKUSHI', '69歳の女性。IgA腎症の管理について相談するために来院した。42歳でIgA腎症と診断され、それ以来自宅近くの診療所を定期受診している。50歳から高血圧を指摘されてカルシウム拮抗薬を服用している。定期的に栄養指導を受けており、最近の食事調査では1日塩分摂取量5.5g、1日蛋白摂取量35gであった。喫煙歴はない。週に2回、赤ワイン2杯/日を飲酒している。週に3回、1回約30分間のプール内歩行を続けている。身長160cm、体重55kg。脈拍72/分、整。血圧140/70mmHg。胸腹部に異常を認めない。両下腿に浮腫を認めない。尿所見:蛋白2+、潜血2+、尿蛋白/クレアチニン比は1.2g/gCr(基準0.15未満)、尿沈渣に赤血球8〜12/HPF、白血球1〜2/HPF、顆粒円柱を少数認める。血液生化学所見:総蛋白6.0g/dL、アルブミン4.0g/dL、尿素窒素18mg/dL、クレアチニン0.7mg/dL、 eGFR62.8mL/分/1.73m2、 Na142mEq/L、 K4.2mEq/L、 Cl 100mEq/L。本患者の腎機能悪化を抑制するためにまずすべきなのはどれか。', '[{"key": "A", "text": "禁酒"}, {"key": "B", "text": "運動制限"}, {"key": "C", "text": "利尿薬の追加"}, {"key": "D", "text": "蛋白摂取量の倍化"}, {"key": "E", "text": "レニン・アンジオテンシン系抑制薬の追加"}]'::jsonb, 'E', '正答は E「レニン・アンジオテンシン系抑制薬の追加」。

尿蛋白1.2g/gCrのIgA腎症で、血圧は140/70mmHgと目標（蛋白尿があれば130/80mmHg未満）に届いていない。減塩と蛋白制限はすでにできているので、ACE阻害薬かARBを加える。血圧とともに糸球体内圧を下げ、蛋白尿を減らして腎機能の低下を抑える。

出典：厚生労働省ホームページ 第116回医師国家試験 D045', '{"A": "飲酒は週2回、ワイン2杯程度で、まず禁酒すべき量ではない。", "B": "適度な運動はむしろ勧められる。いまの運動を制限する必要はない。", "C": "浮腫はなく、利尿薬を加える理由はない。", "D": "蛋白を増やすと糸球体の負担が増える。いまの摂取量（約0.6g/kg/日）は適正である。"}'::jsonb, 'public', 'M', '116-D-45', '', 'pending', 'llm'),
('医学総論', '', 2, 'KOKUSHI', '外来を受診する全身性エリテマトーデス患者を対象に、診療内容と生活の質〈QOL〉の関係を明らかにするための研究を行いたい。患者が外来を受診する際、5分程度で回答できる無記名アンケートの実施を考えている。採血など侵襲のある行為は伴わない。誤っているのはどれか。', '[{"key": "A", "text": "個人情報の保護に注意を払う。"}, {"key": "B", "text": "ヘルシンキ宣言に則って行う。"}, {"key": "C", "text": "患者の診療に関与しない看護師がアンケートを回収する。"}, {"key": "D", "text": "所属長の了承を得れば、倫理審査委員会への申請は不要である。"}, {"key": "E", "text": "患者が協力を拒否しても不利益を被ることがないよう配慮する。"}]'::jsonb, 'D', '正答は D「所属長の了承を得れば、倫理審査委員会への申請は不要である。」。

人を対象とする研究は、侵襲を伴わない無記名のアンケートであっても、研究計画について倫理審査委員会の意見を聴き、研究機関の長の許可を得てから行う（人を対象とする生命科学・医学系研究に関する倫理指針）。所属長の了承だけでは始められない。

出典：厚生労働省ホームページ 第116回医師国家試験 E005', '{"A": "無記名でも回答の内容から個人が分かることがあり、個人情報の保護に注意する。正しい。", "B": "人を対象とする医学研究はヘルシンキ宣言に則って行う。正しい。", "C": "担当医が回収すると本音を書きにくく、協力も断りにくくなるので、診療に関わらない者が回収する。正しい。", "E": "協力を断っても不利益がないようにするのは、自由な意思による参加の前提である。正しい。"}'::jsonb, 'public', 'M', '116-E-5', '', 'pending', 'llm'),
('循環器', '', 2, 'KOKUSHI', '76歳の男性。失神を主訴に来院した。2年前に持続性心房細動と診断され、抗凝固薬が開始されている。その他の投薬はされていない。最近1か月の間に2度失神して、顔面を強打するというエピソードがあった。Holter心電図を施行したところ、最大心拍数112/分であり、ふらつきを伴う最大6.4秒のR-R間隔を認めた。適切な方針はどれか。', '[{"key": "A", "text": "β遮断薬投与"}, {"key": "B", "text": "Holter心電図の再検"}, {"key": "C", "text": "イソプロテレノール投与"}, {"key": "D", "text": "心臓ペースメーカー植込み"}, {"key": "E", "text": "植込み型除細動器〈ICD〉植込み"}]'::jsonb, 'D', '正答は D「心臓ペースメーカー植込み」。

持続性心房細動に、ふらつきを伴う6.4秒のR-R間隔（3秒以上の心停止）があり、失神を繰り返している。症状のある徐脈性心房細動で、失神で顔を打つなど危険が大きいので、恒久的ペースメーカーを植込む。

出典：厚生労働省ホームページ 第116回医師国家試験 E026', '{"A": "β遮断薬は房室伝導をさらに抑え、長い心停止を悪化させる。", "B": "失神と長いR-R間隔の関係はすでに記録されており、Holter心電図を繰り返す必要はない。", "C": "イソプロテレノールは徐脈に対する一時的な治療で、繰り返す失神の根本的な治療にはならない。", "E": "ICDは心室頻拍や心室細動による突然死を防ぐもので、徐脈の治療としての適応ではない。"}'::jsonb, 'public', 'M', '116-E-26', '', 'pending', 'llm'),
('眼科', '', 2, 'KOKUSHI', '72歳の女性。右眼痛を主訴に来院した。昨夜、右眼の痛みとともに頭痛と悪心が出現し、次第に増悪している。右眼に高度の毛様充血、角膜浮腫があり、瞳孔が散大、中等度の白内障を認める。診断に有用な検査はどれか。', '[{"key": "A", "text": "網膜電図"}, {"key": "B", "text": "眼圧検査"}, {"key": "C", "text": "頭部CT検査"}, {"key": "D", "text": "眼部超音波検査"}, {"key": "E", "text": "光干渉断層計〈OCT〉"}]'::jsonb, 'B', '正答は B「眼圧検査」。

急な眼痛、頭痛、悪心に、毛様充血、角膜浮腫、中等度散瞳があり、急性緑内障発作（急性原発閉塞隅角症）である。白内障で厚くなった水晶体が隅角を狭めることが多い。眼圧を測れば著しく高く、診断がつく。放置すると短期間で失明するので、眼圧を下げる薬を使い、レーザー虹彩切開術や水晶体再建術を行う。

出典：厚生労働省ホームページ 第116回医師国家試験 E032', '{"A": "網膜電図は網膜の機能を調べる検査で、網膜色素変性症などの診断に用いる。", "C": "頭痛と悪心から頭蓋内の病気を考えがちだが、眼の所見から急性緑内障発作を疑い、まず眼圧を測る。", "D": "眼部超音波検査は、中間透光体が濁って眼底が見えないときに網膜剝離などを調べる。", "E": "OCTは網膜や視神経乳頭の断面をみる検査で、急性発作の診断には眼圧の測定が要る。"}'::jsonb, 'public', 'M', '116-E-32', '', 'pending', 'llm'),
('神経', '', 2, 'KOKUSHI', '58歳の男性。頭痛と意識障害のため救急車で搬入された。3日前から38°C台の発熱、咳嗽、喀痰の増加を自覚していた。昨晩から強い頭痛を訴えており、今朝になり反応も鈍くなってきたため、家族が救急車を要請した。意識レベルはJCSII-30。体温39.8°C。心拍数128/分、整。血圧116/58mmHg。呼吸数28/分。SpO298%(マスク5L/分酸素投与下)。項部硬直とKernig徴候を認める。①対光反射に左右差を認める。②胸骨左縁に収縮期雑音を認める。③左下胸部にcoarse cracklesを認める。④腸蠕動音は減弱している。⑤両側下腿に浮腫を認める。腰椎穿刺の回避を考えるべき所見はどれか。', '[{"key": "A", "text": "①"}, {"key": "B", "text": "②"}, {"key": "C", "text": "③"}, {"key": "D", "text": "④"}, {"key": "E", "text": "⑤"}]'::jsonb, 'A', '正答は A「①」。

肺炎に続いて、発熱、頭痛、意識障害、項部硬直が出ており、細菌性髄膜炎を考える。頭蓋内圧が高く脳ヘルニアが迫っているときに腰椎穿刺をすると、ヘルニアを進めるおそれがある。瞳孔や対光反射の左右差、局所神経症状、乳頭浮腫などがあれば、先に頭部CTで確かめる。その間も血液培養をとって抗菌薬を遅らせずに始める。

出典：厚生労働省ホームページ 第116回医師国家試験 E033', '{"B": "心雑音は感染性心内膜炎の合併などを考える所見だが、腰椎穿刺を避ける理由にはならない。", "C": "coarse cracklesは肺炎の所見で、髄膜炎の感染源と考えられるが、腰椎穿刺を避ける理由にはならない。", "D": "腸蠕動音の減弱は腰椎穿刺の可否と関係しない。", "E": "下腿浮腫は腰椎穿刺の可否と関係しない。"}'::jsonb, 'public', 'M', '116-E-33', '', 'pending', 'llm'),
('医学総論', '', 2, 'KOKUSHI', '55歳の男性。下腿浮腫を主訴に来院した。1週間前から下腿浮腫を自覚し、徐々に増強したため受診した。20歳台からアルコールの多飲歴がある。意識は清明。頸部リンパ節を触知しない。前胸部にくも状血管腫を認める。打診でshifting dullnessを確認する際、仰臥位の次にとらせる体位はどれか。', '[{"key": "A", "text": "座位"}, {"key": "B", "text": "立位"}, {"key": "C", "text": "砕石位"}, {"key": "D", "text": "側臥位"}, {"key": "E", "text": "腹臥位"}]'::jsonb, 'D', '正答は D「側臥位」。

仰臥位で腹部を打診すると、腹水は側腹部にたまって濁音、腸管の浮いた臍の周りは鼓音になる。次に側臥位にすると腹水が下側に移り、濁音と鼓音の境界が動く（shifting dullness）。飲酒歴、くも状血管腫、浮腫から肝硬変による腹水を疑う。

出典：厚生労働省ホームページ 第116回医師国家試験 E040', '{"A": "座位にしても濁音界の移動は確かめにくく、この手技では用いない。", "B": "立位で腹部を打診しても、濁音界の移動は確かめられない。", "C": "砕石位は内診や肛門の診察に用いる体位である。", "E": "腹臥位では腹部を打診できない。"}'::jsonb, 'public', 'M', '116-E-40', '', 'pending', 'llm'),
('婦人科・乳腺外科', '', 2, 'KOKUSHI', '21歳の女性。発熱と咽頭痛を主訴に来院した。現病歴 : 2日前に咽頭痛と37°C台の発熱が出現し、昨晩は38.6°Cであった。市販の解熱鎮痛薬を内服し、今朝は37.6°Cに下がったが、咽頭痛は悪化している。鼻汁、咳、痰はない。嚥下時に咽頭痛は増悪するが、嚥下障害はない。同様の症状の患者との接触はない。既往歴 : 3年前にA群β溶血性連鎖球菌(A群β溶連菌)性咽頭炎を発症。月経痛に対してアセトアミノフェンを頓用している。生活歴 : 喫煙歴はない。飲酒は機会飲酒。大学3年生で就職活動をしている。ペットは飼育していない。海外渡航歴はない。アレルギー歴はない。家族と同居している。最終月経は7日前から4日間で終了した。家族歴 : 父は高血圧症。母と弟は健康。現症 : 意識は清明。身長156cm、体重52kg。体温38.2°C。脈拍96/分、整。血圧108/62mmHg。呼吸数20/分。四肢・体幹に皮疹を認めない。両側扁桃の発赤と腫大があり、表面に白苔を認める。両側の後頸部に最大径1cmの圧痛を伴うリンパ節腫大をそれぞれ3個認める。心音と呼吸音に異常を認めない。腹部は平坦、軟で、右肋骨弓下に肝を3cm、左肋骨弓下に脾を3cm触知する。肋骨脊柱角叩打痛は両側で認めない。検査所見 : 尿所見:蛋白(−)、糖(−)、潜血(−)、沈渣に白血球を認めない。血液所見:赤血球410万、Hb11.6g/dL、Ht39%、白血球17,400(好中球44%、好酸球1%、単球3%、リンパ球42%、異型リンパ球10%)、血小板21万。血液生化学所見:総蛋白7.0g/dL、アルブミン4.2g/dL、総ビリルビン0.9mg/dL、AST62U/L、ALT94U/L、LD785U/L (基準120〜245)、ALP100U/L (基準38〜113)、尿素窒素24mg/dL、クレアチニン0.8mg/dL。CRP3.5mg/dL。
「発熱」「前頸部リンパ節腫大」「口蓋扁桃の白苔」「咳がない」の4項目について、該当項目数に応じたA群β溶連菌性咽頭炎の事前確率を表に示す。該当項目数 — 事前確率(%)0 — 2.5 1 — 10 2 — 17 3 — 35 4 — 52 A群β溶連菌迅速抗原検査は陰性であった。A群β溶連菌迅速抗原検査の陽性尤度比30、陰性尤度比0.2とすると、この患者におけるA群β溶連菌性咽頭炎の事後確率はどれか。', '[{"key": "A", "text": "10%"}, {"key": "B", "text": "25%"}, {"key": "C", "text": "40%"}, {"key": "D", "text": "50%"}, {"key": "E", "text": "75%"}]'::jsonb, 'A', '正答は A「10%」。

4項目のうち当てはまるのは発熱・口蓋扁桃の白苔・咳がないの3つである。リンパ節腫大は後頸部で、項目にある前頸部ではないため数えない。当てはまるのが3つのときの事前確率は35%で、事前オッズは0.35/0.65≒0.54、陰性尤度比0.2を掛けて事後オッズは約0.11、事後確率は0.11/(1+0.11)≒0.10で10%になる。

出典：厚生労働省ホームページ 第116回医師国家試験 E047', '{"B": "事前確率35%を陰性の結果でいくらか下げただけの値で、尤度比を掛ける計算になっていない。", "C": "事前確率をほぼそのまま残した値で、陰性という結果が反映されていない。", "D": "後頸部の腫大を前頸部と取り違えて4項目とし、事前確率52%をそのまま答えたときの値に近い。検査結果を使っていない。", "E": "確率が上がる向きの値で、陰性尤度比ではなく陽性尤度比を当てはめたときの形になっている。"}'::jsonb, 'public', 'M', '116-E-47', '', 'pending', 'llm'),
('婦人科・乳腺外科', '', 2, 'KOKUSHI', '21歳の女性。発熱と咽頭痛を主訴に来院した。現病歴 : 2日前に咽頭痛と37°C台の発熱が出現し、昨晩は38.6°Cであった。市販の解熱鎮痛薬を内服し、今朝は37.6°Cに下がったが、咽頭痛は悪化している。鼻汁、咳、痰はない。嚥下時に咽頭痛は増悪するが、嚥下障害はない。同様の症状の患者との接触はない。既往歴 : 3年前にA群β溶血性連鎖球菌(A群β溶連菌)性咽頭炎を発症。月経痛に対してアセトアミノフェンを頓用している。生活歴 : 喫煙歴はない。飲酒は機会飲酒。大学3年生で就職活動をしている。ペットは飼育していない。海外渡航歴はない。アレルギー歴はない。家族と同居している。最終月経は7日前から4日間で終了した。家族歴 : 父は高血圧症。母と弟は健康。現症 : 意識は清明。身長156cm、体重52kg。体温38.2°C。脈拍96/分、整。血圧108/62mmHg。呼吸数20/分。四肢・体幹に皮疹を認めない。両側扁桃の発赤と腫大があり、表面に白苔を認める。両側の後頸部に最大径1cmの圧痛を伴うリンパ節腫大をそれぞれ3個認める。心音と呼吸音に異常を認めない。腹部は平坦、軟で、右肋骨弓下に肝を3cm、左肋骨弓下に脾を3cm触知する。肋骨脊柱角叩打痛は両側で認めない。検査所見 : 尿所見:蛋白(−)、糖(−)、潜血(−)、沈渣に白血球を認めない。血液所見:赤血球410万、Hb11.6g/dL、Ht39%、白血球17,400(好中球44%、好酸球1%、単球3%、リンパ球42%、異型リンパ球10%)、血小板21万。血液生化学所見:総蛋白7.0g/dL、アルブミン4.2g/dL、総ビリルビン0.9mg/dL、AST62U/L、ALT94U/L、LD785U/L (基準120〜245)、ALP100U/L (基準38〜113)、尿素窒素24mg/dL、クレアチニン0.8mg/dL。CRP3.5mg/dL。
初診時に提出した検体の抗EBV VCA IgM抗体は陽性であった。この患者で他者への感染源となる可能性が高いのはどれか。', '[{"key": "A", "text": "尿"}, {"key": "B", "text": "汗"}, {"key": "C", "text": "唾液"}, {"key": "D", "text": "糞便"}, {"key": "E", "text": "血液"}]'::jsonb, 'C', '正答は C「唾液」。

抗EBV VCA IgM抗体が陽性で、異型リンパ球10%、肝脾腫、扁桃の白苔を伴う伝染性単核球症である。EBVは唾液中に排出され、food/飲み物の回し飲みやキスなど唾液を介して伝播する。

出典：厚生労働省ホームページ 第116回医師国家試験 E048', '{"A": "サイトメガロウイルスでは尿中排泄が問題になるが、EBVの主な伝播経路ではない。", "B": "汗を介して伝播することは知られていない。", "D": "糞便を介するのは経口感染する腸管ウイルスの経路で、EBVには当てはまらない。", "E": "輸血や臓器移植で伝播することはあるが、日常生活で他者への感染源となるのは唾液である。"}'::jsonb, 'public', 'M', '116-E-48', '', 'pending', 'llm'),
('医学総論', '', 2, 'KOKUSHI', '60歳の女性。背部痛と体重減少を主訴に来院した。現病歴 : 1か月前から背部痛を自覚していた。市販の外用薬を貼ったりマッサージを受けたりしていたが改善しないため来院した。この3か月間で体重が3kg減少している。既往歴 : 55歳時から高血圧症で降圧薬を服用している。生活歴 : 夫と2人暮らし。家族歴 : 父が高血圧症、母が高脂血症。現症 : 意識は清明。身長155cm、体重45kg。体温36.2°C。脈拍96/分、整。血圧126/80mmHg。呼吸数18/分。SpO298%(room air)。眼瞼結膜は蒼白で、眼球結膜に黄染を認めない。甲状腺腫と頸部リンパ節を触知しない。心音と呼吸音に異常を認めない。腹部は膨満しており、波動を認める。聴診で腸雑音は減弱している。肝・脾を触知しない。両下腿に軽度の浮腫を認める。腱反射は正常である。感覚系に異常を認めない。検査所見 : 血液所見:赤血球401万、Hb10.5g/dL、Ht31%、白血球4,500、血小板29万。血液生化学所見:総蛋白5.9g/dL、アルブミン2.9g/dL、総ビリルビン0.9mg/dL、AST24U/L、ALT22U/L、LD363U/L(基準120〜245)、ALP146U/L(基準38〜113)、尿素窒素11mg/dL、クレアチニン0.7mg/dL、血糖93mg/dL、CEA10.6ng/mL(基準5以下)、CA19-9352U/mL(基準37以下)。腹部超音波検査および腹部CTで膵体部に径10cmの腫瘤、肝両葉に径1〜2cmの多発する腫瘤陰影を認める。腹水の貯留を認める。
担当医が今後の治療方針を判断するために最も適切な情報はどれか。', '[{"key": "A", "text": "患者の体験記"}, {"key": "B", "text": "診療ガイドライン"}, {"key": "C", "text": "研究会での症例報告"}, {"key": "D", "text": "製薬会社のホームページ"}, {"key": "E", "text": "医師が発信するソーシャル・メディア"}]'::jsonb, 'B', '正答は B「診療ガイドライン」。

膵体部癌に多発肝転移と腹水があり、切除できない進行膵癌である。治療方針は、系統的に集めた根拠をもとに推奨をまとめた診療ガイドラインを参考にし、患者の価値観や全身状態と合わせて決める。

出典：厚生労働省ホームページ 第116回医師国家試験 E049', '{"A": "患者の体験記は患者の思いを知る手がかりになるが、治療の効果を判断する根拠にはならない。", "C": "症例報告は個別の経験で、根拠としての水準は低い。", "D": "製薬会社のホームページは自社製品に偏るおそれがある。", "E": "ソーシャル・メディアの情報は検証されておらず、治療方針の根拠にはならない。"}'::jsonb, 'public', 'M', '116-E-49', '', 'pending', 'llm'),
('医学総論', '', 2, 'KOKUSHI', '60歳の女性。背部痛と体重減少を主訴に来院した。現病歴 : 1か月前から背部痛を自覚していた。市販の外用薬を貼ったりマッサージを受けたりしていたが改善しないため来院した。この3か月間で体重が3kg減少している。既往歴 : 55歳時から高血圧症で降圧薬を服用している。生活歴 : 夫と2人暮らし。家族歴 : 父が高血圧症、母が高脂血症。現症 : 意識は清明。身長155cm、体重45kg。体温36.2°C。脈拍96/分、整。血圧126/80mmHg。呼吸数18/分。SpO298%(room air)。眼瞼結膜は蒼白で、眼球結膜に黄染を認めない。甲状腺腫と頸部リンパ節を触知しない。心音と呼吸音に異常を認めない。腹部は膨満しており、波動を認める。聴診で腸雑音は減弱している。肝・脾を触知しない。両下腿に軽度の浮腫を認める。腱反射は正常である。感覚系に異常を認めない。検査所見 : 血液所見:赤血球401万、Hb10.5g/dL、Ht31%、白血球4,500、血小板29万。血液生化学所見:総蛋白5.9g/dL、アルブミン2.9g/dL、総ビリルビン0.9mg/dL、AST24U/L、ALT22U/L、LD363U/L(基準120〜245)、ALP146U/L(基準38〜113)、尿素窒素11mg/dL、クレアチニン0.7mg/dL、血糖93mg/dL、CEA10.6ng/mL(基準5以下)、CA19-9352U/mL(基準37以下)。腹部超音波検査および腹部CTで膵体部に径10cmの腫瘤、肝両葉に径1〜2cmの多発する腫瘤陰影を認める。腹水の貯留を認める。
担当医は患者に病状を伝えるために以下のように行動した。まず、①患者との面談の前に夫に電話で検査結果を伝えた。面談では、②今までの症状について患者の認識を確認した。次に、③患者が今回の検査結果をどこまで知りたいか確認した。その上で、なるべく平易な言葉や図を用いて腹部造影CTの結果を説明した。患者は驚き混乱している様子であったため、④患者の気持ちを察して少し間をとってから声をかけた。最後に、⑤患者の気持ちを傾聴し、共感の態度を示した。悪い知らせの伝え方について、下線部のうち誤っているのはどれか。', '[{"key": "A", "text": "①"}, {"key": "B", "text": "②"}, {"key": "C", "text": "③"}, {"key": "D", "text": "④"}, {"key": "E", "text": "⑤"}]'::jsonb, 'A', '正答は A「①」。

悪い知らせは、まず本人に、落ち着いた場所で直接伝える。本人の了解なく先に家族へ電話で知らせるのは、本人の知る権利と個人情報の扱いの点で誤りである（誰と一緒に聞きたいかは本人に尋ねる）。伝え方の手順としてSPIKESがよく知られている。

出典：厚生労働省ホームページ 第116回医師国家試験 E050', '{"B": "患者が病状をどう理解しているかを確かめるのは、SPIKESのPerception（認識の確認）にあたる。正しい。", "C": "どこまで知りたいかを確かめるのは、Invitation（知りたい範囲の確認）にあたる。正しい。", "D": "間をとって気持ちを受け止めるのは、Emotions（感情への対応）にあたる。正しい。", "E": "気持ちを傾聴し、共感を示すのは正しい。"}'::jsonb, 'public', 'M', '116-E-50', '', 'pending', 'llm'),
('医学総論', '', 2, 'KOKUSHI', '1歳6か月の健康診査における言語発達の問診として適切なのはどれか。', '[{"key": "A", "text": "自分の名前が言えますか。"}, {"key": "B", "text": "2語文(ワンワンキタ、マンマチョウダイ)などを言いますか。"}, {"key": "C", "text": "ママ、ブーブーなど意味のあることばをいくつか話しますか。"}, {"key": "D", "text": "家族といっしょにいるとき、話しかけるような声を出しますか。"}, {"key": "E", "text": "大人の言う簡単なことば(おいで、ちょうだいなど)がわかりますか。"}]'::jsonb, 'C', '正答は C「ママ、ブーブーなど意味のあることばをいくつか話しますか。」。

1歳6か月では有意語(ママ、ブーブーなど意味のあることば)がいくつか出ているかを確認する。これが1歳6か月健康診査の言語発達の目安である。

出典：厚生労働省ホームページ 第116回医師国家試験 F021', '{"A": "自分の名前が言えるのは3歳ごろの目安である。", "B": "2語文が出るのは2歳ごろの目安である。", "D": "喃語のような発声は生後6か月ごろの目安で、1歳6か月では遅すぎる基準である。", "E": "簡単な指示の理解は1歳前後の目安で、言語表出の評価にはならない。"}'::jsonb, 'public', 'M', '116-F-21', '', 'pending', 'llm'),
('血液', '', 2, 'KOKUSHI', '出血症状と疾患の組合せで誤っているのはどれか。', '[{"key": "A", "text": "鼻出血 — 遺伝性出血性末梢血管拡張症〈Osler病〉"}, {"key": "B", "text": "歯肉出血 — IgA血管炎〈Schönlein-Henoch紫斑病〉"}, {"key": "C", "text": "点状出血 — 免疫性血小板減少性紫斑病"}, {"key": "D", "text": "関節内出血 — 血友病A"}, {"key": "E", "text": "口腔内出血 — 再生不良性貧血"}]'::jsonb, 'B', '正答は B「歯肉出血 — IgA血管炎〈Schönlein-Henoch紫斑病〉」。

IgA血管炎の紫斑は小血管の炎症によるもので、下肢や殿部に触れることのできる紫斑が出る。血小板も凝固も正常なので、歯肉出血のような粘膜の出血は特徴ではない。

出典：厚生労働省ホームページ 第116回医師国家試験 F026', '{"A": "Osler病は皮膚や粘膜の毛細血管の拡張から出血し、繰り返す鼻出血が特徴である。正しい。", "C": "免疫性血小板減少性紫斑病では血小板が減り、点状出血や紫斑が出る。正しい。", "D": "血友病Aでは関節内や筋肉内の深部出血が特徴である。正しい。", "E": "再生不良性貧血では血小板が減り、口腔内や歯肉の出血、点状出血が出る。正しい。"}'::jsonb, 'public', 'M', '116-F-26', '', 'pending', 'llm'),
('救急・中毒', '', 2, 'KOKUSHI', '48歳の女性。左側腹部痛のため救急車で搬入された。現病歴 : 3日前に自宅で転倒した際、左胸部を強打した。自宅近くの診療所で左下位肋骨骨折と診断され、バストバンドによる固定後に帰宅した。今朝、犬の散歩中、急に左側腹部痛が出現し、倦怠感も伴うため夫が救急車を要請した。既往歴 : 35歳時に急性虫垂炎で手術。生活歴 : 夫、中学生の長男と3人暮らし。喫煙歴はない。飲酒は機会飲酒。家族歴 : 母親が糖尿病で加療中である。現症 : 意識は清明。身長160cm、体重53kg。体温37.0°C。心拍数104/分、整。血圧110/62mmHg。呼吸数20/分。SpO298%(room air)。眼瞼結膜と眼球結膜に異常を認めない。心音と呼吸音に異常を認めない。左側腹部に圧痛と筋性防御を認めた。腸雑音に異常を認めない。歩行に異常を認めない。検査所見 : 尿所見:蛋白(−)、糖(−)、潜血(−)、沈渣に赤血球を認めない。血液所見:赤血球385万、Hb11.4g/dL、Ht34%、白血球12,600、血小板19万。血液生化学所見:総蛋白7.2g/dL、アルブミン4.2g/dL、総ビリルビン0.6 mg/dL、直接ビリルビン0.3mg/dL、AST32U/L、ALT20U/L、LD230U/L(基準120〜245)、ALP103U/L(基準38〜113)、尿素窒素20mg/dL、クレアチニン0.8mg/dL、 尿酸5.4mg/dL、 血糖88mg/dL、 Na140mEq/L、 K 4.5 mEq/L、Cl105mEq/L。CRP0.1mg/dL。胸部エックス線写真で胸水貯留を認めない。心電図は心拍数104/分の洞調律でST-T変化を認めない。
腹部超音波検査で左上腹部に液体貯留所見を認めた。治療方針の確定に最も有用な検査はどれか。', '[{"key": "A", "text": "腹腔穿刺"}, {"key": "B", "text": "腹部MRI"}, {"key": "C", "text": "腹部造影CT"}, {"key": "D", "text": "FDG-PET"}, {"key": "E", "text": "99mTcシンチグラフィ"}]'::jsonb, 'C', '正答は C「腹部造影CT」。

3日前に左下位肋骨を折っており、左上腹部の液体貯留と頻脈から、遅れて起きた脾損傷（被膜下血腫の破裂）による腹腔内出血を考える。循環が保たれているうちに腹部造影CTで損傷の程度と造影剤の血管外漏出を確かめ、経過観察、動脈塞栓術（TAE）、手術のどれにするかを決める。

出典：厚生労働省ホームページ 第116回医師国家試験 F062', '{"A": "腹腔穿刺で血液と分かっても、どの臓器がどの程度傷ついているかは分からない。", "B": "MRIは時間がかかり、循環が急に悪くなりうる外傷患者には向かない。", "D": "FDG-PETは悪性腫瘍や炎症を調べる検査である。", "E": "シンチグラフィでは損傷の程度や出血の部位を急いで評価できない。"}'::jsonb, 'public', 'M', '116-F-62', '', 'pending', 'llm'),
('救急・中毒', '', 2, 'KOKUSHI', '48歳の女性。左側腹部痛のため救急車で搬入された。現病歴 : 3日前に自宅で転倒した際、左胸部を強打した。自宅近くの診療所で左下位肋骨骨折と診断され、バストバンドによる固定後に帰宅した。今朝、犬の散歩中、急に左側腹部痛が出現し、倦怠感も伴うため夫が救急車を要請した。既往歴 : 35歳時に急性虫垂炎で手術。生活歴 : 夫、中学生の長男と3人暮らし。喫煙歴はない。飲酒は機会飲酒。家族歴 : 母親が糖尿病で加療中である。現症 : 意識は清明。身長160cm、体重53kg。体温37.0°C。心拍数104/分、整。血圧110/62mmHg。呼吸数20/分。SpO298%(room air)。眼瞼結膜と眼球結膜に異常を認めない。心音と呼吸音に異常を認めない。左側腹部に圧痛と筋性防御を認めた。腸雑音に異常を認めない。歩行に異常を認めない。検査所見 : 尿所見:蛋白(−)、糖(−)、潜血(−)、沈渣に赤血球を認めない。血液所見:赤血球385万、Hb11.4g/dL、Ht34%、白血球12,600、血小板19万。血液生化学所見:総蛋白7.2g/dL、アルブミン4.2g/dL、総ビリルビン0.6 mg/dL、直接ビリルビン0.3mg/dL、AST32U/L、ALT20U/L、LD230U/L(基準120〜245)、ALP103U/L(基準38〜113)、尿素窒素20mg/dL、クレアチニン0.8mg/dL、 尿酸5.4mg/dL、 血糖88mg/dL、 Na140mEq/L、 K 4.5 mEq/L、Cl105mEq/L。CRP0.1mg/dL。胸部エックス線写真で胸水貯留を認めない。心電図は心拍数104/分の洞調律でST-T変化を認めない。
この時点で追加する検査として優先度が低いのはどれか。', '[{"key": "A", "text": "血液型"}, {"key": "B", "text": "血液培養"}, {"key": "C", "text": "血中乳酸"}, {"key": "D", "text": "交差適合試験"}, {"key": "E", "text": "プロトロンビン時間"}]'::jsonb, 'B', '正答は B「血液培養」。

腹腔内出血を疑う外傷患者では、輸血と止血の準備が優先される（血液型、交差適合試験、凝固、乳酸）。発熱やCRPの上昇はなく、感染を疑う所見がないので、血液培養の優先度は低い。

出典：厚生労働省ホームページ 第116回医師国家試験 F063', '{"A": "輸血に備えて血液型を調べる。優先度は高い。", "C": "乳酸は組織の低灌流（ショック）の程度を知る指標で、優先度は高い。", "D": "輸血に備えて交差適合試験を行う。優先度は高い。", "E": "凝固障害があると出血が止まりにくく、治療方針にも関わる。優先度は高い。"}'::jsonb, 'public', 'M', '116-F-63', '', 'pending', 'llm'),
('感染症', '', 2, 'KOKUSHI', '50歳の女性。発熱を主訴に来院した。現病歴 : 3か月前に大腸癌と診断され、左鎖骨下静脈に中心静脈ポートを造設し外来で抗癌化学療法を行っていた。3日前から悪寒を伴う発熱を認め、改善しないため来院した。既往歴 : 3か月前の大腸癌の診断以外に特記すべきことはない。生活歴 : ADLは自立しており夫と2人暮らし。喫煙歴、飲酒歴はない。家族歴 : 母親が乳癌で死亡している。現症 : 意識は清明。身長157cm、体重52kg。体温38.3°C。脈拍102/分、整。血圧134/76mmHg。呼吸数16/分。SpO297%(room air)。眼瞼結膜は軽度貧血様であり、眼球結膜に黄染はない。甲状腺と頸部リンパ節を触知しない。心尖部にLevine2/6の全収縮期雑音を認める。呼吸音に異常を認めない。腹部は平坦で、肝・脾を触知しない。肋骨脊柱角〈CVA〉叩打痛を認めない。下腿に浮腫や圧痛を認めない。左鎖骨下の中心静脈ポート造設部に発赤と疼痛を認める。検査所見 : 尿所見:蛋白(−)、糖(−)、潜血(−)。血液所見:赤血球360万、Hb8.5g/dL、Ht26%、白血球11,000(好中球84%、好酸球1%、好塩基球1%、単球6%、リンパ球8%)、血小板18万。血液生化学所見:総蛋白6.0g/dL、アルブミン2.9g/dL、総ビリルビン1.0mg/dL、直接ビリルビン0.2mg/dL、AST42 U/L、ALT58U/L、LD321U/L(基準120〜245)、尿素窒素28mg/dL、クレアチニン1.0mg/dL、血糖98mg/dL、Na133mEq/L、K4.1mEq/L、Cl97mEq/L。CRP12mg/dL。心エコー検査で中等度の僧帽弁逆流を認める。疣贅は認めない。血液培養検体を2セット採取したのちに入院した。左鎖骨下の中心静脈ポートを抜去し、抗菌薬治療を開始した。
入院翌日に2セットの血液培養検体の両方から、グラム陽性のクラスター様に集簇する球菌が検出された。最も可能性が高い原因微生物はどれか。', '[{"key": "A", "text": "Clostridium perfringens"}, {"key": "B", "text": "Enterococcus faecalis"}, {"key": "C", "text": "Haemophilus influenzae"}, {"key": "D", "text": "Staphylococcus aureus"}, {"key": "E", "text": "Streptococcus mitis"}]'::jsonb, 'D', '正答は D「Staphylococcus aureus」。

クラスター（ぶどうの房）状のグラム陽性球菌はブドウ球菌である。ポート刺入部の発赤と疼痛を伴うカテーテル関連血流感染症で、2セットとも陽性なので汚染ではなく、黄色ブドウ球菌を最も考える。黄色ブドウ球菌の菌血症では、カテーテルを抜去し、少なくとも2週間抗菌薬を投与し、感染性心内膜炎の合併を調べる。

出典：厚生労働省ホームページ 第116回医師国家試験 F068', '{"A": "Clostridium perfringensは嫌気性のグラム陽性桿菌で、ガス壊疽などを起こす。", "B": "Enterococcus faecalisはグラム陽性球菌だが、双球菌か短い連鎖状に並ぶ。", "C": "Haemophilus influenzaeはグラム陰性桿菌である。", "E": "Streptococcus mitisは連鎖状に並ぶ口腔内の常在菌で、歯科処置のあとの感染性心内膜炎の原因になる。"}'::jsonb, 'public', 'M', '116-F-68', '', 'pending', 'llm'),
('感染症', '', 2, 'KOKUSHI', '50歳の女性。発熱を主訴に来院した。現病歴 : 3か月前に大腸癌と診断され、左鎖骨下静脈に中心静脈ポートを造設し外来で抗癌化学療法を行っていた。3日前から悪寒を伴う発熱を認め、改善しないため来院した。既往歴 : 3か月前の大腸癌の診断以外に特記すべきことはない。生活歴 : ADLは自立しており夫と2人暮らし。喫煙歴、飲酒歴はない。家族歴 : 母親が乳癌で死亡している。現症 : 意識は清明。身長157cm、体重52kg。体温38.3°C。脈拍102/分、整。血圧134/76mmHg。呼吸数16/分。SpO297%(room air)。眼瞼結膜は軽度貧血様であり、眼球結膜に黄染はない。甲状腺と頸部リンパ節を触知しない。心尖部にLevine2/6の全収縮期雑音を認める。呼吸音に異常を認めない。腹部は平坦で、肝・脾を触知しない。肋骨脊柱角〈CVA〉叩打痛を認めない。下腿に浮腫や圧痛を認めない。左鎖骨下の中心静脈ポート造設部に発赤と疼痛を認める。検査所見 : 尿所見:蛋白(−)、糖(−)、潜血(−)。血液所見:赤血球360万、Hb8.5g/dL、Ht26%、白血球11,000(好中球84%、好酸球1%、好塩基球1%、単球6%、リンパ球8%)、血小板18万。血液生化学所見:総蛋白6.0g/dL、アルブミン2.9g/dL、総ビリルビン1.0mg/dL、直接ビリルビン0.2mg/dL、AST42 U/L、ALT58U/L、LD321U/L(基準120〜245)、尿素窒素28mg/dL、クレアチニン1.0mg/dL、血糖98mg/dL、Na133mEq/L、K4.1mEq/L、Cl97mEq/L。CRP12mg/dL。心エコー検査で中等度の僧帽弁逆流を認める。疣贅は認めない。血液培養検体を2セット採取したのちに入院した。左鎖骨下の中心静脈ポートを抜去し、抗菌薬治療を開始した。
中心静脈ポートの再造設に際して誤っているのはどれか。', '[{"key": "A", "text": "血液培養の陰性化を確認後に行う。"}, {"key": "B", "text": "抜去した部位を避けて造設する。"}, {"key": "C", "text": "明らかな静脈閉塞がない部位を選択する。"}, {"key": "D", "text": "新しい中心静脈ポートを抗菌薬に浸してから留置する。"}, {"key": "E", "text": "造設後にエックス線写真で位置を確認する。"}]'::jsonb, 'D', '正答は D「新しい中心静脈ポートを抗菌薬に浸してから留置する。」。

新しいポートを抗菌薬に浸してから留置しても感染は防げず、推奨されない。再造設は、血液培養の陰性化を確かめてから、感染した部位を避け、閉塞のない静脈を選んで、無菌操作（マキシマル・バリアプリコーション）で行う。

出典：厚生労働省ホームページ 第116回医師国家試験 F070', '{"A": "菌が残っていると新しいポートにも付くので、血液培養の陰性化を確かめてから造る。正しい。", "B": "感染した部位を避けて造る。正しい。", "C": "閉塞や血栓のある静脈は避ける。正しい。", "E": "造設後はエックス線写真でカテーテルの先端の位置を確かめる。正しい。"}'::jsonb, 'public', 'M', '116-F-70', '', 'pending', 'llm'),
('産科', '', 2, 'KOKUSHI', '30歳の初産婦(1妊0産)。妊娠38週1日、自宅での破水直後から強い呼吸困難を自覚し救急車で搬入された。妊娠37週までの妊婦健康診査で異常は認めなかった。意識は清明。体温37.8°C。心拍数96/分、整。血圧92/76mmHg。呼吸数20/分。SpO299%(リザーバー付マスク10L/分酸素投与下)。腹部超音波検査で胎児心拍が確認された。腟鏡診で出血交じりの羊水を少量認め、子宮口は2cm開大していた。血液所見:赤血球360万、Hb10.0g/dL、Ht33%、白血球28,000、血小板14万、血漿フィブリノゲン<50mg/dL(妊娠中の基準401〜545mg/dL)。血液生化学所見:AST20U/L、ALT15U/L、尿素窒素12mg/dL、クレアチニン0.8mg/dL。まず投与すべきなのはどれか。', '[{"key": "A", "text": "抗菌薬"}, {"key": "B", "text": "アルブミン"}, {"key": "C", "text": "ジアゼパム"}, {"key": "D", "text": "新鮮凍結血漿"}, {"key": "E", "text": "ノルアドレナリン"}]'::jsonb, 'D', '正答は D「新鮮凍結血漿」。

破水直後の急激な呼吸困難に、フィブリノゲン50mg/dLという著明な低下を伴っている。羊水塞栓症による産科DICで、フィブリノゲンを含む凝固因子を補充する新鮮凍結血漿の大量投与が治療の中心になる。

出典：厚生労働省ホームページ 第117回医師国家試験 A030', '{"A": "感染を示す所見に乏しく、抗菌薬は主治療にならない。", "B": "アルブミンは膠質浸透圧を保つが、凝固因子を含まない。", "C": "けいれんはなく、ジアゼパムの適応がない。", "E": "昇圧薬は循環の補助にはなるが、DICそのものを是正しない。"}'::jsonb, 'public', 'M', '117-A-30', '', 'pending', 'llm'),
('循環器', '', 2, 'KOKUSHI', '71歳の男性。咳嗽と労作時の呼吸困難を主訴に来院した。3年前から咳嗽と労作時の呼吸困難があり、徐々に進行していると自覚したため受診した。40年前に膿胸で胸郭形成術を受けた。喫煙は20本/日を50年間。意識は清明。体温36.2°C。脈拍84/分、整。血圧140/76mmHg。呼吸数16/分。血液生化学所見:尿素窒素16mg/dL、Na133mEq/L、Cl91mEq/L。呼吸機能検査:%VC45%、FEV1%60%。 動脈血ガス分析(room air):pH7.26、PaCO268Torr、PaO248Torr、HCO3−28mEq/L。胸部エックス線写真で透過性亢進および胸郭形成後の肺容量減少を認める。心エコー検査で右心室および右心房の拡張、心室中隔の左室側への偏位を認める。この患者にみられる病態で誤っているのはどれか。', '[{"key": "A", "text": "肺高血圧"}, {"key": "B", "text": "肺胞低換気"}, {"key": "C", "text": "シャント率上昇"}, {"key": "D", "text": "混合性換気障害"}, {"key": "E", "text": "代償性呼吸性アシドーシス"}]'::jsonb, 'E', '正答は E「代償性呼吸性アシドーシス」。

pH7.26と酸血症があり、PaCO2 68TorrとHCO3− 28mEq/Lで、代償が不十分な呼吸性アシドーシスである。慢性呼吸性アシドーシスであれば腎性代償によりHCO3−はもっと上昇するはずで、急性増悪が加わっていることを示す。「代償性」とは言えない。

出典：厚生労働省ホームページ 第117回医師国家試験 A032', '{"A": "心エコーで右心系の拡張と心室中隔の左方偏位があり、肺高血圧を認める。", "B": "PaCO2 68Torrの高二酸化炭素血症は肺胞低換気を示す。", "C": "胸郭形成術後の変形と換気血流不均等によりシャント率は上昇する。", "D": "%VC45%の拘束性障害とFEV1%60%の閉塞性障害を併せもつ混合性換気障害である。"}'::jsonb, 'public', 'M', '117-A-32', '', 'pending', 'llm'),
('消化管', '', 2, 'KOKUSHI', '59歳の男性。倦怠感、悪心、嘔吐および発熱を主訴に来院した。現病歴 : 昨日から倦怠感を自覚していたが、本日、悪心、嘔吐および悪寒戦慄を伴う発熱が出現し、体動困難となったため救急外来を受診した。既往歴 : 糖尿病でSGLT2阻害薬を内服している。高血圧と脂質異常症で食事療法を行っている。生活歴 : 妻と2人暮らし。喫煙歴はない。飲酒は機会飲酒。家族歴 : 父が糖尿病。母が大腸癌。現症 : 意識は清明。身長165cm、体重70kg。体温38.5°C。脈拍92/分、整。血圧120/86mmHg。呼吸数20/分。SpO298%(room air)。眼瞼結膜と眼球結膜とに異常を認めない。甲状腺腫と頸部リンパ節とを触知しない。心音と呼吸音とに異常を認めない。腹部はやや膨満しており腸蠕動音は低下しているが、圧痛や腫瘤は認めない。肝・脾を触知しない。肋骨脊柱角叩打痛は両側とも認めない。検査所見 : 尿所見:蛋白(−)、糖2+、潜血(−)、①沈渣に白血球を認めない。血液所見:赤血球522万、Hb16.2g/dL、Ht47%、白血球19,600(桿状核好中球3%、 分葉核好中球79%、 単球 6%、 リンパ球12%)、 血小板17万、PT-INR1.09(基準0.9〜1.1)。血液生化学所見:総蛋白6.9g/dL、アルブミン4.1g/dL、② 総ビリルビン1.8mg/dL、 直接ビリルビン1.0mg/dL、AST23U/L、ALT33U/L、LD178U/L(基準120〜245)、ALP103U/L(基準38〜113)、γ-GT85U/L(基準 8〜50)、 アミラーゼ45U/L(基準37〜160)、CK144U/L(基準30〜140)、尿素窒素20mg/dL、クレアチニン0.87mg/dL、③eGFR70.1mL/分/1.73m2、④尿酸6.0mg/dL、血糖189mg/dL、HbA1c7.5%(基準 4.6〜6.2)、⑤ Na 136mEq/L 、K 4.4mEq/L、Cl 98mEq/L。CRP11.4mg/dL。
症状の原因を検索するために画像検査が必要と考えた。下線部のうち、造影CT撮影実施の可否を判断する上で最も重要な情報はどれか。', '[{"key": "A", "text": "①"}, {"key": "B", "text": "②"}, {"key": "C", "text": "③"}, {"key": "D", "text": "④"}, {"key": "E", "text": "⑤"}]'::jsonb, 'C', '正答は C「③」。

造影CTを撮れるかどうかを左右するのは腎機能で、ヨード造影剤は腎障害のある患者で造影剤腎症を起こしうる。下線部③のeGFRは保たれており、造影は可能と判断できる。

出典：厚生労働省ホームページ 第117回医師国家試験 B045', '{"A": "尿沈渣に白血球がないことは尿路感染の否定に役立つが、造影剤を使えるかどうかとは関わらない。", "B": "総ビリルビンの上昇は胆道系の評価に関わるもので、造影の可否を決めない。", "D": "尿酸値は造影剤の使用可否と関係しない。", "E": "血清Naも造影の可否を決める指標ではない。"}'::jsonb, 'public', 'M', '117-B-45', '', 'pending', 'llm'),
('医学総論', '', 2, 'KOKUSHI', '視診後の腹部診察順として正しいのはどれか。', '[{"key": "A", "text": "触診 → 打診 → 聴診"}, {"key": "B", "text": "触診 → 聴診 → 打診"}, {"key": "C", "text": "打診 → 聴診 → 触診"}, {"key": "D", "text": "打診 → 触診 → 聴診"}, {"key": "E", "text": "聴診 → 打診 → 触診"}]'::jsonb, 'E', '正答は E「聴診 → 打診 → 触診」。

腹部診察は視診のあと聴診、打診、触診の順に行う。触診や打診を先に行うと腸管が刺激されて腸蠕動音が変化し、本来の音を評価できなくなるためである。

出典：厚生労働省ホームページ 第117回医師国家試験 E015', '{"A": "触診を最初に行うと腸蠕動音が変わってしまう。", "B": "同じく触診が先になっており、聴診の所見が変わってしまう。", "C": "打診も腹壁への刺激となるため、聴診より先に行わない。", "D": "打診と触診が聴診より先になっている。"}'::jsonb, 'public', 'M', '117-E-15', '', 'pending', 'llm'),
('救急・中毒', '', 2, 'KOKUSHI', '61歳の男性。交通外傷のため救急車で搬入された。現病歴 : 乗用車で走行中に塀に衝突し腹部を強打し動けない状態だった。シートベルトを装着しておりエアバッグが作動していた。目撃者が救急車を要請した。既往歴 : 虚血性心疾患で抗血小板薬を服用している。生活歴 : 飲酒は機会飲酒。家族歴 : 父と兄が高血圧症で治療中である。現症 : 意識は清明。身長162cm、体重54kg。体温37.0°C。心拍数112/分、整。血圧80/44 mmHg。呼吸数26/分。SpO2 98%(リザーバー付マスク10L/分酸素投与下)。皮膚は四肢に冷汗と湿潤を認める。眼瞼結膜と眼球結膜とに異常を認めない。口腔内は乾燥している。頸静脈の怒張を認めない。心音と呼吸音とに異常を認めない。腹部は膨満しており、肝・脾を触知しない。腸雑音は減弱している。検査所見 : 血液所見:赤血球410万、Hb10.1g/dL、Ht40%、白血球10,300(好中球75%、好酸球1%、好塩基球1%、単球6%、リンパ球17%)、血小板32万。血液生化学所見:総蛋白7.2g/dL、アルブミン4.0g/dL、総ビリルビン0.9 mg/dL、直接ビリルビン0.2mg/dL、AST65U/L、ALT34U/L、LD177U/L(基準124〜222)、ALP55U/L(基準38〜113)、γ-GT32U/L(基準13〜64)、アミラーゼ130U/L(基準44〜132)、CK382U/L(基準59〜248)、尿素窒素22mg/dL、クレアチニン0.6mg/dL、尿酸6.2mg/dL、血糖228mg/dL、HbA1c5.8%(基準4.9〜6.0)、Na142mEq/L、K4.4mEq/L、Cl97mEq/L。
小腸、腸間膜および脾臓の損傷に対して小腸切除と脾臓摘出を行った。小腸は浮腫が認められたが、閉腹は可能であった。ICU入室後、心拍数68/分、血圧132/76 mmHgまで改善した。動脈血ガス分析(調節呼吸、FIO2 0.3)はpH7.40、PaCO2 35 Torr、PaO2 180 Torr、HCO3− 21mEq/L、BE -6mEq/Lであった。この段階で腹部コンパートメント症候群を評価するために腹腔内圧をモニターする際、最も有用な測定部位はどれか。', '[{"key": "A", "text": "胸腔"}, {"key": "B", "text": "食道"}, {"key": "C", "text": "頭蓋内"}, {"key": "D", "text": "動脈内"}, {"key": "E", "text": "膀胱"}]'::jsonb, 'E', '正答は E「膀胱」。

腹腔内圧は、膀胱に留置した尿道カテーテルから少量（25mL以下）の生理食塩液を入れ、仰臥位の呼気終末に、中腋窩線の高さを基準として膀胱内圧を測って代用する。腹腔内圧が20mmHgを超えて持続し、新たな臓器障害（乏尿、換気障害など）が出れば腹部コンパートメント症候群と診断する。腹部外傷の術後、腸管浮腫、大量輸液のあとに起きやすい。

出典：厚生労働省ホームページ 第118回医師国家試験 C068', '{"A": "胸腔内圧は腹腔内圧の指標にならない。", "B": "食道内圧は胸腔内圧の指標で、人工呼吸の管理などに用いる。", "C": "頭蓋内圧は頭部外傷などで測るもので、腹腔内圧は分からない。", "D": "動脈圧は循環の指標で、腹腔内圧は分からない。"}'::jsonb, 'public', 'M', '118-C-68', '', 'pending', 'llm'),
('婦人科・乳腺外科', '', 2, 'KOKUSHI', '32歳の女性(0妊0産)。無月経を主訴に来院した。初経は13歳。月経周期は順調であったが、29歳から月経不順があり、31歳から無月経となり産婦人科を受診した。6か月前から頭痛を自覚し、2か月前から頭痛の頻度と強さが増加した。身長165cm、体重55kg。体温36.3°C。脈拍64/分、整。血圧120/67 mmHg。呼吸数18/分。乳房は発達している。外性器は女性型で、陰毛・腋毛を認める。血液所見:赤血球350万、Hb 12.1g/dL、Ht33%、白血球3,700、血小板31万。血液生化学所見:TSH2.3 μU/mL(基準0.2〜4.0)、プロラクチン125 ng/mL(基準15以下)、hCG<0.5 IU/L(基準1.0以下)。経腟超音波検査で子宮の大きさは正常だが子宮内膜は薄い。卵巣は正常大で、内部に小卵胞を認める。次に行うべき画像検査はどれか。', '[{"key": "A", "text": "腹部CT"}, {"key": "B", "text": "FDG-PET"}, {"key": "C", "text": "下垂体MRI"}, {"key": "D", "text": "マンモグラフィ"}, {"key": "E", "text": "甲状腺超音波検査"}]'::jsonb, 'C', '正答は C「下垂体MRI」。

無月経に加えてプロラクチン125ng/mLの高値と、増悪する頭痛を認めており、プロラクチン産生下垂体腺腫が疑われる。腫瘍の大きさと視交叉への進展を確かめるため下垂体MRIを行う。

出典：厚生労働省ホームページ 第118回医師国家試験 D018', '{"A": "腹部CTで下垂体は評価できない。", "B": "FDG-PETは悪性腫瘍の検索に用いるもので、下垂体腺腫の描出には適さない。", "D": "乳汁漏出があってもマンモグラフィで下垂体病変は分からない。", "E": "TSHは基準内で、甲状腺機能低下による高プロラクチン血症は考えにくい。"}'::jsonb, 'public', 'M', '118-D-18', '', 'pending', 'llm'),
('代謝・内分泌', '', 2, 'KOKUSHI', '73歳の女性。左足趾の痛みを主訴に来院した。6か月前から約500mの歩行で左ふくらはぎの痛みが出現し、数分の安静で症状は消失していた。かかりつけ医から抗血小板薬が処方されていたが、2か月前の靴ずれを契機に左第五足趾に潰瘍ができ、安静時も痛みが出現したため受診した。高血圧、糖尿病および脂質異常症で55歳から内服治療中である。体温37.0°C。脈拍96/分、整。血圧140/90mmHg(左右差なし)。呼吸数22/分。SpO295%(room air)。心音と呼吸音とに異常を認めない。両側大腿動脈の触知は良好だが左膝窩動脈、後脛骨および足背動脈の触知は減弱している。下腿に触れると、右より左が冷たい。左第五足趾に潰瘍を認め、周囲は発赤を伴い、圧痛を認める。左第一足趾に壊死を認める。血液生化学所見:血糖123mg/dL、HbA1c6.6%(基準4.9〜6.0)、HDLコレステロール30 mg/dL、LDLコレステロール141mg/dL。CRP2.5mg/dL。下肢の動脈造影検査で、左浅大腿動脈の閉塞を認める。この患者に考慮すべき治療で誤っているのはどれか。', '[{"key": "A", "text": "下肢切断術"}, {"key": "B", "text": "β遮断薬の投与"}, {"key": "C", "text": "外科的バイパス術"}, {"key": "D", "text": "経皮的血管形成術"}, {"key": "E", "text": "プロスタグランジン製剤の投与"}]'::jsonb, 'B', '正答は B「β遮断薬の投与」。

安静時痛と潰瘍・壊死を伴う包括的高度慢性下肢虚血で、浅大腿動脈の閉塞に対して血行再建を急ぐ。β遮断薬は末梢血管抵抗を高めて症状を悪化させうるため、この病態での投与は適切でない。

出典：厚生労働省ホームページ 第119回医師国家試験 A064', '{"A": "壊死と感染が制御できなければ切断もやむを得ず、選択肢として考慮される。", "C": "浅大腿動脈の長区間閉塞にはバイパス術が有力な選択肢である。", "D": "血管内治療による血行再建も第一に検討される。", "E": "プロスタグランジン製剤は血行再建が難しい場合の補助的治療として用いられる。"}'::jsonb, 'public', 'M', '119-A-64', '', 'pending', 'llm'),
('医学総論', '', 2, 'KOKUSHI', '42歳の男性。職場の健康診断で1高血圧を指摘され来院した。仕事は2事務職で、1年前から仕事が忙しく、3過食気味で体重が8kg増加した。既往歴に特記すべきことはない。喫煙歴はない。飲酒はビール350mL/日。身長172cm、体重80kg。4脈拍72/分、整。血圧144/92 mmHg。身体診察に異常を認めない。血液生化学所見:血糖72mg/dL、HbA1c5.8%(基準4.9〜6.0)、トリグリセリド190mg/dL、HDLコレステロール62mg/dL、5LDLコレステロール146mg/dL。体重の減量を目的に食事療法を行う。下線部のうち、推定エネルギー必要量(kcal/日)の算出に必要なのはどれか。', '[{"key": "A", "text": "1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "3"}, {"key": "D", "text": "4"}, {"key": "E", "text": "5"}]'::jsonb, 'B', '正答は B「2」。

推定エネルギー必要量は、標準体重(身長から算出)に身体活動レベルに応じた係数を掛けて求める。身長と職業(事務職=軽い労作)が必要で、下線部のうち該当するのは事務職という職業の情報である。

出典：厚生労働省ホームページ 第119回医師国家試験 E026', '{"A": "高血圧という診断名は必要量の算出に用いない。", "C": "過食気味であることは現在の摂取量の問題で、必要量の算出には用いない。", "D": "脈拍は算出に用いない。", "E": "LDLコレステロール値は脂質の配分を考える材料だが、総エネルギー量の算出には用いない。"}'::jsonb, 'public', 'M', '119-E-26', '', 'pending', 'llm')
),
added AS (
    INSERT INTO quiz_question (category, topic, difficulty, exam_type, question_text, choices, correct_choice_key, explanation, choice_explanations, visibility, question_type, blueprint_code, class_group, status, source, correct_rate, answer_count, created_at)
    SELECT v.category, v.topic, v.difficulty, v.exam_type, v.question_text, v.choices, v.correct_choice_key, v.explanation, v.choice_explanations, v.visibility, v.question_type, v.blueprint_code, v.class_group, v.status, v.source, 0, 0, now()
    FROM v
    WHERE NOT EXISTS (
        SELECT 1 FROM quiz_question q
        WHERE q.exam_type = v.exam_type
          AND q.question_text = v.question_text
          AND q.choices = v.choices)
      AND NOT (v.exam_type = 'KOKUSHI' AND v.blueprint_code <> '' AND EXISTS (
        SELECT 1 FROM quiz_question q
        WHERE q.exam_type = v.exam_type
          AND q.blueprint_code = v.blueprint_code))
    RETURNING 1
)
SELECT (SELECT count(*) FROM added) AS "追加した問題",
       (SELECT count(*) FROM v) - (SELECT count(*) FROM added) AS "すでにあった問題",
       (SELECT count(*) FROM v) AS "このファイルの問題";
